export function resolveTavernNarrativeLifecycleModelAdapter(
  exactModelId: string,
): TavernNarrativeLifecycleModelAdapter {
  if (exactModelId.length === 0 || exactModelId !== exactModelId.trim()) {
    throw new TypeError("Tavern lifecycle model ID must be a non-empty exact value");
  }
  const matches = TAVERN_NARRATIVE_LIFECYCLE_MODEL_ADAPTERS.filter(
    (adapter) => adapter.exact_model_id === exactModelId,
  );
  if (matches.length !== 1) {
    throw new Error(`No exact Tavern lifecycle adapter for model ID: ${exactModelId}`);
  }
  return matches[0] as TavernNarrativeLifecycleModelAdapter;
}
