import type { AgentTransportOperationRecord } from "@narramem/agent-runtime";
import type { TavernAgentTransportWorldbookStore } from "./agent-transport-worldbook-store.js";
import type { TavernCausalAuditTaskStateRecord } from "./causal-audit-task-store-contracts.js";
import type {
  TavernHostPort,
  TavernStructuredGenerationRequest,
  TavernStructuredGenerationResult,
} from "./contracts.js";
import { canonicalJson, sha256HexUtf8, utf8ByteLength } from "./worldbook-codec.js";

const CODE_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/u;

export interface TavernAgentTransportClock {
  now(): string;
}

export type TavernAgentResponseValidation<Value> =
  | { readonly accepted: true; readonly value: Value }
  | { readonly accepted: false; readonly error_code: string };

export interface BeginTavernAgentTransportCallRequest {
  readonly task: Pick<
    TavernCausalAuditTaskStateRecord,
    "task_seed_id" | "source_revision_id" | "source_checksum" | "status" | "lease"
  >;
  readonly operation_kind: string;
  readonly call_index: number;
  readonly provider_route_id: string;
  readonly generation: Omit<TavernStructuredGenerationRequest, "generation_id">;
  readonly max_attempts: number;
  readonly is_source_current: () => boolean | Promise<boolean>;
}

export interface TavernAgentTransportCallRequest<Value>
  extends BeginTavernAgentTransportCallRequest {
  readonly validate: (
    result: TavernStructuredGenerationResult,
  ) => TavernAgentResponseValidation<Value> | Promise<TavernAgentResponseValidation<Value>>;
}

export interface BeginTavernAgentTransportCallResult {
  readonly operation: AgentTransportOperationRecord;
  readonly attempt_id: string;
  readonly generation_request: TavernStructuredGenerationRequest;
}

export interface SettleTavernAgentTransportCallRequest<Value> {
  readonly operation_id: string;
  readonly attempt_id: string;
  readonly response: TavernStructuredGenerationResult;
  readonly validate: TavernAgentTransportCallRequest<Value>["validate"];
  readonly is_source_current: BeginTavernAgentTransportCallRequest["is_source_current"];
  readonly stale_error_code?: string;
}

export type TavernAgentTransportCallResult<Value> =
  | {
      readonly status: "COMMITTED";
      readonly operation: AgentTransportOperationRecord;
      readonly value: Value;
    }
  | {
      readonly status: "REJECTED";
      readonly operation: AgentTransportOperationRecord;
      readonly error_code: string;
    }
  | {
      readonly status: "SUSPENDED_UNKNOWN";
      readonly operation: AgentTransportOperationRecord;
      readonly error_code: string;
    };

export interface TavernAgentTransportCancellationReport {
  readonly generation_id: string | null;
  readonly host_cancel_requested: boolean;
  readonly error_code: string;
  readonly operation_status: AgentTransportOperationRecord["status"] | null;
}

interface ActiveTavernAgentCall {
  readonly operation_id: string;
  readonly attempt_id: string;
  invalidated_error_code?: string;
}

function assertErrorCode(value: string): void {
  if (!CODE_PATTERN.test(value)) throw new TypeError("Agent transport error code is invalid");
}

function requestBody(request: BeginTavernAgentTransportCallRequest): string {
  return canonicalJson({
    target: request.generation.target,
    messages: request.generation.messages,
    prompt_asset_refs: request.generation.prompt_asset_refs,
    json_schema: request.generation.json_schema,
    should_silence: request.generation.should_silence,
    should_stream: request.generation.should_stream,
    max_chat_history: request.generation.max_chat_history,
  });
}

/**
 * The Tavern Helper call itself is not provider-idempotent. This runner makes
 * NarraMem's local side recoverable and uses the durable attempt ID as the exact
 * `generation_id`; an unknown dispatch is never retried automatically.
 */
export class TavernAgentTransportCallRunner {
  private active: ActiveTavernAgentCall | null = null;

  constructor(
    private readonly port: TavernHostPort,
    private readonly store: TavernAgentTransportWorldbookStore,
    private readonly clock: TavernAgentTransportClock,
  ) {}

  async invalidateActive(
    errorCode = "SOURCE_MUTATION_CANCELLED",
  ): Promise<TavernAgentTransportCancellationReport> {
    assertErrorCode(errorCode);
    const active = this.active;
    if (active === null) {
      return {
        generation_id: null,
        host_cancel_requested: false,
        error_code: errorCode,
        operation_status: null,
      };
    }
    active.invalidated_error_code = errorCode;
    const hostCancelRequested = this.port.cancelGeneration?.(active.attempt_id) ?? false;
    let current = await this.currentOperation(active.operation_id);
    if (
      current.operation.status === "dispatch_reserved" ||
      current.operation.status === "in_flight"
    ) {
      try {
        const failed = await this.store.recordFailure(
          current.payload_checksum,
          current.operation.operation_id,
          current.operation.record_version,
          {
            kind: "unknown_after_dispatch",
            error_code: errorCode,
            observed_at: this.clock.now(),
          },
        );
        current = { payload_checksum: failed.payload.checksum, operation: failed.operation };
      } catch {
        current = await this.currentOperation(active.operation_id);
      }
    }
    return {
      generation_id: active.attempt_id,
      host_cancel_requested: hostCancelRequested,
      error_code: errorCode,
      operation_status: current.operation.status,
    };
  }

  async execute<Value>(
    request: TavernAgentTransportCallRequest<Value>,
  ): Promise<TavernAgentTransportCallResult<Value>> {
    if (this.port.generateStructured === undefined || this.port.cancelGeneration === undefined) {
      throw new TypeError("Tavern Agent transport requires generation and per-ID cancellation");
    }
    const begun = await this.begin(request);
    const active = this.active;
    if (active === null) throw new TypeError("Tavern Agent active transport state disappeared");

    let response: TavernStructuredGenerationResult;
    try {
      response = await this.port.generateStructured(begun.generation_request);
    } catch {
      const current = await this.currentOperation(active.operation_id);
      if (
        current.operation.status === "dispatch_reserved" ||
        current.operation.status === "in_flight"
      ) {
        const errorCode = active.invalidated_error_code ?? "HOST_DISPATCH_OUTCOME_UNKNOWN";
        const failed = await this.store.recordFailure(
          current.payload_checksum,
          current.operation.operation_id,
          current.operation.record_version,
          {
            kind: "unknown_after_dispatch",
            error_code: errorCode,
            observed_at: this.clock.now(),
          },
        );
        if (this.active === active) this.active = null;
        return { status: "SUSPENDED_UNKNOWN", operation: failed.operation, error_code: errorCode };
      }
      if (this.active === active) this.active = null;
      return {
        status: "SUSPENDED_UNKNOWN",
        operation: current.operation,
        error_code: active.invalidated_error_code ?? "HOST_DISPATCH_OUTCOME_UNKNOWN",
      };
    }

    return this.settle({
      operation_id: begun.operation.operation_id,
      attempt_id: begun.attempt_id,
      response,
      validate: request.validate,
      is_source_current: request.is_source_current,
    });
  }

  async begin(
    request: BeginTavernAgentTransportCallRequest,
  ): Promise<BeginTavernAgentTransportCallResult> {
    if (this.active !== null) throw new TypeError("Only one Tavern Agent call may run at a time");
    if (!(await request.is_source_current())) {
      throw new TypeError("Tavern Agent call cannot start from a stale source revision");
    }
    const body = requestBody(request);
    const initialized = (await this.store.read()) ?? (await this.store.initialize());
    const created = await this.store.create({
      expected_checksum: initialized.checksum,
      task: request.task,
      operation_kind: request.operation_kind,
      call_index: request.call_index,
      provider_route_id: request.provider_route_id,
      requested_model_id: request.generation.target.requested_model_id,
      prompt_asset_refs: request.generation.prompt_asset_refs,
      request_sha256: await sha256HexUtf8(body),
      request_utf8_bytes: utf8ByteLength(body),
      max_attempts: request.max_attempts,
      created_at: this.clock.now(),
    });
    if (created.operation.status !== "ready") {
      throw new TypeError("Existing Tavern Agent transport operation is not ready for dispatch");
    }
    const reserved = await this.store.reserve(
      created.payload.checksum,
      created.operation.operation_id,
      created.operation.record_version,
      this.clock.now(),
    );
    const dispatched = await this.store.markDispatched(
      reserved.payload.checksum,
      reserved.operation.operation_id,
      reserved.operation.record_version,
      this.clock.now(),
    );
    const attempt = dispatched.operation.attempts.at(-1);
    if (attempt === undefined) throw new TypeError("Dispatched Tavern Agent attempt disappeared");
    const active: ActiveTavernAgentCall = {
      operation_id: dispatched.operation.operation_id,
      attempt_id: attempt.attempt_id,
    };
    this.active = active;
    return {
      operation: dispatched.operation,
      attempt_id: attempt.attempt_id,
      generation_request: {
        ...request.generation,
        generation_id: attempt.attempt_id,
      },
    };
  }

  async settle<Value>(
    request: SettleTavernAgentTransportCallRequest<Value>,
  ): Promise<TavernAgentTransportCallResult<Value>> {
    if (this.active !== null && this.active.operation_id !== request.operation_id) {
      throw new TypeError("A different Tavern Agent call is already active");
    }
    const active =
      this.active ??
      ({
        operation_id: request.operation_id,
        attempt_id: request.attempt_id,
        ...(request.stale_error_code === undefined
          ? {}
          : { invalidated_error_code: request.stale_error_code }),
      } satisfies ActiveTavernAgentCall);
    try {
      const settled = await this.settleResponse(active, request.response, request);
      return settled;
    } finally {
      if (this.active === active) this.active = null;
    }
  }

  private async settleResponse<Value>(
    active: ActiveTavernAgentCall,
    response: TavernStructuredGenerationResult,
    request: SettleTavernAgentTransportCallRequest<Value>,
  ): Promise<TavernAgentTransportCallResult<Value>> {
    let current = await this.currentOperation(active.operation_id);
    const serializedResponse = canonicalJson(response);
    if (current.operation.status !== "response_attested") {
      const attested = await this.store.attestHostResponse(
        current.payload_checksum,
        current.operation.operation_id,
        current.operation.record_version,
        { content: serializedResponse, received_at: this.clock.now() },
      );
      current = { payload_checksum: attested.payload.checksum, operation: attested.operation };
    }
    const attestation = current.operation.attempts
      .find((item) => item.attempt_id === active.attempt_id)
      ?.response_attestations.at(-1);
    if (attestation === undefined)
      throw new TypeError("Tavern Agent response attestation disappeared");
    const staleError = active.invalidated_error_code ?? "SOURCE_REVISION_STALE";
    if (active.invalidated_error_code !== undefined || !(await request.is_source_current())) {
      return this.reject(current, attestation.attestation_id, staleError);
    }
    if (response.kind !== "text") {
      return this.reject(current, attestation.attestation_id, "UNEXPECTED_TOOL_CALLS");
    }
    let validation: TavernAgentResponseValidation<Value>;
    try {
      validation = await request.validate(response);
    } catch {
      validation = { accepted: false, error_code: "RESPONSE_VALIDATION_EXCEPTION" };
    }
    if (!validation.accepted) {
      assertErrorCode(validation.error_code);
      return this.reject(current, attestation.attestation_id, validation.error_code);
    }
    if (active.invalidated_error_code !== undefined || !(await request.is_source_current())) {
      return this.reject(current, attestation.attestation_id, staleError);
    }
    const committed = await this.store.commitResponse(
      current.payload_checksum,
      current.operation.operation_id,
      current.operation.record_version,
      attestation.attestation_id,
      this.clock.now(),
    );
    return { status: "COMMITTED", operation: committed.operation, value: validation.value };
  }

  private async reject(
    current: {
      readonly payload_checksum: string;
      readonly operation: AgentTransportOperationRecord;
    },
    attestationId: string,
    errorCode: string,
  ): Promise<TavernAgentTransportCallResult<never>> {
    assertErrorCode(errorCode);
    const rejected = await this.store.rejectResponse(
      current.payload_checksum,
      current.operation.operation_id,
      current.operation.record_version,
      attestationId,
      errorCode,
      this.clock.now(),
    );
    return { status: "REJECTED", operation: rejected.operation, error_code: errorCode };
  }

  private async currentOperation(operationId: string): Promise<{
    readonly payload_checksum: string;
    readonly operation: AgentTransportOperationRecord;
  }> {
    const payload = await this.store.read();
    const operation = payload?.operations.find((item) => item.operation_id === operationId);
    if (payload === null || payload === undefined || operation === undefined) {
      throw new TypeError("Tavern Agent transport operation does not exist");
    }
    return { payload_checksum: payload.checksum, operation };
  }
}
