import type { SillyTavernChatMessage, TavernObserverCycleReport } from "@narramem/tavern-adapter";

export const PRESERVED_LATEST_AI_FLOORS = 4 as const;
export const NARRAMEM_AUTO_HIDDEN_FIELD = "narramem_auto_hidden" as const;

interface MutableChatMessage {
  is_system?: boolean;
  extra?: Record<string, unknown>;
}

export interface NarraMemFloorVisibilityPlan {
  readonly covered_message_count: number;
  readonly hide_through_message_id: number | null;
  readonly protected_ai_message_ids: readonly number[];
  readonly unhide_ai_message_ids: readonly number[];
}

function completedCoverageMessageCount(
  report: TavernObserverCycleReport,
  totalMessageCount: number,
): number | null {
  if (report.status !== "EXTRACTION_FINISHED") return null;
  const extraction = report.extraction;
  if (!("audit" in extraction)) return null;
  const lifecycleStatus = report.lifecycle?.status;
  const extractionCompleteWithoutLifecycle =
    report.lifecycle === undefined &&
    (extraction.status === "COMMITTED" || extraction.status === "ALREADY_CURRENT");
  const lifecycleComplete =
    lifecycleStatus === "COMMITTED" || lifecycleStatus === "ALREADY_CURRENT";
  if (!extractionCompleteWithoutLifecycle && !lifecycleComplete) return null;
  if (extraction.status === "COMMITTED" && extraction.incremental_backlog !== undefined) {
    return extraction.incremental_backlog.semantic_covered_message_count_after;
  }
  return totalMessageCount;
}

function isAiFloor(message: SillyTavernChatMessage): boolean {
  return (
    message.is_user !== true &&
    (message.is_system !== true || message.extra?.[NARRAMEM_AUTO_HIDDEN_FIELD] === true)
  );
}

export function planFloorVisibility(
  report: TavernObserverCycleReport,
  chat: readonly SillyTavernChatMessage[],
): NarraMemFloorVisibilityPlan | null {
  const coveredMessageCount = completedCoverageMessageCount(report, chat.length);
  if (coveredMessageCount === null || coveredMessageCount <= 0 || chat.length === 0) return null;

  const aiMessageIds = chat
    .map((message, index) => (isAiFloor(message) ? index : -1))
    .filter((index) => index >= 0);
  if (aiMessageIds.length < PRESERVED_LATEST_AI_FLOORS) {
    return {
      covered_message_count: coveredMessageCount,
      hide_through_message_id: null,
      protected_ai_message_ids: aiMessageIds,
      unhide_ai_message_ids: aiMessageIds.filter(
        (index) => chat[index]?.extra?.[NARRAMEM_AUTO_HIDDEN_FIELD] === true,
      ),
    };
  }

  const protectedAiMessageIds = aiMessageIds.slice(-PRESERVED_LATEST_AI_FLOORS);
  const protectedWindowStart = protectedAiMessageIds[0] ?? 0;
  const hideThrough = Math.min(coveredMessageCount - 1, protectedWindowStart - 1, chat.length - 1);
  return {
    covered_message_count: coveredMessageCount,
    hide_through_message_id: hideThrough >= 0 ? hideThrough : null,
    protected_ai_message_ids: protectedAiMessageIds,
    unhide_ai_message_ids: protectedAiMessageIds.filter(
      (index) => chat[index]?.extra?.[NARRAMEM_AUTO_HIDDEN_FIELD] === true,
    ),
  };
}

function mutable(message: SillyTavernChatMessage): MutableChatMessage {
  return message as MutableChatMessage;
}

function markAutoHidden(message: SillyTavernChatMessage): void {
  const target = mutable(message);
  target.extra ??= {};
  target.extra[NARRAMEM_AUTO_HIDDEN_FIELD] = true;
}

function clearAutoHidden(message: SillyTavernChatMessage): void {
  const target = mutable(message);
  if (target.extra === undefined) return;
  delete target.extra[NARRAMEM_AUTO_HIDDEN_FIELD];
}

export async function applyFloorVisibilityPlan(
  chat: readonly SillyTavernChatMessage[],
  plan: NarraMemFloorVisibilityPlan,
  hideRange: (start: number, end: number, unhide: boolean) => Promise<void>,
): Promise<{ readonly hidden_through: number | null; readonly unhidden_ai_count: number }> {
  if (plan.hide_through_message_id !== null) {
    for (let index = 0; index <= plan.hide_through_message_id; index += 1) {
      const message = chat[index];
      if (message !== undefined && message.is_system !== true) markAutoHidden(message);
    }
    await hideRange(0, plan.hide_through_message_id, false);
  }
  for (const messageId of plan.unhide_ai_message_ids) {
    const message = chat[messageId];
    if (message === undefined) continue;
    clearAutoHidden(message);
    await hideRange(messageId, messageId, true);
  }
  return {
    hidden_through: plan.hide_through_message_id,
    unhidden_ai_count: plan.unhide_ai_message_ids.length,
  };
}
