import {
  type TavernHostPort,
  TavernMemoryRegistry,
  TavernWorldbookSnapshotStore,
} from "@narramem/tavern-adapter";

import type { NarraMemBetaSettings } from "./memory-api-settings.js";

export const NARRAMEM_BETA_EXPORT_VERSION = "0.1.0" as const;

export interface NarraMemDiagnosticExportEntry {
  readonly at: string;
  readonly type: string;
  readonly detail: Readonly<Record<string, unknown>>;
}

export interface NarraMemCoreDataExport {
  readonly format: "narramem.tavern-beta-export";
  readonly export_version: typeof NARRAMEM_BETA_EXPORT_VERSION;
  readonly exported_at: string;
  readonly privacy: {
    readonly may_include_chat_content: true;
    readonly may_include_character_and_chat_identifiers: true;
    readonly api_configuration_included: false;
    readonly api_key_included: false;
    readonly credential_value_included: false;
  };
  readonly settings: ReturnType<typeof safeSettingsForExport>;
  readonly runtime_state: Readonly<Record<string, unknown>>;
  readonly diagnostics: readonly NarraMemDiagnosticExportEntry[];
  readonly memory: {
    readonly resolution: unknown;
    readonly control: unknown | null;
    readonly records: readonly unknown[];
  };
}

export function safeSettingsForExport(
  settings: NarraMemBetaSettings,
): Readonly<
  Pick<
    NarraMemBetaSettings,
    | "schema_version"
    | "enabled"
    | "narrative_content_tag"
    | "assistant_prefill_enabled"
    | "timeout_ms"
    | "min_interval_ms"
    | "max_requests_per_minute"
    | "concurrency"
    | "retry_count"
  >
> {
  return {
    schema_version: settings.schema_version,
    enabled: settings.enabled,
    narrative_content_tag: settings.narrative_content_tag,
    assistant_prefill_enabled: settings.assistant_prefill_enabled,
    timeout_ms: settings.timeout_ms,
    min_interval_ms: settings.min_interval_ms,
    max_requests_per_minute: settings.max_requests_per_minute,
    concurrency: settings.concurrency,
    retry_count: settings.retry_count,
  };
}

export async function collectNarraMemCoreDataExport(input: {
  readonly port: TavernHostPort;
  readonly settings: NarraMemBetaSettings;
  readonly runtime_state: Readonly<Record<string, unknown>>;
  readonly diagnostics: readonly NarraMemDiagnosticExportEntry[];
  readonly now_iso?: string;
}): Promise<NarraMemCoreDataExport> {
  const registry = new TavernMemoryRegistry(input.port);
  const resolution = await registry.resolveCurrentMemorySet();
  const selected = resolution.selected;
  let control: unknown | null = null;
  let records: readonly unknown[] = [];
  if (selected !== null) {
    const memorySetId = selected.control.memory_set_id;
    const store = new TavernWorldbookSnapshotStore(input.port, {
      memory_set_id: memorySetId,
      control_book_name: selected.control_book_name,
      segment_book_prefix: `NarraMem__ARCHIVE__${memorySetId}__`,
      initial_identity_anchor: selected.control.identity_anchor,
      max_records_per_segment: 64,
      max_segment_utf8_bytes: 350_000,
    });
    control = await store.readControl();
    records = await store.readActiveSnapshot();
  }
  return {
    format: "narramem.tavern-beta-export",
    export_version: NARRAMEM_BETA_EXPORT_VERSION,
    exported_at: input.now_iso ?? new Date().toISOString(),
    privacy: {
      may_include_chat_content: true,
      may_include_character_and_chat_identifiers: true,
      api_configuration_included: false,
      api_key_included: false,
      credential_value_included: false,
    },
    settings: safeSettingsForExport(input.settings),
    runtime_state: input.runtime_state,
    diagnostics: [...input.diagnostics],
    memory: { resolution, control, records },
  };
}

export function downloadJson(filename: string, value: unknown): void {
  const blob = new Blob([JSON.stringify(value, null, 2)], {
    type: "application/json;charset=utf-8",
  });
  const url = URL.createObjectURL(blob);
  try {
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
  } finally {
    URL.revokeObjectURL(url);
  }
}
