import {
  type AgentControlEnvelope,
  type HashDigest,
  INVESTIGATION_TRANSCRIPT_VERSION,
  type InvestigationAction,
  type InvestigationRuntimeLimits,
  type InvestigationStopReason,
  type InvestigationTranscript,
  isHashDigest,
  type JsonValue,
  type NarraMemId,
} from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

type ReadonlyToolAction = Exclude<InvestigationAction, { readonly tool: "stop" }>;

export interface InvestigationSnapshotIdentity {
  readonly revision_id: NarraMemId<"source_revision">;
  readonly fingerprint: HashDigest;
}

export interface InvestigationToolExecution {
  readonly result: JsonValue;
  readonly returned_record_refs: readonly NarraMemId[];
  readonly returned_evidence_refs: readonly NarraMemId<"evidence">[];
}

export interface InvestigationToolExecutionContext {
  readonly investigation_id: NarraMemId<"investigation">;
  readonly step: number;
  readonly snapshot: InvestigationSnapshotIdentity;
  readonly limits: InvestigationRuntimeLimits;
  readonly signal?: AbortSignal;
}

export interface InvestigationRuntimePorts {
  readonly execute_readonly_tool: (
    action: ReadonlyToolAction,
    context: InvestigationToolExecutionContext,
  ) => Promise<InvestigationToolExecution>;
  readonly hash_text: (text: string) => Promise<HashDigest>;
}

export interface InvestigationTranscriptSeed {
  readonly investigation_id: NarraMemId<"investigation">;
  readonly control: AgentControlEnvelope;
  readonly snapshot_fingerprint: HashDigest;
  readonly limits: InvestigationRuntimeLimits;
}

export interface InvestigationRuntimeIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export type InvestigationStepResult =
  | {
      readonly status: "advanced" | "stopped";
      readonly transcript: InvestigationTranscript;
      readonly issues: readonly [];
    }
  | {
      readonly status: "rejected";
      readonly transcript: InvestigationTranscript;
      readonly issues: readonly InvestigationRuntimeIssue[];
    };

export class InvestigationToolExecutionError extends Error {
  constructor(
    readonly code: string,
    message = code,
  ) {
    super(message);
    this.name = "InvestigationToolExecutionError";
  }
}

function issue(code: string, path: string, message: string): InvestigationRuntimeIssue {
  return { code, path, message };
}

export function canonicalInvestigationJson(value: JsonValue): string {
  if (value === null || typeof value !== "object") {
    if (typeof value === "number" && !Number.isFinite(value)) {
      throw new TypeError("Investigation JSON cannot contain non-finite numbers");
    }
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalInvestigationJson).join(",")}]`;
  }
  return `{${Object.entries(value)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(
      ([key, nested]) =>
        `${JSON.stringify(key)}:${canonicalInvestigationJson(nested as JsonValue)}`,
    )
    .join(",")}}`;
}

function sameHash(left: HashDigest, right: HashDigest): boolean {
  return left.algorithm === right.algorithm && left.value === right.value;
}

function distinct<T extends string>(values: readonly T[]): T[] {
  return [...new Set(values)].sort();
}

function safeErrorCode(error: unknown): string {
  if (error instanceof InvestigationToolExecutionError && /^[A-Z0-9_]{1,128}$/u.test(error.code)) {
    return error.code;
  }
  return "INVESTIGATION_TOOL_EXECUTION_FAILED";
}

function stoppedTranscript(
  transcript: InvestigationTranscript,
  reason: InvestigationStopReason,
): InvestigationTranscript {
  return { ...transcript, status: "stopped", stop_reason: reason };
}

function toolStepCount(transcript: InvestigationTranscript): number {
  return transcript.steps.filter((step) => step.kind === "tool").length;
}

function automaticStopReason(
  transcript: InvestigationTranscript,
): InvestigationStopReason | undefined {
  const lastStep = transcript.steps.at(-1);
  if (
    lastStep?.kind === "stop" ||
    (lastStep?.kind === "tool" && lastStep.observation.status === "error")
  ) {
    return undefined;
  }
  if (transcript.steps.length >= transcript.control.max_steps) return "step_budget_exhausted";
  if (toolStepCount(transcript) >= transcript.limits.max_tool_calls) {
    return "tool_budget_exhausted";
  }
  return undefined;
}

export function createInvestigationTranscript(
  seed: InvestigationTranscriptSeed,
): InvestigationTranscript {
  const transcript: InvestigationTranscript = {
    transcript_version: INVESTIGATION_TRANSCRIPT_VERSION,
    delivery: "executor_private_replay_log",
    investigation_id: seed.investigation_id,
    control: seed.control,
    snapshot_fingerprint: seed.snapshot_fingerprint,
    limits: seed.limits,
    steps: [],
    status:
      seed.limits.max_tool_calls === 0
        ? "stopped"
        : seed.control.max_steps > 0
          ? "investigating"
          : "stopped",
    ...(seed.limits.max_tool_calls === 0 ? { stop_reason: "tool_budget_exhausted" as const } : {}),
  };
  const wire = validateWireValue("investigation_transcript", transcript);
  if (!wire.valid) {
    const first = wire.errors[0];
    throw new TypeError(
      `Invalid Investigation transcript seed at ${first?.instancePath || "/"}: ${first?.message ?? "invalid"}`,
    );
  }
  if (!isHashDigest(seed.snapshot_fingerprint)) {
    throw new TypeError("Investigation snapshot fingerprint must be a SHA-256 digest");
  }
  if (seed.control.snapshot_revision_id === undefined) {
    throw new TypeError("Investigation control requires a frozen source revision");
  }
  return transcript;
}

export async function verifyInvestigationTranscript(
  value: unknown,
  hashText: (text: string) => Promise<HashDigest>,
): Promise<readonly InvestigationRuntimeIssue[]> {
  const wire = validateWireValue("investigation_transcript", value);
  if (!wire.valid) {
    return wire.errors.map((error) =>
      issue(
        "INVESTIGATION_TRANSCRIPT_SCHEMA_INVALID",
        error.instancePath || "/",
        error.message ?? "invalid",
      ),
    );
  }
  const transcript = value as InvestigationTranscript;
  const issues: InvestigationRuntimeIssue[] = [];
  const allowedTools = new Set(transcript.control.allowed_tools);
  let observedToolSteps = 0;
  for (const [index, step] of transcript.steps.entries()) {
    if (step.step !== index) {
      issues.push(
        issue(
          "INVESTIGATION_STEP_SEQUENCE_INVALID",
          `/steps/${index}/step`,
          "Transcript steps must be contiguous and zero-based",
        ),
      );
    }
    if (step.kind === "stop") {
      if (index !== transcript.steps.length - 1) {
        issues.push(
          issue(
            "INVESTIGATION_STOP_NOT_FINAL",
            `/steps/${index}`,
            "An Agent stop action must be the final transcript step",
          ),
        );
      }
      continue;
    }
    observedToolSteps += 1;
    if (!allowedTools.has(step.action.tool)) {
      issues.push(
        issue(
          "INVESTIGATION_TOOL_NOT_ALLOWED",
          `/steps/${index}/action/tool`,
          "Transcript contains a tool outside trusted control",
        ),
      );
    }
    if (
      step.action.tool === "follow_causal_links" &&
      step.action.max_depth > transcript.limits.max_causal_depth
    ) {
      issues.push(
        issue(
          "INVESTIGATION_CAUSAL_DEPTH_EXCEEDED",
          `/steps/${index}/action/max_depth`,
          "Causal traversal exceeds the frozen runtime limit",
        ),
      );
    }
    const observation = step.observation;
    if (
      observation.investigation_id !== transcript.investigation_id ||
      observation.step !== index ||
      observation.snapshot_revision_id !== transcript.control.snapshot_revision_id ||
      observation.tool !== step.action.tool
    ) {
      issues.push(
        issue(
          "INVESTIGATION_OBSERVATION_BINDING_INVALID",
          `/steps/${index}/observation`,
          "Tool observation is not bound to its transcript action and snapshot",
        ),
      );
    }
    if (observation.status === "error") {
      if (index !== transcript.steps.length - 1 || transcript.stop_reason !== "tool_error") {
        issues.push(
          issue(
            "INVESTIGATION_TOOL_ERROR_NOT_TERMINAL",
            `/steps/${index}/observation`,
            "A tool execution error must terminate the transcript",
          ),
        );
      }
      continue;
    }
    if (
      observation.returned_record_refs.length > transcript.limits.max_record_refs_per_result ||
      observation.returned_evidence_refs.length > transcript.limits.max_evidence_refs_per_result
    ) {
      issues.push(
        issue(
          "INVESTIGATION_RESULT_REF_LIMIT_EXCEEDED",
          `/steps/${index}/observation`,
          "Tool observation exceeds its frozen record or Evidence limit",
        ),
      );
    }
    const serialized = canonicalInvestigationJson(observation.result);
    if (new TextEncoder().encode(serialized).byteLength > transcript.limits.max_result_utf8_bytes) {
      issues.push(
        issue(
          "INVESTIGATION_RESULT_BYTES_EXCEEDED",
          `/steps/${index}/observation/result`,
          "Tool observation exceeds its frozen UTF-8 byte limit",
        ),
      );
    }
    const recomputed = await hashText(serialized);
    if (!isHashDigest(recomputed) || !sameHash(recomputed, observation.result_sha256)) {
      issues.push(
        issue(
          "INVESTIGATION_RESULT_HASH_MISMATCH",
          `/steps/${index}/observation/result_sha256`,
          "Tool observation payload does not match its content hash",
        ),
      );
    }
  }
  if (transcript.steps.length > transcript.control.max_steps) {
    issues.push(
      issue(
        "INVESTIGATION_STEP_LIMIT_EXCEEDED",
        "/steps",
        "Transcript contains more steps than trusted control permits",
      ),
    );
  }
  if (observedToolSteps > transcript.limits.max_tool_calls) {
    issues.push(
      issue(
        "INVESTIGATION_TOOL_LIMIT_EXCEEDED",
        "/steps",
        "Transcript contains more tool calls than the frozen budget permits",
      ),
    );
  }
  const lastStep = transcript.steps.at(-1);
  if (transcript.status === "investigating") {
    if (transcript.stop_reason !== undefined || automaticStopReason(transcript) !== undefined) {
      issues.push(
        issue(
          "INVESTIGATION_ACTIVE_STATUS_INVALID",
          "/status",
          "An investigating transcript cannot carry a stop reason or exhausted budget",
        ),
      );
    }
  } else if (transcript.stop_reason === undefined) {
    issues.push(
      issue(
        "INVESTIGATION_STOP_REASON_MISSING",
        "/stop_reason",
        "A stopped transcript requires an explicit reason",
      ),
    );
  } else if (
    lastStep?.kind === "stop" &&
    (transcript.stop_reason !== lastStep.action.reason || transcript.status !== "stopped")
  ) {
    issues.push(
      issue(
        "INVESTIGATION_AGENT_STOP_MISMATCH",
        "/stop_reason",
        "Agent stop action and transcript stop reason must match",
      ),
    );
  } else {
    const exhausted = automaticStopReason(transcript);
    if (exhausted !== undefined && transcript.stop_reason !== exhausted) {
      issues.push(
        issue(
          "INVESTIGATION_BUDGET_STOP_MISMATCH",
          "/stop_reason",
          "Exhausted transcript must carry the deterministic budget stop reason",
        ),
      );
    }
    if (
      (transcript.stop_reason === "sufficient_evidence" ||
        transcript.stop_reason === "no_progress") &&
      lastStep?.kind !== "stop"
    ) {
      issues.push(
        issue(
          "INVESTIGATION_AGENT_STOP_STEP_MISSING",
          "/steps",
          "Agent-requested stop reason requires a final stop action",
        ),
      );
    }
  }
  return issues;
}

export async function executeInvestigationStep(
  transcript: InvestigationTranscript,
  actionValue: unknown,
  currentSnapshot: InvestigationSnapshotIdentity,
  ports: InvestigationRuntimePorts,
  signal?: AbortSignal,
): Promise<InvestigationStepResult> {
  const existingIssues = await verifyInvestigationTranscript(transcript, ports.hash_text);
  if (existingIssues.length > 0) {
    return { status: "rejected", transcript, issues: existingIssues };
  }
  if (transcript.status !== "investigating") {
    return {
      status: "rejected",
      transcript,
      issues: [
        issue(
          "INVESTIGATION_ALREADY_STOPPED",
          "/status",
          "Stopped transcript cannot execute actions",
        ),
      ],
    };
  }
  if (
    currentSnapshot.revision_id !== transcript.control.snapshot_revision_id ||
    !sameHash(currentSnapshot.fingerprint, transcript.snapshot_fingerprint)
  ) {
    return {
      status: "stopped",
      transcript: stoppedTranscript(transcript, "snapshot_stale"),
      issues: [],
    };
  }
  if (signal?.aborted) {
    return {
      status: "stopped",
      transcript: stoppedTranscript(transcript, "cancelled"),
      issues: [],
    };
  }
  const actionWire = validateWireValue("investigation_action", actionValue);
  if (!actionWire.valid) {
    return {
      status: "rejected",
      transcript,
      issues: actionWire.errors.map((error) =>
        issue(
          "INVESTIGATION_ACTION_SCHEMA_INVALID",
          error.instancePath || "/",
          error.message ?? "invalid",
        ),
      ),
    };
  }
  const action = actionValue as InvestigationAction;
  const preexistingStop = automaticStopReason(transcript);
  if (preexistingStop !== undefined) {
    return {
      status: "stopped",
      transcript: stoppedTranscript(transcript, preexistingStop),
      issues: [],
    };
  }
  const stepIndex = transcript.steps.length;
  if (action.tool === "stop") {
    const next: InvestigationTranscript = {
      ...transcript,
      steps: [...transcript.steps, { kind: "stop", step: stepIndex, action }],
      status: "stopped",
      stop_reason: action.reason,
    };
    return { status: "stopped", transcript: next, issues: [] };
  }
  if (!transcript.control.allowed_tools.includes(action.tool)) {
    return {
      status: "rejected",
      transcript,
      issues: [
        issue(
          "INVESTIGATION_TOOL_NOT_ALLOWED",
          "/tool",
          "Requested tool is outside trusted control",
        ),
      ],
    };
  }
  if (
    action.tool === "follow_causal_links" &&
    action.max_depth > transcript.limits.max_causal_depth
  ) {
    return {
      status: "rejected",
      transcript,
      issues: [
        issue(
          "INVESTIGATION_CAUSAL_DEPTH_EXCEEDED",
          "/max_depth",
          "Requested causal depth exceeds the frozen runtime limit",
        ),
      ],
    };
  }

  let execution: InvestigationToolExecution;
  try {
    execution = await ports.execute_readonly_tool(action, {
      investigation_id: transcript.investigation_id,
      step: stepIndex,
      snapshot: currentSnapshot,
      limits: transcript.limits,
      ...(signal === undefined ? {} : { signal }),
    });
    if (signal?.aborted) {
      return {
        status: "stopped",
        transcript: stoppedTranscript(transcript, "cancelled"),
        issues: [],
      };
    }
    const recordRefs = distinct(execution.returned_record_refs);
    const evidenceRefs = distinct(execution.returned_evidence_refs);
    const serialized = canonicalInvestigationJson(execution.result);
    if (
      recordRefs.length !== execution.returned_record_refs.length ||
      evidenceRefs.length !== execution.returned_evidence_refs.length ||
      recordRefs.length > transcript.limits.max_record_refs_per_result ||
      evidenceRefs.length > transcript.limits.max_evidence_refs_per_result ||
      new TextEncoder().encode(serialized).byteLength > transcript.limits.max_result_utf8_bytes
    ) {
      throw new InvestigationToolExecutionError("INVESTIGATION_TOOL_RESULT_INVALID");
    }
    const resultHash = await ports.hash_text(serialized);
    if (!isHashDigest(resultHash)) {
      throw new InvestigationToolExecutionError("INVESTIGATION_TOOL_HASH_INVALID");
    }
    const nextBase: InvestigationTranscript = {
      ...transcript,
      steps: [
        ...transcript.steps,
        {
          kind: "tool",
          step: stepIndex,
          action,
          observation: {
            observation_version: INVESTIGATION_TRANSCRIPT_VERSION,
            trust_boundary: "untrusted_tool_result",
            investigation_id: transcript.investigation_id,
            step: stepIndex,
            snapshot_revision_id: transcript.control.snapshot_revision_id,
            tool: action.tool,
            status: "ok",
            returned_record_refs: recordRefs,
            returned_evidence_refs: evidenceRefs,
            result: execution.result,
            result_sha256: resultHash,
            persistent_state_unchanged: true,
          },
        },
      ],
    };
    const exhausted = automaticStopReason(nextBase);
    const next = exhausted === undefined ? nextBase : stoppedTranscript(nextBase, exhausted);
    const nextIssues = await verifyInvestigationTranscript(next, ports.hash_text);
    if (nextIssues.length > 0) {
      throw new InvestigationToolExecutionError("INVESTIGATION_TOOL_RESULT_INVALID");
    }
    return {
      status: next.status === "stopped" ? "stopped" : "advanced",
      transcript: next,
      issues: [],
    };
  } catch (error) {
    const next: InvestigationTranscript = {
      ...transcript,
      steps: [
        ...transcript.steps,
        {
          kind: "tool",
          step: stepIndex,
          action,
          observation: {
            observation_version: INVESTIGATION_TRANSCRIPT_VERSION,
            trust_boundary: "untrusted_tool_result",
            investigation_id: transcript.investigation_id,
            step: stepIndex,
            snapshot_revision_id: transcript.control.snapshot_revision_id,
            tool: action.tool,
            status: "error",
            error_code: safeErrorCode(error),
            returned_record_refs: [],
            returned_evidence_refs: [],
            persistent_state_unchanged: true,
          },
        },
      ],
      status: "stopped",
      stop_reason: "tool_error",
    };
    const nextIssues = await verifyInvestigationTranscript(next, ports.hash_text);
    return nextIssues.length === 0
      ? { status: "stopped", transcript: next, issues: [] }
      : { status: "rejected", transcript, issues: nextIssues };
  }
}
