const WORKER_ID = "narramem-tavern-manual-audit-v1";
const AUTHORIZATION_LIFETIME_MS = 30_000;
const SEGMENT_LIMITS = {
  max_records_per_segment: 64,
  max_segment_utf8_bytes: 350_000,
} as const;
const TASK_BUDGET = {
  max_attempts: 1,
  max_model_calls: 4,
  max_tool_calls: 3,
  max_input_tokens: 100_000,
  lease_duration_ms: 1_800_000,
} as const;

interface MemoryState {
  readonly memory_set_id: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly semantic_task_fingerprint: string;
  readonly seeds: Awaited<ReturnType<typeof projectTavernCausalAuditTaskSeeds>>;
  readonly archive_records: readonly TavernArchiveRecord[];
  readonly control_checksum: string;
  readonly control_commit_sequence: number;
  readonly active_view_id: string;
}

interface PreparedAuthorization {
  readonly authorization_token: string;
  readonly authorized_at: string;
  readonly memory: MemoryState;
  readonly task_store_checksum: string;
  readonly task_seed_id: string;
}

