export interface CausalAuditAgentTaskSeed {
  readonly task_id: string;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly finding: CausalAuditAgentFindingControl;
  readonly seed_context: JsonValue;
  readonly seed_record_refs: readonly NarraMemId[];
  readonly seed_evidence_refs: readonly NarraMemId<"evidence">[];
}

export interface CausalAuditAgentFinalAllowlists {
  readonly allowed_cause_refs: readonly CausalAuditCandidateCauseRef[];
  readonly allowed_effect_refs: readonly CausalAuditCandidateEffectRef[];
  readonly allowed_holder_entity_ids: readonly NarraMemId<"entity">[];
}

export interface CausalAuditFinalOptionSource {
  readonly evidence_quotes: readonly CandidateEvidenceQuote[];
  readonly candidate_context: CausalAuditCandidateValidationContext;
}

function distinctSorted<T extends string>(values: readonly T[]): T[] {
  return [...new Set(values)].sort();
}

function endpointId(
  reference: CausalAuditCandidateCauseRef | CausalAuditCandidateEffectRef,
): NarraMemId {
  switch (reference.kind) {
    case "event":
      return reference.event_id;
    case "state_assertion":
      return reference.assertion_id;
    case "state_delta":
      return reference.delta_id;
    case "epistemic_state":
      return reference.epistemic_id;
    case "proposition":
      return reference.proposition_id;
    case "narrative_thread":
      return reference.thread_id;
  }
}

function assertTaskBinding(
  task: CausalAuditAgentTaskSeed,
  transcript: InvestigationTranscript,
): void {
  if (
    task.task_id !== transcript.investigation_id ||
    task.source_revision_id !== transcript.control.snapshot_revision_id
  ) {
    throw new TypeError("Causal Audit Agent task does not match the verified investigation");
  }
  if (!task.seed_evidence_refs.includes(task.finding.evidence_id)) {
    throw new TypeError("Causal Audit Agent seed must include the finding Evidence");
  }
}

async function verifyTranscript(
  transcript: InvestigationTranscript,
  ports: Pick<InvestigationRuntimePorts, "hash_text">,
): Promise<void> {
  const issues = await verifyInvestigationTranscript(transcript, ports.hash_text);
  if (issues.length > 0) {
    throw new TypeError(`Invalid Causal Audit Agent transcript: ${issues[0]?.code}`);
  }
}

function toolObservations(transcript: InvestigationTranscript) {
  return transcript.steps.flatMap((step) => (step.kind === "tool" ? [step.observation] : []));
}

export function deriveCausalAuditAgentBudgetControlV020(
  transcript: InvestigationTranscript,
): CausalAuditAgentBudgetControlV020 {
  const usedToolCalls = transcript.steps.filter((step) => step.kind === "tool").length;
  return {
    max_action_calls: transcript.control.max_steps,
    used_action_calls: transcript.steps.length,
    remaining_action_calls: Math.max(0, transcript.control.max_steps - transcript.steps.length),
    max_tool_calls: transcript.limits.max_tool_calls,
    used_tool_calls: usedToolCalls,
    remaining_tool_calls: Math.max(0, transcript.limits.max_tool_calls - usedToolCalls),
    final_decision_call_limit: 1,
  };
}

export function deriveCausalAuditFinalHandoff(
  transcript: InvestigationTranscript,
): CausalAuditFinalHandoff {
  if (transcript.status !== "stopped" || transcript.stop_reason === undefined) {
    throw new TypeError("Causal Audit final handoff requires a stopped investigation");
  }
  if (transcript.stop_reason === "sufficient_evidence") {
    return {
      kind: "model_declared_sufficient",
      execution_stop_reason: transcript.stop_reason,
    };
  }
  if (transcript.stop_reason === "no_progress") {
    return {
      kind: "model_declared_no_progress",
      execution_stop_reason: transcript.stop_reason,
    };
  }
  const lastStep = transcript.steps.at(-1);
  if (
    (transcript.stop_reason === "step_budget_exhausted" ||
      transcript.stop_reason === "tool_budget_exhausted") &&
    lastStep?.kind === "tool" &&
    lastStep.observation.status === "ok"
  ) {
    return {
      kind: "investigation_window_complete",
      execution_stop_reason: transcript.stop_reason,
    };
  }
  return { kind: "runtime_failure", execution_stop_reason: transcript.stop_reason };
}

function assertInput(input: CausalAuditAgentTurnInput): CausalAuditAgentTurnInput {
  const wire = validateWireValue("causal_audit_agent_turn_input", input);
  if (!wire.valid) {
    const first = wire.errors[0];
    throw new TypeError(
      `Invalid Causal Audit Agent turn input at ${first?.instancePath || "/"}: ${first?.message ?? "invalid"}`,
    );
  }
  return input;
}

