function createActionOptions(
  transcript: InvestigationTranscript,
  candidateActions: readonly InvestigationAction[],
): readonly CausalAuditActionOption[] {
  if (candidateActions.length === 0 || candidateActions.length > 64) {
    throw new TypeError("Causal Audit action option catalog must contain between 1 and 64 actions");
  }
  const canonicalActions = candidateActions.map((action) => {
    const wire = validateWireValue("investigation_action", action);
    if (!wire.valid) {
      throw new TypeError("Causal Audit action option contains an invalid canonical action");
    }
    if (action.tool !== "stop" && !transcript.control.allowed_tools.includes(action.tool)) {
      throw new TypeError("Causal Audit action option contains a tool outside trusted control");
    }
    if (
      action.tool === "follow_causal_links" &&
      action.max_depth > transcript.limits.max_causal_depth
    ) {
      throw new TypeError("Causal Audit action option exceeds the trusted causal-depth limit");
    }
    return {
      action,
      canonical: canonicalInvestigationJson(action as unknown as JsonValue),
    };
  });
  if (new Set(canonicalActions.map((item) => item.canonical)).size !== canonicalActions.length) {
    throw new TypeError("Causal Audit action option catalog contains duplicate canonical actions");
  }
  return canonicalActions
    .sort((left, right) => left.canonical.localeCompare(right.canonical))
    .map((item, index) => ({
      option_id: `action_${String(index + 1).padStart(3, "0")}`,
      action: item.action,
    }));
}

export type FlatInvestigationActionTranslation =
  | {
      readonly accepted: true;
      readonly draft: FlatInvestigationActionDraft;
      readonly action: InvestigationAction;
      readonly issues: readonly [];
    }
  | {
      readonly accepted: false;
      readonly issues: readonly {
        readonly code: string;
        readonly path: string;
        readonly message: string;
      }[];
    };

export function translateFlatInvestigationActionDraft(
  value: unknown,
  actionOptions: readonly CausalAuditActionOption[],
): FlatInvestigationActionTranslation {
  const wire = validateWireValue("flat_investigation_action_draft", value);
  if (!wire.valid) {
    return {
      accepted: false,
      issues: wire.errors.map((error) => ({
        code: "FLAT_INVESTIGATION_ACTION_DRAFT_SCHEMA_INVALID",
        path: error.instancePath || "/",
        message: error.message ?? "invalid",
      })),
    };
  }
  const draft = value as FlatInvestigationActionDraft;
  const matches = actionOptions.filter((option) => option.option_id === draft.option_id);
  const [match] = matches;
  if (matches.length !== 1 || match === undefined) {
    return {
      accepted: false,
      issues: [
        {
          code: "FLAT_INVESTIGATION_ACTION_OPTION_NOT_ALLOWED",
          path: "/option_id",
          message: "Flat action draft must select exactly one trusted action option",
        },
      ],
    };
  }
  return { accepted: true, draft, action: match.action, issues: [] };
}

export async function createCausalAuditAgentActionInput(
  task: CausalAuditAgentTaskSeed,
  transcript: InvestigationTranscript,
  ports: Pick<InvestigationRuntimePorts, "hash_text">,
): Promise<Extract<CausalAuditAgentTurnInput, { readonly phase: "investigation_action" }>> {
  await verifyTranscript(transcript, ports);
  assertTaskBinding(task, transcript);
  if (transcript.status !== "investigating") {
    throw new TypeError("Only an investigating transcript can request another Agent action");
  }
  const usedToolCalls = transcript.steps.filter((step) => step.kind === "tool").length;
  const remainingToolCalls = Math.max(0, transcript.limits.max_tool_calls - usedToolCalls);
  if (remainingToolCalls === 0) {
    throw new TypeError("Causal Audit Agent action input has no remaining tool budget");
  }
  const input: Extract<CausalAuditAgentTurnInput, { readonly phase: "investigation_action" }> = {
    input_version: CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION,
    phase: "investigation_action",
    control: {
      trust_boundary: "trusted_control",
      task_id: task.task_id,
      source_revision_id: task.source_revision_id,
      finding: task.finding,
      allowed_tools: transcript.control.allowed_tools,
      max_steps: transcript.control.max_steps,
      next_step: transcript.steps.length,
      remaining_tool_calls: remainingToolCalls,
    },
    material: {
      trust_boundary: "untrusted_evidence",
      seed_context: task.seed_context,
      transcript_steps: transcript.steps,
    },
  };
  return assertInput(input) as typeof input;
}

export async function createCausalAuditAgentFinalInput(
  task: CausalAuditAgentTaskSeed,
  transcript: InvestigationTranscript,
  allowlists: CausalAuditAgentFinalAllowlists,
  ports: Pick<InvestigationRuntimePorts, "hash_text">,
): Promise<Extract<CausalAuditAgentTurnInput, { readonly phase: "final_decision" }>> {
  await verifyTranscript(transcript, ports);
  assertTaskBinding(task, transcript);
  if (transcript.status !== "stopped" || transcript.stop_reason === undefined) {
    throw new TypeError("Causal Audit Agent final input requires a stopped investigation");
  }
  if (transcript.stop_reason === "snapshot_stale" || transcript.stop_reason === "cancelled") {
    throw new TypeError("A stale or cancelled investigation cannot request a model final decision");
  }
  const observations = toolObservations(transcript);
  const reviewedRecordRefs = distinctSorted([
    ...task.seed_record_refs,
    ...observations.flatMap((observation) => observation.returned_record_refs),
  ]);
  const reviewedEvidenceRefs = distinctSorted([
    ...task.seed_evidence_refs,
    ...observations.flatMap((observation) => observation.returned_evidence_refs),
  ]);
  const reviewed = new Set<NarraMemId>(reviewedRecordRefs);
  for (const endpoint of [...allowlists.allowed_cause_refs, ...allowlists.allowed_effect_refs]) {
    if (!reviewed.has(endpointId(endpoint))) {
      throw new TypeError(
        "Causal Audit final allowlist contains an endpoint not reviewed by the Agent",
      );
    }
  }
  const input: Extract<CausalAuditAgentTurnInput, { readonly phase: "final_decision" }> = {
    input_version: CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION,
    phase: "final_decision",
    control: {
      trust_boundary: "trusted_control",
      task_id: task.task_id,
      source_revision_id: task.source_revision_id,
      finding: task.finding,
      stop_reason: transcript.stop_reason,
      allowed_cause_refs: allowlists.allowed_cause_refs,
      allowed_effect_refs: allowlists.allowed_effect_refs,
      allowed_holder_entity_ids: allowlists.allowed_holder_entity_ids,
      allowed_reviewed_record_refs: reviewedRecordRefs,
      allowed_reviewed_evidence_refs: reviewedEvidenceRefs,
    },
    material: {
      trust_boundary: "untrusted_evidence",
      seed_context: task.seed_context,
      transcript_steps: transcript.steps,
    },
  };
  return assertInput(input) as typeof input;
}

export function renderCausalAuditAgentTurnInput(input: CausalAuditAgentTurnInput): string {
  assertInput(input);
  return canonicalInvestigationJson(input as unknown as JsonValue);
}

