import {
  type EventAtom,
  type FutureImpact,
  getNarraMemIdKind,
  type NarraMemId,
  type NarrativeThread,
  type StateDelta,
} from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

import {
  TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_LEGACY_VERSION,
  TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID,
  TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_KIND,
  TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION,
  type TavernNarrativeLifecycleContinuityBaselinePayload,
  type TavernNarrativeLifecycleContinuityBaselineV020Payload,
} from "./narrative-lifecycle-contracts.js";
import type { TavernArchiveRecord } from "./worldbook-store-contracts.js";

const SHA256_PATTERN = /^[0-9a-f]{64}$/u;

export function readTavernNarrativeLifecycleContinuityBaselineFromArchive(
  records: readonly TavernArchiveRecord[],
): TavernNarrativeLifecycleContinuityBaselinePayload | null {
  const candidates = records.filter(
    (record) => record.record_id === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID,
  );
  if (candidates.length === 0) return null;
  const record = candidates[0];
  const payload = record?.payload;
  const baseKeys = [
    "version",
    "memory_set_id",
    "source_revision_id",
    "source_checksum",
    "narrative_thread_count",
    "future_impact_count",
  ];
  if (
    candidates.length !== 1 ||
    record?.record_kind !== TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_KIND ||
    payload === null ||
    typeof payload !== "object" ||
    Array.isArray(payload) ||
    !baseKeys.every((key) => Object.hasOwn(payload, key))
  ) {
    throw new TypeError("Invalid narrative lifecycle continuity baseline shape");
  }
  const value = payload as Readonly<Record<string, unknown>>;
  if (
    (value.version !== TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_LEGACY_VERSION &&
      value.version !== TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION) ||
    typeof value.memory_set_id !== "string" ||
    value.memory_set_id.length === 0 ||
    getNarraMemIdKind(value.source_revision_id) !== "source_revision" ||
    typeof value.source_checksum !== "string" ||
    !SHA256_PATTERN.test(value.source_checksum) ||
    !Number.isInteger(value.narrative_thread_count) ||
    (value.narrative_thread_count as number) < 0 ||
    !Number.isInteger(value.future_impact_count) ||
    (value.future_impact_count as number) < 0
  ) {
    throw new TypeError("Invalid narrative lifecycle continuity baseline values");
  }
  if (value.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_LEGACY_VERSION) {
    if (Object.keys(value).length !== baseKeys.length) {
      throw new TypeError("Invalid legacy narrative lifecycle continuity baseline shape");
    }
    return value as unknown as TavernNarrativeLifecycleContinuityBaselinePayload;
  }
  const v020Keys = [
    ...baseKeys,
    "previous_source_max_ordinal",
    "narrative_threads",
    "future_impacts",
    "semantic_events",
    "semantic_state_deltas",
  ];
  if (
    Object.keys(value).length !== v020Keys.length ||
    !v020Keys.every((key) => Object.hasOwn(value, key)) ||
    (value.previous_source_max_ordinal !== null &&
      (!Number.isInteger(value.previous_source_max_ordinal) ||
        (value.previous_source_max_ordinal as number) < 0)) ||
    !Array.isArray(value.narrative_threads) ||
    !Array.isArray(value.future_impacts) ||
    !Array.isArray(value.semantic_events) ||
    !Array.isArray(value.semantic_state_deltas) ||
    value.narrative_threads.length !== value.narrative_thread_count ||
    value.future_impacts.length !== value.future_impact_count
  ) {
    throw new TypeError("Invalid narrative lifecycle continuity baseline v0.2 shape");
  }
  const threadIds = new Set<string>();
  for (const candidate of value.narrative_threads) {
    const report = validateWireValue("narrative_thread", candidate);
    const thread = candidate as NarrativeThread;
    if (
      !report.valid ||
      threadIds.has(thread.thread_id) ||
      thread.derivation.input_revision_id !== value.source_revision_id
    ) {
      throw new TypeError("Invalid NarrativeThread in lifecycle continuity baseline");
    }
    threadIds.add(thread.thread_id);
  }
  const impactIds = new Set<string>();
  for (const candidate of value.future_impacts) {
    const report = validateWireValue("future_impact", candidate);
    const impact = candidate as FutureImpact;
    if (
      !report.valid ||
      impactIds.has(impact.impact_id) ||
      impact.derivation.input_revision_id !== value.source_revision_id
    ) {
      throw new TypeError("Invalid FutureImpact in lifecycle continuity baseline");
    }
    impactIds.add(impact.impact_id);
  }
  for (const candidate of value.semantic_events) {
    const report = validateWireValue("event_atom", candidate);
    const event = candidate as EventAtom;
    if (!report.valid || event.derivation.input_revision_id !== value.source_revision_id) {
      throw new TypeError("Invalid EventAtom in lifecycle continuity baseline");
    }
  }
  for (const candidate of value.semantic_state_deltas) {
    const report = validateWireValue("state_delta", candidate);
    const delta = candidate as StateDelta;
    if (!report.valid || delta.derivation.input_revision_id !== value.source_revision_id) {
      throw new TypeError("Invalid StateDelta in lifecycle continuity baseline");
    }
  }
  return value as unknown as TavernNarrativeLifecycleContinuityBaselineV020Payload;
}

export function deriveTavernNarrativeLifecycleContinuityBaseline(
  records: readonly TavernArchiveRecord[],
  source: {
    readonly memory_set_id: string;
    readonly source_revision_id: NarraMemId<"source_revision">;
    readonly source_checksum: string;
    readonly previous_source_max_ordinal: number | null;
  },
): TavernNarrativeLifecycleContinuityBaselinePayload | null {
  const existing = readTavernNarrativeLifecycleContinuityBaselineFromArchive(records);
  if (existing !== null) {
    if (existing.memory_set_id !== source.memory_set_id) {
      throw new TypeError("Lifecycle continuity baseline belongs to another Memory Set");
    }
    return existing;
  }
  const narrativeThreads: NarrativeThread[] = [];
  const futureImpacts: FutureImpact[] = [];
  const semanticEvents: EventAtom[] = [];
  const semanticStateDeltas: StateDelta[] = [];
  for (const record of records) {
    if (record.record_kind === "core_narrative_thread_v1") {
      const report = validateWireValue("narrative_thread", record.payload);
      if (!report.valid) throw new TypeError("Carried NarrativeThread failed Wire validation");
      const thread = record.payload as unknown as NarrativeThread;
      if (
        record.record_id !== thread.thread_id ||
        thread.derivation.input_revision_id !== source.source_revision_id
      ) {
        throw new TypeError("Carried NarrativeThread does not belong to the semantic base");
      }
      narrativeThreads.push(thread);
    }
    if (record.record_kind === "core_future_impact_v1") {
      const report = validateWireValue("future_impact", record.payload);
      if (!report.valid) throw new TypeError("Carried FutureImpact failed Wire validation");
      const impact = record.payload as unknown as FutureImpact;
      if (
        record.record_id !== impact.impact_id ||
        impact.derivation.input_revision_id !== source.source_revision_id
      ) {
        throw new TypeError("Carried FutureImpact does not belong to the semantic base");
      }
      futureImpacts.push(impact);
    }
    if (record.record_kind === "core_event_v1") {
      const report = validateWireValue("event_atom", record.payload);
      if (!report.valid) throw new TypeError("Carried EventAtom failed Wire validation");
      semanticEvents.push(record.payload as unknown as EventAtom);
    }
    if (record.record_kind === "core_state_delta_v1") {
      const report = validateWireValue("state_delta", record.payload);
      if (!report.valid) throw new TypeError("Carried StateDelta failed Wire validation");
      semanticStateDeltas.push(record.payload as unknown as StateDelta);
    }
  }
  if (narrativeThreads.length === 0 && futureImpacts.length === 0) return null;
  return {
    version: TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION,
    memory_set_id: source.memory_set_id,
    source_revision_id: source.source_revision_id,
    source_checksum: source.source_checksum,
    previous_source_max_ordinal: source.previous_source_max_ordinal,
    narrative_thread_count: narrativeThreads.length,
    future_impact_count: futureImpacts.length,
    narrative_threads: narrativeThreads,
    future_impacts: futureImpacts,
    semantic_events: semanticEvents,
    semantic_state_deltas: semanticStateDeltas,
  };
}
