import { getNarraMemIdKind, isHashDigest } from "@narramem/core-domain";

import type { TavernJsonValue } from "./contracts.js";
import {
  TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID,
  TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND,
  TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_VERSION,
  type TavernCoverageModelProvenance,
  type TavernIncrementalConsumerSafeCoverageHead,
  type TavernIncrementalCoverageArchiveRecoveryRequest,
  type TavernIncrementalCoverageRecoveryResult,
  TavernIncrementalSemanticCoverageError,
  type TavernIncrementalSemanticCoverageHead,
  type TavernIncrementalSemanticCoveragePayload,
  type TavernLifecycleCoverageCommitRequest,
  type TavernSemanticCoverageCommitRequest,
} from "./incremental-semantic-coverage-contracts.js";
import { verifyTavernSourceSnapshot } from "./source-snapshot.js";
import type { TavernSourceSnapshot } from "./source-snapshot-contracts.js";
import { canonicalJson } from "./worldbook-codec.js";
import type { TavernArchiveRecord } from "./worldbook-store-contracts.js";

const SHA256_PATTERN = /^[0-9a-f]{64}$/u;
const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function hasExactKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  return (
    Object.keys(value).length === expected.length &&
    expected.every((key) => Object.hasOwn(value, key))
  );
}

function isSha256(value: unknown): value is string {
  return typeof value === "string" && SHA256_PATTERN.test(value);
}

function isPositiveInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) > 0;
}

function isNonNegativeInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 0;
}

function isProvenance(value: unknown): value is TavernCoverageModelProvenance {
  return (
    isObject(value) &&
    hasExactKeys(value, [
      "model_id",
      "model_identity_assurance",
      "prompt_contract_version",
      "prompt_body_sha256",
      "parameters_hash",
      "validator_version",
    ]) &&
    typeof value.model_id === "string" &&
    value.model_id.length > 0 &&
    value.model_identity_assurance === "requested_not_attested" &&
    typeof value.prompt_contract_version === "string" &&
    value.prompt_contract_version.length > 0 &&
    isObject(value.prompt_body_sha256) &&
    hasExactKeys(value.prompt_body_sha256, ["algorithm", "value"]) &&
    isHashDigest(value.prompt_body_sha256) &&
    isObject(value.parameters_hash) &&
    hasExactKeys(value.parameters_hash, ["algorithm", "value"]) &&
    isHashDigest(value.parameters_hash) &&
    typeof value.validator_version === "string" &&
    value.validator_version.length > 0
  );
}

function isSemanticHead(value: unknown): value is TavernIncrementalSemanticCoverageHead {
  return (
    isObject(value) &&
    hasExactKeys(value, [
      "source_revision_id",
      "source_revision",
      "source_checksum",
      "source_message_count_at_commit",
      "chunk_sequence",
      "covered_message_count",
      "covered_prefix_chain_hash",
      "last_covered_source_unit_id",
      "last_covered_content_fingerprint",
      "context_start_ordinal",
      "novel_start_ordinal",
      "novel_end_ordinal",
      "previous_semantic_corpus_sha256",
      "semantic_corpus_sha256",
      "semantic_changeset_id",
      "provenance",
    ]) &&
    getNarraMemIdKind(value.source_revision_id) === "source_revision" &&
    isPositiveInteger(value.source_revision) &&
    isSha256(value.source_checksum) &&
    isPositiveInteger(value.source_message_count_at_commit) &&
    isPositiveInteger(value.chunk_sequence) &&
    isPositiveInteger(value.covered_message_count) &&
    value.covered_message_count <= value.source_message_count_at_commit &&
    isSha256(value.covered_prefix_chain_hash) &&
    typeof value.last_covered_source_unit_id === "string" &&
    value.last_covered_source_unit_id.startsWith("src_") &&
    isSha256(value.last_covered_content_fingerprint) &&
    isNonNegativeInteger(value.context_start_ordinal) &&
    isNonNegativeInteger(value.novel_start_ordinal) &&
    isNonNegativeInteger(value.novel_end_ordinal) &&
    value.context_start_ordinal <= value.novel_start_ordinal &&
    value.novel_start_ordinal <= value.novel_end_ordinal &&
    (value.previous_semantic_corpus_sha256 === null ||
      isSha256(value.previous_semantic_corpus_sha256)) &&
    isSha256(value.semantic_corpus_sha256) &&
    getNarraMemIdKind(value.semantic_changeset_id) === "change_set" &&
    isProvenance(value.provenance)
  );
}

function isConsumerSafeHead(value: unknown): value is TavernIncrementalConsumerSafeCoverageHead {
  return (
    isObject(value) &&
    hasExactKeys(value, [
      "source_revision_id",
      "source_revision",
      "source_checksum",
      "chunk_sequence",
      "covered_message_count",
      "covered_prefix_chain_hash",
      "last_covered_source_unit_id",
      "last_covered_content_fingerprint",
      "semantic_corpus_sha256",
      "semantic_changeset_id",
      "lifecycle_changeset_id",
      "semantic_provenance",
      "lifecycle_provenance",
    ]) &&
    getNarraMemIdKind(value.source_revision_id) === "source_revision" &&
    isPositiveInteger(value.source_revision) &&
    isSha256(value.source_checksum) &&
    isPositiveInteger(value.chunk_sequence) &&
    isPositiveInteger(value.covered_message_count) &&
    isSha256(value.covered_prefix_chain_hash) &&
    typeof value.last_covered_source_unit_id === "string" &&
    value.last_covered_source_unit_id.startsWith("src_") &&
    isSha256(value.last_covered_content_fingerprint) &&
    isSha256(value.semantic_corpus_sha256) &&
    getNarraMemIdKind(value.semantic_changeset_id) === "change_set" &&
    getNarraMemIdKind(value.lifecycle_changeset_id) === "change_set" &&
    isProvenance(value.semantic_provenance) &&
    isProvenance(value.lifecycle_provenance)
  );
}

function assertCursor(value: unknown): asserts value is TavernIncrementalSemanticCoveragePayload {
  if (
    !isObject(value) ||
    !hasExactKeys(value, [
      "version",
      "memory_set_id",
      "stage",
      "semantic_head",
      "consumer_safe_head",
    ]) ||
    value.version !== TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_VERSION ||
    typeof value.memory_set_id !== "string" ||
    !SAFE_MEMORY_SET_PATTERN.test(value.memory_set_id) ||
    !["semantic_committed", "lifecycle_committed"].includes(value.stage as string) ||
    !isSemanticHead(value.semantic_head) ||
    (value.consumer_safe_head !== null && !isConsumerSafeHead(value.consumer_safe_head))
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "CURSOR_CORRUPT",
      "Invalid incremental semantic coverage cursor",
    );
  }
  const semantic = value.semantic_head;
  const safe = value.consumer_safe_head;
  const synchronized =
    safe !== null &&
    safe.source_revision_id === semantic.source_revision_id &&
    safe.source_revision === semantic.source_revision &&
    safe.source_checksum === semantic.source_checksum &&
    safe.chunk_sequence === semantic.chunk_sequence &&
    safe.covered_message_count === semantic.covered_message_count &&
    safe.covered_prefix_chain_hash === semantic.covered_prefix_chain_hash &&
    safe.last_covered_source_unit_id === semantic.last_covered_source_unit_id &&
    safe.last_covered_content_fingerprint === semantic.last_covered_content_fingerprint &&
    safe.semantic_corpus_sha256 === semantic.semantic_corpus_sha256 &&
    safe.semantic_changeset_id === semantic.semantic_changeset_id;
  const validPendingStage =
    value.stage !== "semantic_committed" ||
    (semantic.chunk_sequence === 1
      ? safe === null && semantic.previous_semantic_corpus_sha256 === null
      : safe !== null &&
        safe.chunk_sequence === semantic.chunk_sequence - 1 &&
        safe.covered_message_count < semantic.covered_message_count &&
        safe.source_revision <= semantic.source_revision &&
        safe.semantic_corpus_sha256 === semantic.previous_semantic_corpus_sha256);
  if ((value.stage === "lifecycle_committed" && !synchronized) || !validPendingStage) {
    throw new TavernIncrementalSemanticCoverageError(
      "CURSOR_CORRUPT",
      "Coverage stage and consumer-safe head disagree",
    );
  }
}

function asJsonValue(value: unknown): TavernJsonValue {
  canonicalJson(value);
  return value as TavernJsonValue;
}

function assertPrefix(
  snapshot: TavernSourceSnapshot,
  head: Pick<
    TavernIncrementalSemanticCoverageHead,
    | "covered_message_count"
    | "covered_prefix_chain_hash"
    | "last_covered_source_unit_id"
    | "last_covered_content_fingerprint"
  >,
  label: string,
): void {
  const message = snapshot.messages[head.covered_message_count - 1];
  if (
    message === undefined ||
    message.chain_hash !== head.covered_prefix_chain_hash ||
    message.source_unit_id !== head.last_covered_source_unit_id ||
    message.content_fingerprint !== head.last_covered_content_fingerprint
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "SOURCE_DIVERGED",
      `${label} no longer matches the authoritative Source prefix`,
    );
  }
}

export function readTavernIncrementalSemanticCoverageFromArchive(
  records: readonly TavernArchiveRecord[],
): TavernIncrementalSemanticCoveragePayload | null {
  const candidates = records.filter(
    (record) =>
      record.record_id === TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID ||
      record.record_kind === TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND,
  );
  if (candidates.length === 0) return null;
  const record = candidates[0];
  if (
    candidates.length !== 1 ||
    record?.record_id !== TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID ||
    record.record_kind !== TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "CURSOR_CORRUPT",
      "Active archive contains an ambiguous incremental coverage record",
    );
  }
  assertCursor(record.payload);
  return record.payload;
}

export function createTavernIncrementalSemanticCoverageArchiveRecord(
  cursor: TavernIncrementalSemanticCoveragePayload,
): TavernArchiveRecord {
  assertCursor(cursor);
  return {
    record_id: TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID,
    record_kind: TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND,
    payload: asJsonValue(cursor),
  };
}

export function replaceTavernIncrementalSemanticCoverageRecord(
  records: readonly TavernArchiveRecord[],
  cursor: TavernIncrementalSemanticCoveragePayload,
): readonly TavernArchiveRecord[] {
  readTavernIncrementalSemanticCoverageFromArchive(records);
  return [
    ...records.filter(
      (record) =>
        record.record_id !== TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_ID &&
        record.record_kind !== TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_RECORD_KIND,
    ),
    createTavernIncrementalSemanticCoverageArchiveRecord(cursor),
  ];
}

export async function recoverTavernIncrementalSemanticCoverage(
  cursor: TavernIncrementalSemanticCoveragePayload,
  sourceSnapshot: TavernSourceSnapshot,
): Promise<TavernIncrementalCoverageRecoveryResult> {
  assertCursor(cursor);
  await verifyTavernSourceSnapshot(sourceSnapshot);
  if (cursor.memory_set_id !== sourceSnapshot.memory_set_id) {
    throw new TavernIncrementalSemanticCoverageError(
      "SOURCE_DIVERGED",
      "Coverage cursor belongs to a different Memory Set",
    );
  }
  const semantic = cursor.semantic_head;
  if (sourceSnapshot.source_revision < semantic.source_revision) {
    throw new TavernIncrementalSemanticCoverageError(
      "SOURCE_DIVERGED",
      "Authoritative Source revision predates the coverage cursor",
    );
  }
  if (
    sourceSnapshot.source_revision === semantic.source_revision &&
    (sourceSnapshot.checksum !== semantic.source_checksum ||
      sourceSnapshot.messages.length !== semantic.source_message_count_at_commit)
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "SOURCE_DIVERGED",
      "Coverage checksum disagrees with its authoritative Source revision",
    );
  }
  assertPrefix(sourceSnapshot, semantic, "Semantic coverage");
  if (cursor.consumer_safe_head !== null) {
    assertPrefix(sourceSnapshot, cursor.consumer_safe_head, "Consumer-safe coverage");
  }
  const compatibility =
    sourceSnapshot.source_revision === semantic.source_revision &&
    sourceSnapshot.checksum === semantic.source_checksum
      ? "CURRENT"
      : "APPEND_COMPATIBLE";
  const nextAction =
    cursor.stage === "semantic_committed"
      ? "RUN_LIFECYCLE"
      : semantic.covered_message_count < sourceSnapshot.messages.length
        ? "RUN_NEXT_SEMANTIC_CHUNK"
        : "CAUGHT_UP";
  return {
    cursor,
    source_compatibility: compatibility,
    next_action: nextAction,
    semantic_covered_message_count: semantic.covered_message_count,
    consumer_safe_covered_message_count: cursor.consumer_safe_head?.covered_message_count ?? 0,
  };
}

export async function recoverTavernIncrementalSemanticCoverageFromArchive(
  request: TavernIncrementalCoverageArchiveRecoveryRequest,
): Promise<TavernIncrementalCoverageRecoveryResult | null> {
  const cursor = readTavernIncrementalSemanticCoverageFromArchive(request.records);
  return cursor === null
    ? null
    : recoverTavernIncrementalSemanticCoverage(cursor, request.source_snapshot);
}

export async function createTavernSemanticCoverageCommit(
  request: TavernSemanticCoverageCommitRequest,
): Promise<TavernIncrementalSemanticCoveragePayload> {
  await verifyTavernSourceSnapshot(request.source_snapshot);
  if (
    getNarraMemIdKind(request.source_revision_id) !== "source_revision" ||
    getNarraMemIdKind(request.semantic_changeset_id) !== "change_set" ||
    !isSha256(request.semantic_corpus_sha256) ||
    !isProvenance(request.provenance)
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "INVALID_INPUT",
      "Semantic coverage commit metadata is invalid",
    );
  }
  const prior = request.previous_cursor;
  if (prior !== null) {
    const recovered = await recoverTavernIncrementalSemanticCoverage(
      prior,
      request.source_snapshot,
    );
    if (prior.stage !== "lifecycle_committed" || recovered.next_action === "RUN_LIFECYCLE") {
      throw new TavernIncrementalSemanticCoverageError(
        "STAGE_CONFLICT",
        "The previous semantic chunk must finish lifecycle before the next chunk",
      );
    }
  }
  const beforeCount = prior?.semantic_head.covered_message_count ?? 0;
  const expectedSequence = (prior?.semantic_head.chunk_sequence ?? 0) + 1;
  const firstNovel = request.source_snapshot.messages[beforeCount];
  const contextIndex = request.source_snapshot.messages.findIndex(
    (message) => message.message_id_at_capture === request.boundary.context_start_ordinal,
  );
  const endIndex = request.source_snapshot.messages.findIndex(
    (message) => message.message_id_at_capture === request.boundary.novel_end_ordinal,
  );
  if (
    request.boundary.covered_message_count !== beforeCount ||
    request.boundary.chunk_sequence !== expectedSequence ||
    firstNovel === undefined ||
    firstNovel.message_id_at_capture !== request.boundary.novel_start_ordinal ||
    contextIndex < 0 ||
    contextIndex > beforeCount ||
    endIndex < beforeCount ||
    request.boundary.context_start_ordinal > request.boundary.novel_start_ordinal ||
    request.boundary.novel_start_ordinal > request.boundary.novel_end_ordinal
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "INVALID_INPUT",
      "Coverage boundary has a gap, overlap, or non-monotonic chunk sequence",
    );
  }
  const lastCovered = request.source_snapshot.messages[endIndex];
  if (lastCovered === undefined) {
    throw new TavernIncrementalSemanticCoverageError(
      "INVALID_INPUT",
      "Coverage boundary does not end on an authoritative Source message",
    );
  }
  const semanticHead: TavernIncrementalSemanticCoverageHead = {
    source_revision_id: request.source_revision_id,
    source_revision: request.source_snapshot.source_revision,
    source_checksum: request.source_snapshot.checksum,
    source_message_count_at_commit: request.source_snapshot.messages.length,
    chunk_sequence: request.boundary.chunk_sequence,
    covered_message_count: endIndex + 1,
    covered_prefix_chain_hash: lastCovered.chain_hash,
    last_covered_source_unit_id: lastCovered.source_unit_id,
    last_covered_content_fingerprint: lastCovered.content_fingerprint,
    context_start_ordinal: request.boundary.context_start_ordinal,
    novel_start_ordinal: request.boundary.novel_start_ordinal,
    novel_end_ordinal: request.boundary.novel_end_ordinal,
    previous_semantic_corpus_sha256: prior?.semantic_head.semantic_corpus_sha256 ?? null,
    semantic_corpus_sha256: request.semantic_corpus_sha256,
    semantic_changeset_id: request.semantic_changeset_id,
    provenance: request.provenance,
  };
  const cursor: TavernIncrementalSemanticCoveragePayload = {
    version: TAVERN_INCREMENTAL_SEMANTIC_COVERAGE_VERSION,
    memory_set_id: request.source_snapshot.memory_set_id,
    stage: "semantic_committed",
    semantic_head: semanticHead,
    consumer_safe_head: prior?.consumer_safe_head ?? null,
  };
  assertCursor(cursor);
  return cursor;
}

export async function createTavernLifecycleCoverageCommit(
  request: TavernLifecycleCoverageCommitRequest,
): Promise<TavernIncrementalSemanticCoveragePayload> {
  const recovered = await recoverTavernIncrementalSemanticCoverage(
    request.cursor,
    request.source_snapshot,
  );
  if (
    request.cursor.stage !== "semantic_committed" ||
    recovered.source_compatibility !== "CURRENT"
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "STAGE_CONFLICT",
      "Lifecycle can only advance the current pending semantic chunk",
    );
  }
  if (
    getNarraMemIdKind(request.lifecycle_changeset_id) !== "change_set" ||
    !isProvenance(request.provenance)
  ) {
    throw new TavernIncrementalSemanticCoverageError(
      "INVALID_INPUT",
      "Lifecycle coverage commit metadata is invalid",
    );
  }
  const semantic = request.cursor.semantic_head;
  const safe: TavernIncrementalConsumerSafeCoverageHead = {
    source_revision_id: semantic.source_revision_id,
    source_revision: semantic.source_revision,
    source_checksum: semantic.source_checksum,
    chunk_sequence: semantic.chunk_sequence,
    covered_message_count: semantic.covered_message_count,
    covered_prefix_chain_hash: semantic.covered_prefix_chain_hash,
    last_covered_source_unit_id: semantic.last_covered_source_unit_id,
    last_covered_content_fingerprint: semantic.last_covered_content_fingerprint,
    semantic_corpus_sha256: semantic.semantic_corpus_sha256,
    semantic_changeset_id: semantic.semantic_changeset_id,
    lifecycle_changeset_id: request.lifecycle_changeset_id,
    semantic_provenance: semantic.provenance,
    lifecycle_provenance: request.provenance,
  };
  const cursor: TavernIncrementalSemanticCoveragePayload = {
    ...request.cursor,
    stage: "lifecycle_committed",
    consumer_safe_head: safe,
  };
  assertCursor(cursor);
  return cursor;
}
