import type { HashDigest, NarraMemId, NarraMemIdKind } from "@narramem/core-domain";

export interface CandidateCompilerPorts {
  readonly allocate_id: <Kind extends NarraMemIdKind>(
    kind: Kind,
    stable_key: string,
  ) => NarraMemId<Kind>;
  readonly hash_text: (text: string) => Promise<HashDigest>;
  readonly now: () => string;
}

export class CandidateCompilationError extends Error {
  public readonly codes: readonly string[];

  public constructor(message: string, codes: readonly string[]) {
    super(message);
    this.name = "CandidateCompilationError";
    this.codes = codes;
  }
}
