function canonicalModelId(modelId: string): string {
  return modelId
    .normalize("NFKC")
    .toLocaleLowerCase("en-US")
    .replace(/[^a-z0-9]+/g, "");
}

function detectFamily(modelId: string): CausalAuditModelFamily | undefined {
  const canonical = canonicalModelId(modelId);
  if (canonical.includes("gemini31propreview")) return "gemini-3.1-pro-preview";
  if (canonical.includes("mimov25pro")) return "mimo-v2.5-pro";
  if (canonical.includes("kimik3")) return "kimi-k3";
  return undefined;
}

export function resolveCausalAuditModelAdapter(modelId: string): CausalAuditModelAdapter {
  if (modelId.trim().length === 0) throw new TypeError("Causal Audit model ID cannot be empty");
  const exclusion = findQualityModelExclusion(modelId);
  if (exclusion !== undefined) {
    throw new Error(`Causal Audit model is excluded by quality policy marker: ${exclusion}`);
  }
  const family = detectFamily(modelId);
  if (family === undefined) {
    throw new Error(`No reviewed Causal Audit adapter for exact model ID: ${modelId}`);
  }
  const matches = CAUSAL_AUDIT_MODEL_ADAPTERS.filter((adapter) => adapter.family === family);
  if (matches.length !== 1) {
    throw new Error(`Causal Audit model family must resolve to exactly one adapter: ${family}`);
  }
  return matches[0] as CausalAuditModelAdapter;
}

