import type {
  TavernHostPort,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import {
  TAVERN_REGISTRY_FORMAT,
  TAVERN_REGISTRY_VERSION,
  type TavernControlCandidate,
  type TavernIdentityProbe,
  TavernMemoryRegistryError,
  type TavernMemorySetCreateRequest,
  type TavernMemorySetCreateResult,
  type TavernMemorySetRebindRequest,
  type TavernMemorySetRebindResult,
  type TavernMemorySetResolution,
  type TavernRegistryIssue,
  type TavernRegistryPayload,
  type TavernRegistryRebuildResult,
  type TavernRegistryRecord,
} from "./memory-registry-contracts.js";
import { canonicalJson, checksumJson, sha256HexUtf8 } from "./worldbook-codec.js";
import {
  readTavernControlPayload,
  TavernWorldbookSnapshotStore,
} from "./worldbook-snapshot-store.js";
import {
  type TavernMemoryIdentityAnchor,
  TavernWorldbookStoreError,
} from "./worldbook-store-contracts.js";

const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const REGISTRY_BOOK_NAME = "NarraMem__REGISTRY__v1";
const CONTROL_BOOK_PREFIX = "NarraMem__CONTROL__";
const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";
const ANCHOR_MESSAGE_LIMIT = 8;
const CONTROL_READ_CONCURRENCY = 8;

type RegistryState = {
  readonly entry: TavernWorldbookEntry;
  readonly payload: TavernRegistryPayload;
};

type ControlScanItem =
  | { readonly candidate: TavernControlCandidate; readonly issue?: never }
  | { readonly candidate?: never; readonly issue: TavernRegistryIssue };

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const hasOnlyKeys = (value: Record<string, unknown>, allowed: readonly string[]): boolean => {
  const allowedSet = new Set(allowed);
  return Object.keys(value).every((key) => allowedSet.has(key));
};

function machineEntryDraft(content: string): TavernWorldbookEntryDraft {
  return {
    name: "NarraMem Registry",
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: {
      type: "after_character_definition",
      role: "system",
      depth: 0,
      order: 0,
    },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: { narramem: { record_kind: "registry" } },
  };
}

function assertRegistryEntry(entry: TavernWorldbookEntry): void {
  if (
    !Number.isInteger(entry.uid) ||
    entry.uid < 0 ||
    entry.enabled ||
    entry.strategy.type !== "constant" ||
    entry.strategy.keys.length !== 0 ||
    !entry.recursion.prevent_incoming ||
    !entry.recursion.prevent_outgoing
  ) {
    throw new TavernMemoryRegistryError(
      "REGISTRY_CORRUPT",
      "Registry entry safety settings changed",
    );
  }
}

function validateRegistryRecord(value: unknown): asserts value is TavernRegistryRecord {
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "memory_set_id",
      "control_book_name",
      "character_id",
      "chat_id",
      "chat_anchor_hash",
    ]) ||
    typeof value.memory_set_id !== "string" ||
    !SAFE_MEMORY_SET_PATTERN.test(value.memory_set_id) ||
    typeof value.control_book_name !== "string" ||
    value.control_book_name !== `${CONTROL_BOOK_PREFIX}${value.memory_set_id}` ||
    typeof value.character_id !== "string" ||
    value.character_id.trim().length === 0 ||
    typeof value.chat_id !== "string" ||
    value.chat_id.trim().length === 0 ||
    typeof value.chat_anchor_hash !== "string" ||
    !SHA256_PATTERN.test(value.chat_anchor_hash)
  ) {
    throw new TavernMemoryRegistryError("REGISTRY_CORRUPT", "Invalid Registry record");
  }
}

async function parseRegistry(content: string): Promise<TavernRegistryPayload> {
  let value: unknown;
  try {
    value = JSON.parse(content);
  } catch {
    throw new TavernMemoryRegistryError("REGISTRY_CORRUPT", "Registry is not valid JSON");
  }
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, ["format", "schema_version", "records", "checksum"]) ||
    value.format !== TAVERN_REGISTRY_FORMAT ||
    value.schema_version !== TAVERN_REGISTRY_VERSION ||
    !Array.isArray(value.records) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernMemoryRegistryError("REGISTRY_CORRUPT", "Invalid Registry payload");
  }
  for (const record of value.records) validateRegistryRecord(record);
  const records = value.records as unknown as TavernRegistryRecord[];
  const memoryIds = records.map((record) => record.memory_set_id);
  const controlNames = records.map((record) => record.control_book_name);
  if (
    new Set(memoryIds).size !== memoryIds.length ||
    new Set(controlNames).size !== controlNames.length ||
    records.some((record, index) => {
      const previous = records[index - 1];
      return index > 0 && previous !== undefined && record.memory_set_id < previous.memory_set_id;
    })
  ) {
    throw new TavernMemoryRegistryError(
      "REGISTRY_CORRUPT",
      "Registry records are duplicated or not sorted",
    );
  }
  const payload: TavernRegistryPayload = {
    format: TAVERN_REGISTRY_FORMAT,
    schema_version: TAVERN_REGISTRY_VERSION,
    records,
    checksum: value.checksum,
  };
  const { checksum: _checksum, ...unsigned } = payload;
  if ((await checksumJson(unsigned)) !== payload.checksum) {
    throw new TavernMemoryRegistryError("REGISTRY_CORRUPT", "Registry checksum mismatch");
  }
  return payload;
}

async function encodeRegistry(
  records: readonly TavernRegistryRecord[],
): Promise<TavernRegistryPayload> {
  const sorted = [...records].sort((left, right) =>
    left.memory_set_id.localeCompare(right.memory_set_id),
  );
  for (const record of sorted) validateRegistryRecord(record);
  if (new Set(sorted.map((record) => record.memory_set_id)).size !== sorted.length) {
    throw new TavernMemoryRegistryError("INVALID_INPUT", "Duplicate Memory Set in Registry");
  }
  const unsigned = {
    format: TAVERN_REGISTRY_FORMAT,
    schema_version: TAVERN_REGISTRY_VERSION,
    records: sorted,
  };
  return { ...unsigned, checksum: await checksumJson(unsigned) };
}

function recordFromCandidate(candidate: TavernControlCandidate): TavernRegistryRecord {
  const identity = candidate.control.identity_anchor;
  return {
    memory_set_id: candidate.control.memory_set_id,
    control_book_name: candidate.control_book_name,
    character_id: identity.character_locator.host_character_id,
    chat_id: identity.chat_locator.host_chat_id,
    chat_anchor_hash: identity.chat_anchor_hash,
  };
}

function recordsEqual(
  left: readonly TavernRegistryRecord[],
  right: readonly TavernRegistryRecord[],
): boolean {
  return canonicalJson(left) === canonicalJson(right);
}

const safeIssueDetail = (error: unknown): string =>
  error instanceof Error ? error.name.slice(0, 80) : "UnknownError";

export async function captureTavernIdentityProbe(
  port: TavernHostPort,
): Promise<TavernIdentityProbe> {
  const identity = port.getCurrentIdentity();
  if (identity.character_id === null || identity.chat_id === null) {
    throw new TavernMemoryRegistryError("INVALID_INPUT", "No active character/chat identity");
  }
  const messages = port.readCurrentMessages({ include_swipes: false });
  for (const [index, message] of messages.entries()) {
    if (
      !Number.isInteger(message.message_id) ||
      message.message_id < 0 ||
      (index > 0 && message.message_id <= (messages[index - 1]?.message_id ?? -1)) ||
      message.message === undefined
    ) {
      throw new TavernMemoryRegistryError("INVALID_INPUT", "Current chat snapshot is inconsistent");
    }
  }
  const visible = messages.filter((message) => !message.is_hidden).slice(0, ANCHOR_MESSAGE_LIMIT);
  const sampled = await Promise.all(
    visible.map(async (message) => ({
      role: message.role,
      selected_content_hash: await sha256HexUtf8(message.message ?? ""),
    })),
  );
  return {
    character_id: identity.character_id,
    chat_id: identity.chat_id,
    chat_anchor_hash: await checksumJson({
      version: "tavern-chat-anchor@0.1.0",
      visible_prefix: sampled,
    }),
    sampled_visible_messages: sampled.length,
  };
}

export function identityAnchorFromProbe(
  probe: TavernIdentityProbe,
  characterRevisionHash: string | null,
): TavernMemoryIdentityAnchor {
  if (
    probe.character_id.trim().length === 0 ||
    probe.chat_id.trim().length === 0 ||
    !SHA256_PATTERN.test(probe.chat_anchor_hash) ||
    (characterRevisionHash !== null && !SHA256_PATTERN.test(characterRevisionHash))
  ) {
    throw new TavernMemoryRegistryError("INVALID_INPUT", "Invalid identity probe");
  }
  return {
    identity_version: "0.1.0",
    character_locator: { host_character_id: probe.character_id },
    chat_locator: { host_chat_id: probe.chat_id },
    chat_anchor_hash: probe.chat_anchor_hash,
    character_revision_hash: characterRevisionHash,
  };
}

export class TavernMemoryRegistry {
  private writerTail: Promise<void> = Promise.resolve();

  constructor(private readonly port: TavernHostPort) {}

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writerTail.then(operation, operation);
    this.writerTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async readRegistry(): Promise<TavernRegistryPayload | null> {
    return (await this.readRegistryState())?.payload ?? null;
  }

  /**
   * Bounded read path for generation-time Recall. A checksum-valid Registry may
   * address one current Control directly while its registered Control-name set
   * still covers the host. Extra unregistered names are bounded only when each
   * is freshly proven CONTROL_CORRUPT in this read. Any valid extra Control,
   * missing registered name, uncertain read, ambiguity, or identity mismatch
   * falls back to the authoritative all-Control scan.
   */
  async resolveCurrentMemorySetForBoundedRead(): Promise<TavernMemorySetResolution> {
    try {
      const probe = await captureTavernIdentityProbe(this.port);
      const registry = await this.readRegistry();
      if (registry === null) return this.resolveCurrentMemorySet();
      const hostControlNames = this.port
        .listWorldbooks()
        .filter((name) => name.startsWith(CONTROL_BOOK_PREFIX))
        .sort();
      const registryControlNames = registry.records
        .map((record) => record.control_book_name)
        .sort();
      if (registryControlNames.some((name) => !hostControlNames.includes(name))) {
        return this.resolveCurrentMemorySet();
      }
      const unregisteredControlNames = hostControlNames.filter(
        (name) => !registryControlNames.includes(name),
      );
      const exactRecords = registry.records.filter(
        (record) => record.character_id === probe.character_id && record.chat_id === probe.chat_id,
      );
      const record = exactRecords[0];
      if (exactRecords.length !== 1 || record === undefined) {
        return this.resolveCurrentMemorySet();
      }
      const control = await readTavernControlPayload(this.port, record.control_book_name);
      const anchor = control.identity_anchor;
      if (
        control.memory_set_id !== record.memory_set_id ||
        record.control_book_name !== `${CONTROL_BOOK_PREFIX}${control.memory_set_id}` ||
        anchor.character_locator.host_character_id !== probe.character_id ||
        anchor.chat_locator.host_chat_id !== probe.chat_id
      ) {
        return this.resolveCurrentMemorySet();
      }
      const corruptIssues =
        await this.verifyUnregisteredControlsRemainCorrupt(unregisteredControlNames);
      if (corruptIssues === null) return this.resolveCurrentMemorySet();
      const selected: TavernControlCandidate = {
        control_book_name: record.control_book_name,
        control,
      };
      return {
        status: "EXACT",
        probe,
        selected,
        candidates: [selected],
        registry_repair_needed: corruptIssues.length > 0,
        issues: corruptIssues,
      };
    } catch {
      return this.resolveCurrentMemorySet();
    }
  }

  async resolveCurrentMemorySet(): Promise<TavernMemorySetResolution> {
    const probe = await captureTavernIdentityProbe(this.port);
    const issues: TavernRegistryIssue[] = [];
    let registry: TavernRegistryPayload | null = null;
    try {
      registry = await this.readRegistry();
      if (registry === null) {
        issues.push({
          book_name: REGISTRY_BOOK_NAME,
          code: "REGISTRY_MISSING",
          detail: "Registry book is absent and can be rebuilt from Control books",
        });
      }
    } catch (error) {
      issues.push({
        book_name: REGISTRY_BOOK_NAME,
        code: "REGISTRY_CORRUPT",
        detail: safeIssueDetail(error),
      });
    }
    const scan = await this.scanControlBooks();
    issues.push(...scan.issues);
    const authoritativeRecords = scan.candidates.map(recordFromCandidate);
    if (registry !== null) {
      for (const record of registry.records) {
        if (
          !scan.candidates.some(
            (candidate) => candidate.control_book_name === record.control_book_name,
          )
        ) {
          issues.push({
            book_name: record.control_book_name,
            code: "STALE_RECORD",
            detail: "Registry record has no valid Control book",
          });
        }
      }
    }
    const registryRepairNeeded =
      registry === null ||
      !recordsEqual(registry.records, authoritativeRecords) ||
      issues.length > 0;
    const exact = scan.candidates.filter((candidate) => {
      const anchor = candidate.control.identity_anchor;
      return (
        anchor.character_locator.host_character_id === probe.character_id &&
        anchor.chat_locator.host_chat_id === probe.chat_id
      );
    });
    if (exact.length === 1) {
      return {
        status: "EXACT",
        probe,
        selected: exact[0] ?? null,
        candidates: exact,
        registry_repair_needed: registryRepairNeeded,
        issues,
      };
    }
    if (exact.length > 1) {
      return {
        status: "LOCATOR_CONFLICT",
        probe,
        selected: null,
        candidates: exact,
        registry_repair_needed: true,
        issues,
      };
    }
    const anchorCandidates = scan.candidates.filter(
      (candidate) => candidate.control.identity_anchor.chat_anchor_hash === probe.chat_anchor_hash,
    );
    return {
      status: anchorCandidates.length > 0 ? "ANCHOR_CONFIRMATION_REQUIRED" : "NOT_FOUND",
      probe,
      selected: null,
      candidates: anchorCandidates,
      registry_repair_needed: registryRepairNeeded,
      issues,
    };
  }

  rebuildRegistry(allowReplaceCorruptRegistry = false): Promise<TavernRegistryRebuildResult> {
    return this.enqueue(() => this.rebuildRegistryExclusive(allowReplaceCorruptRegistry));
  }

  private async rebuildRegistryExclusive(
    allowReplaceCorruptRegistry: boolean,
  ): Promise<TavernRegistryRebuildResult> {
    const scan = await this.scanControlBooks();
    const records = scan.candidates.map(recordFromCandidate);
    const payload = await encodeRegistry(records);
    const existing = this.port.listWorldbooks().includes(REGISTRY_BOOK_NAME);
    if (!existing) {
      if (!(await this.port.createWorldbook(REGISTRY_BOOK_NAME))) {
        throw new TavernMemoryRegistryError(
          "REGISTRY_WRITE_CONFLICT",
          "Registry creation collided",
        );
      }
      try {
        const appended = await this.port.appendWorldbookEntries(REGISTRY_BOOK_NAME, [
          machineEntryDraft(canonicalJson(payload)),
        ]);
        if (appended.new_entries.length !== 1) {
          throw new TavernMemoryRegistryError(
            "REGISTRY_WRITE_CONFLICT",
            "Registry initialization did not create one entry",
          );
        }
      } catch (error) {
        const entries = await this.port.readWorldbook(REGISTRY_BOOK_NAME);
        if (entries.length === 0) await this.port.deleteWorldbook(REGISTRY_BOOK_NAME);
        throw error;
      }
    } else {
      const entries = await this.port.readWorldbook(REGISTRY_BOOK_NAME);
      const entry = entries[0];
      if (entries.length !== 1 || entry === undefined) {
        throw new TavernMemoryRegistryError(
          "UNSAFE_REBUILD",
          "Registry book does not contain exactly one machine entry",
        );
      }
      assertRegistryEntry(entry);
      try {
        await parseRegistry(entry.content);
      } catch (error) {
        if (!allowReplaceCorruptRegistry) throw error;
      }
      await this.port.replaceWorldbook(REGISTRY_BOOK_NAME, [
        { ...machineEntryDraft(canonicalJson(payload)), uid: entry.uid },
      ]);
    }
    const verified = await this.readRegistry();
    if (verified === null || verified.checksum !== payload.checksum) {
      throw new TavernMemoryRegistryError(
        "REGISTRY_WRITE_CONFLICT",
        "Registry read-back checksum mismatch",
      );
    }
    return { registry: verified, control_count: records.length, issues: scan.issues };
  }

  createMemorySet(request: TavernMemorySetCreateRequest): Promise<TavernMemorySetCreateResult> {
    return this.enqueue(async () => {
      if (!SAFE_MEMORY_SET_PATTERN.test(request.memory_set_id)) {
        throw new TavernMemoryRegistryError("INVALID_INPUT", "Invalid memory_set_id");
      }
      if (
        request.probe.character_id.trim().length === 0 ||
        request.probe.chat_id.trim().length === 0 ||
        !SHA256_PATTERN.test(request.probe.chat_anchor_hash)
      ) {
        throw new TavernMemoryRegistryError("INVALID_INPUT", "Invalid identity probe");
      }
      const scan = await this.scanControlBooks();
      const exactExists = scan.candidates.some((candidate) => {
        const anchor = candidate.control.identity_anchor;
        return (
          anchor.character_locator.host_character_id === request.probe.character_id &&
          anchor.chat_locator.host_chat_id === request.probe.chat_id
        );
      });
      const controlBookName = `${CONTROL_BOOK_PREFIX}${request.memory_set_id}`;
      if (exactExists || this.port.listWorldbooks().includes(controlBookName)) {
        throw new TavernMemoryRegistryError(
          "MEMORY_SET_COLLISION",
          "Current locator or requested Memory Set already has a Control book",
        );
      }
      const identityAnchor = identityAnchorFromProbe(
        request.probe,
        request.character_revision_hash,
      );
      const segmentBookPrefix = `${ARCHIVE_BOOK_PREFIX}${request.memory_set_id}__`;
      const store = new TavernWorldbookSnapshotStore(this.port, {
        memory_set_id: request.memory_set_id,
        control_book_name: controlBookName,
        segment_book_prefix: segmentBookPrefix,
        initial_identity_anchor: identityAnchor,
        max_records_per_segment: request.max_records_per_segment,
        max_segment_utf8_bytes: request.max_segment_utf8_bytes,
      });
      const control = await store.initialize();
      let registryUpdated = true;
      let registryIssue: string | undefined;
      try {
        await this.rebuildRegistryExclusive(false);
      } catch (error) {
        registryUpdated = false;
        registryIssue = safeIssueDetail(error);
      }
      return {
        control_book_name: controlBookName,
        segment_book_prefix: segmentBookPrefix,
        identity_anchor: identityAnchor,
        control,
        registry_updated: registryUpdated,
        ...(registryIssue === undefined ? {} : { registry_issue: registryIssue }),
      };
    });
  }

  rebindMemorySet(request: TavernMemorySetRebindRequest): Promise<TavernMemorySetRebindResult> {
    return this.enqueue(async () => {
      if (
        !request.control_book_name.startsWith(CONTROL_BOOK_PREFIX) ||
        !SHA256_PATTERN.test(request.expected_control_checksum)
      ) {
        throw new TavernMemoryRegistryError("INVALID_INPUT", "Invalid rebind request");
      }
      const liveProbe = await captureTavernIdentityProbe(this.port);
      if (canonicalJson(liveProbe) !== canonicalJson(request.probe)) {
        throw new TavernMemoryRegistryError(
          "REGISTRY_WRITE_CONFLICT",
          "Active chat changed after the rebind probe was captured",
        );
      }
      const selected = await readTavernControlPayload(this.port, request.control_book_name);
      if (selected.checksum !== request.expected_control_checksum) {
        throw new TavernMemoryRegistryError(
          "REGISTRY_WRITE_CONFLICT",
          "Selected Control changed before rebind",
        );
      }
      const scan = await this.scanControlBooks();
      const locatorOwner = scan.candidates.find((candidate) => {
        const identity = candidate.control.identity_anchor;
        return (
          candidate.control_book_name !== request.control_book_name &&
          identity.character_locator.host_character_id === request.probe.character_id &&
          identity.chat_locator.host_chat_id === request.probe.chat_id
        );
      });
      if (locatorOwner !== undefined) {
        throw new TavernMemoryRegistryError(
          "MEMORY_SET_COLLISION",
          "The current character/chat locator already belongs to another Memory Set",
        );
      }
      const nextIdentity = identityAnchorFromProbe(request.probe, request.character_revision_hash);
      const store = new TavernWorldbookSnapshotStore(this.port, {
        memory_set_id: selected.memory_set_id,
        control_book_name: request.control_book_name,
        segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${selected.memory_set_id}__`,
        initial_identity_anchor: selected.identity_anchor,
        max_records_per_segment: 1,
        max_segment_utf8_bytes: 256,
      });
      const control = await store.updateIdentityAnchor({
        expected_control_checksum: selected.checksum,
        next_identity_anchor: nextIdentity,
      });
      let registryUpdated = true;
      let registryIssue: string | undefined;
      try {
        await this.rebuildRegistryExclusive(false);
      } catch (error) {
        registryUpdated = false;
        registryIssue = safeIssueDetail(error);
      }
      return {
        control,
        registry_updated: registryUpdated,
        ...(registryIssue === undefined ? {} : { registry_issue: registryIssue }),
      };
    });
  }

  private async readRegistryState(): Promise<RegistryState | null> {
    if (!this.port.listWorldbooks().includes(REGISTRY_BOOK_NAME)) return null;
    const entries = await this.port.readWorldbook(REGISTRY_BOOK_NAME);
    const entry = entries[0];
    if (entries.length !== 1 || entry === undefined) {
      throw new TavernMemoryRegistryError(
        "REGISTRY_CORRUPT",
        "Registry book must contain exactly one entry",
      );
    }
    assertRegistryEntry(entry);
    return { entry, payload: await parseRegistry(entry.content) };
  }

  private async scanControlBooks(): Promise<{
    readonly candidates: readonly TavernControlCandidate[];
    readonly issues: readonly TavernRegistryIssue[];
  }> {
    const candidates: TavernControlCandidate[] = [];
    const issues: TavernRegistryIssue[] = [];
    const names = this.port
      .listWorldbooks()
      .filter((name) => name.startsWith(CONTROL_BOOK_PREFIX))
      .sort();
    const scanned = new Array<ControlScanItem | undefined>(names.length);
    let nextIndex = 0;
    const worker = async (): Promise<void> => {
      while (nextIndex < names.length) {
        const index = nextIndex;
        nextIndex += 1;
        const name = names[index];
        if (name === undefined) return;
        try {
          const control = await readTavernControlPayload(this.port, name);
          if (name !== `${CONTROL_BOOK_PREFIX}${control.memory_set_id}`) {
            throw new TavernMemoryRegistryError(
              "REGISTRY_CORRUPT",
              "Control book name does not match Memory Set",
            );
          }
          scanned[index] = { candidate: { control_book_name: name, control } };
        } catch (error) {
          scanned[index] = {
            issue: {
              book_name: name,
              code: "CONTROL_CORRUPT",
              detail: safeIssueDetail(error),
            },
          };
        }
      }
    };
    await Promise.all(
      Array.from({ length: Math.min(CONTROL_READ_CONCURRENCY, names.length) }, () => worker()),
    );
    for (const item of scanned) {
      if (item?.candidate !== undefined) candidates.push(item.candidate);
      if (item?.issue !== undefined) issues.push(item.issue);
    }
    return { candidates, issues };
  }

  private async verifyUnregisteredControlsRemainCorrupt(
    names: readonly string[],
  ): Promise<readonly TavernRegistryIssue[] | null> {
    const issues = new Array<TavernRegistryIssue | undefined>(names.length);
    let nextIndex = 0;
    let unsafe = false;
    const worker = async (): Promise<void> => {
      while (!unsafe && nextIndex < names.length) {
        const index = nextIndex;
        nextIndex += 1;
        const name = names[index];
        if (name === undefined) continue;
        try {
          await readTavernControlPayload(this.port, name);
          unsafe = true;
        } catch (error) {
          if (!(error instanceof TavernWorldbookStoreError) || error.code !== "CONTROL_CORRUPT") {
            unsafe = true;
            continue;
          }
          issues[index] = {
            book_name: name,
            code: "CONTROL_CORRUPT",
            detail: safeIssueDetail(error),
          };
        }
      }
    };
    await Promise.all(
      Array.from({ length: Math.min(CONTROL_READ_CONCURRENCY, names.length) }, () => worker()),
    );
    if (unsafe || issues.filter((issue) => issue !== undefined).length !== names.length)
      return null;
    return issues as TavernRegistryIssue[];
  }
}
