import type { TavernCausalAuditTaskSeed } from "./causal-audit-task-mapping.js";

export const TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION = "0.1.0" as const;

export type TavernCausalAuditActivationMode = "disabled" | "manual" | "idle_opt_in";

export interface TavernCausalAuditExecutionPolicy {
  readonly policy_version: typeof TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION;
  readonly activation_mode: TavernCausalAuditActivationMode;
  /** Required only for unattended idle execution; manual trigger is itself explicit consent. */
  readonly unattended_opt_in_acknowledged: boolean;
  readonly minimum_idle_ms: number;
  readonly max_tasks_per_session: number;
  readonly max_model_calls_per_session: number;
  readonly max_input_tokens_per_session: number;
}

export interface TavernCausalAuditExecutionContext {
  readonly seed: TavernCausalAuditTaskSeed;
  readonly current_memory_set_id: string;
  readonly current_source_revision_id: string;
  readonly current_source_checksum: string;
  readonly current_semantic_task_fingerprint: string;
  readonly page_lifecycle: "visible" | "hidden" | "unloading";
  readonly observer_running: boolean;
  /** Manual-only lane: the product observer is deliberately stopped after an exact live-source check. */
  readonly manual_observer_quiesced?: boolean;
  readonly main_generation_active: boolean;
  readonly source_cycle_in_flight: boolean;
  readonly extraction_in_flight: boolean;
  readonly mutation_fence_stable: boolean;
  readonly idle_for_ms: number;
  readonly tasks_started_in_session: number;
  readonly model_calls_used_in_session: number;
  readonly input_tokens_used_in_session: number;
  readonly active_task_count: number;
  /** A manual command must name the exact current seed; a boolean click is not enough. */
  readonly manual_task_seed_id?: string;
}

export type TavernCausalAuditExecutionDecision =
  | {
      readonly status: "ELIGIBLE";
      readonly policy_version: typeof TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION;
      readonly trigger: "manual" | "idle_opt_in";
      readonly authorization: "start_readonly_investigation_only";
      readonly model_persistent_write_authorized: false;
    }
  | {
      readonly status: "BLOCKED";
      readonly policy_version: typeof TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION;
      readonly reason:
        | "EXECUTION_DISABLED"
        | "MANUAL_TRIGGER_REQUIRED"
        | "UNATTENDED_OPT_IN_REQUIRED"
        | "STALE_TASK_SEED"
        | "PAGE_NOT_VISIBLE"
        | "OBSERVER_NOT_RUNNING"
        | "MAIN_GENERATION_ACTIVE"
        | "SOURCE_CYCLE_IN_FLIGHT"
        | "EXTRACTION_IN_FLIGHT"
        | "MUTATION_FENCE_UNSTABLE"
        | "IDLE_WINDOW_NOT_REACHED"
        | "SINGLE_TASK_LIMIT"
        | "SESSION_TASK_BUDGET_EXHAUSTED"
        | "SESSION_MODEL_BUDGET_EXHAUSTED"
        | "SESSION_INPUT_TOKEN_BUDGET_EXHAUSTED";
    };

function assertNonNegative(value: number, field: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${field} must be a non-negative safe integer`);
  }
}

function assertPositive(value: number, field: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TypeError(`${field} must be a positive safe integer`);
  }
}

/**
 * Tavern never inherits Game's background default. This pure gate must pass
 * immediately before constructing a read-only harness; every mutation advances
 * the host fence and makes the pending execution ineligible.
 */
export function decideTavernCausalAuditExecution(
  policy: TavernCausalAuditExecutionPolicy,
  context: TavernCausalAuditExecutionContext,
): TavernCausalAuditExecutionDecision {
  if (policy.policy_version !== TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION) {
    throw new TypeError("Unsupported Tavern causal audit execution policy version");
  }
  assertNonNegative(policy.minimum_idle_ms, "minimum_idle_ms");
  assertPositive(policy.max_tasks_per_session, "max_tasks_per_session");
  assertPositive(policy.max_model_calls_per_session, "max_model_calls_per_session");
  assertPositive(policy.max_input_tokens_per_session, "max_input_tokens_per_session");
  for (const [field, value] of Object.entries(context)) {
    if (typeof value === "number") assertNonNegative(value, field);
  }

  const blocked = (
    reason: Extract<TavernCausalAuditExecutionDecision, { status: "BLOCKED" }>["reason"],
  ): TavernCausalAuditExecutionDecision => ({
    status: "BLOCKED",
    policy_version: TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION,
    reason,
  });
  if (policy.activation_mode === "disabled") return blocked("EXECUTION_DISABLED");
  if (
    context.seed.memory_set_id !== context.current_memory_set_id ||
    context.seed.source_revision_id !== context.current_source_revision_id ||
    context.seed.source_checksum !== context.current_source_checksum ||
    context.seed.semantic_task_fingerprint !== context.current_semantic_task_fingerprint
  ) {
    return blocked("STALE_TASK_SEED");
  }
  if (
    policy.activation_mode === "manual" &&
    context.manual_task_seed_id !== context.seed.task_seed_id
  )
    return blocked("MANUAL_TRIGGER_REQUIRED");
  if (policy.activation_mode === "idle_opt_in" && !policy.unattended_opt_in_acknowledged)
    return blocked("UNATTENDED_OPT_IN_REQUIRED");
  if (context.page_lifecycle !== "visible") return blocked("PAGE_NOT_VISIBLE");
  const manualObserverQuiesced =
    policy.activation_mode === "manual" && context.manual_observer_quiesced === true;
  if (!context.observer_running && !manualObserverQuiesced) return blocked("OBSERVER_NOT_RUNNING");
  if (context.main_generation_active) return blocked("MAIN_GENERATION_ACTIVE");
  if (context.source_cycle_in_flight) return blocked("SOURCE_CYCLE_IN_FLIGHT");
  if (context.extraction_in_flight) return blocked("EXTRACTION_IN_FLIGHT");
  if (!context.mutation_fence_stable) return blocked("MUTATION_FENCE_UNSTABLE");
  if (policy.activation_mode === "idle_opt_in" && context.idle_for_ms < policy.minimum_idle_ms)
    return blocked("IDLE_WINDOW_NOT_REACHED");
  if (context.active_task_count > 0) return blocked("SINGLE_TASK_LIMIT");
  if (context.tasks_started_in_session >= policy.max_tasks_per_session)
    return blocked("SESSION_TASK_BUDGET_EXHAUSTED");
  if (context.model_calls_used_in_session >= policy.max_model_calls_per_session)
    return blocked("SESSION_MODEL_BUDGET_EXHAUSTED");
  if (context.input_tokens_used_in_session >= policy.max_input_tokens_per_session)
    return blocked("SESSION_INPUT_TOKEN_BUDGET_EXHAUSTED");
  return {
    status: "ELIGIBLE",
    policy_version: TAVERN_CAUSAL_AUDIT_EXECUTION_POLICY_VERSION,
    trigger: policy.activation_mode,
    authorization: "start_readonly_investigation_only",
    model_persistent_write_authorized: false,
  };
}
