import type { NarraMemId, RejectionReasonCode } from "@narramem/core-domain";

import type { TavernEventSubscription, TavernInjectionHandle } from "./contracts.js";
import type { TavernExtractionJobAudit } from "./extraction-job-contracts.js";
import type {
  TavernObserverMainGenerationTrigger,
  TavernObserverRecallPreparation,
} from "./observer-scheduler-contracts.js";
import type {
  TavernRecallAssemblyRequest,
  TavernRecallAssemblyResult,
} from "./recall-contracts.js";
import type {
  TavernRenderedRecallPrompt,
  TavernRuntimeRecallPromptAsset,
} from "./recall-prompt-contracts.js";
import type { TavernSemanticMetadataNormalizer } from "./source-snapshot-contracts.js";

export const TAVERN_RECALL_GENERATION_BARRIER_VERSION = "0.4.0" as const;

export const TAVERN_RECALL_INVALIDATION_EVENT_NAMES = [
  "message_swiped",
  "message_received",
  "message_edited",
  "message_deleted",
  "message_updated",
  "message_swipe_deleted",
  "chat_id_changed",
  "generation_stopped",
  "generation_ended",
] as const;

export interface TavernRecallBarrierObserverService {
  prepareForMainGeneration(
    trigger?: TavernObserverMainGenerationTrigger,
  ): Promise<TavernObserverRecallPreparation>;
}

export type TavernRecallBarrierTrigger = "USER_MESSAGE_COMMITTED" | "NO_NEW_USER_MESSAGE";

export interface TavernRecallBarrierAssemblyService {
  assemble(request: TavernRecallAssemblyRequest): Promise<TavernRecallAssemblyResult>;
}

export interface TavernRecallGenerationBarrierConfig {
  readonly token_budget: number;
  /** Put Recall immediately before the continuous window beginning at this latest AI floor. */
  readonly latest_ai_floor_count: number;
  readonly max_prepare_ms?: number;
  readonly prompt_asset: TavernRuntimeRecallPromptAsset;
  readonly principal_entity_id?: NarraMemId<"entity">;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export interface TavernRecallGenerationBarrierSnapshot {
  readonly barrier_version: typeof TAVERN_RECALL_GENERATION_BARRIER_VERSION;
  readonly lifecycle: "idle" | "running" | "stopped" | "disposed";
  readonly latest_sequence: number;
  readonly preparation_in_flight: boolean;
  readonly waiting_for_user_message: boolean;
  readonly injection_installed: boolean;
  readonly last_report: TavernRecallGenerationBarrierReport | null;
}

export type TavernRecallGenerationBarrierReport =
  | {
      readonly status: "INJECTION_INSTALLED";
      readonly sequence: number;
      readonly extraction_audit: TavernExtractionJobAudit;
      readonly memory_set_id: string;
      readonly source_checksum: string;
      readonly source_alignment: "EXACT" | "APPEND_ONLY_LIVE_TAIL";
      readonly live_tail_message_count: number;
      readonly bundle_id: NarraMemId<"recall_bundle">;
      readonly immediate_context_count: number;
      readonly causal_antecedent_count: number;
      readonly experience_echo_count: number;
      readonly active_thread_count: number;
      readonly matched_impact_count: number;
      readonly perspective_safe_entity_count: number;
      readonly rejection_reason_counts: Readonly<Record<RejectionReasonCode, number>>;
      readonly prompt_asset_ref: string;
      readonly prompt_body_sha256: string;
      readonly injection_depth: number;
      readonly elapsed_ms: number;
      readonly trigger: TavernRecallBarrierTrigger;
    }
  | {
      readonly status: "DEFERRED_TO_MESSAGE_SENT";
      readonly sequence: number;
    }
  | {
      readonly status: "SKIPPED_DRY_RUN";
      readonly sequence: number;
    }
  | {
      readonly status: "DEGRADED_NO_INJECTION";
      readonly sequence: number;
      readonly reason:
        | "NO_COMMITTED_COVERAGE"
        | "UNSAFE_SOURCE_CHANGE"
        | "DEADLINE_EXCEEDED"
        | "RECALL_UNAVAILABLE";
      readonly elapsed_ms: number;
      readonly trigger: TavernRecallBarrierTrigger;
      readonly error_name?: string;
      readonly error_message?: string;
      readonly error_code?: string;
    }
  | {
      readonly status: "INVALIDATED";
      readonly sequence: number;
      readonly reason: string;
      readonly injection_removed: boolean;
    }
  | {
      readonly status: "FAILED";
      readonly sequence: number;
      readonly error_name: string;
      readonly error_message: string;
      readonly error_code?: string;
    };

export interface TavernRecallBarrierPreparation {
  readonly extraction_audit: TavernExtractionJobAudit;
}

export interface TavernRecallBarrierRuntime {
  now_ms(): number;
  set_timer(callback: () => void, delay_ms: number): unknown;
  clear_timer(handle: unknown): void;
}

export type TavernRecallBarrierReportListener = (
  report: TavernRecallGenerationBarrierReport,
) => void;

export interface TavernRecallBarrierInstalledInjection {
  readonly rendered: TavernRenderedRecallPrompt;
  readonly handle: TavernInjectionHandle;
}

export interface TavernRecallBarrierSubscription extends TavernEventSubscription {}

export class TavernRecallGenerationBarrierError extends Error {
  constructor(
    readonly code:
      | "INVALID_CONFIG"
      | "INVALID_RUNTIME"
      | "SUBSCRIPTION_FAILED"
      | "HOST_INJECTION_UNAVAILABLE"
      | "SEMANTIC_COVERAGE_NOT_READY"
      | "DEADLINE_EXCEEDED"
      | "SUPERSEDED"
      | "DISPOSED",
    message: string,
  ) {
    super(message);
    this.name = "TavernRecallGenerationBarrierError";
  }
}
