import type { AgentTransportOperationRecord } from "@narramem/agent-runtime";

export const TAVERN_AGENT_TRANSPORT_STORE_VERSION = "0.1.0" as const;
export const TAVERN_AGENT_TRANSPORT_STORE_FORMAT = "narramem.tavern-agent-transport" as const;

export interface TavernAgentTransportResponseArtifactRecord {
  readonly artifact_ref: string;
  readonly content_sha256: string;
  readonly utf8_bytes: number;
  readonly content: string;
}

export interface TavernAgentTransportStorePayload {
  readonly format: typeof TAVERN_AGENT_TRANSPORT_STORE_FORMAT;
  readonly schema_version: typeof TAVERN_AGENT_TRANSPORT_STORE_VERSION;
  readonly memory_set_id: string;
  readonly operations: readonly AgentTransportOperationRecord[];
  readonly response_artifacts: readonly TavernAgentTransportResponseArtifactRecord[];
  readonly checksum: string;
}

export class TavernAgentTransportStoreError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "STORE_NOT_FOUND"
      | "STORE_CORRUPT"
      | "WRITE_CONFLICT"
      | "OPERATION_NOT_FOUND"
      | "RECORD_VERSION_MISMATCH"
      | "ARTIFACT_NOT_FOUND",
    message: string,
  ) {
    super(message);
    this.name = "TavernAgentTransportStoreError";
  }
}
