import type {
  EvidenceItem,
  FlatDraftCausal,
  FlatDraftEpistemic,
  FlatDraftQuote,
  FlatNarrativeExtractionDraft,
  NarraMemId,
} from "@narramem/core-domain";

export const FLAT_DRAFT_QUARANTINE_VERSION = "0.2.0" as const;

export type FlatDraftQuarantineCandidateKind =
  | "entity"
  | "event"
  | "state"
  | "epistemic"
  | "causal";

export interface FlatDraftQuarantineFinding {
  readonly code:
    | "FLAT_DRAFT_STATE_UNKNOWN_BOTH_QUARANTINED"
    | "FLAT_DRAFT_DEPENDENT_CANDIDATE_QUARANTINED"
    | "FLAT_DRAFT_UNRESOLVED_REFERENCE_REMOVED"
    | "FLAT_DRAFT_NONCONTIGUOUS_QUOTE_SPLIT";
  readonly candidate_kind: FlatDraftQuarantineCandidateKind | "unresolved_item";
  readonly candidate_key: string;
  readonly root_candidate_keys: readonly string[];
  readonly evidence_ids: readonly NarraMemId<"evidence">[];
  readonly message: string;
}

export interface FlatDraftQuarantineResult {
  readonly quarantine_version: typeof FLAT_DRAFT_QUARANTINE_VERSION;
  readonly draft: FlatNarrativeExtractionDraft;
  readonly findings: readonly FlatDraftQuarantineFinding[];
}

interface QuarantinedCandidate {
  readonly kind: FlatDraftQuarantineCandidateKind;
  readonly roots: ReadonlySet<string>;
}

function rootsFor(
  references: readonly string[],
  quarantined: ReadonlyMap<string, QuarantinedCandidate>,
): ReadonlySet<string> {
  const roots = new Set<string>();
  for (const reference of references) {
    const item = quarantined.get(reference);
    if (item === undefined) continue;
    for (const root of item.roots) roots.add(root);
  }
  return roots;
}

function epistemicReferences(epistemic: FlatDraftEpistemic): readonly string[] {
  if (epistemic.target.kind === "event" || epistemic.target.kind === "state") {
    return [epistemic.target.key];
  }
  return epistemic.target.claim.arguments.flatMap((argument) =>
    argument.kind === "event" || argument.kind === "state" ? [argument.key] : [],
  );
}

function causalReferences(causal: FlatDraftCausal): readonly string[] {
  return [...causal.causes.map((item) => item.key), ...causal.effects.map((item) => item.key)];
}

function sorted(values: ReadonlySet<string>): readonly string[] {
  return [...values].sort();
}

function occurrencePositions(text: string, quote: string): readonly number[] {
  const positions: number[] = [];
  let searchFrom = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) break;
    positions.push(index);
    searchFrom = index + Math.max(1, quote.length);
  }
  return positions;
}

function splitStrongClauses(quote: string): readonly string[] {
  return (
    quote
      .match(/[^。！？!?；;]+[。！？!?；;]?/gu)
      ?.map((item) => item.trim())
      .filter((item) => [...item].length >= 4) ?? []
  );
}

function splitNoncontiguousQuote(
  quote: FlatDraftQuote,
  evidenceById: ReadonlyMap<string, EvidenceItem>,
): readonly FlatDraftQuote[] | null {
  const evidence = evidenceById.get(quote.evidence_id);
  if (evidence?.raw_content.kind !== "text") return null;
  const exactPositions = occurrencePositions(evidence.raw_content.text, quote.quote);
  if (quote.occurrence >= 0 && quote.occurrence < exactPositions.length) return null;
  if (exactPositions.length > 0) return null;
  const clauses = splitStrongClauses(quote.quote);
  if (clauses.length < 2) return null;
  const repaired: FlatDraftQuote[] = [];
  let cursor = 0;
  for (const clause of clauses) {
    const positions = occurrencePositions(evidence.raw_content.text, clause);
    const selectedOccurrence = positions.findIndex((position) => position >= cursor);
    if (selectedOccurrence < 0) return null;
    const selectedPosition = positions[selectedOccurrence];
    if (selectedPosition === undefined) return null;
    repaired.push({
      evidence_id: quote.evidence_id,
      quote: clause,
      occurrence: selectedOccurrence,
    });
    cursor = selectedPosition + clause.length;
  }
  return repaired;
}

function normalizeQuotes(
  kind: FlatDraftQuarantineCandidateKind,
  key: string,
  quotes: readonly FlatDraftQuote[],
  evidenceById: ReadonlyMap<string, EvidenceItem>,
  findings: FlatDraftQuarantineFinding[],
): readonly FlatDraftQuote[] {
  return quotes.flatMap((quote) => {
    const repaired = splitNoncontiguousQuote(quote, evidenceById);
    if (repaired === null) return [quote];
    findings.push({
      code: "FLAT_DRAFT_NONCONTIGUOUS_QUOTE_SPLIT",
      candidate_kind: kind,
      candidate_key: key,
      root_candidate_keys: [key],
      evidence_ids: [quote.evidence_id],
      message:
        "A model-spliced quote was replaced only by its exact ordered clauses from the same Evidence",
    });
    return repaired;
  });
}

/**
 * Applies one evidence-preserving normalization, then quarantines only locally
 * impossible Flat Draft atoms and their strict dependants. Version 0.2.0 may
 * split a model-spliced quote only when every strong clause exists verbatim and
 * in order in the same Evidence. It never paraphrases or invents replacement
 * text. The root quarantine rule remains: a State with unknown before and
 * unknown after cannot describe a transition.
 */
export function quarantineFlatNarrativeExtractionDraft(
  draft: FlatNarrativeExtractionDraft,
  evidenceItems: readonly EvidenceItem[] = [],
): FlatDraftQuarantineResult {
  const quarantined = new Map<string, QuarantinedCandidate>();
  const findings: FlatDraftQuarantineFinding[] = [];
  const evidenceById = new Map(evidenceItems.map((item) => [item.evidence_id, item]));
  const normalizedDraft: FlatNarrativeExtractionDraft = {
    ...draft,
    entities: draft.entities.map((item) => ({
      ...item,
      quotes: normalizeQuotes("entity", item.key, item.quotes, evidenceById, findings),
    })),
    events: draft.events.map((item) => ({
      ...item,
      quotes: normalizeQuotes("event", item.key, item.quotes, evidenceById, findings),
    })),
    states: draft.states.map((item) => ({
      ...item,
      quotes: normalizeQuotes("state", item.key, item.quotes, evidenceById, findings),
    })),
    epistemics: draft.epistemics.map((item) => ({
      ...item,
      quotes: normalizeQuotes("epistemic", item.key, item.quotes, evidenceById, findings),
    })),
    causals: draft.causals.map((item) => ({
      ...item,
      quotes: normalizeQuotes("causal", item.key, item.quotes, evidenceById, findings),
    })),
  };

  for (const state of normalizedDraft.states) {
    if (state.before.known || state.after.known) continue;
    quarantined.set(state.key, { kind: "state", roots: new Set([state.key]) });
    findings.push({
      code: "FLAT_DRAFT_STATE_UNKNOWN_BOTH_QUARANTINED",
      candidate_kind: "state",
      candidate_key: state.key,
      root_candidate_keys: [state.key],
      evidence_ids: [...new Set(state.quotes.map((item) => item.evidence_id))],
      message: "State had unknown before and unknown after and cannot represent a transition",
    });
  }

  let changed = true;
  while (changed) {
    changed = false;
    for (const epistemic of normalizedDraft.epistemics) {
      if (quarantined.has(epistemic.key)) continue;
      const roots = rootsFor(epistemicReferences(epistemic), quarantined);
      if (roots.size === 0) continue;
      quarantined.set(epistemic.key, { kind: "epistemic", roots });
      findings.push({
        code: "FLAT_DRAFT_DEPENDENT_CANDIDATE_QUARANTINED",
        candidate_kind: "epistemic",
        candidate_key: epistemic.key,
        root_candidate_keys: sorted(roots),
        evidence_ids: [...new Set(epistemic.quotes.map((item) => item.evidence_id))],
        message: "Epistemic candidate depended on a quarantined candidate",
      });
      changed = true;
    }
    for (const causal of normalizedDraft.causals) {
      if (quarantined.has(causal.key)) continue;
      const roots = rootsFor(causalReferences(causal), quarantined);
      if (roots.size === 0) continue;
      quarantined.set(causal.key, { kind: "causal", roots });
      findings.push({
        code: "FLAT_DRAFT_DEPENDENT_CANDIDATE_QUARANTINED",
        candidate_kind: "causal",
        candidate_key: causal.key,
        root_candidate_keys: sorted(roots),
        evidence_ids: [...new Set(causal.quotes.map((item) => item.evidence_id))],
        message: "Causal candidate depended on a quarantined candidate",
      });
      changed = true;
    }
  }

  const filteredUnresolved = normalizedDraft.unresolved_items.map((item) => {
    const removed = item.related_candidate_keys.filter((key) => quarantined.has(key));
    if (removed.length === 0) return item;
    findings.push({
      code: "FLAT_DRAFT_UNRESOLVED_REFERENCE_REMOVED",
      candidate_kind: "unresolved_item",
      candidate_key: item.code,
      root_candidate_keys: sorted(rootsFor(removed, quarantined)),
      evidence_ids: item.evidence_ids,
      message: "Unresolved item reference to a quarantined candidate was removed",
    });
    return {
      ...item,
      related_candidate_keys: item.related_candidate_keys.filter((key) => !quarantined.has(key)),
    };
  });

  if (quarantined.size === 0) {
    return {
      quarantine_version: FLAT_DRAFT_QUARANTINE_VERSION,
      draft: normalizedDraft,
      findings,
    };
  }

  return {
    quarantine_version: FLAT_DRAFT_QUARANTINE_VERSION,
    draft: {
      ...normalizedDraft,
      states: normalizedDraft.states.filter((item) => !quarantined.has(item.key)),
      epistemics: normalizedDraft.epistemics.filter((item) => !quarantined.has(item.key)),
      causals: normalizedDraft.causals.filter((item) => !quarantined.has(item.key)),
      unresolved_items: filteredUnresolved,
    },
    findings,
  };
}
