import { getNarraMemIdKind, type NarraMemId } from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";
import type {
  TavernCausalAuditAuthorizationResult,
  TavernCausalAuditCandidateTask,
} from "./causal-audit-candidate.js";
import { createTavernCausalAuditReadonlyCorpus } from "./causal-audit-investigation.js";
import { createTavernCausalAuditAgentTaskId } from "./causal-audit-task-mapping.js";
import type { TavernHostPort, TavernJsonValue } from "./contracts.js";
import { reconstructTavernSourceSnapshot } from "./current-archive.js";
import { TavernMemoryRegistry } from "./memory-registry.js";
import { reconcileTavernSourceSnapshot } from "./source-snapshot.js";
import type { TavernSemanticMetadataNormalizer } from "./source-snapshot-contracts.js";
import { canonicalJson } from "./worldbook-codec.js";
import { TavernWorldbookSnapshotStore } from "./worldbook-snapshot-store.js";
import type {
  TavernArchiveRecord,
  TavernControlPayload,
  TavernDurableCommitPhase,
} from "./worldbook-store-contracts.js";

export const TAVERN_CAUSAL_AUDIT_ARCHIVE_COMMIT_VERSION = "0.1.0" as const;
export const TAVERN_CAUSAL_AUDIT_RECEIPT_FORMAT = "narramem.tavern-causal-audit-receipt" as const;
export const TAVERN_CAUSAL_AUDIT_RECEIPT_RECORD_KIND = "tavern_causal_audit_receipt_v1" as const;
const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";
const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const TASK_SEED_PATTERN = /^tavern_causal_audit_seed_[a-f0-9]{64}$/u;

export type AuthorizedTavernCausalAuditCandidate = Extract<
  TavernCausalAuditAuthorizationResult,
  { readonly status: "authorized" }
>;

export interface TavernCausalAuditArchiveCommitRequest {
  readonly task: TavernCausalAuditCandidateTask;
  readonly authorization: AuthorizedTavernCausalAuditCandidate;
  readonly expected_control_checksum: string;
  readonly expected_active_view_id: string;
  readonly transaction_id: string;
  readonly writer_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
  readonly after_durable_phase?: (phase: TavernDurableCommitPhase) => void | Promise<void>;
}

export interface TavernCausalAuditArchiveCommitResult {
  readonly status: "committed" | "already_committed";
  readonly control: TavernControlPayload;
  readonly authorized_changeset_id: NarraMemId<"change_set">;
  readonly causal_link_ids: readonly NarraMemId<"causal_link">[];
  readonly archive_record_count: number;
}

export interface TavernCausalAuditCommitReceipt {
  readonly format: typeof TAVERN_CAUSAL_AUDIT_RECEIPT_FORMAT;
  readonly schema_version: typeof TAVERN_CAUSAL_AUDIT_ARCHIVE_COMMIT_VERSION;
  readonly task_seed_id: string;
  readonly agent_task_id: NarraMemId<"investigation">;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly candidate_artifact_sha256: string;
  readonly authorized_changeset_id: NarraMemId<"change_set">;
  readonly causal_link_ids: readonly NarraMemId<"causal_link">[];
}

export class TavernCausalAuditArchiveCommitError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "MEMORY_SET_NOT_EXACT"
      | "STALE_TASK"
      | "ARCHIVE_CONFLICT"
      | "FOREIGN_PENDING_TRANSACTION"
      | "SOURCE_CHANGED_DURING_COMMIT",
    message: string,
  ) {
    super(message);
    this.name = "TavernCausalAuditArchiveCommitError";
  }
}

function asJsonValue(value: unknown): TavernJsonValue {
  canonicalJson(value);
  return value as TavernJsonValue;
}

function receiptRecordId(changesetId: NarraMemId<"change_set">): string {
  return `audit_receipt_${changesetId}`;
}

function targetRecords(
  request: TavernCausalAuditArchiveCommitRequest,
): readonly TavernArchiveRecord[] {
  const { authorization } = request;
  const authorizedWire = validateWireValue(
    "authorized_change_set",
    authorization.authorized_changeset,
  );
  if (!authorizedWire.valid) {
    throw new TavernCausalAuditArchiveCommitError(
      "INVALID_INPUT",
      "Causal Audit AuthorizedChangeSet failed its Core wire boundary",
    );
  }
  const linksById = new Map<string, string>();
  const records: TavernArchiveRecord[] = [];
  for (const link of authorization.causal_links) {
    const wire = validateWireValue("causal_link", link);
    if (!wire.valid || linksById.has(link.causal_id)) {
      throw new TavernCausalAuditArchiveCommitError(
        "INVALID_INPUT",
        "Causal Audit authorization contains an invalid or duplicate CausalLink",
      );
    }
    linksById.set(link.causal_id, canonicalJson(link));
    records.push({
      record_id: link.causal_id,
      record_kind: "core_causal_link_v1",
      payload: asJsonValue(link),
    });
  }
  const operationLinks = authorization.authorized_changeset.operations.flatMap((operation) =>
    operation.op === "add_derived" && "causal_id" in operation.record ? [operation.record] : [],
  );
  if (
    operationLinks.length !== authorization.authorized_changeset.operations.length ||
    operationLinks.length !== linksById.size ||
    operationLinks.some((link) => linksById.get(link.causal_id) !== canonicalJson(link))
  ) {
    throw new TavernCausalAuditArchiveCommitError(
      "INVALID_INPUT",
      "AuthorizedChangeSet operations do not exactly match the trusted CausalLinks",
    );
  }
  records.push({
    record_id: authorization.authorized_changeset.changeset_id,
    record_kind: "core_authorized_changeset_v1",
    payload: asJsonValue(authorization.authorized_changeset),
  });
  const receipt: TavernCausalAuditCommitReceipt = {
    format: TAVERN_CAUSAL_AUDIT_RECEIPT_FORMAT,
    schema_version: TAVERN_CAUSAL_AUDIT_ARCHIVE_COMMIT_VERSION,
    task_seed_id: request.task.seed.task_seed_id,
    agent_task_id: request.task.task_id,
    source_revision_id: request.task.seed.source_revision_id,
    source_checksum: request.task.seed.source_checksum,
    candidate_artifact_sha256: authorization.candidate_artifact_sha256,
    authorized_changeset_id: authorization.authorized_changeset.changeset_id,
    causal_link_ids: authorization.causal_links.map((link) => link.causal_id),
  };
  records.push({
    record_id: receiptRecordId(authorization.authorized_changeset.changeset_id),
    record_kind: TAVERN_CAUSAL_AUDIT_RECEIPT_RECORD_KIND,
    payload: asJsonValue(receipt),
  });
  return records;
}

function isObject(value: unknown): value is Readonly<Record<string, unknown>> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function hasOnlyKeys(value: Readonly<Record<string, unknown>>, allowed: readonly string[]) {
  const allowedSet = new Set(allowed);
  return Object.keys(value).every((key) => allowedSet.has(key));
}

function decodeReceipt(value: unknown): TavernCausalAuditCommitReceipt | null {
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "format",
      "schema_version",
      "task_seed_id",
      "agent_task_id",
      "source_revision_id",
      "source_checksum",
      "candidate_artifact_sha256",
      "authorized_changeset_id",
      "causal_link_ids",
    ]) ||
    value.format !== TAVERN_CAUSAL_AUDIT_RECEIPT_FORMAT ||
    value.schema_version !== TAVERN_CAUSAL_AUDIT_ARCHIVE_COMMIT_VERSION ||
    typeof value.task_seed_id !== "string" ||
    !TASK_SEED_PATTERN.test(value.task_seed_id) ||
    typeof value.agent_task_id !== "string" ||
    getNarraMemIdKind(value.agent_task_id) !== "investigation" ||
    typeof value.source_revision_id !== "string" ||
    getNarraMemIdKind(value.source_revision_id) !== "source_revision" ||
    typeof value.source_checksum !== "string" ||
    !SHA256_PATTERN.test(value.source_checksum) ||
    typeof value.candidate_artifact_sha256 !== "string" ||
    !SHA256_PATTERN.test(value.candidate_artifact_sha256) ||
    typeof value.authorized_changeset_id !== "string" ||
    getNarraMemIdKind(value.authorized_changeset_id) !== "change_set" ||
    !Array.isArray(value.causal_link_ids) ||
    value.causal_link_ids.length === 0 ||
    value.causal_link_ids.some(
      (id) => typeof id !== "string" || getNarraMemIdKind(id) !== "causal_link",
    ) ||
    new Set(value.causal_link_ids).size !== value.causal_link_ids.length
  ) {
    return null;
  }
  return value as unknown as TavernCausalAuditCommitReceipt;
}

export function readTavernCausalAuditCommitReceipt(
  records: readonly TavernArchiveRecord[],
  taskSeedId: string,
): TavernCausalAuditCommitReceipt | null {
  const matching = records.flatMap((record) => {
    if (record.record_kind !== TAVERN_CAUSAL_AUDIT_RECEIPT_RECORD_KIND) return [];
    const receipt = decodeReceipt(record.payload);
    if (receipt === null || record.record_id !== receiptRecordId(receipt.authorized_changeset_id)) {
      throw new TavernCausalAuditArchiveCommitError(
        "ARCHIVE_CONFLICT",
        `Archive contains an invalid Causal Audit receipt: ${record.record_id}`,
      );
    }
    return receipt.task_seed_id === taskSeedId ? [receipt] : [];
  });
  if (matching.length > 1) {
    throw new TavernCausalAuditArchiveCommitError(
      "ARCHIVE_CONFLICT",
      "Archive contains multiple receipts for one Causal Audit task",
    );
  }
  return matching[0] ?? null;
}

function mergeTargetRecords(
  activeRecords: readonly TavernArchiveRecord[],
  targets: readonly TavernArchiveRecord[],
):
  | { readonly status: "append"; readonly records: readonly TavernArchiveRecord[] }
  | { readonly status: "already_committed" } {
  const activeById = new Map(activeRecords.map((record) => [record.record_id, record]));
  let exactMatches = 0;
  for (const target of targets) {
    const existing = activeById.get(target.record_id);
    if (existing === undefined) continue;
    if (
      existing.record_kind !== target.record_kind ||
      canonicalJson(existing.payload) !== canonicalJson(target.payload)
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "ARCHIVE_CONFLICT",
        `Archive record ${target.record_id} collides with a different payload`,
      );
    }
    exactMatches += 1;
  }
  if (exactMatches === targets.length) return { status: "already_committed" };
  if (exactMatches !== 0) {
    throw new TavernCausalAuditArchiveCommitError(
      "ARCHIVE_CONFLICT",
      "Active archive contains only part of the atomic Causal Audit commit",
    );
  }
  return { status: "append", records: [...activeRecords, ...targets] };
}

export class TavernCausalAuditArchiveCommitService {
  private readonly registry: TavernMemoryRegistry;

  constructor(
    private readonly port: TavernHostPort,
    private readonly segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.registry = new TavernMemoryRegistry(port);
  }

  async commit(
    request: TavernCausalAuditArchiveCommitRequest,
  ): Promise<TavernCausalAuditArchiveCommitResult> {
    const expectedTaskId = await createTavernCausalAuditAgentTaskId(request.task.seed);
    if (
      request.task.task_id !== expectedTaskId ||
      request.authorization.authorized_changeset.based_on_revision_id !==
        request.task.corpus.snapshot_revision_id ||
      request.authorization.authorized_changeset.memory_space_id !==
        request.task.corpus.memory_space_id ||
      request.authorization.authorized_changeset.branch_id !== request.task.corpus.branch_id
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "INVALID_INPUT",
        "Causal Audit authorization does not belong to its frozen Tavern task",
      );
    }
    const targets = targetRecords(request);
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (
      resolution.status !== "EXACT" ||
      resolution.selected === null ||
      resolution.selected.control.memory_set_id !== request.task.seed.memory_set_id
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "MEMORY_SET_NOT_EXACT",
        `Causal Audit commit requires its exact Memory Set, received ${resolution.status}`,
      );
    }
    const selected = resolution.selected;
    const store = new TavernWorldbookSnapshotStore(this.port, {
      memory_set_id: selected.control.memory_set_id,
      control_book_name: selected.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${selected.control.memory_set_id}__`,
      initial_identity_anchor: selected.control.identity_anchor,
      max_records_per_segment: this.segmentLimits.max_records_per_segment,
      max_segment_utf8_bytes: this.segmentLimits.max_segment_utf8_bytes,
    });
    let control = await store.readControl();
    let activeRecords = await store.readActiveSnapshot();
    let sourceSnapshot = await reconstructTavernSourceSnapshot(
      activeRecords,
      request.task.seed.memory_set_id,
    );
    await this.assertCurrentSource(request, control, sourceSnapshot);

    if (control.pending_transaction !== null) {
      if (control.pending_transaction.transaction_id !== request.transaction_id) {
        throw new TavernCausalAuditArchiveCommitError(
          "FOREIGN_PENDING_TRANSACTION",
          "A different World Book archive transaction requires recovery",
        );
      }
      await store.recover({
        current_source_revision: sourceSnapshot.source_revision,
        current_source_checksum: sourceSnapshot.checksum,
        exclusive_writer_confirmed: true,
      });
      control = await store.readControl();
      activeRecords = await store.readActiveSnapshot();
      sourceSnapshot = await reconstructTavernSourceSnapshot(
        activeRecords,
        request.task.seed.memory_set_id,
      );
      await this.assertCurrentSource(request, control, sourceSnapshot);
    }

    const merged = mergeTargetRecords(activeRecords, targets);
    if (merged.status === "already_committed") {
      return this.result("already_committed", control, request, activeRecords.length);
    }
    if (
      control.checksum !== request.expected_control_checksum ||
      control.active_view?.view_id !== request.expected_active_view_id ||
      control.pending_transaction !== null
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "STALE_TASK",
        "World Book Control changed after the Causal Audit task was frozen",
      );
    }
    const currentCorpus = await createTavernCausalAuditReadonlyCorpus(
      request.task.seed,
      activeRecords,
    );
    if (
      currentCorpus.snapshot_revision_id !== request.task.corpus.snapshot_revision_id ||
      currentCorpus.snapshot_fingerprint.value !== request.task.corpus.snapshot_fingerprint.value
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "STALE_TASK",
        "Active Core archive changed after the Causal Audit investigation",
      );
    }
    const committed = await store.commitFullSnapshot({
      transaction_id: request.transaction_id,
      writer_id: request.writer_id,
      build_id: request.build_id,
      view_id: request.view_id,
      source_revision: sourceSnapshot.source_revision,
      source_checksum: sourceSnapshot.checksum,
      expected_commit_sequence: control.commit_sequence,
      expected_view_id: control.active_view.view_id,
      records: merged.records,
      after_durable_phase: async (phase) => {
        if (phase === "pending_recorded" || phase === "pointer_committed") {
          const stability = await reconcileTavernSourceSnapshot(this.port, {
            memory_set_id: sourceSnapshot.memory_set_id,
            previous_snapshot: sourceSnapshot,
            observed_hints: [],
            ...(request.normalize_semantic_metadata === undefined
              ? {}
              : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
          });
          if (stability.status !== "UNCHANGED") {
            throw new TavernCausalAuditArchiveCommitError(
              "SOURCE_CHANGED_DURING_COMMIT",
              `Current chat changed during Causal Audit ${phase}`,
            );
          }
        }
        await request.after_durable_phase?.(phase);
      },
    });
    return this.result("committed", committed.control, request, merged.records.length);
  }

  private async assertCurrentSource(
    request: TavernCausalAuditArchiveCommitRequest,
    control: TavernControlPayload,
    sourceSnapshot: Awaited<ReturnType<typeof reconstructTavernSourceSnapshot>>,
  ): Promise<void> {
    if (
      control.active_view === null ||
      control.active_view.source_revision !== sourceSnapshot.source_revision ||
      control.active_view.source_checksum !== sourceSnapshot.checksum ||
      sourceSnapshot.checksum !== request.task.seed.source_checksum
    ) {
      throw new TavernCausalAuditArchiveCommitError(
        "STALE_TASK",
        "Causal Audit source no longer matches the active World Book archive",
      );
    }
    const stability = await reconcileTavernSourceSnapshot(this.port, {
      memory_set_id: sourceSnapshot.memory_set_id,
      previous_snapshot: sourceSnapshot,
      observed_hints: [],
      ...(request.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
    });
    if (stability.status !== "UNCHANGED") {
      throw new TavernCausalAuditArchiveCommitError(
        "STALE_TASK",
        "Current Tavern chat changed before the Causal Audit commit",
      );
    }
  }

  private result(
    status: TavernCausalAuditArchiveCommitResult["status"],
    control: TavernControlPayload,
    request: TavernCausalAuditArchiveCommitRequest,
    archiveRecordCount: number,
  ): TavernCausalAuditArchiveCommitResult {
    return {
      status,
      control,
      authorized_changeset_id: request.authorization.authorized_changeset.changeset_id,
      causal_link_ids: request.authorization.causal_links.map((link) => link.causal_id),
      archive_record_count: archiveRecordCount,
    };
  }
}
