import type {
  FlatLifecycleTrigger,
  FlatLifecycleTriggerCondition,
  FlatNarrativeLifecycleDraftV020,
  FutureImpactState,
  NarraMemId,
  NarrativeThreadState,
  TriggerRule,
} from "@narramem/core-domain";
import { getNarraMemIdKind } from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";
import { createTavernLifecycleThreadId } from "./narrative-lifecycle.js";
import type {
  TavernNarrativeLifecycleModelInput,
  TavernNarrativeLifecycleSpec,
} from "./narrative-lifecycle-contracts.js";
import {
  TAVERN_NARRATIVE_LIFECYCLE_VERSION,
  TavernNarrativeLifecycleError,
} from "./narrative-lifecycle-contracts.js";
import { checksumJson } from "./worldbook-codec.js";

function assertReference<T extends NarraMemId>(value: T, known: ReadonlySet<T>, label: string): T {
  if (!known.has(value)) {
    throw new TavernNarrativeLifecycleError("INVALID_INPUT", `${label} references an unknown ID`);
  }
  return value;
}

function expectedStateValue(
  condition: Extract<
    FlatLifecycleTriggerCondition,
    { readonly kind: "entity_state" | "relationship_state" }
  >,
) {
  if (condition.comparison === "exists") {
    if (condition.expected !== undefined) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        "An exists lifecycle condition must omit expected",
      );
    }
    return {};
  }
  if (condition.expected === undefined) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "A non-exists lifecycle condition requires expected",
    );
  }
  return { expected: condition.expected };
}

function baseRule(
  condition: FlatLifecycleTriggerCondition,
  entityIds: ReadonlySet<NarraMemId<"entity">>,
  eventIds: ReadonlySet<NarraMemId<"event">>,
  threadIds: ReadonlyMap<string, NarraMemId<"narrative_thread">>,
): TriggerRule {
  switch (condition.kind) {
    case "event_type":
      return { op: "event_type", event_type: condition.event_type };
    case "entity_involved":
      return {
        op: "entity_involved",
        entity_id: assertReference(condition.entity_id, entityIds, "entity_involved"),
      };
    case "object_present":
      return {
        op: "object_present",
        object_id: assertReference(condition.object_id, entityIds, "object_present"),
      };
    case "location_is":
      return {
        op: "location_is",
        location_id: assertReference(condition.location_id, entityIds, "location_is"),
      };
    case "entity_state":
      return {
        op: "state_predicate",
        predicate: {
          subject: {
            kind: "entity",
            entity_id: assertReference(condition.entity_id, entityIds, "entity_state"),
          },
          state_key: condition.state_key,
          comparison: condition.comparison,
          ...expectedStateValue(condition),
        },
      };
    case "relationship_state":
      return {
        op: "relationship_predicate",
        predicate: {
          subject: {
            kind: "relation",
            relation_type: condition.relation_type,
            participant_ids: condition.participant_ids.map((entityId) =>
              assertReference(entityId, entityIds, "relationship_state"),
            ),
          },
          state_key: condition.state_key,
          comparison: condition.comparison,
          ...expectedStateValue(condition),
        },
      };
    case "thread_state": {
      const threadId = threadIds.get(condition.thread_candidate_key);
      if (threadId === undefined) {
        throw new TavernNarrativeLifecycleError(
          "INVALID_INPUT",
          "thread_state references an unknown thread candidate",
        );
      }
      return {
        op: "thread_state",
        predicate: { thread_id: threadId, state_in: condition.state_in },
      };
    }
    case "elapsed_turns":
      if (
        (condition.comparison === "between" &&
          (condition.upper_amount === undefined || condition.upper_amount < condition.amount)) ||
        (condition.comparison !== "between" && condition.upper_amount !== undefined)
      ) {
        throw new TavernNarrativeLifecycleError(
          "INVALID_INPUT",
          "elapsed_turns has an invalid upper_amount",
        );
      }
      return {
        op: "elapsed_story_time",
        predicate: {
          since_ref: assertReference(condition.since_event_id, eventIds, "elapsed_turns"),
          comparison: condition.comparison,
          amount: condition.amount,
          ...(condition.upper_amount === undefined ? {} : { upper_amount: condition.upper_amount }),
          unit: "turn",
        },
      };
    case "semantic_cue":
      return { op: "semantic_cue", cue: condition.cue, strength: "soft" };
  }
}

function translateTrigger(
  trigger: FlatLifecycleTrigger,
  entityIds: ReadonlySet<NarraMemId<"entity">>,
  eventIds: ReadonlySet<NarraMemId<"event">>,
  threadIds: ReadonlyMap<string, NarraMemId<"narrative_thread">>,
): TriggerRule {
  const rules = trigger.conditions.map((condition) => {
    const rule = baseRule(condition, entityIds, eventIds, threadIds);
    return condition.negated ? ({ op: "not", rule } as const) : rule;
  });
  return trigger.match === "all" ? { op: "all", rules } : { op: "any", rules };
}

export interface TavernNarrativeLifecycleCandidateCompilation {
  readonly spec: TavernNarrativeLifecycleSpec;
  readonly unresolved_items: FlatNarrativeLifecycleDraftV020["unresolved_items"];
}

const THREAD_TRANSITIONS: Readonly<Record<NarrativeThreadState, readonly NarrativeThreadState[]>> =
  {
    latent: ["latent", "open", "armed", "abandoned", "superseded"],
    open: ["open", "armed", "triggered", "resolved", "failed", "abandoned", "superseded"],
    armed: ["armed", "triggered", "resolved", "failed", "abandoned", "superseded"],
    triggered: ["triggered", "resolved", "failed", "abandoned", "superseded"],
    resolved: ["resolved"],
    failed: ["failed"],
    abandoned: ["abandoned"],
    superseded: ["superseded"],
  };

const IMPACT_TRANSITIONS: Readonly<Record<FutureImpactState, readonly FutureImpactState[]>> = {
  candidate: [
    "candidate",
    "armed",
    "matched",
    "surfaced",
    "realized",
    "expired",
    "cancelled",
    "superseded",
  ],
  armed: ["armed", "matched", "surfaced", "realized", "expired", "cancelled", "superseded"],
  matched: ["matched", "surfaced", "realized", "expired", "cancelled", "superseded"],
  surfaced: ["surfaced", "realized", "expired", "cancelled", "superseded"],
  realized: ["realized"],
  expired: ["expired"],
  cancelled: ["cancelled"],
  superseded: ["superseded"],
};

function assertExactCoverage(
  expected: ReadonlySet<string>,
  actual: readonly string[],
  label: string,
) {
  if (
    new Set(actual).size !== actual.length ||
    actual.length !== expected.size ||
    actual.some((id) => !expected.has(id))
  ) {
    throw new TavernNarrativeLifecycleError(
      "LIFECYCLE_CONTINUITY_UNEXPLAINED",
      `${label} dispositions must cover every authenticated prior record exactly once`,
    );
  }
}

function eventIsAfterBoundary(
  event: { readonly source_range: { readonly end: { readonly ordinal: number } } },
  boundary: number | null,
): boolean {
  return boundary !== null && event.source_range.end.ordinal > boundary;
}

export async function compileFlatNarrativeLifecycleDraft(
  value: unknown,
  input: TavernNarrativeLifecycleModelInput,
  memorySetId: string,
): Promise<TavernNarrativeLifecycleCandidateCompilation> {
  const report = validateWireValue("flat_narrative_lifecycle_draft_v020", value);
  if (!report.valid) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      `Lifecycle response failed Wire Schema: ${report.errors[0]?.message ?? "invalid"}`,
    );
  }
  const draft = value as FlatNarrativeLifecycleDraftV020;
  if (draft.source_revision_id !== input.source_revision_id) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Lifecycle response targets another source revision",
    );
  }
  const priorThreads = new Map(input.prior_threads.map((thread) => [thread.thread_id, thread]));
  const priorImpacts = new Map(
    input.prior_future_impacts.map((impact) => [impact.impact_id, impact]),
  );
  assertExactCoverage(
    new Set(priorThreads.keys()),
    draft.prior_thread_dispositions.map((item) => item.prior_thread_id),
    "Thread",
  );
  assertExactCoverage(
    new Set(priorImpacts.keys()),
    draft.prior_future_impact_dispositions.map((item) => item.prior_impact_id),
    "FutureImpact",
  );
  const eventMap = new Map(input.events.map((event) => [event.event_id, event]));
  const deltaMap = new Map(input.state_deltas.map((delta) => [delta.delta_id, delta]));
  for (const item of draft.prior_thread_dispositions) {
    const prior = priorThreads.get(item.prior_thread_id) as (typeof input.prior_threads)[number];
    const changed = item.next_state !== prior.state;
    const events = item.transition_event_ids.map((id) => eventMap.get(id));
    if (
      !THREAD_TRANSITIONS[prior.state].includes(item.next_state) ||
      events.some((event) => event === undefined) ||
      (changed &&
        (events.length === 0 ||
          !events.some(
            (event) =>
              event !== undefined &&
              eventIsAfterBoundary(event, input.append_evidence_boundary_ordinal),
          ))) ||
      (!changed && events.length !== 0)
    ) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Thread ${item.prior_thread_id} has an illegal or unsupported lifecycle transition`,
      );
    }
  }
  for (const item of draft.prior_future_impact_dispositions) {
    const prior = priorImpacts.get(
      item.prior_impact_id,
    ) as (typeof input.prior_future_impacts)[number];
    const changed = item.next_state !== prior.state;
    const references = item.transition_refs.map((reference) => ({
      reference,
      value:
        reference.kind === "event"
          ? eventMap.get(reference.event_id)
          : deltaMap.get(reference.delta_id),
    }));
    const hasAppendedEvidence = references.some(({ reference, value }) => {
      if (value === undefined) return false;
      if (reference.kind === "event") {
        return eventIsAfterBoundary(
          value as (typeof input.events)[number],
          input.append_evidence_boundary_ordinal,
        );
      }
      const delta = value as (typeof input.state_deltas)[number];
      return [...(delta.caused_by ?? []), ...(delta.cooccurs_with ?? [])].some((eventId) => {
        const event = eventMap.get(eventId);
        return (
          event !== undefined && eventIsAfterBoundary(event, input.append_evidence_boundary_ordinal)
        );
      });
    });
    if (
      !IMPACT_TRANSITIONS[prior.state].includes(item.next_state) ||
      references.some(({ value: reference }) => reference === undefined) ||
      (changed && (references.length === 0 || !hasAppendedEvidence)) ||
      (!changed && references.length !== 0)
    ) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `FutureImpact ${item.prior_impact_id} has an illegal or unsupported lifecycle transition`,
      );
    }
  }
  const allKeys = [...draft.new_threads, ...draft.new_future_impacts].map(
    (item) => item.candidate_key,
  );
  if (new Set(allKeys).size !== allKeys.length) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Lifecycle candidate keys must be globally unique",
    );
  }
  const entityIds = new Set(input.entities.map((entity) => entity.entity_id));
  const eventIds = new Set(eventMap.keys());
  const deltaIds = new Set(input.state_deltas.map((delta) => delta.delta_id));
  const threadIds = new Map<string, NarraMemId<"narrative_thread">>();
  for (const thread of draft.new_threads) {
    threadIds.set(
      thread.candidate_key,
      await createTavernLifecycleThreadId(memorySetId, thread.candidate_key),
    );
  }
  const threads = draft.new_threads.map((thread) => ({
    spec_key: thread.candidate_key,
    kind: thread.kind,
    title: thread.title,
    participant_ids: thread.participant_ids.map((id) =>
      assertReference(id, entityIds, "thread participant"),
    ),
    opened_by: thread.opened_by_event_ids.map((id) =>
      assertReference(id, eventIds, "thread opening"),
    ),
    initial_state: thread.initial_state,
    ...(thread.expected_payoff === undefined ? {} : { expected_payoff: thread.expected_payoff }),
    trigger_rules: [translateTrigger(thread.trigger, entityIds, eventIds, threadIds)],
  }));
  const futureImpacts = draft.new_future_impacts.map((impact) => ({
    spec_key: impact.candidate_key,
    origin_refs: impact.origin_refs.map((origin) => {
      if (origin.kind === "event") {
        return assertReference(origin.event_id, eventIds, "impact origin");
      }
      if (origin.kind === "state_delta") {
        return assertReference(origin.delta_id, deltaIds, "impact origin");
      }
      const threadId = threadIds.get(origin.thread_candidate_key);
      if (threadId === undefined) {
        throw new TavernNarrativeLifecycleError(
          "INVALID_INPUT",
          "Impact origin references an unknown thread candidate",
        );
      }
      return threadId;
    }),
    target_refs: impact.target_ids.map((id) => assertReference(id, entityIds, "impact target")),
    initial_state: impact.initial_state,
    trigger: translateTrigger(impact.trigger, entityIds, eventIds, threadIds),
    possible_effects: impact.possible_effects.map((effect) => ({
      epistemic_status: "hypothetical" as const,
      kind: effect.kind,
      description: effect.description,
      target_refs: effect.target_ids.map((id) => assertReference(id, entityIds, "effect target")),
      ...(effect.state_key === undefined ? {} : { state_key: effect.state_key }),
      ...(effect.proposed_value === undefined ? {} : { proposed_value: effect.proposed_value }),
    })),
    direction: impact.direction,
    priority: impact.priority,
    ...(impact.expires_when === undefined
      ? {}
      : {
          expires_when: translateTrigger(impact.expires_when, entityIds, eventIds, threadIds),
        }),
  }));
  for (const item of draft.unresolved_items) {
    if (item.related_refs.some((id) => getNarraMemIdKind(id) === undefined)) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        "Lifecycle unresolved item contains an invalid record reference",
      );
    }
  }
  return {
    spec: {
      contract_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
      spec_id: await checksumJson(draft),
      source_revision_id: draft.source_revision_id,
      prior_thread_dispositions: draft.prior_thread_dispositions,
      prior_future_impact_dispositions: draft.prior_future_impact_dispositions,
      threads,
      future_impacts: futureImpacts,
    },
    unresolved_items: draft.unresolved_items,
  };
}
