import type {
  InvestigationAction,
  InvestigationStopReason,
  InvestigationToolName,
  InvestigationTranscriptStep,
} from "./agent.js";
import type { CausalEffectRef, CausalNecessity, CausalRelation } from "./causal.js";
import type { CandidateEvidenceQuote } from "./extraction.js";
import type { HashDigest } from "./hash.js";
import type { NarraMemId } from "./ids.js";
import type { JsonValue } from "./json.js";
import type { QualitativeMagnitude } from "./state.js";
import type { TemporalExtent } from "./time.js";

export const CAUSAL_AUDIT_CANDIDATE_CONTRACT_VERSION = "0.1.0" as const;
export const CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION = "0.2.0" as const;
export const CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION_V030 = "0.3.0" as const;
export const CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION = "0.1.0" as const;
export const CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION_V020 = "0.2.0" as const;
export const CAUSAL_AUDIT_AGENT_FINAL_CHOICE_INPUT_VERSION_V030 = "0.3.0" as const;
export const CAUSAL_AUDIT_FINAL_OPTION_CATALOG_VERSION = "0.1.0" as const;
export const FLAT_CAUSAL_AUDIT_FINAL_DRAFT_VERSION = "0.1.0" as const;

export const CAUSAL_AUDIT_NO_SUPPORTED_REASON_CODES = [
  "reported_claim_without_attributable_belief",
  "cooccurrence_or_sequence_only",
  "counterevidence_blocks_link",
  "no_explicit_endpoint_link",
] as const;

export type CausalAuditNoSupportedReasonCode =
  (typeof CAUSAL_AUDIT_NO_SUPPORTED_REASON_CODES)[number];

export const CAUSAL_AUDIT_UNRESOLVED_REASON_CODES = [
  "cause_endpoint_missing",
  "effect_endpoint_missing",
  "endpoint_provenance_missing",
  "causal_quote_missing",
  "attribution_ambiguous",
  "contradictory_evidence",
  "investigation_budget_exhausted",
  "tool_result_incomplete",
] as const;

export type CausalAuditUnresolvedReasonCode = (typeof CAUSAL_AUDIT_UNRESOLVED_REASON_CODES)[number];

/** Existing durable records only. Free-form condition claims are deliberately excluded. */
export type CausalAuditCandidateCauseRef =
  | { readonly kind: "event"; readonly event_id: NarraMemId<"event"> }
  | {
      readonly kind: "state_assertion";
      readonly assertion_id: NarraMemId<"state_assertion">;
    }
  | { readonly kind: "state_delta"; readonly delta_id: NarraMemId<"state_delta"> }
  | {
      readonly kind: "epistemic_state";
      readonly epistemic_id: NarraMemId<"epistemic_state">;
    }
  | { readonly kind: "proposition"; readonly proposition_id: NarraMemId<"proposition"> }
  | {
      readonly kind: "narrative_thread";
      readonly thread_id: NarraMemId<"narrative_thread">;
    };

export type CausalAuditCandidateEffectRef = CausalEffectRef;

/** The trusted compiler maps attribution to CausalLink.scope and holder. */
export type CausalAuditCandidateAttribution =
  | { readonly kind: "narrator_claim" }
  | {
      readonly kind: "character_belief";
      readonly holder_entity_id: NarraMemId<"entity">;
    };

export interface CausalAuditLinkCandidate {
  readonly candidate_key: string;
  readonly cause_refs: readonly CausalAuditCandidateCauseRef[];
  readonly effect_refs: readonly CausalAuditCandidateEffectRef[];
  readonly relation: CausalRelation;
  readonly mechanism: string;
  readonly attribution: CausalAuditCandidateAttribution;
  readonly necessity: CausalNecessity;
  readonly strength: QualitativeMagnitude;
  readonly persistence?: TemporalExtent;
  readonly evidence_quotes: readonly CandidateEvidenceQuote[];
  readonly support_level: "explicit";
}

/**
 * Untrusted Agent output. It can select current record IDs and exact Evidence
 * quotes, but cannot provide final Causal IDs, scope, authority, confidence,
 * hashes, DerivationMeta, MemorySpace/branch scope, or write operations.
 */
export interface CausalAuditCandidateBatch {
  readonly contract_version: typeof CAUSAL_AUDIT_CANDIDATE_CONTRACT_VERSION;
  readonly task_id: string;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly causal_links: readonly CausalAuditLinkCandidate[];
}

/**
 * Untrusted model decision after a read-only investigation. Only the candidate
 * variant can enter the trusted compiler. Negative and unresolved variants are
 * bounded task outcomes and never become narrative facts.
 */
export type CausalAuditFinalDecision =
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION;
      readonly decision: "candidate";
      readonly candidate: CausalAuditCandidateBatch;
    }
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION;
      readonly decision: "no_supported_causal";
      readonly task_id: string;
      readonly source_revision_id: NarraMemId<"source_revision">;
      readonly reason_code: CausalAuditNoSupportedReasonCode;
      readonly reviewed_record_refs: readonly NarraMemId[];
      readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
    }
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION;
      readonly decision: "unresolved";
      readonly task_id: string;
      readonly source_revision_id: NarraMemId<"source_revision">;
      readonly reason_code: CausalAuditUnresolvedReasonCode;
      readonly about_refs: readonly NarraMemId[];
      readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
    };

/** v0.3 changes final authorization semantics, not the Candidate payload. */
export type CausalAuditFinalDecisionV030 =
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION_V030;
      readonly decision: "candidate";
      readonly candidate: CausalAuditCandidateBatch;
    }
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION_V030;
      readonly decision: "no_supported_causal";
      readonly task_id: string;
      readonly source_revision_id: NarraMemId<"source_revision">;
      readonly reason_code: CausalAuditNoSupportedReasonCode;
      readonly reviewed_record_refs: readonly NarraMemId[];
      readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
    }
  | {
      readonly contract_version: typeof CAUSAL_AUDIT_FINAL_DECISION_CONTRACT_VERSION_V030;
      readonly decision: "unresolved";
      readonly task_id: string;
      readonly source_revision_id: NarraMemId<"source_revision">;
      readonly reason_code: CausalAuditUnresolvedReasonCode;
      readonly about_refs: readonly NarraMemId[];
      readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
    };

export const CAUSAL_AUDIT_FINAL_HANDOFF_KINDS = [
  "model_declared_sufficient",
  "investigation_window_complete",
  "model_declared_no_progress",
  "runtime_failure",
] as const;

export type CausalAuditFinalHandoffKind = (typeof CAUSAL_AUDIT_FINAL_HANDOFF_KINDS)[number];

/**
 * Trusted interpretation of why a stopped executor transcript may enter the
 * separate final-decision phase. It never asserts that tool material is true.
 */
export interface CausalAuditFinalHandoff {
  readonly kind: CausalAuditFinalHandoffKind;
  readonly execution_stop_reason: InvestigationStopReason;
}

export interface CausalAuditAgentBudgetControlV020 {
  readonly max_action_calls: number;
  readonly used_action_calls: number;
  readonly remaining_action_calls: number;
  readonly max_tool_calls: number;
  readonly used_tool_calls: number;
  readonly remaining_tool_calls: number;
  readonly final_decision_call_limit: 1;
}

export const FLAT_INVESTIGATION_ACTION_DRAFT_VERSION = "0.1.0" as const;

export interface CausalAuditActionOption {
  readonly option_id: string;
  readonly action: InvestigationAction;
}

/** MiMo-specific shallow output; trusted Runtime resolves the exact canonical action. */
export interface FlatInvestigationActionDraft {
  readonly draft_version: typeof FLAT_INVESTIGATION_ACTION_DRAFT_VERSION;
  readonly option_id: string;
}

export interface CausalAuditAgentFindingControl {
  readonly code: "EXPLICIT_CAUSAL_CUE_UNCOVERED";
  readonly evidence_id: NarraMemId<"evidence">;
  readonly cue: string;
  readonly start_code_point: number;
  readonly end_code_point: number;
}

export interface CausalAuditAgentMaterialEnvelope {
  readonly trust_boundary: "untrusted_evidence";
  readonly seed_context: JsonValue;
  readonly transcript_steps: readonly InvestigationTranscriptStep[];
}

export type CausalAuditAgentTurnInput =
  | {
      readonly input_version: typeof CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION;
      readonly phase: "investigation_action";
      readonly control: {
        readonly trust_boundary: "trusted_control";
        readonly task_id: string;
        readonly source_revision_id: NarraMemId<"source_revision">;
        readonly finding: CausalAuditAgentFindingControl;
        readonly allowed_tools: readonly InvestigationToolName[];
        readonly max_steps: number;
        readonly next_step: number;
        readonly remaining_tool_calls: number;
      };
      readonly material: CausalAuditAgentMaterialEnvelope;
    }
  | {
      readonly input_version: typeof CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION;
      readonly phase: "final_decision";
      readonly control: {
        readonly trust_boundary: "trusted_control";
        readonly task_id: string;
        readonly source_revision_id: NarraMemId<"source_revision">;
        readonly finding: CausalAuditAgentFindingControl;
        readonly stop_reason: InvestigationStopReason;
        readonly allowed_cause_refs: readonly CausalAuditCandidateCauseRef[];
        readonly allowed_effect_refs: readonly CausalAuditCandidateEffectRef[];
        readonly allowed_holder_entity_ids: readonly NarraMemId<"entity">[];
        readonly allowed_reviewed_record_refs: readonly NarraMemId[];
        readonly allowed_reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
      };
      readonly material: CausalAuditAgentMaterialEnvelope;
    };

/**
 * v0.2 makes action/tool/final budgets explicit and separates executor stop
 * reasons from final-decision handoff semantics. Historical v0.1 inputs remain
 * available for frozen report replay.
 */
export type CausalAuditAgentTurnInputV020 =
  | {
      readonly input_version: typeof CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION_V020;
      readonly phase: "investigation_action";
      readonly control: {
        readonly trust_boundary: "trusted_control";
        readonly task_id: string;
        readonly source_revision_id: NarraMemId<"source_revision">;
        readonly finding: CausalAuditAgentFindingControl;
        readonly allowed_tools: readonly InvestigationToolName[];
        readonly next_action_call: number;
        readonly budget: CausalAuditAgentBudgetControlV020;
      };
      readonly material: CausalAuditAgentMaterialEnvelope;
    }
  | {
      readonly input_version: typeof CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION_V020;
      readonly phase: "final_decision";
      readonly control: {
        readonly trust_boundary: "trusted_control";
        readonly task_id: string;
        readonly source_revision_id: NarraMemId<"source_revision">;
        readonly finding: CausalAuditAgentFindingControl;
        readonly handoff: CausalAuditFinalHandoff;
        readonly budget: CausalAuditAgentBudgetControlV020;
        readonly allowed_cause_refs: readonly CausalAuditCandidateCauseRef[];
        readonly allowed_effect_refs: readonly CausalAuditCandidateEffectRef[];
        readonly allowed_holder_entity_ids: readonly NarraMemId<"entity">[];
        readonly allowed_reviewed_record_refs: readonly NarraMemId[];
        readonly allowed_reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
      };
      readonly material: CausalAuditAgentMaterialEnvelope;
    };

export interface CausalAuditAgentActionChoiceInputV020 {
  readonly input_version: typeof CAUSAL_AUDIT_AGENT_TURN_INPUT_VERSION_V020;
  readonly phase: "investigation_action_choice";
  readonly control: {
    readonly trust_boundary: "trusted_control";
    readonly task_id: string;
    readonly source_revision_id: NarraMemId<"source_revision">;
    readonly finding: CausalAuditAgentFindingControl;
    readonly next_action_call: number;
    readonly budget: CausalAuditAgentBudgetControlV020;
    readonly action_options: readonly CausalAuditActionOption[];
  };
  readonly material: CausalAuditAgentMaterialEnvelope;
}

export interface CausalAuditFinalCauseOption {
  readonly option_id: string;
  readonly reference: CausalAuditCandidateCauseRef;
}

export interface CausalAuditFinalEffectOption {
  readonly option_id: string;
  readonly reference: CausalAuditCandidateEffectRef;
}

export interface CausalAuditFinalAttributionOption {
  readonly option_id: string;
  readonly attribution: CausalAuditCandidateAttribution;
}

export interface CausalAuditFinalReviewedRecordOption {
  readonly option_id: string;
  readonly record_id: NarraMemId;
}

export interface CausalAuditFinalReviewedEvidenceOption {
  readonly option_id: string;
  readonly evidence_id: NarraMemId<"evidence">;
}

/** Trusted metadata for an exact quote whose text remains untrusted material. */
export interface CausalAuditFinalQuoteOptionControl {
  readonly option_id: string;
  readonly evidence_id: NarraMemId<"evidence">;
  readonly occurrence: number;
  readonly support_role: CandidateEvidenceQuote["support_role"];
  readonly quote_sha256: HashDigest;
}

export interface CausalAuditFinalQuoteOptionMaterial {
  readonly option_id: string;
  readonly quote: string;
}

export interface CausalAuditFinalOptionCatalog {
  readonly catalog_version: typeof CAUSAL_AUDIT_FINAL_OPTION_CATALOG_VERSION;
  readonly allowed_decisions: readonly ("candidate" | "no_supported_causal" | "unresolved")[];
  readonly cause_options: readonly CausalAuditFinalCauseOption[];
  readonly effect_options: readonly CausalAuditFinalEffectOption[];
  readonly attribution_options: readonly CausalAuditFinalAttributionOption[];
  readonly reviewed_record_options: readonly CausalAuditFinalReviewedRecordOption[];
  readonly reviewed_evidence_options: readonly CausalAuditFinalReviewedEvidenceOption[];
  readonly quote_options: readonly CausalAuditFinalQuoteOptionControl[];
}

/**
 * Final-choice input keeps typed option authority in control while exact story
 * quote text remains explicitly untrusted material. The model selects option
 * IDs; only trusted Runtime may expand them into canonical records.
 */
export interface CausalAuditAgentFinalChoiceInputV030 {
  readonly input_version: typeof CAUSAL_AUDIT_AGENT_FINAL_CHOICE_INPUT_VERSION_V030;
  readonly phase: "final_decision_choice";
  readonly control: {
    readonly trust_boundary: "trusted_control";
    readonly task_id: string;
    readonly source_revision_id: NarraMemId<"source_revision">;
    readonly finding: CausalAuditAgentFindingControl;
    readonly handoff: CausalAuditFinalHandoff;
    readonly budget: CausalAuditAgentBudgetControlV020;
    readonly final_options: CausalAuditFinalOptionCatalog;
  };
  readonly material: CausalAuditAgentMaterialEnvelope & {
    readonly quote_option_material: readonly CausalAuditFinalQuoteOptionMaterial[];
  };
}

export interface FlatCausalAuditCandidateDraft {
  readonly draft_version: typeof FLAT_CAUSAL_AUDIT_FINAL_DRAFT_VERSION;
  readonly decision: "candidate";
  readonly candidate_key: string;
  readonly cause_option_ids: readonly string[];
  readonly effect_option_ids: readonly string[];
  readonly relation: CausalRelation;
  readonly mechanism: string;
  readonly attribution_option_id: string;
  readonly necessity: CausalNecessity;
  readonly strength: QualitativeMagnitude;
  readonly evidence_quote_option_ids: readonly string[];
}

export interface FlatCausalAuditNoSupportedDraft {
  readonly draft_version: typeof FLAT_CAUSAL_AUDIT_FINAL_DRAFT_VERSION;
  readonly decision: "no_supported_causal";
  readonly reason_code: CausalAuditNoSupportedReasonCode;
  readonly reviewed_record_option_ids: readonly string[];
  readonly reviewed_evidence_option_ids: readonly string[];
}

export interface FlatCausalAuditUnresolvedDraft {
  readonly draft_version: typeof FLAT_CAUSAL_AUDIT_FINAL_DRAFT_VERSION;
  readonly decision: "unresolved";
  readonly reason_code: CausalAuditUnresolvedReasonCode;
  readonly about_record_option_ids: readonly string[];
  readonly reviewed_evidence_option_ids: readonly string[];
}

/** One audit finding yields at most one causal link in this first bounded IR. */
export type FlatCausalAuditFinalDraft =
  | FlatCausalAuditCandidateDraft
  | FlatCausalAuditNoSupportedDraft
  | FlatCausalAuditUnresolvedDraft;
