import {
  type TavernExtensionRuntimeHandle,
  type TavernHostPort,
  TavernInteractionPerformanceProbe,
  type TavernInteractionPerformanceSnapshot,
  type TavernObserverSchedulerSnapshot,
  type TavernRecallGenerationBarrierSnapshot,
} from "@narramem/tavern-adapter";
import type {
  TavernCausalAuditDiagnosticBindingSnapshot,
  TavernCausalAuditDiagnosticPort,
  TavernCausalAuditDiagnosticPreflight,
  TavernCausalAuditDiagnosticRecoverySnapshot,
  TavernCausalAuditDiagnosticRunResult,
  TavernCausalAuditDiagnosticRuntimeContext,
} from "./causal-audit-diagnostic-contracts.js";
import {
  TavernCausalAuditPositiveFixtureDiagnostic,
  type TavernCausalAuditPositiveFixtureResult,
} from "./positive-causal-audit-fixture.js";
import {
  type TavernWorldbookStressCommand,
  TavernWorldbookStressDiagnostic,
} from "./worldbook-stress-diagnostic.js";

export const NARRAMEM_EXTENSION_DIAGNOSTIC_CONTROL_SYMBOL =
  "narramem.tavern-extension-diagnostic-control.v1" as const;

export type TavernExtensionDiagnosticArm = "runtime" | "baseline" | "paused";

export interface TavernExtensionDiagnosticControlSnapshot {
  readonly arm: TavernExtensionDiagnosticArm;
  readonly runtime_available: boolean;
  readonly runtime_lifecycle: TavernObserverSchedulerSnapshot["lifecycle"] | null;
  readonly runtime_cycle_in_flight: boolean;
  readonly runtime_main_generation_active: boolean;
  readonly runtime_timer_pending: boolean;
  readonly runtime_pending_hint_count: number;
  readonly runtime_pending_extraction_requested: boolean;
  readonly runtime_committed_coverage_available: boolean;
  readonly baseline_switch_pending: boolean;
  readonly runtime_performance_samples: number;
  readonly baseline_performance_samples: number;
  readonly causal_audit_in_flight: boolean;
  readonly causal_audit_fixture_in_flight: boolean;
  readonly content_recorded: false;
  readonly browser_persistent_storage_used: false;
}

export interface TavernExtensionDiagnosticControlHandle {
  readonly control_version: "0.6.0";
  getState(): TavernExtensionDiagnosticControlSnapshot;
  getRuntimeSnapshot(): TavernObserverSchedulerSnapshot | null;
  getRecallSnapshot(): TavernRecallGenerationBarrierSnapshot | null;
  getRuntimePerformanceSnapshot(): TavernInteractionPerformanceSnapshot | null;
  getBaselinePerformanceSnapshot(): TavernInteractionPerformanceSnapshot;
  clearRuntimePerformanceSamples(): boolean;
  clearBaselinePerformanceSamples(): void;
  switchToBaseline(): Promise<TavernExtensionDiagnosticControlSnapshot>;
  switchToBaselineAfterCurrentGeneration(): Promise<TavernExtensionDiagnosticControlSnapshot>;
  switchToRuntime(): Promise<TavernExtensionDiagnosticControlSnapshot>;
  pause(): TavernExtensionDiagnosticControlSnapshot;
  executeWorldbookStress(command: TavernWorldbookStressCommand): Promise<unknown>;
  preparePositiveCausalAuditFixture(): Promise<TavernCausalAuditPositiveFixtureResult>;
  preflightCausalAudit(): Promise<TavernCausalAuditDiagnosticPreflight>;
  snapshotCausalAuditBinding(): Promise<TavernCausalAuditDiagnosticBindingSnapshot>;
  snapshotCausalAuditRecovery(): Promise<TavernCausalAuditDiagnosticRecoverySnapshot>;
  runManualCausalAudit(taskSeedId: string): Promise<TavernCausalAuditDiagnosticRunResult>;
}

export type TavernExtensionDiagnosticCommand =
  | "GET_STATE"
  | "GET_RUNTIME_PERFORMANCE"
  | "GET_BASELINE_PERFORMANCE"
  | "CLEAR_RUNTIME_PERFORMANCE"
  | "CLEAR_BASELINE_PERFORMANCE"
  | "SWITCH_TO_BASELINE"
  | "SWITCH_TO_BASELINE_AFTER_GENERATION"
  | "SWITCH_TO_RUNTIME"
  | "PAUSE"
  | "CAUSAL_AUDIT_PREPARE_POSITIVE_FIXTURE"
  | "CAUSAL_AUDIT_PREFLIGHT"
  | "CAUSAL_AUDIT_BINDING_SNAPSHOT"
  | "CAUSAL_AUDIT_RECOVERY_SNAPSHOT"
  | `CAUSAL_AUDIT_RUN_MANUAL:${string}`
  | TavernWorldbookStressCommand;

const MANUAL_CAUSAL_AUDIT_COMMAND =
  /^CAUSAL_AUDIT_RUN_MANUAL:(tavern_causal_audit_seed_[a-f0-9]{64})$/u;

export function parseManualCausalAuditCommand(command: string): string | null {
  return MANUAL_CAUSAL_AUDIT_COMMAND.exec(command)?.[1] ?? null;
}

export async function executeTavernExtensionDiagnosticCommand(
  control: TavernExtensionDiagnosticControlHandle,
  command: TavernExtensionDiagnosticCommand,
): Promise<unknown> {
  const manualTaskSeedId = parseManualCausalAuditCommand(command);
  if (manualTaskSeedId !== null) return control.runManualCausalAudit(manualTaskSeedId);
  switch (command) {
    case "GET_STATE":
      return control.getState();
    case "GET_RUNTIME_PERFORMANCE":
      return control.getRuntimePerformanceSnapshot();
    case "GET_BASELINE_PERFORMANCE":
      return control.getBaselinePerformanceSnapshot();
    case "CLEAR_RUNTIME_PERFORMANCE":
      return { cleared: control.clearRuntimePerformanceSamples() };
    case "CLEAR_BASELINE_PERFORMANCE":
      control.clearBaselinePerformanceSamples();
      return { cleared: true };
    case "SWITCH_TO_BASELINE":
      return control.switchToBaseline();
    case "SWITCH_TO_BASELINE_AFTER_GENERATION":
      return control.switchToBaselineAfterCurrentGeneration();
    case "SWITCH_TO_RUNTIME":
      return control.switchToRuntime();
    case "PAUSE":
      return control.pause();
    case "CAUSAL_AUDIT_PREPARE_POSITIVE_FIXTURE":
      return control.preparePositiveCausalAuditFixture();
    case "CAUSAL_AUDIT_PREFLIGHT":
      return control.preflightCausalAudit();
    case "CAUSAL_AUDIT_BINDING_SNAPSHOT":
      return control.snapshotCausalAuditBinding();
    case "CAUSAL_AUDIT_RECOVERY_SNAPSHOT":
      return control.snapshotCausalAuditRecovery();
    case "WORLDBOOK_STRESS_PREFLIGHT":
    case "WORLDBOOK_STRESS_RUN_COUNT":
    case "WORLDBOOK_STRESS_RUN_BYTES":
    case "WORLDBOOK_STRESS_RUN_SCALE":
    case "WORLDBOOK_STRESS_RUN_SCALE_OPTIMIZED":
    case "WORLDBOOK_STRESS_RUN_SCALE_64":
    case "WORLDBOOK_STRESS_RUN_SCALE_CACHED_ARCHIVE":
    case "WORLDBOOK_STRESS_RUN_SCALE_SINGLE_ARCHIVE":
    case "WORLDBOOK_STRESS_RUN_SCALE_APPEND_RESULT":
    case "WORLDBOOK_STRESS_START_RECOVERY":
    case "WORLDBOOK_STRESS_RECOVER_AFTER_REFRESH":
    case "WORLDBOOK_STRESS_INIT_CONCURRENCY":
    case "WORLDBOOK_STRESS_PREPARE_STALE_WRITER":
    case "WORLDBOOK_STRESS_COMMIT_PRIMARY_WRITER":
    case "WORLDBOOK_STRESS_COMMIT_STALE_WRITER":
    case "WORLDBOOK_STRESS_VERIFY_ALL":
    case "WORLDBOOK_STRESS_PREPARE_CLEANUP":
    case "WORLDBOOK_STRESS_EXECUTE_PREPARED_CLEANUP":
      return control.executeWorldbookStress(command);
  }
}

const IDLE_WAIT_TIMEOUT_MS = 360_000;
const IDLE_POLL_MS = 100;

function wait(milliseconds: number): Promise<void> {
  return new Promise((resolve) => globalThis.setTimeout(resolve, milliseconds));
}

/**
 * Diagnostics for validating the one standard extension in its real host.
 * It deliberately exposes only lifecycle controls and content-free snapshots.
 */
export class TavernExtensionDiagnosticControl implements TavernExtensionDiagnosticControlHandle {
  readonly control_version = "0.6.0" as const;
  private arm: TavernExtensionDiagnosticArm = "runtime";
  private baselineSwitchPending = false;
  private runtime: TavernExtensionRuntimeHandle | null = null;
  private causalAuditInFlight = false;
  private causalAuditFixtureInFlight = false;
  private readonly baselineProbe: TavernInteractionPerformanceProbe;
  private readonly worldbookStress: TavernWorldbookStressDiagnostic;
  private readonly positiveCausalAuditFixture: TavernCausalAuditPositiveFixturePort;

  constructor(
    port: TavernHostPort,
    maxSamples = 200,
    private readonly causalAudit: TavernCausalAuditDiagnosticPort | null = null,
    positiveCausalAuditFixture: TavernCausalAuditPositiveFixturePort | null = null,
  ) {
    this.baselineProbe = new TavernInteractionPerformanceProbe(port, maxSamples);
    this.worldbookStress = new TavernWorldbookStressDiagnostic(port);
    this.positiveCausalAuditFixture =
      positiveCausalAuditFixture ?? new TavernCausalAuditPositiveFixtureDiagnostic({ port });
  }

  setRuntime(runtime: TavernExtensionRuntimeHandle | null): void {
    if (runtime === null) this.baselineSwitchPending = false;
    this.runtime = runtime;
    if (runtime !== null && this.arm !== "runtime") {
      runtime.stop("diagnostic_control_non_runtime_arm");
    }
  }

  getState(): TavernExtensionDiagnosticControlSnapshot {
    const runtimeSnapshot = this.runtime?.getSnapshot() ?? null;
    return {
      arm: this.arm,
      runtime_available: this.runtime !== null,
      runtime_lifecycle: runtimeSnapshot?.lifecycle ?? null,
      runtime_cycle_in_flight: runtimeSnapshot?.cycle_in_flight ?? false,
      runtime_main_generation_active: runtimeSnapshot?.main_generation_active ?? false,
      runtime_timer_pending: runtimeSnapshot?.timer_pending ?? false,
      runtime_pending_hint_count: runtimeSnapshot?.pending_hints.length ?? 0,
      runtime_pending_extraction_requested: runtimeSnapshot?.pending_extraction_requested ?? false,
      runtime_committed_coverage_available: runtimeSnapshot?.committed_coverage_available ?? false,
      baseline_switch_pending: this.baselineSwitchPending,
      runtime_performance_samples:
        this.runtime?.getInteractionPerformanceSnapshot().retained_samples.length ?? 0,
      baseline_performance_samples: this.baselineProbe.getSnapshot().retained_samples.length,
      causal_audit_in_flight: this.causalAuditInFlight,
      causal_audit_fixture_in_flight: this.causalAuditFixtureInFlight,
      content_recorded: false,
      browser_persistent_storage_used: false,
    };
  }

  getRuntimeSnapshot(): TavernObserverSchedulerSnapshot | null {
    return this.runtime?.getSnapshot() ?? null;
  }

  getRecallSnapshot(): TavernRecallGenerationBarrierSnapshot | null {
    return this.runtime?.getRecallSnapshot() ?? null;
  }

  getRuntimePerformanceSnapshot(): TavernInteractionPerformanceSnapshot | null {
    return this.runtime?.getInteractionPerformanceSnapshot() ?? null;
  }

  getBaselinePerformanceSnapshot(): TavernInteractionPerformanceSnapshot {
    return this.baselineProbe.getSnapshot();
  }

  clearRuntimePerformanceSamples(): boolean {
    if (this.runtime === null) return false;
    this.runtime.clearInteractionPerformanceSamples();
    return true;
  }

  clearBaselinePerformanceSamples(): void {
    this.baselineProbe.clearSamples();
  }

  async switchToBaseline(): Promise<TavernExtensionDiagnosticControlSnapshot> {
    this.requireNoCausalAuditMutation("switch arms");
    if (this.arm === "baseline") {
      // Re-assert exclusivity in case a host chat-change restart happened
      // between diagnostic commands.  An A/B arm must never leave both probes
      // subscribed to the same generation.
      this.runtime?.stop("diagnostic_ab_reassert_baseline");
      this.baselineProbe.start();
      this.baselineSwitchPending = false;
      return this.getState();
    }
    const snapshot = this.runtime?.getSnapshot() ?? null;
    if (snapshot?.main_generation_active) {
      throw new Error("Cannot switch A/B arms during a main generation");
    }
    this.runtime?.stop("diagnostic_ab_switch_to_baseline");
    this.baselineSwitchPending = false;
    await this.waitForRuntimeIdle();
    this.baselineProbe.start();
    this.arm = "baseline";
    return this.getState();
  }

  async switchToBaselineAfterCurrentGeneration(): Promise<TavernExtensionDiagnosticControlSnapshot> {
    if (this.arm === "baseline") return this.switchToBaseline();
    if (this.runtime?.getSnapshot().main_generation_active) {
      this.baselineSwitchPending = true;
      return this.getState();
    }
    return this.switchToBaseline();
  }

  notifyRuntimePerformanceSample(): void {
    if (!this.baselineSwitchPending || this.runtime === null) return;
    this.baselineSwitchPending = false;
    this.runtime.stop("diagnostic_ab_scheduled_switch_to_baseline");
    void this.waitForRuntimeIdle().then(() => {
      if (this.arm !== "runtime") return;
      this.baselineProbe.start();
      this.arm = "baseline";
    });
  }

  async switchToRuntime(): Promise<TavernExtensionDiagnosticControlSnapshot> {
    this.requireNoCausalAuditMutation("switch arms");
    if (this.runtime === null)
      throw new Error("NarraMem runtime is unavailable for the current model");
    if (this.runtime.getSnapshot().main_generation_active) {
      throw new Error("Cannot re-arm NarraMem Runtime during a main generation");
    }
    this.baselineProbe.stop();
    this.baselineSwitchPending = false;
    if (this.arm !== "runtime") this.runtime.start();
    this.arm = "runtime";
    try {
      await this.runtime.flushNow();
      const snapshot = this.runtime.getSnapshot();
      if (
        snapshot.lifecycle !== "running" ||
        snapshot.main_generation_active ||
        snapshot.timer_pending ||
        snapshot.cycle_in_flight ||
        snapshot.pending_hints.length > 0 ||
        snapshot.pending_extraction_requested ||
        !snapshot.committed_coverage_available
      ) {
        throw new Error(
          "NarraMem Runtime re-arm settled without committed semantic coverage readiness",
        );
      }
      return this.getState();
    } catch (error) {
      this.runtime.stop("diagnostic_runtime_rearm_not_ready");
      this.arm = "paused";
      throw error;
    }
  }

  pause(): TavernExtensionDiagnosticControlSnapshot {
    this.requireNoCausalAuditMutation("pause");
    this.runtime?.stop("diagnostic_control_paused");
    this.baselineProbe.stop();
    this.baselineSwitchPending = false;
    this.arm = "paused";
    return this.getState();
  }

  async executeWorldbookStress(command: TavernWorldbookStressCommand): Promise<unknown> {
    this.requireNoCausalAuditMutation("run Worldbook stress diagnostics");
    const snapshot = this.runtime?.getSnapshot() ?? null;
    if (
      this.arm !== "paused" ||
      snapshot?.cycle_in_flight === true ||
      snapshot?.main_generation_active === true
    ) {
      throw new Error("Worldbook stress diagnostics require a paused and idle product runtime");
    }
    return this.worldbookStress.execute(command);
  }

  async preparePositiveCausalAuditFixture(): Promise<TavernCausalAuditPositiveFixtureResult> {
    if (this.causalAuditInFlight || this.causalAuditFixtureInFlight) {
      throw new Error("A Causal Audit mutation is already running");
    }
    const snapshot = this.runtime?.getSnapshot() ?? null;
    if (
      this.arm !== "paused" ||
      snapshot?.cycle_in_flight === true ||
      snapshot?.main_generation_active === true
    ) {
      throw new Error("Positive Causal Audit fixture requires a paused and idle product runtime");
    }
    this.causalAuditFixtureInFlight = true;
    try {
      return await this.positiveCausalAuditFixture.prepare();
    } finally {
      this.causalAuditFixtureInFlight = false;
    }
  }

  async preflightCausalAudit(): Promise<TavernCausalAuditDiagnosticPreflight> {
    if (this.causalAudit === null) throw new Error("Causal Audit diagnostic is unavailable");
    this.requireNoCausalAuditMutation("run Causal Audit preflight");
    return this.causalAudit.preflight(this.requireCausalAuditRuntimeContext());
  }

  async snapshotCausalAuditBinding(): Promise<TavernCausalAuditDiagnosticBindingSnapshot> {
    if (this.causalAudit === null) throw new Error("Causal Audit diagnostic is unavailable");
    this.requireNoCausalAuditMutation("snapshot Causal Audit binding");
    return this.causalAudit.bindingSnapshot(this.requireCausalAuditRuntimeContext());
  }

  async snapshotCausalAuditRecovery(): Promise<TavernCausalAuditDiagnosticRecoverySnapshot> {
    if (this.causalAudit === null) throw new Error("Causal Audit diagnostic is unavailable");
    this.requireNoCausalAuditMutation("snapshot Causal Audit recovery");
    return this.causalAudit.recoverySnapshot(this.requireCausalAuditRuntimeContext());
  }

  async runManualCausalAudit(taskSeedId: string): Promise<TavernCausalAuditDiagnosticRunResult> {
    if (this.causalAudit === null) throw new Error("Causal Audit diagnostic is unavailable");
    if (this.causalAuditInFlight || this.causalAuditFixtureInFlight) {
      throw new Error("A Causal Audit mutation is already running");
    }
    const authorization = await this.causalAudit.authorizeManual(
      taskSeedId,
      this.requireCausalAuditRuntimeContext(),
    );
    this.causalAuditInFlight = true;
    this.runtime?.stop("diagnostic_manual_causal_audit_lane");
    try {
      await this.waitForRuntimeIdle();
      return await this.causalAudit.runAuthorized(authorization);
    } finally {
      this.causalAuditInFlight = false;
      if (this.arm === "runtime") this.runtime?.start();
    }
  }

  private requireCausalAuditRuntimeContext(): TavernCausalAuditDiagnosticRuntimeContext {
    const snapshot = this.runtime?.getSnapshot() ?? null;
    const runningLane = this.arm === "runtime" && snapshot?.lifecycle === "running";
    const pausedLane = this.arm === "paused" && snapshot?.lifecycle === "stopped";
    if (
      snapshot === null ||
      (!runningLane && !pausedLane) ||
      snapshot.main_generation_active ||
      snapshot.timer_pending ||
      snapshot.cycle_in_flight ||
      snapshot.pending_hints.length > 0 ||
      snapshot.pending_extraction_requested
    ) {
      throw new Error(
        "Causal Audit requires a visible idle Runtime or an explicitly paused quiesced manual lane",
      );
    }
    return {
      snapshot,
      execution_lane: pausedLane ? "paused_quiesced_manual" : "running_product_runtime",
      page_lifecycle:
        typeof document === "undefined" || document.visibilityState === "visible"
          ? "visible"
          : "hidden",
    };
  }

  private requireNoCausalAuditMutation(action: string): void {
    if (this.causalAuditInFlight || this.causalAuditFixtureInFlight) {
      throw new Error(`Cannot ${action} during a Causal Audit mutation`);
    }
  }

  private async waitForRuntimeIdle(): Promise<void> {
    const startedAt = Date.now();
    while (this.runtime?.getSnapshot().cycle_in_flight) {
      if (Date.now() - startedAt >= IDLE_WAIT_TIMEOUT_MS) {
        throw new Error("Timed out waiting for the NarraMem background model lane to settle");
      }
      await wait(IDLE_POLL_MS);
    }
  }
}

interface TavernCausalAuditPositiveFixturePort {
  prepare(): Promise<TavernCausalAuditPositiveFixtureResult>;
}
