import { getNarraMemIdKind } from "@narramem/core-domain";
import type { TavernCausalAuditTaskSeed } from "./causal-audit-task-mapping.js";
import {
  type ClaimTavernCausalAuditTaskRequest,
  type ClaimTavernCausalAuditTaskResult,
  type CompleteTavernCausalAuditTaskRequest,
  type CompleteTavernCausalAuditTaskResult,
  type FinalizeTavernCausalAuditCandidateRequest,
  type FinalizeTavernCausalAuditCandidateResult,
  TAVERN_CAUSAL_AUDIT_TASK_STORE_FORMAT,
  TAVERN_CAUSAL_AUDIT_TASK_STORE_VERSION,
  type TavernCausalAuditExecutionPreference,
  type TavernCausalAuditTaskBudget,
  type TavernCausalAuditTaskResolution,
  type TavernCausalAuditTaskStateRecord,
  TavernCausalAuditTaskStoreError,
  type TavernCausalAuditTaskStorePayload,
  type TavernCausalAuditTaskStoreReconcileRequest,
  type TavernCausalAuditTaskStoreReconcileResult,
} from "./causal-audit-task-store-contracts.js";
import type {
  TavernHostPort,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import { canonicalJson, checksumJson, sha256HexUtf8 } from "./worldbook-codec.js";

const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const SAFE_WORKER_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:/-]{0,127}$/u;
const TASK_SEED_PATTERN = /^tavern_causal_audit_seed_[a-f0-9]{64}$/u;
const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const CODE_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/u;
const NON_TERMINAL = new Set(["pending", "leased", "proposal_pending_validation"]);
const TERMINAL = new Set(["resolved", "unresolved", "stale", "cancelled", "failed"]);
const PRIORITY_RANK = { low: 0, normal: 1, high: 2, critical: 3 } as const;

type StoreState = {
  readonly entry: TavernWorldbookEntry;
  readonly payload: TavernCausalAuditTaskStorePayload;
};

const clone = <T>(value: T): T => structuredClone(value);
const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function hasOnlyKeys(value: Record<string, unknown>, allowed: readonly string[]): boolean {
  const set = new Set(allowed);
  return Object.keys(value).every((key) => set.has(key));
}

function assertCanonicalTimestamp(value: unknown, field: string): asserts value is string {
  if (typeof value !== "string") {
    throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", `${field} must be a timestamp`);
  }
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed) || new Date(parsed).toISOString() !== value) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      `${field} must be a canonical UTC ISO timestamp`,
    );
  }
}

function assertNonNegativeInteger(value: unknown, field: string): asserts value is number {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      `${field} must be a non-negative safe integer`,
    );
  }
}

function assertPositiveInteger(value: unknown, field: string): asserts value is number {
  assertNonNegativeInteger(value, field);
  if (value < 1) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      `${field} must be a positive safe integer`,
    );
  }
}

function assertBudget(budget: unknown): asserts budget is TavernCausalAuditTaskBudget {
  if (
    !isObject(budget) ||
    !hasOnlyKeys(budget, [
      "max_attempts",
      "max_model_calls",
      "max_tool_calls",
      "max_input_tokens",
      "lease_duration_ms",
    ])
  ) {
    throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid Tavern task budget");
  }
  assertPositiveInteger(budget.max_attempts, "budget.max_attempts");
  assertNonNegativeInteger(budget.max_model_calls, "budget.max_model_calls");
  assertNonNegativeInteger(budget.max_tool_calls, "budget.max_tool_calls");
  assertNonNegativeInteger(budget.max_input_tokens, "budget.max_input_tokens");
  assertPositiveInteger(budget.lease_duration_ms, "budget.lease_duration_ms");
  if (
    budget.max_attempts > 100 ||
    budget.max_model_calls > 1000 ||
    budget.max_tool_calls > 100_000 ||
    budget.lease_duration_ms > 86_400_000
  ) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      "Tavern causal audit budget exceeds the bounded contract",
    );
  }
}

function assertPreference(
  preference: unknown,
): asserts preference is TavernCausalAuditExecutionPreference {
  if (
    !isObject(preference) ||
    !hasOnlyKeys(preference, ["activation_mode", "unattended_opt_in_acknowledged", "updated_at"]) ||
    !["disabled", "manual", "idle_opt_in"].includes(String(preference.activation_mode)) ||
    typeof preference.unattended_opt_in_acknowledged !== "boolean"
  ) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      "Invalid Tavern Agent execution preference",
    );
  }
  assertCanonicalTimestamp(preference.updated_at, "execution_preference.updated_at");
  if (preference.activation_mode !== "idle_opt_in" && preference.unattended_opt_in_acknowledged) {
    throw new TavernCausalAuditTaskStoreError(
      "INVALID_INPUT",
      "Unattended acknowledgement is valid only for idle_opt_in",
    );
  }
}

function assertResolution(value: unknown): asserts value is TavernCausalAuditTaskResolution {
  if (!isObject(value) || typeof value.kind !== "string") {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid task resolution");
  }
  if (value.kind === "candidate_proposed" || value.kind === "candidate_committed") {
    const allowed =
      value.kind === "candidate_committed"
        ? [
            "kind",
            "candidate_contract_version",
            "candidate_artifact_sha256",
            "authorized_changeset_id",
          ]
        : ["kind", "candidate_contract_version", "candidate_artifact_sha256"];
    if (
      !hasOnlyKeys(value, allowed) ||
      typeof value.candidate_contract_version !== "string" ||
      value.candidate_contract_version.length < 1 ||
      value.candidate_contract_version.length > 128 ||
      typeof value.candidate_artifact_sha256 !== "string" ||
      !SHA256_PATTERN.test(value.candidate_artifact_sha256) ||
      (value.kind === "candidate_committed" &&
        getNarraMemIdKind(value.authorized_changeset_id) !== "change_set")
    ) {
      throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid candidate resolution");
    }
    return;
  }
  if (
    (value.kind !== "no_supported_causal" && value.kind !== "unresolved") ||
    !hasOnlyKeys(value, ["kind", "reason_code"]) ||
    typeof value.reason_code !== "string" ||
    !CODE_PATTERN.test(value.reason_code)
  ) {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid terminal resolution");
  }
}

function assertTask(task: unknown): asserts task is TavernCausalAuditTaskStateRecord {
  if (
    !isObject(task) ||
    !hasOnlyKeys(task, [
      "task_seed_id",
      "finding_fingerprint",
      "source_revision_id",
      "source_checksum",
      "semantic_task_fingerprint",
      "source_response_sha256",
      "finding_policy_version",
      "priority",
      "budget",
      "usage",
      "status",
      "created_at",
      "updated_at",
      "record_version",
      "lease",
      "resolution",
      "last_error_code",
      "terminal_reason",
    ]) ||
    typeof task.task_seed_id !== "string" ||
    !TASK_SEED_PATTERN.test(task.task_seed_id) ||
    typeof task.finding_fingerprint !== "string" ||
    !SHA256_PATTERN.test(task.finding_fingerprint) ||
    typeof task.source_revision_id !== "string" ||
    getNarraMemIdKind(task.source_revision_id) !== "source_revision" ||
    typeof task.source_checksum !== "string" ||
    !SHA256_PATTERN.test(task.source_checksum) ||
    typeof task.semantic_task_fingerprint !== "string" ||
    !SHA256_PATTERN.test(task.semantic_task_fingerprint) ||
    typeof task.source_response_sha256 !== "string" ||
    !SHA256_PATTERN.test(task.source_response_sha256) ||
    typeof task.finding_policy_version !== "string" ||
    task.finding_policy_version.length < 1 ||
    task.finding_policy_version.length > 128 ||
    !Object.hasOwn(PRIORITY_RANK, String(task.priority)) ||
    !isObject(task.usage) ||
    !hasOnlyKeys(task.usage, [
      "attempts_used",
      "model_calls_used",
      "tool_calls_used",
      "input_tokens_used",
    ]) ||
    ![
      "pending",
      "leased",
      "proposal_pending_validation",
      "resolved",
      "unresolved",
      "stale",
      "cancelled",
      "failed",
    ].includes(String(task.status))
  ) {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid task record shape");
  }
  assertBudget(task.budget);
  assertNonNegativeInteger(task.usage.attempts_used, "usage.attempts_used");
  assertNonNegativeInteger(task.usage.model_calls_used, "usage.model_calls_used");
  assertNonNegativeInteger(task.usage.tool_calls_used, "usage.tool_calls_used");
  assertNonNegativeInteger(task.usage.input_tokens_used, "usage.input_tokens_used");
  assertCanonicalTimestamp(task.created_at, "task.created_at");
  assertCanonicalTimestamp(task.updated_at, "task.updated_at");
  assertNonNegativeInteger(task.record_version, "task.record_version");
  if (
    task.usage.attempts_used > task.budget.max_attempts ||
    task.usage.model_calls_used > task.budget.max_model_calls ||
    task.usage.tool_calls_used > task.budget.max_tool_calls ||
    task.usage.input_tokens_used > task.budget.max_input_tokens
  ) {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Task usage exceeds budget");
  }
  if (task.lease !== undefined) {
    if (
      !isObject(task.lease) ||
      !hasOnlyKeys(task.lease, ["lease_id", "worker_id", "leased_at", "expires_at"]) ||
      typeof task.lease.lease_id !== "string" ||
      !SHA256_PATTERN.test(task.lease.lease_id) ||
      typeof task.lease.worker_id !== "string" ||
      !SAFE_WORKER_PATTERN.test(task.lease.worker_id)
    ) {
      throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid task lease");
    }
    assertCanonicalTimestamp(task.lease.leased_at, "lease.leased_at");
    assertCanonicalTimestamp(task.lease.expires_at, "lease.expires_at");
  }
  if (task.resolution !== undefined) assertResolution(task.resolution);
  if (
    (task.last_error_code !== undefined &&
      (typeof task.last_error_code !== "string" || !CODE_PATTERN.test(task.last_error_code))) ||
    (task.terminal_reason !== undefined &&
      (typeof task.terminal_reason !== "string" || !CODE_PATTERN.test(task.terminal_reason))) ||
    (task.status === "leased") !== (task.lease !== undefined) ||
    (task.status === "proposal_pending_validation") !==
      (task.resolution?.kind === "candidate_proposed") ||
    (TERMINAL.has(String(task.status)) && task.terminal_reason === undefined) ||
    (!TERMINAL.has(String(task.status)) && task.terminal_reason !== undefined)
  ) {
    throw new TavernCausalAuditTaskStoreError(
      "STORE_CORRUPT",
      "Task status, lease, resolution, or terminal reason is inconsistent",
    );
  }
}

function machineEntryDraft(content: string): TavernWorldbookEntryDraft {
  return {
    name: "NarraMem Causal Audit Tasks",
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 0, order: 0 },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: { narramem: { record_kind: "causal_audit_task_store" } },
  };
}

function assertMachineEntry(entry: TavernWorldbookEntry): void {
  if (
    !Number.isInteger(entry.uid) ||
    entry.uid < 0 ||
    entry.enabled ||
    entry.strategy.type !== "constant" ||
    entry.strategy.keys.length !== 0 ||
    !entry.recursion.prevent_incoming ||
    !entry.recursion.prevent_outgoing
  ) {
    throw new TavernCausalAuditTaskStoreError(
      "STORE_CORRUPT",
      "Tavern Agent task entry safety settings changed",
    );
  }
}

async function parsePayload(
  content: string,
  memorySetId: string,
): Promise<TavernCausalAuditTaskStorePayload> {
  let value: unknown;
  try {
    value = JSON.parse(content);
  } catch {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Task store is not JSON");
  }
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "format",
      "schema_version",
      "memory_set_id",
      "execution_preference",
      "tasks",
      "checksum",
    ]) ||
    value.format !== TAVERN_CAUSAL_AUDIT_TASK_STORE_FORMAT ||
    value.schema_version !== TAVERN_CAUSAL_AUDIT_TASK_STORE_VERSION ||
    value.memory_set_id !== memorySetId ||
    !Array.isArray(value.tasks) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Invalid task store payload");
  }
  try {
    assertPreference(value.execution_preference);
    for (const task of value.tasks) assertTask(task);
  } catch (error) {
    throw new TavernCausalAuditTaskStoreError(
      "STORE_CORRUPT",
      error instanceof Error ? error.message : "Task store validation failed",
    );
  }
  const tasks = value.tasks as unknown as TavernCausalAuditTaskStateRecord[];
  if (
    new Set(tasks.map((task) => task.task_seed_id)).size !== tasks.length ||
    tasks.some(
      (task, index) => index > 0 && task.task_seed_id < (tasks[index - 1]?.task_seed_id ?? ""),
    )
  ) {
    throw new TavernCausalAuditTaskStoreError(
      "STORE_CORRUPT",
      "Task records are duplicated or not sorted",
    );
  }
  const payload = value as unknown as TavernCausalAuditTaskStorePayload;
  const { checksum: _checksum, ...unsigned } = payload;
  if ((await checksumJson(unsigned)) !== payload.checksum) {
    throw new TavernCausalAuditTaskStoreError("STORE_CORRUPT", "Task store checksum mismatch");
  }
  return payload;
}

async function encodePayload(
  memorySetId: string,
  preference: TavernCausalAuditExecutionPreference,
  tasks: readonly TavernCausalAuditTaskStateRecord[],
): Promise<TavernCausalAuditTaskStorePayload> {
  assertPreference(preference);
  const sorted = [...tasks].sort((left, right) =>
    left.task_seed_id.localeCompare(right.task_seed_id),
  );
  for (const task of sorted) assertTask(task);
  if (new Set(sorted.map((task) => task.task_seed_id)).size !== sorted.length) {
    throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Duplicate task seed IDs");
  }
  const unsigned = {
    format: TAVERN_CAUSAL_AUDIT_TASK_STORE_FORMAT,
    schema_version: TAVERN_CAUSAL_AUDIT_TASK_STORE_VERSION,
    memory_set_id: memorySetId,
    execution_preference: clone(preference),
    tasks: sorted.map(clone),
  };
  return { ...unsigned, checksum: await checksumJson(unsigned) };
}

function omitTask(
  task: TavernCausalAuditTaskStateRecord,
  ...fields: readonly (keyof TavernCausalAuditTaskStateRecord)[]
): TavernCausalAuditTaskStateRecord {
  const result = clone(task) as unknown as Record<string, unknown>;
  for (const field of fields) delete result[field];
  return result as unknown as TavernCausalAuditTaskStateRecord;
}

async function findingFingerprint(seed: TavernCausalAuditTaskSeed): Promise<string> {
  return sha256HexUtf8(
    canonicalJson({
      memory_set_id: seed.memory_set_id,
      policy_version: seed.policy_version,
      evidence_id: seed.finding.evidence_id,
      cue: seed.finding.cue,
      start_code_point: seed.finding.start_code_point,
      end_code_point: seed.finding.end_code_point,
    }),
  );
}

function sameSeed(
  task: TavernCausalAuditTaskStateRecord,
  seed: TavernCausalAuditTaskSeed | null,
  currentFindingFingerprint: string | null,
) {
  return (
    seed !== null &&
    currentFindingFingerprint !== null &&
    task.task_seed_id === seed.task_seed_id &&
    task.finding_fingerprint === currentFindingFingerprint &&
    task.source_revision_id === seed.source_revision_id &&
    task.source_checksum === seed.source_checksum &&
    task.semantic_task_fingerprint === seed.semantic_task_fingerprint &&
    task.source_response_sha256 === seed.source_response_sha256 &&
    task.finding_policy_version === seed.policy_version
  );
}

function staleTask(
  task: TavernCausalAuditTaskStateRecord,
  at: string,
): TavernCausalAuditTaskStateRecord {
  return {
    ...omitTask(task, "lease", "resolution", "last_error_code", "terminal_reason"),
    status: "stale",
    updated_at: at,
    record_version: task.record_version + 1,
    terminal_reason: "SOURCE_SEED_STALE",
  };
}

export function tavernCausalAuditTaskBookName(memorySetId: string): string {
  if (!SAFE_MEMORY_SET_PATTERN.test(memorySetId)) {
    throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid memory_set_id");
  }
  return `NarraMem__AGENT_TASKS__${memorySetId}`;
}

export class TavernCausalAuditTaskWorldbookStore {
  readonly book_name: string;
  private writerTail: Promise<void> = Promise.resolve();

  constructor(
    private readonly port: TavernHostPort,
    readonly memory_set_id: string,
  ) {
    this.book_name = tavernCausalAuditTaskBookName(memory_set_id);
  }

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writerTail.then(operation, operation);
    this.writerTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async read(): Promise<TavernCausalAuditTaskStorePayload | null> {
    return (await this.readState())?.payload ?? null;
  }

  initialize(
    preference: TavernCausalAuditExecutionPreference,
  ): Promise<TavernCausalAuditTaskStorePayload> {
    return this.enqueue(async () => {
      assertPreference(preference);
      const existing = await this.readState();
      if (existing !== null) return existing.payload;
      if (!(await this.port.createWorldbook(this.book_name))) {
        const raced = await this.readState();
        if (raced !== null) return raced.payload;
        throw new TavernCausalAuditTaskStoreError(
          "WRITE_CONFLICT",
          "Task World Book creation collided",
        );
      }
      const payload = await encodePayload(this.memory_set_id, preference, []);
      try {
        const appended = await this.port.appendWorldbookEntries(this.book_name, [
          machineEntryDraft(canonicalJson(payload)),
        ]);
        if (appended.new_entries.length !== 1) {
          throw new TavernCausalAuditTaskStoreError(
            "WRITE_CONFLICT",
            "Task store initialization did not create one entry",
          );
        }
      } catch (error) {
        const entries = await this.port.readWorldbook(this.book_name);
        if (entries.length === 0) await this.port.deleteWorldbook(this.book_name);
        throw error;
      }
      const verified = await this.read();
      if (verified?.checksum !== payload.checksum) {
        throw new TavernCausalAuditTaskStoreError(
          "WRITE_CONFLICT",
          "Task store initialization read-back mismatch",
        );
      }
      return verified;
    });
  }

  reconcile(
    request: TavernCausalAuditTaskStoreReconcileRequest,
  ): Promise<TavernCausalAuditTaskStoreReconcileResult> {
    return this.enqueue(async () => {
      assertCanonicalTimestamp(request.reconciled_at, "reconciled_at");
      assertPreference(request.execution_preference);
      assertBudget(request.task_budget);
      assertNonNegativeInteger(request.max_terminal_history, "max_terminal_history");
      if (!Object.hasOwn(PRIORITY_RANK, request.priority)) {
        throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid task priority");
      }
      const seedIds = request.current_seeds.map((seed) => seed.task_seed_id);
      if (
        request.current_seeds.some(
          (seed) =>
            seed.memory_set_id !== this.memory_set_id || !TASK_SEED_PATTERN.test(seed.task_seed_id),
        ) ||
        new Set(seedIds).size !== seedIds.length
      ) {
        throw new TavernCausalAuditTaskStoreError(
          "INVALID_INPUT",
          "Current seeds must be unique and belong to this Memory Set",
        );
      }
      const state = await this.requireExpected(request.expected_checksum);
      const currentSeeds = await Promise.all(
        request.current_seeds.map(async (seed) => ({
          seed,
          finding_fingerprint: await findingFingerprint(seed),
        })),
      );
      const currentById = new Map(currentSeeds.map((item) => [item.seed.task_seed_id, item]));
      const created: string[] = [];
      const stale: string[] = [];
      const recovered: string[] = [];
      const suppressed: string[] = [];
      const tasks = state.payload.tasks.map((task) => {
        const current = currentById.get(task.task_seed_id);
        if (
          NON_TERMINAL.has(task.status) &&
          !sameSeed(task, current?.seed ?? null, current?.finding_fingerprint ?? null)
        ) {
          stale.push(task.task_seed_id);
          return staleTask(task, request.reconciled_at);
        }
        if (
          task.status === "leased" &&
          Date.parse(task.lease?.expires_at ?? "") <= Date.parse(request.reconciled_at)
        ) {
          recovered.push(task.task_seed_id);
          const exhausted = task.usage.attempts_used >= task.budget.max_attempts;
          return {
            ...omitTask(task, "lease", "resolution", "terminal_reason"),
            status: exhausted ? ("failed" as const) : ("pending" as const),
            updated_at: request.reconciled_at,
            record_version: task.record_version + 1,
            last_error_code: "LEASE_EXPIRED",
            ...(exhausted ? { terminal_reason: "ATTEMPT_BUDGET_EXHAUSTED" } : {}),
          };
        }
        return task;
      });
      const existingIds = new Set(tasks.map((task) => task.task_seed_id));
      const terminalFindingFingerprints = new Set(
        tasks
          .filter((task) => TERMINAL.has(task.status) && task.status !== "stale")
          .map((task) => task.finding_fingerprint),
      );
      for (const current of currentSeeds.sort((left, right) =>
        left.seed.task_seed_id.localeCompare(right.seed.task_seed_id),
      )) {
        const { seed } = current;
        if (existingIds.has(seed.task_seed_id)) continue;
        if (terminalFindingFingerprints.has(current.finding_fingerprint)) {
          suppressed.push(seed.task_seed_id);
          continue;
        }
        created.push(seed.task_seed_id);
        tasks.push({
          task_seed_id: seed.task_seed_id,
          finding_fingerprint: current.finding_fingerprint,
          source_revision_id: seed.source_revision_id,
          source_checksum: seed.source_checksum,
          semantic_task_fingerprint: seed.semantic_task_fingerprint,
          source_response_sha256: seed.source_response_sha256,
          finding_policy_version: seed.policy_version,
          priority: request.priority,
          budget: clone(request.task_budget),
          usage: {
            attempts_used: 0,
            model_calls_used: 0,
            tool_calls_used: 0,
            input_tokens_used: 0,
          },
          status: "pending",
          created_at: request.reconciled_at,
          updated_at: request.reconciled_at,
          record_version: 0,
        });
      }

      const open = tasks.filter((task) => NON_TERMINAL.has(task.status));
      const terminal = tasks
        .filter((task) => TERMINAL.has(task.status))
        .sort(
          (left, right) =>
            right.updated_at.localeCompare(left.updated_at) ||
            left.task_seed_id.localeCompare(right.task_seed_id),
        );
      const keptTerminal = terminal.slice(0, request.max_terminal_history);
      const pruned = terminal
        .slice(request.max_terminal_history)
        .map((task) => task.task_seed_id)
        .sort();
      const payload = await this.writePayload(state, request.execution_preference, [
        ...open,
        ...keptTerminal,
      ]);
      return {
        payload,
        created_task_seed_ids: created.sort(),
        stale_task_seed_ids: stale.sort(),
        recovered_task_seed_ids: recovered.sort(),
        suppressed_task_seed_ids: suppressed.sort(),
        pruned_terminal_task_seed_ids: pruned,
      };
    });
  }

  claimNext(request: ClaimTavernCausalAuditTaskRequest): Promise<ClaimTavernCausalAuditTaskResult> {
    return this.enqueue(async () => {
      assertCanonicalTimestamp(request.claimed_at, "claimed_at");
      if (!SAFE_WORKER_PATTERN.test(request.worker_id)) {
        throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid worker_id");
      }
      const state = await this.requireExpected(request.expected_checksum);
      const preference = state.payload.execution_preference;
      if (
        preference.activation_mode === "disabled" ||
        preference.activation_mode !== request.execution_trigger ||
        (request.execution_trigger === "idle_opt_in" && !preference.unattended_opt_in_acknowledged)
      ) {
        throw new TavernCausalAuditTaskStoreError(
          "INVALID_INPUT",
          "Claim trigger is not authorized by the durable execution preference",
        );
      }
      const candidates = state.payload.tasks
        .filter(
          (task) =>
            task.status === "pending" && task.usage.attempts_used < task.budget.max_attempts,
        )
        .sort(
          (left, right) =>
            PRIORITY_RANK[right.priority] - PRIORITY_RANK[left.priority] ||
            left.created_at.localeCompare(right.created_at) ||
            left.task_seed_id.localeCompare(right.task_seed_id),
        );
      const task = candidates[0];
      if (task === undefined) return { status: "none", payload: state.payload };
      const attempts = task.usage.attempts_used + 1;
      const leaseId = await sha256HexUtf8(
        canonicalJson({
          task_seed_id: task.task_seed_id,
          worker_id: request.worker_id,
          attempts,
          claimed_at: request.claimed_at,
          store_checksum: state.payload.checksum,
        }),
      );
      const claimed: TavernCausalAuditTaskStateRecord = {
        ...omitTask(task, "last_error_code", "terminal_reason", "resolution"),
        status: "leased",
        usage: { ...task.usage, attempts_used: attempts },
        lease: {
          lease_id: leaseId,
          worker_id: request.worker_id,
          leased_at: request.claimed_at,
          expires_at: new Date(
            Date.parse(request.claimed_at) + task.budget.lease_duration_ms,
          ).toISOString(),
        },
        updated_at: request.claimed_at,
        record_version: task.record_version + 1,
      };
      const payload = await this.replaceTask(state, claimed);
      return { status: "claimed", payload, task: claimed };
    });
  }

  complete(
    request: CompleteTavernCausalAuditTaskRequest,
  ): Promise<CompleteTavernCausalAuditTaskResult> {
    return this.enqueue(async () => {
      assertCanonicalTimestamp(request.completed_at, "completed_at");
      assertNonNegativeInteger(request.usage.model_calls, "usage.model_calls");
      assertNonNegativeInteger(request.usage.tool_calls, "usage.tool_calls");
      assertNonNegativeInteger(request.usage.input_tokens, "usage.input_tokens");
      const state = await this.requireExpected(request.expected_checksum);
      const task = this.requireTask(state, request.task_seed_id);
      const currentFindingFingerprint =
        request.current_seed === null ? null : await findingFingerprint(request.current_seed);
      if (!sameSeed(task, request.current_seed, currentFindingFingerprint)) {
        const stale = staleTask(task, request.completed_at);
        const payload = await this.replaceTask(state, stale);
        return { status: "stale", payload, task: stale };
      }
      if (
        task.status === "leased" &&
        Date.parse(task.lease?.expires_at ?? "") <= Date.parse(request.completed_at)
      ) {
        const exhausted = task.usage.attempts_used >= task.budget.max_attempts;
        const recovered: TavernCausalAuditTaskStateRecord = {
          ...omitTask(task, "lease", "resolution", "terminal_reason"),
          status: exhausted ? "failed" : "pending",
          updated_at: request.completed_at,
          record_version: task.record_version + 1,
          last_error_code: "LEASE_EXPIRED",
          ...(exhausted ? { terminal_reason: "ATTEMPT_BUDGET_EXHAUSTED" } : {}),
        };
        const payload = await this.replaceTask(state, recovered);
        return { status: exhausted ? "failed" : "retry_pending", payload, task: recovered };
      }
      if (task.status !== "leased" || task.lease?.lease_id !== request.lease_id) {
        throw new TavernCausalAuditTaskStoreError(
          "LEASE_MISMATCH",
          "Completion requires the current Tavern task lease",
        );
      }
      const usage = {
        attempts_used: task.usage.attempts_used,
        model_calls_used: task.usage.model_calls_used + request.usage.model_calls,
        tool_calls_used: task.usage.tool_calls_used + request.usage.tool_calls,
        input_tokens_used: task.usage.input_tokens_used + request.usage.input_tokens,
      };
      if (
        usage.model_calls_used > task.budget.max_model_calls ||
        usage.tool_calls_used > task.budget.max_tool_calls ||
        usage.input_tokens_used > task.budget.max_input_tokens
      ) {
        const failed: TavernCausalAuditTaskStateRecord = {
          ...omitTask(task, "lease", "resolution"),
          status: "failed",
          updated_at: request.completed_at,
          record_version: task.record_version + 1,
          terminal_reason: "BUDGET_EXCEEDED",
          last_error_code: "BUDGET_EXCEEDED",
        };
        const payload = await this.replaceTask(state, failed);
        return { status: "failed", payload, task: failed };
      }
      if (request.outcome.kind === "retryable_failure") {
        if (!CODE_PATTERN.test(request.outcome.error_code)) {
          throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid retry error code");
        }
        const canRetry = usage.attempts_used < task.budget.max_attempts;
        const next: TavernCausalAuditTaskStateRecord = {
          ...omitTask(task, "lease", "resolution", "terminal_reason"),
          status: canRetry ? "pending" : "failed",
          usage,
          updated_at: request.completed_at,
          record_version: task.record_version + 1,
          last_error_code: request.outcome.error_code,
          ...(canRetry ? {} : { terminal_reason: "ATTEMPT_BUDGET_EXHAUSTED" }),
        };
        const payload = await this.replaceTask(state, next);
        return { status: canRetry ? "retry_pending" : "failed", payload, task: next };
      }
      if (request.outcome.kind === "candidate_proposed") {
        if (
          request.outcome.candidate_contract_version.length < 1 ||
          request.outcome.candidate_contract_version.length > 128 ||
          !SHA256_PATTERN.test(request.outcome.candidate_artifact_sha256)
        ) {
          throw new TavernCausalAuditTaskStoreError(
            "INVALID_INPUT",
            "Invalid content-addressed candidate proposal",
          );
        }
      } else if (!CODE_PATTERN.test(request.outcome.reason_code)) {
        throw new TavernCausalAuditTaskStoreError(
          "INVALID_INPUT",
          "Invalid resolution reason code",
        );
      }
      const resolution = clone(request.outcome as TavernCausalAuditTaskResolution);
      const status =
        resolution.kind === "candidate_proposed"
          ? "proposal_pending_validation"
          : resolution.kind === "unresolved"
            ? "unresolved"
            : "resolved";
      const next: TavernCausalAuditTaskStateRecord = {
        ...omitTask(task, "lease", "resolution", "last_error_code", "terminal_reason"),
        status,
        usage,
        resolution,
        updated_at: request.completed_at,
        record_version: task.record_version + 1,
        ...(status === "resolved" || status === "unresolved"
          ? { terminal_reason: "AUDIT_COMPLETED" }
          : {}),
      };
      const payload = await this.replaceTask(state, next);
      return {
        status:
          status === "proposal_pending_validation" ? "proposal_pending_validation" : "completed",
        payload,
        task: next,
      };
    });
  }

  finalizeCandidate(
    request: FinalizeTavernCausalAuditCandidateRequest,
  ): Promise<FinalizeTavernCausalAuditCandidateResult> {
    return this.enqueue(async () => {
      assertCanonicalTimestamp(request.finalized_at, "finalized_at");
      assertNonNegativeInteger(request.expected_record_version, "expected_record_version");
      const state = await this.requireExpected(request.expected_checksum);
      const task = this.requireTask(state, request.task_seed_id);
      const currentFindingFingerprint =
        request.current_seed === null ? null : await findingFingerprint(request.current_seed);
      if (!sameSeed(task, request.current_seed, currentFindingFingerprint)) {
        const stale = staleTask(task, request.finalized_at);
        const payload = await this.replaceTask(state, stale);
        return { status: "stale", payload, task: stale };
      }
      if (task.record_version !== request.expected_record_version) {
        throw new TavernCausalAuditTaskStoreError(
          "RECORD_VERSION_MISMATCH",
          "Candidate finalization requires the current task version",
        );
      }
      if (
        task.status !== "proposal_pending_validation" ||
        task.resolution?.kind !== "candidate_proposed"
      ) {
        throw new TavernCausalAuditTaskStoreError(
          "INVALID_INPUT",
          "Only a pending candidate can be finalized",
        );
      }
      if (request.outcome.kind === "accepted") {
        if (getNarraMemIdKind(request.outcome.authorized_changeset_id) !== "change_set") {
          throw new TavernCausalAuditTaskStoreError(
            "INVALID_INPUT",
            "Accepted candidate requires an AuthorizedChangeSet ID",
          );
        }
        const resolved: TavernCausalAuditTaskStateRecord = {
          ...omitTask(task, "resolution", "last_error_code", "terminal_reason"),
          status: "resolved",
          resolution: {
            kind: "candidate_committed",
            candidate_contract_version: task.resolution.candidate_contract_version,
            candidate_artifact_sha256: task.resolution.candidate_artifact_sha256,
            authorized_changeset_id: request.outcome.authorized_changeset_id,
          },
          updated_at: request.finalized_at,
          record_version: task.record_version + 1,
          terminal_reason: "CANDIDATE_COMMITTED",
        };
        const payload = await this.replaceTask(state, resolved);
        return { status: "resolved", payload, task: resolved };
      }
      if (!CODE_PATTERN.test(request.outcome.error_code)) {
        throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid rejection error code");
      }
      const canRetry =
        request.outcome.retryable && task.usage.attempts_used < task.budget.max_attempts;
      const next: TavernCausalAuditTaskStateRecord = {
        ...omitTask(task, "resolution", "terminal_reason"),
        status: canRetry ? "pending" : "failed",
        updated_at: request.finalized_at,
        record_version: task.record_version + 1,
        last_error_code: request.outcome.error_code,
        ...(canRetry ? {} : { terminal_reason: "CANDIDATE_REJECTED" }),
      };
      const payload = await this.replaceTask(state, next);
      return { status: canRetry ? "retry_pending" : "failed", payload, task: next };
    });
  }

  cancel(
    expectedChecksum: string,
    taskSeedId: string,
    reason: string,
    cancelledAt: string,
  ): Promise<TavernCausalAuditTaskStorePayload> {
    return this.enqueue(async () => {
      assertCanonicalTimestamp(cancelledAt, "cancelled_at");
      if (!CODE_PATTERN.test(reason)) {
        throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid cancellation reason");
      }
      const state = await this.requireExpected(expectedChecksum);
      const task = this.requireTask(state, taskSeedId);
      if (TERMINAL.has(task.status)) return state.payload;
      const cancelled: TavernCausalAuditTaskStateRecord = {
        ...omitTask(task, "lease", "resolution", "last_error_code", "terminal_reason"),
        status: "cancelled",
        updated_at: cancelledAt,
        record_version: task.record_version + 1,
        terminal_reason: reason,
      };
      return this.replaceTask(state, cancelled);
    });
  }

  private async readState(): Promise<StoreState | null> {
    if (!this.port.listWorldbooks().includes(this.book_name)) return null;
    const entries = await this.port.readWorldbook(this.book_name);
    const entry = entries[0];
    if (entries.length !== 1 || entry === undefined) {
      throw new TavernCausalAuditTaskStoreError(
        "STORE_CORRUPT",
        "Task World Book must contain exactly one entry",
      );
    }
    assertMachineEntry(entry);
    return { entry, payload: await parsePayload(entry.content, this.memory_set_id) };
  }

  private async requireExpected(expectedChecksum: string): Promise<StoreState> {
    if (!SHA256_PATTERN.test(expectedChecksum)) {
      throw new TavernCausalAuditTaskStoreError("INVALID_INPUT", "Invalid expected checksum");
    }
    const state = await this.readState();
    if (state === null) {
      throw new TavernCausalAuditTaskStoreError("STORE_NOT_FOUND", "Task World Book is missing");
    }
    if (state.payload.checksum !== expectedChecksum) {
      throw new TavernCausalAuditTaskStoreError(
        "WRITE_CONFLICT",
        "Task World Book changed before mutation",
      );
    }
    return state;
  }

  private requireTask(state: StoreState, taskSeedId: string): TavernCausalAuditTaskStateRecord {
    const task = state.payload.tasks.find((candidate) => candidate.task_seed_id === taskSeedId);
    if (task === undefined) {
      throw new TavernCausalAuditTaskStoreError("TASK_NOT_FOUND", "Task seed is not persisted");
    }
    return task;
  }

  private async replaceTask(
    state: StoreState,
    nextTask: TavernCausalAuditTaskStateRecord,
  ): Promise<TavernCausalAuditTaskStorePayload> {
    return this.writePayload(
      state,
      state.payload.execution_preference,
      state.payload.tasks.map((task) =>
        task.task_seed_id === nextTask.task_seed_id ? nextTask : task,
      ),
    );
  }

  private async writePayload(
    state: StoreState,
    preference: TavernCausalAuditExecutionPreference,
    tasks: readonly TavernCausalAuditTaskStateRecord[],
  ): Promise<TavernCausalAuditTaskStorePayload> {
    const current = await this.readState();
    if (
      current === null ||
      current.entry.uid !== state.entry.uid ||
      current.payload.checksum !== state.payload.checksum
    ) {
      throw new TavernCausalAuditTaskStoreError(
        "WRITE_CONFLICT",
        "Task World Book changed during mutation",
      );
    }
    const payload = await encodePayload(this.memory_set_id, preference, tasks);
    if (payload.checksum === state.payload.checksum) return state.payload;
    await this.port.replaceWorldbook(this.book_name, [
      { ...machineEntryDraft(canonicalJson(payload)), uid: state.entry.uid },
    ]);
    const verified = await this.readState();
    if (verified?.payload.checksum !== payload.checksum) {
      throw new TavernCausalAuditTaskStoreError(
        "WRITE_CONFLICT",
        "Task World Book write lost the read-back race",
      );
    }
    return verified.payload;
  }
}
