import type {
  TavernControlPayload,
  TavernMemoryIdentityAnchor,
} from "./worldbook-store-contracts.js";

export const TAVERN_REGISTRY_VERSION = "0.1.0" as const;
export const TAVERN_REGISTRY_FORMAT = "narramem.tavern-registry" as const;

export interface TavernRegistryRecord {
  readonly memory_set_id: string;
  readonly control_book_name: string;
  readonly character_id: string;
  readonly chat_id: string;
  readonly chat_anchor_hash: string;
}

export interface TavernRegistryPayload {
  readonly format: typeof TAVERN_REGISTRY_FORMAT;
  readonly schema_version: typeof TAVERN_REGISTRY_VERSION;
  readonly records: readonly TavernRegistryRecord[];
  readonly checksum: string;
}

export interface TavernIdentityProbe {
  readonly character_id: string;
  readonly chat_id: string;
  readonly chat_anchor_hash: string;
  readonly sampled_visible_messages: number;
}

export interface TavernControlCandidate {
  readonly control_book_name: string;
  readonly control: TavernControlPayload;
}

export interface TavernRegistryIssue {
  readonly book_name: string;
  readonly code: "REGISTRY_MISSING" | "REGISTRY_CORRUPT" | "CONTROL_CORRUPT" | "STALE_RECORD";
  readonly detail: string;
}

export interface TavernMemorySetResolution {
  readonly status: "EXACT" | "LOCATOR_CONFLICT" | "ANCHOR_CONFIRMATION_REQUIRED" | "NOT_FOUND";
  readonly probe: TavernIdentityProbe;
  readonly selected: TavernControlCandidate | null;
  readonly candidates: readonly TavernControlCandidate[];
  readonly registry_repair_needed: boolean;
  readonly issues: readonly TavernRegistryIssue[];
}

export interface TavernRegistryRebuildResult {
  readonly registry: TavernRegistryPayload;
  readonly control_count: number;
  readonly issues: readonly TavernRegistryIssue[];
}

export interface TavernMemorySetCreateRequest {
  readonly memory_set_id: string;
  readonly probe: TavernIdentityProbe;
  readonly character_revision_hash: string | null;
  readonly max_records_per_segment: number;
  readonly max_segment_utf8_bytes: number;
}

export interface TavernMemorySetCreateResult {
  readonly control_book_name: string;
  readonly segment_book_prefix: string;
  readonly identity_anchor: TavernMemoryIdentityAnchor;
  readonly control: TavernControlPayload;
  readonly registry_updated: boolean;
  readonly registry_issue?: string;
}

export interface TavernMemorySetRebindRequest {
  readonly control_book_name: string;
  readonly expected_control_checksum: string;
  readonly probe: TavernIdentityProbe;
  readonly character_revision_hash: string | null;
}

export interface TavernMemorySetRebindResult {
  readonly control: TavernControlPayload;
  readonly registry_updated: boolean;
  readonly registry_issue?: string;
}

export class TavernMemoryRegistryError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "REGISTRY_CORRUPT"
      | "REGISTRY_WRITE_CONFLICT"
      | "MEMORY_SET_COLLISION"
      | "UNSAFE_REBUILD",
    message: string,
  ) {
    super(message);
    this.name = "TavernMemoryRegistryError";
  }
}
