export const TAVERN_CAUSAL_AUDIT_WORKER_VERSION = "0.1.0" as const;
const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";
const CODE_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/u;

export interface TavernCausalAuditWorkerClock {
  now(): string;
}

export interface TavernCausalAuditModelPort {
  readonly provider_route_id: string;
  readonly max_transport_attempts: number;
  render_generation(
    request: CausalAuditWorkerCompletionRequest,
  ):
    | Omit<TavernStructuredGenerationRequest, "generation_id">
    | Promise<Omit<TavernStructuredGenerationRequest, "generation_id">>;
  count_input_tokens(
    generation: Omit<TavernStructuredGenerationRequest, "generation_id">,
  ): number | Promise<number>;
}

interface TavernCausalAuditWorkerSnapshot {
  readonly control: TavernControlPayload;
  readonly archive_records: readonly TavernArchiveRecord[];
  readonly semantic_manifest: TavernSemanticManifestPayload;
  readonly seed: TavernCausalAuditTaskSeed;
  readonly live_source_current: boolean;
}

export interface RunTavernCausalAuditWorkerAttemptRequest {
  readonly memory_set_id: string;
  readonly task: TavernCausalAuditTaskStateRecord;
  readonly task_store: TavernCausalAuditTaskWorldbookStore;
  readonly transport: TavernAgentTransportCallRunner;
  readonly port: TavernHostPort;
  readonly model: TavernCausalAuditModelPort;
  readonly adapter: CausalAuditWorkerAdapter;
  readonly investigation_options: TavernCausalAuditInvestigationOptions;
  readonly segment_limits: {
    readonly max_records_per_segment: number;
    readonly max_segment_utf8_bytes: number;
  };
  readonly clock: TavernCausalAuditWorkerClock;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export type RunTavernCausalAuditWorkerAttemptResult =
  | {
      readonly status: "completed";
      readonly worker: Extract<CausalAuditWorkerResult, { readonly status: "completed" }>;
      readonly task_completion: CompleteTavernCausalAuditTaskResult;
      readonly candidate_authorization?: TavernCausalAuditAuthorizationResult;
      readonly archive_commit?: TavernCausalAuditArchiveCommitResult;
      readonly candidate_finalization?: FinalizeTavernCausalAuditCandidateResult;
    }
  | {
      readonly status: "blocked";
      readonly worker: Extract<CausalAuditWorkerResult, { readonly status: "blocked" }>;
      readonly task_completion?: CompleteTavernCausalAuditTaskResult;
    }
  | {
      readonly status: "suspended_unknown";
      readonly worker: Extract<CausalAuditWorkerResult, { readonly status: "blocked" }>;
      readonly task: TavernCausalAuditTaskStateRecord;
    }
  | {
      readonly status: "archive_commit_pending_recovery";
      readonly worker: Extract<CausalAuditWorkerResult, { readonly status: "completed" }>;
      readonly task_completion: CompleteTavernCausalAuditTaskResult;
      readonly candidate_authorization: AuthorizedTavernCausalAuditCandidate;
      readonly error_code: string;
    }
  | {
      readonly status: "archive_committed_pending_finalization";
      readonly worker: Extract<CausalAuditWorkerResult, { readonly status: "completed" }>;
      readonly task_completion: CompleteTavernCausalAuditTaskResult;
      readonly candidate_authorization: AuthorizedTavernCausalAuditCandidate;
      readonly archive_commit: TavernCausalAuditArchiveCommitResult;
      readonly error_code: string;
    };

export interface RecoverTavernCausalAuditFinalizationRequest {
  readonly memory_set_id: string;
  readonly task_seed_id: string;
  readonly task_store: TavernCausalAuditTaskWorldbookStore;
  readonly port: TavernHostPort;
  readonly segment_limits: RunTavernCausalAuditWorkerAttemptRequest["segment_limits"];
  readonly clock: TavernCausalAuditWorkerClock;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

function sameSeed(left: TavernCausalAuditTaskSeed, right: TavernCausalAuditTaskSeed): boolean {
  return (
    left.task_seed_id === right.task_seed_id &&
    left.memory_set_id === right.memory_set_id &&
    left.source_revision_id === right.source_revision_id &&
    left.source_checksum === right.source_checksum &&
    left.semantic_task_fingerprint === right.semantic_task_fingerprint &&
    left.source_response_sha256 === right.source_response_sha256 &&
    canonicalJson(left.finding) === canonicalJson(right.finding)
  );
}

function findTask(
  payload: TavernCausalAuditTaskStorePayload | null,
  taskSeedId: string,
): TavernCausalAuditTaskStateRecord | undefined {
  return payload?.tasks.find((task) => task.task_seed_id === taskSeedId);
}

function taskUsage(worker: CausalAuditWorkerResult) {
  return {
    model_calls: worker.usage.model_calls,
    tool_calls: worker.usage.tool_calls,
    input_tokens: worker.usage.input_tokens,
  };
}

function uppercaseReason(reason: string): string {
  const code = reason.toUpperCase();
  return CODE_PATTERN.test(code) ? code : "MODEL_REASON_CODE_INVALID";
}

function storeFor(
  port: TavernHostPort,
  controlBookName: string,
  control: TavernControlPayload,
  limits: RunTavernCausalAuditWorkerAttemptRequest["segment_limits"],
) {
  return new TavernWorldbookSnapshotStore(port, {
    memory_set_id: control.memory_set_id,
    control_book_name: controlBookName,
    segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${control.memory_set_id}__`,
    initial_identity_anchor: control.identity_anchor,
    max_records_per_segment: limits.max_records_per_segment,
    max_segment_utf8_bytes: limits.max_segment_utf8_bytes,
  });
}

async function loadSnapshot(
  port: TavernHostPort,
  memorySetId: string,
  taskSeedId: string,
  limits: RunTavernCausalAuditWorkerAttemptRequest["segment_limits"],
  normalizeSemanticMetadata?: TavernSemanticMetadataNormalizer,
): Promise<TavernCausalAuditWorkerSnapshot> {
  const resolution = await new TavernMemoryRegistry(port).resolveCurrentMemorySet();
  if (
    resolution.status !== "EXACT" ||
    resolution.selected === null ||
    resolution.selected.control.memory_set_id !== memorySetId
  ) {
    throw new TypeError(`Tavern Causal Audit requires exact Memory Set ${memorySetId}`);
  }
  const store = storeFor(
    port,
    resolution.selected.control_book_name,
    resolution.selected.control,
    limits,
  );
  const control = await store.readControl();
  if (control.active_view === null)
    throw new TypeError("Tavern Causal Audit has no active archive");
  const archiveRecords = await store.readActiveSnapshot();
  const source = await reconstructTavernSourceSnapshot(archiveRecords, memorySetId);
  if (
    source.source_revision !== control.active_view.source_revision ||
    source.checksum !== control.active_view.source_checksum
  ) {
    throw new TypeError("Tavern Causal Audit source manifest does not match Control");
  }
  const semanticManifest = readTavernSemanticManifestFromArchive(archiveRecords);
  if (semanticManifest === null)
    throw new TypeError("Tavern Causal Audit semantic manifest is absent");
  const seeds = await projectTavernCausalAuditTaskSeeds(memorySetId, semanticManifest);
  const seed = seeds.find((item) => item.task_seed_id === taskSeedId);
  if (seed === undefined) throw new TypeError("Tavern Causal Audit seed is no longer active");
  const live = await reconcileTavernSourceSnapshot(port, {
    memory_set_id: memorySetId,
    previous_snapshot: source,
    observed_hints: [],
    ...(normalizeSemanticMetadata === undefined
      ? {}
      : { normalize_semantic_metadata: normalizeSemanticMetadata }),
  });
  return {
    control,
    archive_records: archiveRecords,
    semantic_manifest: semanticManifest,
    seed,
    live_source_current: live.status === "UNCHANGED",
  };
}

function evidenceQuotes(
  task: TavernCausalAuditCandidateTask,
  reviewedEvidenceIds: ReadonlySet<NarraMemId<"evidence">>,
) {
  return [...task.evidence_items]
    .sort((left, right) => {
      if (left.evidence_id === task.seed.finding.evidence_id) return -1;
      if (right.evidence_id === task.seed.finding.evidence_id) return 1;
      return left.evidence_id.localeCompare(right.evidence_id);
    })
    .flatMap((evidence) =>
      reviewedEvidenceIds.has(evidence.evidence_id) && evidence.raw_content.kind === "text"
        ? [
            {
              evidence_id: evidence.evidence_id,
              quote: evidence.raw_content.text,
              occurrence: 0,
              support_role:
                evidence.evidence_id === task.seed.finding.evidence_id
                  ? ("direct" as const)
                  : ("context" as const),
            },
          ]
        : [],
    );
}

function assertGeneration(
  workerRequest: CausalAuditWorkerCompletionRequest,
  generation: Omit<TavernStructuredGenerationRequest, "generation_id">,
): void {
  if (
    generation.target.requested_model_id !== workerRequest.exact_model_id ||
    generation.target.identity_assurance !== "requested_not_attested" ||
    generation.should_silence !== true ||
    generation.should_stream !== false ||
    generation.max_chat_history !== 0 ||
    generation.json_schema.name !== workerRequest.output_schema ||
    canonicalJson(generation.prompt_asset_refs) !==
      canonicalJson([workerRequest.prompt_asset_ref]) ||
    !generation.messages.some((message) => message.content === workerRequest.input_json)
  ) {
    throw new TypeError("Tavern model generation does not preserve the exact Worker contract");
  }
}

async function deterministicArchiveIds(taskSeedId: string, leaseId: string) {
  const hash = await sha256HexUtf8(
    canonicalJson({
      worker_version: TAVERN_CAUSAL_AUDIT_WORKER_VERSION,
      task_seed_id: taskSeedId,
      lease_id: leaseId,
    }),
  );
  return {
    transaction_id: `audit_tx_${hash}`,
    writer_id: `audit_writer_${hash}`,
    build_id: `audit_build_${hash}`,
    view_id: `audit_view_${hash}`,
  };
}

export async function runTavernCausalAuditWorkerAttempt(
  request: RunTavernCausalAuditWorkerAttemptRequest,
): Promise<RunTavernCausalAuditWorkerAttemptResult> {
  const lease = request.task.lease;
  if (request.task.status !== "leased" || lease === undefined) {
    throw new TypeError("Tavern Causal Audit Worker requires a leased task");
  }
  const initialTaskPayload = await request.task_store.read();
  const currentTask = findTask(initialTaskPayload, request.task.task_seed_id);
  if (
    currentTask?.status !== "leased" ||
    currentTask.lease?.lease_id !== lease.lease_id ||
    currentTask.record_version !== request.task.record_version
  ) {
    throw new TypeError("Tavern Causal Audit Worker task is not the current durable lease");
  }
  const remainingModelCalls =
    request.task.budget.max_model_calls - request.task.usage.model_calls_used;
  if (remainingModelCalls < 1) {
    throw new TypeError("Tavern Causal Audit Worker has no remaining model-call budget");
  }
  const frozen = await loadSnapshot(
    request.port,
    request.memory_set_id,
    request.task.task_seed_id,
    request.segment_limits,
    request.normalize_semantic_metadata,
  );
  if (!frozen.live_source_current)
    throw new TypeError("Tavern Causal Audit source is already stale");
  const investigation = await TavernCausalAuditReadonlyInvestigation.create(
    frozen.seed,
    request.task,
    frozen.archive_records,
    request.investigation_options,
  );
  const agentTaskId = await createTavernCausalAuditAgentTaskId(frozen.seed);
  const seed: CausalAuditAgentTaskSeed = createTavernCausalAuditAgentSeed(
    agentTaskId,
    frozen.seed,
    investigation.frozen_corpus,
  );
  let inputTokensAccounted = 0;
  let suspendedUnknown = false;
  let candidateTask: TavernCausalAuditCandidateTask | undefined;

  const currentSnapshot = () =>
    loadSnapshot(
      request.port,
      request.memory_set_id,
      request.task.task_seed_id,
      request.segment_limits,
      request.normalize_semantic_metadata,
    );
  const sourceIsCurrent = async () => {
    try {
      const taskPayload = await request.task_store.read();
      const task = findTask(taskPayload, request.task.task_seed_id);
      if (
        task?.status !== "leased" ||
        task.lease?.lease_id !== lease.lease_id ||
        task.record_version !== request.task.record_version ||
        Date.parse(task.lease.expires_at) <= Date.parse(request.clock.now())
      ) {
        return false;
      }
      const snapshot = await currentSnapshot();
      if (!snapshot.live_source_current || !sameSeed(snapshot.seed, frozen.seed)) return false;
      const corpus = await createTavernCausalAuditReadonlyCorpus(
        snapshot.seed,
        snapshot.archive_records,
      );
      return (
        snapshot.control.checksum === frozen.control.checksum &&
        corpus.snapshot_fingerprint.value === investigation.frozen_corpus.snapshot_fingerprint.value
      );
    } catch {
      return false;
    }
  };

  const completion: CausalAuditWorkerCompletionPort = {
    async complete<Value>(
      workerRequest: CausalAuditWorkerCompletionRequest,
      validate: (
        content: string,
      ) => CausalAuditWorkerValidation<Value> | Promise<CausalAuditWorkerValidation<Value>>,
    ): Promise<CausalAuditWorkerCompletionResult<Value>> {
      if (!(await sourceIsCurrent())) {
        return { status: "blocked", error_code: "SOURCE_REVISION_STALE" };
      }
      let generation: Omit<TavernStructuredGenerationRequest, "generation_id">;
      let countedInputTokens: number;
      try {
        generation = await request.model.render_generation(workerRequest);
        assertGeneration(workerRequest, generation);
        countedInputTokens = await request.model.count_input_tokens(generation);
      } catch {
        return { status: "blocked", error_code: "MODEL_REQUEST_BUILD_FAILED" };
      }
      if (!Number.isSafeInteger(countedInputTokens) || countedInputTokens < 0) {
        return { status: "blocked", error_code: "MODEL_REQUEST_ACCOUNTING_INVALID" };
      }
      const remainingInputTokens =
        request.task.budget.max_input_tokens -
        request.task.usage.input_tokens_used -
        inputTokensAccounted;
      if (countedInputTokens > remainingInputTokens) {
        return { status: "blocked", error_code: "INPUT_TOKEN_BUDGET_EXCEEDED" };
      }
      let result: TavernAgentTransportCallResult<Value>;
      try {
        result = await request.transport.execute({
          task: request.task,
          operation_kind: workerRequest.operation_kind,
          call_index: workerRequest.call_index,
          provider_route_id: request.model.provider_route_id,
          generation,
          max_attempts: request.model.max_transport_attempts,
          is_source_current: sourceIsCurrent,
          validate: async (response: TavernStructuredGenerationResult) => {
            if (response.kind !== "text") {
              return { accepted: false, error_code: "UNEXPECTED_TOOL_CALLS" };
            }
            return validate(response.content);
          },
        });
      } catch {
        suspendedUnknown = true;
        inputTokensAccounted += countedInputTokens;
        return {
          status: "blocked",
          error_code: "DISPATCH_OUTCOME_UNKNOWN",
          model_call_accounted: true,
          input_tokens_accounted: countedInputTokens,
          output_tokens_observed: 0,
        };
      }
      inputTokensAccounted += countedInputTokens;
      if (result.status === "COMMITTED") {
        return {
          status: "committed",
          value: result.value,
          transport_operation_id: result.operation.operation_id,
          input_tokens_accounted: countedInputTokens,
          output_tokens_observed: 0,
        };
      }
      if (
        result.status === "SUSPENDED_UNKNOWN" ||
        result.error_code === "SOURCE_MUTATION_CANCELLED" ||
        result.error_code === "HOST_DISPATCH_OUTCOME_UNKNOWN"
      ) {
        suspendedUnknown = true;
      }
      return {
        status: "blocked",
        error_code: result.error_code,
        transport_operation_id: result.operation.operation_id,
        model_call_accounted: true,
        input_tokens_accounted: countedInputTokens,
        output_tokens_observed: 0,
      };
    },
  };

  const worker = await runCausalAuditWorker({
    task: seed,
    adapter: request.adapter,
    investigation: {
      get transcript() {
        return investigation.transcript;
      },
      execute: async (action: InvestigationAction) => {
        try {
          const snapshot = await currentSnapshot();
          return investigation.execute(action, snapshot.seed, snapshot.archive_records);
        } catch {
          return investigation.execute(action, null, frozen.archive_records);
        }
      },
    },
    completion,
    hash_text: async (text) => createSha256Digest(await sha256HexUtf8(text)),
    max_model_calls: remainingModelCalls,
    enumerate_actions: (task, transcript) =>
      enumerateCausalAuditProgressiveFrontierActions(investigation.frozen_corpus, task, transcript),
    build_final_context: async (transcript) => {
      const selection = await deriveTavernCausalAuditSelectionFromTranscript(transcript);
      candidateTask = createTavernCausalAuditCandidateTask(
        agentTaskId,
        frozen.seed,
        investigation.frozen_corpus,
        frozen.archive_records,
        {
          reviewed_record_refs: [
            ...new Set([...seed.seed_record_refs, ...selection.reviewed_record_refs]),
          ],
          reviewed_evidence_refs: [
            ...new Set([...seed.seed_evidence_refs, ...selection.reviewed_evidence_refs]),
          ],
        },
      );
      const reviewedEvidenceIds = new Set<NarraMemId<"evidence">>([
        ...seed.seed_evidence_refs,
        ...transcript.steps.flatMap((step) =>
          step.kind === "tool" ? step.observation.returned_evidence_refs : [],
        ),
      ]);
      return {
        allowlists: {
          allowed_cause_refs: candidateTask.allowed_cause_refs,
          allowed_effect_refs: candidateTask.allowed_effect_refs,
          allowed_holder_entity_ids: candidateTask.allowed_holder_entity_ids,
        },
        option_source: {
          evidence_quotes: evidenceQuotes(candidateTask, reviewedEvidenceIds),
          candidate_context: candidateTask.validation_context,
        },
      };
    },
  });

  if (worker.status === "blocked") {
    if (suspendedUnknown) {
      return {
        status: "suspended_unknown",
        worker,
        task: findTask(await request.task_store.read(), request.task.task_seed_id) ?? request.task,
      };
    }
    let currentSeed: TavernCausalAuditTaskSeed | null = null;
    try {
      const snapshot = await currentSnapshot();
      currentSeed = snapshot.live_source_current ? snapshot.seed : null;
    } catch {
      // A missing current seed is persisted as stale by the Task Store.
    }
    const payload = await request.task_store.read();
    if (payload === null) throw new TypeError("Tavern Causal Audit Task Store disappeared");
    const taskCompletion = await request.task_store.complete({
      expected_checksum: payload.checksum,
      task_seed_id: request.task.task_seed_id,
      lease_id: lease.lease_id,
      current_seed: currentSeed,
      completed_at: request.clock.now(),
      usage: taskUsage(worker),
      outcome: { kind: "retryable_failure", error_code: worker.error_code },
    });
    return { status: "blocked", worker, task_completion: taskCompletion };
  }

  const afterWorker = await currentSnapshot().catch(() => null);
  const currentSeed = afterWorker?.live_source_current === true ? afterWorker.seed : null;
  const taskPayload = await request.task_store.read();
  if (taskPayload === null) throw new TypeError("Tavern Causal Audit Task Store disappeared");
  if (worker.decision.decision !== "candidate") {
    const taskCompletion = await request.task_store.complete({
      expected_checksum: taskPayload.checksum,
      task_seed_id: request.task.task_seed_id,
      lease_id: lease.lease_id,
      current_seed: currentSeed,
      completed_at: request.clock.now(),
      usage: taskUsage(worker),
      outcome: {
        kind: worker.decision.decision,
        reason_code: uppercaseReason(worker.decision.reason_code),
      },
    });
    return { status: "completed", worker, task_completion: taskCompletion };
  }
  if (candidateTask === undefined) {
    throw new TypeError("Tavern Causal Audit Worker lost its frozen Candidate task");
  }
  const authorization = await authorizeTavernCausalAuditCandidate(
    candidateTask,
    worker.decision.candidate,
    {
      extractor: {
        kind: "llm",
        model_id: request.adapter.exact_model_id,
        prompt_contract_version: `${request.adapter.action_prompt_asset_ref}+${request.adapter.final_prompt_asset_ref}`,
        parameters_hash: createSha256Digest(
          await sha256HexUtf8(
            canonicalJson({
              adapter_id: request.adapter.adapter_id,
              action_parameters: request.adapter.action_parameters,
              final_parameters: request.adapter.final_parameters,
            }),
          ),
        ),
      },
      compilation_key: `${request.task.task_seed_id}:${lease.lease_id}`,
      authorized_at: request.clock.now(),
    },
  );
  const artifactHash =
    authorization.status === "authorized"
      ? authorization.candidate_artifact_sha256
      : await sha256HexUtf8(canonicalJson(worker.decision.candidate));
  const proposed = await request.task_store.complete({
    expected_checksum: taskPayload.checksum,
    task_seed_id: request.task.task_seed_id,
    lease_id: lease.lease_id,
    current_seed: currentSeed,
    completed_at: request.clock.now(),
    usage: taskUsage(worker),
    outcome: {
      kind: "candidate_proposed",
      candidate_contract_version: CAUSAL_AUDIT_CANDIDATE_CONTRACT_VERSION,
      candidate_artifact_sha256: artifactHash,
    },
  });
  if (proposed.status !== "proposal_pending_validation") {
    return {
      status: "completed",
      worker,
      task_completion: proposed,
      candidate_authorization: authorization,
    };
  }
  if (authorization.status !== "authorized") {
    const finalized = await request.task_store.finalizeCandidate({
      expected_checksum: proposed.payload.checksum,
      expected_record_version: proposed.task.record_version,
      task_seed_id: request.task.task_seed_id,
      current_seed: currentSeed,
      finalized_at: request.clock.now(),
      outcome: {
        kind: "rejected",
        error_code: authorization.issues[0]?.code ?? "CANDIDATE_AUTHORIZATION_REJECTED",
        retryable: false,
      },
    });
    return {
      status: "completed",
      worker,
      task_completion: proposed,
      candidate_authorization: authorization,
      candidate_finalization: finalized,
    };
  }
  const archiveIds = await deterministicArchiveIds(request.task.task_seed_id, lease.lease_id);
  let archiveCommit: TavernCausalAuditArchiveCommitResult;
  try {
    archiveCommit = await new TavernCausalAuditArchiveCommitService(
      request.port,
      request.segment_limits,
    ).commit({
      task: candidateTask,
      authorization,
      expected_control_checksum: frozen.control.checksum,
      expected_active_view_id: frozen.control.active_view?.view_id ?? "",
      ...archiveIds,
      ...(request.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
    });
  } catch (error) {
    return {
      status: "archive_commit_pending_recovery",
      worker,
      task_completion: proposed,
      candidate_authorization: authorization,
      error_code:
        error instanceof TavernCausalAuditArchiveCommitError
          ? error.code
          : "ARCHIVE_COMMIT_OUTCOME_UNKNOWN",
    };
  }
  try {
    const finalSnapshot = await currentSnapshot();
    const latestTaskPayload = await request.task_store.read();
    if (latestTaskPayload === null) throw new TypeError("Tavern Task Store disappeared");
    const finalTask = findTask(latestTaskPayload, request.task.task_seed_id);
    if (finalTask === undefined) throw new TypeError("Tavern Causal Audit task disappeared");
    const finalized = await request.task_store.finalizeCandidate({
      expected_checksum: latestTaskPayload.checksum,
      expected_record_version: finalTask.record_version,
      task_seed_id: request.task.task_seed_id,
      current_seed: finalSnapshot.live_source_current ? finalSnapshot.seed : null,
      finalized_at: request.clock.now(),
      outcome: {
        kind: "accepted",
        authorized_changeset_id: authorization.authorized_changeset.changeset_id,
      },
    });
    return {
      status: "completed",
      worker,
      task_completion: proposed,
      candidate_authorization: authorization,
      archive_commit: archiveCommit,
      candidate_finalization: finalized,
    };
  } catch {
    return {
      status: "archive_committed_pending_finalization",
      worker,
      task_completion: proposed,
      candidate_authorization: authorization,
      archive_commit: archiveCommit,
      error_code: "TASK_FINALIZATION_WRITE_CONFLICT",
    };
  }
}

export async function recoverTavernCausalAuditCandidateFinalization(
  request: RecoverTavernCausalAuditFinalizationRequest,
): Promise<FinalizeTavernCausalAuditCandidateResult> {
  const taskPayload = await request.task_store.read();
  const task = findTask(taskPayload, request.task_seed_id);
  if (
    taskPayload === null ||
    task?.status !== "proposal_pending_validation" ||
    task.resolution?.kind !== "candidate_proposed"
  ) {
    throw new TypeError("Tavern recovery requires one pending Candidate task");
  }
  const snapshot = await loadSnapshot(
    request.port,
    request.memory_set_id,
    request.task_seed_id,
    request.segment_limits,
    request.normalize_semantic_metadata,
  );
  const receipt = readTavernCausalAuditCommitReceipt(
    snapshot.archive_records,
    request.task_seed_id,
  );
  const expectedAgentTaskId = await createTavernCausalAuditAgentTaskId(snapshot.seed);
  if (
    receipt === null ||
    receipt.agent_task_id !== expectedAgentTaskId ||
    receipt.source_revision_id !== task.source_revision_id ||
    receipt.source_checksum !== task.source_checksum ||
    receipt.candidate_artifact_sha256 !== task.resolution.candidate_artifact_sha256
  ) {
    throw new TypeError("Active archive has no exact receipt for the pending Candidate");
  }
  const authorized = snapshot.archive_records.find(
    (record) =>
      record.record_id === receipt.authorized_changeset_id &&
      record.record_kind === "core_authorized_changeset_v1",
  );
  const authorizedWire =
    authorized === undefined
      ? null
      : validateWireValue("authorized_change_set", authorized.payload);
  const authorizedPayload =
    authorizedWire?.valid === true
      ? (authorized?.payload as unknown as AuthorizedTavernCausalAuditCandidate["authorized_changeset"])
      : null;
  const operationLinks =
    authorizedPayload?.operations.flatMap((operation) =>
      operation.op === "add_derived" && "causal_id" in operation.record ? [operation.record] : [],
    ) ?? [];
  const operationIds = operationLinks.map((link) => link.causal_id).sort();
  const receiptIds = [...receipt.causal_link_ids].sort();
  const linkedRecordsValid = operationLinks.every((link) => {
    const record = snapshot.archive_records.find(
      (item) => item.record_id === link.causal_id && item.record_kind === "core_causal_link_v1",
    );
    return (
      record !== undefined &&
      validateWireValue("causal_link", record.payload).valid &&
      canonicalJson(record.payload) === canonicalJson(link)
    );
  });
  if (
    authorizedPayload === null ||
    authorizedPayload.changeset_id !== receipt.authorized_changeset_id ||
    operationLinks.length !== authorizedPayload.operations.length ||
    canonicalJson(operationIds) !== canonicalJson(receiptIds) ||
    !linkedRecordsValid
  ) {
    throw new TypeError("Causal Audit receipt does not resolve to complete trusted Core records");
  }
  return request.task_store.finalizeCandidate({
    expected_checksum: taskPayload.checksum,
    expected_record_version: task.record_version,
    task_seed_id: task.task_seed_id,
    current_seed: snapshot.live_source_current ? snapshot.seed : null,
    finalized_at: request.clock.now(),
    outcome: { kind: "accepted", authorized_changeset_id: receipt.authorized_changeset_id },
  });
}
