import type {
  TavernCausalAuditPositiveReadiness,
  TavernHostPort,
  TavernObserverSchedulerSnapshot,
} from "@narramem/tavern-adapter";

export const TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION = "0.6.0" as const;
export const TAVERN_CAUSAL_AUDIT_EXACT_MODEL_ID = "[A-1000k]gemini-3.1-pro-preview" as const;

export interface TavernCausalAuditDiagnosticRuntimeContext {
  readonly snapshot: TavernObserverSchedulerSnapshot;
  readonly page_lifecycle: "visible" | "hidden" | "unloading";
  readonly execution_lane: "running_product_runtime" | "paused_quiesced_manual";
}

export interface TavernCausalAuditDiagnosticTaskSummary {
  readonly task_seed_id: string;
  readonly finding_code: "EXPLICIT_CAUSAL_CUE_UNCOVERED";
  readonly status: string;
  readonly positive_readiness?: TavernCausalAuditPositiveReadiness;
  readonly manual_execution: "ELIGIBLE" | "BLOCKED";
  readonly blocked_reason?: string;
  readonly manual_command?: `CAUSAL_AUDIT_RUN_MANUAL:${string}`;
}

export type TavernCausalAuditDiagnosticPreflight =
  | {
      readonly status: "READY";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly exact_model_id: typeof TAVERN_CAUSAL_AUDIT_EXACT_MODEL_ID;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly source_checksum: string;
      readonly semantic_task_fingerprint: string;
      readonly current_seed_count: number;
      readonly tasks: readonly TavernCausalAuditDiagnosticTaskSummary[];
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    }
  | {
      readonly status: "BLOCKED";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly reason: string;
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    };

export type TavernCausalAuditDiagnosticBindingSnapshot =
  | {
      readonly status: "READY";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly source_checksum: string;
      readonly semantic_task_fingerprint: string;
      readonly selected_task_seed_id: string;
      readonly task_store_checksum: string;
      readonly task_status_counts: Readonly<Record<string, number>>;
      readonly control_checksum: string;
      readonly control_commit_sequence: number;
      readonly active_view_id: string;
      readonly archive_record_counts: {
        readonly total: number;
        readonly core_causal_link_v1: number;
        readonly core_authorized_changeset_v1: number;
        readonly tavern_causal_audit_receipt_v1: number;
      };
      readonly transport_store_checksum: string | null;
      readonly transport_operation_count: number;
      readonly transport_response_artifact_count: number;
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    }
  | {
      readonly status: "BLOCKED";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly reason: string;
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    };

export type TavernCausalAuditDiagnosticRecoverySnapshot =
  | {
      readonly status: "READY";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly source_checksum: string;
      readonly semantic_task_fingerprint: string;
      readonly task_store_checksum: string;
      readonly task_status_counts: Readonly<Record<string, number>>;
      readonly tasks: readonly {
        readonly task_seed_id: string;
        readonly status: string;
        readonly record_version: number;
        readonly usage: {
          readonly attempts_used: number;
          readonly model_calls_used: number;
          readonly tool_calls_used: number;
          readonly input_tokens_used: number;
        };
        readonly resolution_kind: string | null;
      }[];
      readonly control_checksum: string;
      readonly control_commit_sequence: number;
      readonly active_view_id: string;
      readonly archive_record_counts: {
        readonly total: number;
        readonly core_causal_link_v1: number;
        readonly core_authorized_changeset_v1: number;
        readonly tavern_causal_audit_receipt_v1: number;
      };
      readonly transport_store_checksum: string | null;
      readonly transport_operation_count: number;
      readonly transport_response_artifact_count: number;
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    }
  | {
      readonly status: "BLOCKED";
      readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
      readonly reason: string;
      readonly external_model_calls: 0;
      readonly content_recorded: false;
      readonly browser_persistent_storage_used: false;
    };

export interface TavernCausalAuditManualAuthorization {
  readonly authorization_token: string;
  readonly task_seed_id: string;
}

export interface TavernCausalAuditDiagnosticRunResult {
  readonly diagnostic_version: typeof TAVERN_CAUSAL_AUDIT_DIAGNOSTIC_VERSION;
  readonly task_seed_id: string;
  readonly status: string;
  readonly worker_status: string;
  readonly worker_error_code: string | null;
  readonly decision: string | null;
  readonly decision_reason_code: string | null;
  readonly model_calls: number;
  readonly tool_calls: number;
  readonly input_tokens: number;
  readonly transport_operation_count: number;
  readonly candidate_authorized: boolean;
  readonly archive_committed: boolean;
  readonly task_finalized: boolean;
  readonly content_recorded: false;
  readonly browser_persistent_storage_used: false;
}

export interface TavernCausalAuditDiagnosticOptions {
  readonly port: TavernHostPort;
  readonly get_current_model_id: () => string;
  readonly count_tokens: (text: string) => number | Promise<number>;
  readonly now?: () => string;
}

export interface TavernCausalAuditDiagnosticPort {
  preflight(
    runtime: TavernCausalAuditDiagnosticRuntimeContext,
  ): Promise<TavernCausalAuditDiagnosticPreflight>;
  bindingSnapshot(
    runtime: TavernCausalAuditDiagnosticRuntimeContext,
  ): Promise<TavernCausalAuditDiagnosticBindingSnapshot>;
  recoverySnapshot(
    runtime: TavernCausalAuditDiagnosticRuntimeContext,
  ): Promise<TavernCausalAuditDiagnosticRecoverySnapshot>;
  authorizeManual(
    taskSeedId: string,
    runtime: TavernCausalAuditDiagnosticRuntimeContext,
  ): Promise<TavernCausalAuditManualAuthorization>;
  runAuthorized(
    authorization: TavernCausalAuditManualAuthorization,
  ): Promise<TavernCausalAuditDiagnosticRunResult>;
}
