import type { CausalCauseRef, CausalEffectRef } from "./causal.js";
import type { Confidence } from "./confidence.js";
import type { EpistemicPrincipalRef } from "./entity.js";
import type { EvidenceSpan } from "./evidence.js";
import type { HashDigest } from "./hash.js";
import type { NarraMemId } from "./ids.js";
import type { JsonValue } from "./json.js";
import type { StructuredClaim } from "./perspective.js";
import type { RecallQuery, RecallRejection } from "./recall.js";
import type { StateSubjectRef } from "./state.js";

export const INVESTIGATION_TOOL_NAMES = [
  "get_episode_context",
  "follow_causal_links",
  "get_state_as_of",
  "get_epistemic_state",
  "inspect_thread",
  "evaluate_trigger",
  "read_evidence_spans",
  "find_contradictions",
] as const;

export type InvestigationToolName = (typeof INVESTIGATION_TOOL_NAMES)[number];

export const AGENT_REQUESTED_INVESTIGATION_STOP_REASONS = [
  "sufficient_evidence",
  "no_progress",
] as const;

export type AgentRequestedInvestigationStopReason =
  (typeof AGENT_REQUESTED_INVESTIGATION_STOP_REASONS)[number];

export type InvestigationAction =
  | {
      readonly tool: "get_episode_context";
      readonly episode_id: NarraMemId<"episode">;
    }
  | {
      readonly tool: "follow_causal_links";
      readonly from: CausalCauseRef | CausalEffectRef;
      readonly direction: "predecessors" | "successors";
      readonly max_depth: number;
    }
  | {
      readonly tool: "get_state_as_of";
      readonly subject: StateSubjectRef;
      readonly state_keys: readonly string[];
    }
  | {
      readonly tool: "get_epistemic_state";
      readonly holder: EpistemicPrincipalRef;
      readonly proposition_ids?: readonly NarraMemId<"proposition">[];
    }
  | { readonly tool: "inspect_thread"; readonly thread_id: NarraMemId<"narrative_thread"> }
  | { readonly tool: "evaluate_trigger"; readonly impact_id: NarraMemId<"future_impact"> }
  | {
      readonly tool: "read_evidence_spans";
      readonly spans: readonly EvidenceSpan[];
    }
  | {
      readonly tool: "find_contradictions";
      readonly record_refs: readonly NarraMemId[];
    }
  | { readonly tool: "stop"; readonly reason: AgentRequestedInvestigationStopReason };

export interface SupportedInvestigationClaim {
  readonly claim: StructuredClaim;
  readonly support: readonly EvidenceSpan[];
  readonly source_record_refs: readonly NarraMemId[];
  readonly confidence: Confidence;
}

export interface InvestigationQuestion {
  readonly question_id: string;
  readonly question: string;
  readonly about_refs: readonly NarraMemId[];
  readonly status: "open" | "answered" | "unresolved";
}

export interface InvestigationVisit {
  readonly step: number;
  readonly tool: InvestigationToolName;
  readonly returned_record_refs: readonly NarraMemId[];
  readonly returned_evidence_refs: readonly NarraMemId<"evidence">[];
  readonly error_code?: string;
}

export const INVESTIGATION_STOP_REASONS = [
  "sufficient_evidence",
  "step_budget_exhausted",
  "tool_budget_exhausted",
  "token_budget_exhausted",
  "latency_budget_exhausted",
  "no_progress",
  "snapshot_stale",
  "cancelled",
  "tool_error",
] as const;

export type InvestigationStopReason = (typeof INVESTIGATION_STOP_REASONS)[number];

export interface InvestigationState {
  readonly investigation_id: NarraMemId<"investigation">;
  readonly query: RecallQuery;
  readonly snapshot_revision_id: NarraMemId<"source_revision">;
  readonly known_claims: readonly SupportedInvestigationClaim[];
  readonly open_questions: readonly InvestigationQuestion[];
  readonly visits: readonly InvestigationVisit[];
  readonly rejected_candidates: readonly RecallRejection[];
  readonly risk_codes: readonly string[];
  readonly remaining_tool_calls: number;
  readonly remaining_token_budget: number;
  readonly status: "investigating" | "stopped";
  readonly stop_reason?: InvestigationStopReason;
}

export interface AgentControlEnvelope {
  readonly trust_boundary: "trusted_control";
  readonly snapshot_revision_id: NarraMemId<"source_revision">;
  readonly allowed_tools: readonly InvestigationToolName[];
  readonly max_steps: number;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
}

export interface AgentEvidenceEnvelope {
  readonly trust_boundary: "untrusted_evidence";
  readonly evidence_refs: readonly NarraMemId<"evidence">[];
  readonly rendered_material: string;
}

export const INVESTIGATION_TRANSCRIPT_VERSION = "0.1.0" as const;

export interface InvestigationRuntimeLimits {
  readonly max_tool_calls: number;
  readonly max_causal_depth: number;
  readonly max_record_refs_per_result: number;
  readonly max_evidence_refs_per_result: number;
  readonly max_result_utf8_bytes: number;
}

export interface InvestigationToolSuccessObservation {
  readonly observation_version: typeof INVESTIGATION_TRANSCRIPT_VERSION;
  readonly trust_boundary: "untrusted_tool_result";
  readonly investigation_id: NarraMemId<"investigation">;
  readonly step: number;
  readonly snapshot_revision_id: NarraMemId<"source_revision">;
  readonly tool: InvestigationToolName;
  readonly status: "ok";
  readonly returned_record_refs: readonly NarraMemId[];
  readonly returned_evidence_refs: readonly NarraMemId<"evidence">[];
  readonly result: JsonValue;
  readonly result_sha256: HashDigest;
  readonly persistent_state_unchanged: true;
}

export interface InvestigationToolErrorObservation {
  readonly observation_version: typeof INVESTIGATION_TRANSCRIPT_VERSION;
  readonly trust_boundary: "untrusted_tool_result";
  readonly investigation_id: NarraMemId<"investigation">;
  readonly step: number;
  readonly snapshot_revision_id: NarraMemId<"source_revision">;
  readonly tool: InvestigationToolName;
  readonly status: "error";
  readonly error_code: string;
  readonly returned_record_refs: readonly [];
  readonly returned_evidence_refs: readonly [];
  readonly persistent_state_unchanged: true;
}

export type InvestigationToolObservation =
  | InvestigationToolSuccessObservation
  | InvestigationToolErrorObservation;

export type InvestigationTranscriptStep =
  | {
      readonly kind: "tool";
      readonly step: number;
      readonly action: Exclude<InvestigationAction, { readonly tool: "stop" }>;
      readonly observation: InvestigationToolObservation;
    }
  | {
      readonly kind: "stop";
      readonly step: number;
      readonly action: Extract<InvestigationAction, { readonly tool: "stop" }>;
    };

/** Executor-private replay log. Tool payloads remain untrusted and never become memory records. */
export interface InvestigationTranscript {
  readonly transcript_version: typeof INVESTIGATION_TRANSCRIPT_VERSION;
  readonly delivery: "executor_private_replay_log";
  readonly investigation_id: NarraMemId<"investigation">;
  readonly control: AgentControlEnvelope;
  readonly snapshot_fingerprint: HashDigest;
  readonly limits: InvestigationRuntimeLimits;
  readonly steps: readonly InvestigationTranscriptStep[];
  readonly status: "investigating" | "stopped";
  readonly stop_reason?: InvestigationStopReason;
}
