import type {
  CausalAuditFinalDecision,
  InvestigationStopReason,
  NarraMemId,
} from "@narramem/core-domain";

import type { CausalAuditCandidateValidationContext } from "./validate-causal-audit-candidate.js";
import { validateCausalAuditCandidateBatch } from "./validate-causal-audit-candidate.js";
import { validateWireValue } from "./wire-schema-registry.js";

export interface CausalAuditFinalDecisionValidationContext {
  readonly task_id: string;
  readonly active_revision_id: NarraMemId<"source_revision">;
  readonly finding_evidence_id: NarraMemId<"evidence">;
  readonly stop_reason: InvestigationStopReason;
  readonly allowed_reviewed_record_refs: readonly NarraMemId[];
  readonly allowed_reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
  readonly candidate_context: CausalAuditCandidateValidationContext;
}

export interface CausalAuditFinalDecisionValidationIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export type CausalAuditFinalDecisionValidationResult =
  | {
      readonly accepted: true;
      readonly decision: CausalAuditFinalDecision;
      readonly issues: readonly [];
    }
  | {
      readonly accepted: false;
      readonly issues: readonly CausalAuditFinalDecisionValidationIssue[];
    };

function issue(
  code: string,
  path: string,
  message: string,
): CausalAuditFinalDecisionValidationIssue {
  return { code, path, message };
}

function decisionTaskId(decision: CausalAuditFinalDecision): string {
  return decision.decision === "candidate" ? decision.candidate.task_id : decision.task_id;
}

function decisionRevisionId(decision: CausalAuditFinalDecision): NarraMemId<"source_revision"> {
  return decision.decision === "candidate"
    ? decision.candidate.source_revision_id
    : decision.source_revision_id;
}

function outsideAllowlist<T extends string>(
  values: readonly T[],
  allowedValues: readonly T[],
): readonly T[] {
  const allowed = new Set(allowedValues);
  return values.filter((value) => !allowed.has(value));
}

export function validateCausalAuditFinalDecision(
  value: unknown,
  context: CausalAuditFinalDecisionValidationContext,
): CausalAuditFinalDecisionValidationResult {
  const wire = validateWireValue("causal_audit_final_decision", value);
  if (!wire.valid) {
    return {
      accepted: false,
      issues: wire.errors.map((error) =>
        issue(
          "CAUSAL_AUDIT_FINAL_DECISION_SCHEMA_INVALID",
          error.instancePath || "/",
          error.message ?? "invalid",
        ),
      ),
    };
  }

  const decision = value as CausalAuditFinalDecision;
  const issues: CausalAuditFinalDecisionValidationIssue[] = [];
  if (decisionTaskId(decision) !== context.task_id) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_FINAL_DECISION_TASK_MISMATCH",
        decision.decision === "candidate" ? "/candidate/task_id" : "/task_id",
        "Final decision belongs to another Causal Audit task",
      ),
    );
  }
  if (decisionRevisionId(decision) !== context.active_revision_id) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_FINAL_DECISION_REVISION_MISMATCH",
        decision.decision === "candidate" ? "/candidate/source_revision_id" : "/source_revision_id",
        "Final decision does not target the frozen source revision",
      ),
    );
  }
  if (context.stop_reason === "snapshot_stale" || context.stop_reason === "cancelled") {
    issues.push(
      issue(
        "CAUSAL_AUDIT_FINAL_DECISION_RUNTIME_STOPPED",
        "/decision",
        "A stale or cancelled investigation cannot produce a model final decision",
      ),
    );
  }

  if (decision.decision === "candidate") {
    if (context.stop_reason !== "sufficient_evidence") {
      issues.push(
        issue(
          "CAUSAL_AUDIT_CANDIDATE_STOP_REASON_INVALID",
          "/decision",
          "A causal candidate requires an Agent sufficient_evidence stop",
        ),
      );
    }
    const candidateValidation = validateCausalAuditCandidateBatch(
      decision.candidate,
      context.candidate_context,
    );
    if (!candidateValidation.accepted) {
      issues.push(
        ...candidateValidation.issues.map((candidateIssue) => ({
          ...candidateIssue,
          code: `FINAL_${candidateIssue.code}`,
          path: `/candidate${candidateIssue.path === "/" ? "" : candidateIssue.path}`,
        })),
      );
    }
  } else {
    const recordRefs =
      decision.decision === "no_supported_causal"
        ? decision.reviewed_record_refs
        : decision.about_refs;
    for (const foreign of outsideAllowlist(recordRefs, context.allowed_reviewed_record_refs)) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_FINAL_DECISION_RECORD_NOT_REVIEWED",
          decision.decision === "no_supported_causal" ? "/reviewed_record_refs" : "/about_refs",
          `Final decision references a record outside the verified investigation: ${foreign}`,
        ),
      );
    }
    for (const foreign of outsideAllowlist(
      decision.reviewed_evidence_refs,
      context.allowed_reviewed_evidence_refs,
    )) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_FINAL_DECISION_EVIDENCE_NOT_REVIEWED",
          "/reviewed_evidence_refs",
          `Final decision references Evidence outside the verified investigation: ${foreign}`,
        ),
      );
    }
    if (!decision.reviewed_evidence_refs.includes(context.finding_evidence_id)) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_FINAL_DECISION_FINDING_NOT_REVIEWED",
          "/reviewed_evidence_refs",
          "A negative or unresolved decision must review the Evidence containing the audited cue",
        ),
      );
    }
  }

  if (
    decision.decision === "no_supported_causal" &&
    context.stop_reason !== "sufficient_evidence"
  ) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_NO_SUPPORTED_STOP_REASON_INVALID",
        "/decision",
        "Closing a finding as unsupported requires an Agent sufficient_evidence stop",
      ),
    );
  }
  if (decision.decision === "unresolved") {
    const budgetStop = [
      "step_budget_exhausted",
      "tool_budget_exhausted",
      "token_budget_exhausted",
      "latency_budget_exhausted",
    ].includes(context.stop_reason);
    if (budgetStop && decision.reason_code !== "investigation_budget_exhausted") {
      issues.push(
        issue(
          "CAUSAL_AUDIT_UNRESOLVED_BUDGET_REASON_MISMATCH",
          "/reason_code",
          "A budget-stopped investigation must report investigation_budget_exhausted",
        ),
      );
    }
    if (context.stop_reason === "tool_error" && decision.reason_code !== "tool_result_incomplete") {
      issues.push(
        issue(
          "CAUSAL_AUDIT_UNRESOLVED_TOOL_REASON_MISMATCH",
          "/reason_code",
          "A tool-error investigation must report tool_result_incomplete",
        ),
      );
    }
  }

  return issues.length === 0
    ? { accepted: true, decision, issues: [] }
    : { accepted: false, issues };
}
