import type {
  CausalAuditAgentFinalChoiceInputV030,
  CausalAuditFinalDecisionV030,
  InvestigationAction,
  InvestigationTranscript,
} from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

import {
  type CausalAuditAgentFinalAllowlists,
  type CausalAuditAgentTaskSeed,
  type CausalAuditFinalOptionSource,
  createCausalAuditAgentActionChoiceInputV020,
  createCausalAuditAgentActionInputV020,
  createCausalAuditAgentFinalChoiceInputV030,
  renderCausalAuditAgentActionChoiceInputV020,
  renderCausalAuditAgentFinalChoiceInputV030,
  renderCausalAuditAgentTurnInputV020,
  translateFlatCausalAuditFinalDraft,
  translateFlatInvestigationActionDraft,
} from "./model-turn.js";
import type { InvestigationRuntimePorts, InvestigationStepResult } from "./transcript.js";

const CODE_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/u;

export type CausalAuditWorkerActionStrategy = "canonical_action" | "flat_action_option";

export interface CausalAuditWorkerAdapter {
  readonly adapter_id: string;
  readonly exact_model_id: string;
  readonly action_prompt_asset_ref: string;
  readonly final_prompt_asset_ref: string;
  readonly action_parameters: Readonly<Record<string, unknown>>;
  readonly final_parameters: Readonly<Record<string, unknown>>;
  readonly action_input_schema:
    | "causal_audit_agent_turn_input_v020"
    | "causal_audit_agent_action_choice_input_v020";
  readonly action_output_strategy: CausalAuditWorkerActionStrategy;
  readonly action_output_schema: "investigation_action" | "flat_investigation_action_draft";
  readonly final_input_schema: "causal_audit_agent_final_choice_input_v030";
  readonly final_output_schema: "flat_causal_audit_final_draft";
}

export interface CausalAuditWorkerCompletionRequest {
  readonly operation_kind: "causal_audit_action" | "causal_audit_final";
  readonly call_index: number;
  readonly exact_model_id: string;
  readonly prompt_asset_ref: string;
  readonly input_schema: string;
  readonly output_schema: string;
  readonly parameters: Readonly<Record<string, unknown>>;
  readonly input_json: string;
}

export type CausalAuditWorkerValidation<Value> =
  | { readonly accepted: true; readonly value: Value }
  | { readonly accepted: false; readonly error_code: string };

export type CausalAuditWorkerCompletionResult<Value> =
  | {
      readonly status: "committed";
      readonly value: Value;
      readonly transport_operation_id: string;
      readonly input_tokens_accounted: number;
      readonly output_tokens_observed: number;
    }
  | {
      readonly status: "blocked";
      readonly error_code: string;
      readonly transport_operation_id?: string;
      /** True only after a provider call was actually dispatched and must consume task budget. */
      readonly model_call_accounted?: boolean;
      readonly input_tokens_accounted?: number;
      readonly output_tokens_observed?: number;
    };

export interface CausalAuditWorkerCompletionPort {
  complete<Value>(
    request: CausalAuditWorkerCompletionRequest,
    validate: (
      content: string,
    ) => CausalAuditWorkerValidation<Value> | Promise<CausalAuditWorkerValidation<Value>>,
  ): Promise<CausalAuditWorkerCompletionResult<Value>>;
}

export interface CausalAuditWorkerInvestigationPort {
  readonly transcript: InvestigationTranscript;
  execute(action: InvestigationAction): Promise<InvestigationStepResult>;
}

export interface CausalAuditWorkerFinalContext {
  readonly allowlists: CausalAuditAgentFinalAllowlists;
  readonly option_source: CausalAuditFinalOptionSource;
}

export interface RunCausalAuditWorkerRequest {
  readonly task: CausalAuditAgentTaskSeed;
  readonly adapter: CausalAuditWorkerAdapter;
  readonly investigation: CausalAuditWorkerInvestigationPort;
  readonly completion: CausalAuditWorkerCompletionPort;
  readonly hash_text: InvestigationRuntimePorts["hash_text"];
  readonly max_model_calls: number;
  readonly enumerate_actions: (
    task: CausalAuditAgentTaskSeed,
    transcript: InvestigationTranscript,
  ) => readonly InvestigationAction[];
  readonly build_final_context: (
    transcript: InvestigationTranscript,
  ) => CausalAuditWorkerFinalContext | Promise<CausalAuditWorkerFinalContext>;
}

export interface CausalAuditWorkerUsage {
  readonly model_calls: number;
  readonly tool_calls: number;
  readonly input_tokens: number;
  readonly output_tokens: number;
}

export type CausalAuditWorkerResult =
  | {
      readonly status: "completed";
      readonly decision: CausalAuditFinalDecisionV030;
      readonly final_input: CausalAuditAgentFinalChoiceInputV030;
      readonly transcript: InvestigationTranscript;
      readonly usage: CausalAuditWorkerUsage;
      readonly transport_operation_ids: readonly string[];
    }
  | {
      readonly status: "blocked";
      readonly error_code: string;
      readonly transcript: InvestigationTranscript;
      readonly usage: CausalAuditWorkerUsage;
      readonly transport_operation_ids: readonly string[];
    };

function parseOneJson(content: string): unknown {
  try {
    return JSON.parse(content) as unknown;
  } catch {
    return undefined;
  }
}

function assertAdapter(adapter: CausalAuditWorkerAdapter): void {
  if (
    adapter.adapter_id.trim().length === 0 ||
    adapter.exact_model_id.trim().length === 0 ||
    adapter.action_prompt_asset_ref.trim().length === 0 ||
    adapter.final_prompt_asset_ref.trim().length === 0
  ) {
    throw new TypeError("Causal Audit Worker adapter identifiers cannot be empty");
  }
  const flat = adapter.action_output_strategy === "flat_action_option";
  if (
    flat !== (adapter.action_input_schema === "causal_audit_agent_action_choice_input_v020") ||
    flat !== (adapter.action_output_schema === "flat_investigation_action_draft")
  ) {
    throw new TypeError("Causal Audit Worker action adapter schemas do not match its strategy");
  }
}

function assertBudget(value: number): void {
  if (!Number.isSafeInteger(value) || value < 1 || value > 1_000) {
    throw new TypeError("Causal Audit Worker model-call budget must be between 1 and 1000");
  }
}

function blocked(
  errorCode: string,
  transcript: InvestigationTranscript,
  usage: CausalAuditWorkerUsage,
  transportOperationIds: readonly string[],
): CausalAuditWorkerResult {
  if (!CODE_PATTERN.test(errorCode)) throw new TypeError("Worker error code is invalid");
  return {
    status: "blocked",
    error_code: errorCode,
    transcript,
    usage,
    transport_operation_ids: [...transportOperationIds],
  };
}

function nextUsage(
  usage: CausalAuditWorkerUsage,
  result: Extract<CausalAuditWorkerCompletionResult<unknown>, { readonly status: "committed" }>,
): CausalAuditWorkerUsage {
  return {
    ...usage,
    model_calls: usage.model_calls + 1,
    input_tokens: usage.input_tokens + result.input_tokens_accounted,
    output_tokens: usage.output_tokens + result.output_tokens_observed,
  };
}

function accountBlockedCompletion(
  usage: CausalAuditWorkerUsage,
  result: Extract<CausalAuditWorkerCompletionResult<unknown>, { readonly status: "blocked" }>,
): CausalAuditWorkerUsage {
  if (result.model_call_accounted !== true) return usage;
  const inputTokens = result.input_tokens_accounted ?? 0;
  const outputTokens = result.output_tokens_observed ?? 0;
  if (
    !Number.isSafeInteger(inputTokens) ||
    inputTokens < 0 ||
    !Number.isSafeInteger(outputTokens) ||
    outputTokens < 0
  ) {
    throw new TypeError("Blocked Causal Audit completion reported invalid token usage");
  }
  return {
    ...usage,
    model_calls: usage.model_calls + 1,
    input_tokens: usage.input_tokens + inputTokens,
    output_tokens: usage.output_tokens + outputTokens,
  };
}

export async function runCausalAuditWorker(
  request: RunCausalAuditWorkerRequest,
): Promise<CausalAuditWorkerResult> {
  assertAdapter(request.adapter);
  assertBudget(request.max_model_calls);
  let usage: CausalAuditWorkerUsage = {
    model_calls: 0,
    tool_calls: request.investigation.transcript.steps.filter((step) => step.kind === "tool")
      .length,
    input_tokens: 0,
    output_tokens: 0,
  };
  const operationIds: string[] = [];
  let callIndex = 0;

  while (request.investigation.transcript.status === "investigating") {
    if (usage.model_calls + 1 >= request.max_model_calls) {
      return blocked(
        "MODEL_CALL_BUDGET_REQUIRES_FINAL_RESERVE",
        request.investigation.transcript,
        usage,
        operationIds,
      );
    }
    const actions = request.enumerate_actions(request.task, request.investigation.transcript);
    if (actions.length === 0) {
      return blocked(
        "ACTION_FRONTIER_EMPTY",
        request.investigation.transcript,
        usage,
        operationIds,
      );
    }
    const actionInput =
      request.adapter.action_output_strategy === "flat_action_option"
        ? await createCausalAuditAgentActionChoiceInputV020(
            request.task,
            request.investigation.transcript,
            actions,
            { hash_text: request.hash_text },
          )
        : await createCausalAuditAgentActionInputV020(
            request.task,
            request.investigation.transcript,
            { hash_text: request.hash_text },
          );
    const inputJson =
      actionInput.phase === "investigation_action_choice"
        ? renderCausalAuditAgentActionChoiceInputV020(actionInput)
        : renderCausalAuditAgentTurnInputV020(actionInput);
    const completion = await request.completion.complete<InvestigationAction>(
      {
        operation_kind: "causal_audit_action",
        call_index: callIndex,
        exact_model_id: request.adapter.exact_model_id,
        prompt_asset_ref: request.adapter.action_prompt_asset_ref,
        input_schema: request.adapter.action_input_schema,
        output_schema: request.adapter.action_output_schema,
        parameters: request.adapter.action_parameters,
        input_json: inputJson,
      },
      (content) => {
        const value = parseOneJson(content);
        if (value === undefined) return { accepted: false, error_code: "ACTION_JSON_INVALID" };
        if (actionInput.phase === "investigation_action_choice") {
          const translation = translateFlatInvestigationActionDraft(
            value,
            actionInput.control.action_options,
          );
          return translation.accepted
            ? { accepted: true, value: translation.action }
            : { accepted: false, error_code: "ACTION_TRANSLATION_REJECTED" };
        }
        const wire = validateWireValue("investigation_action", value);
        return wire.valid
          ? { accepted: true, value: value as InvestigationAction }
          : { accepted: false, error_code: "ACTION_SCHEMA_REJECTED" };
      },
    );
    callIndex += 1;
    if (completion.status === "blocked") {
      usage = accountBlockedCompletion(usage, completion);
      if (completion.transport_operation_id !== undefined)
        operationIds.push(completion.transport_operation_id);
      return blocked(completion.error_code, request.investigation.transcript, usage, operationIds);
    }
    operationIds.push(completion.transport_operation_id);
    usage = nextUsage(usage, completion);
    const step = await request.investigation.execute(completion.value);
    usage = {
      ...usage,
      tool_calls: step.transcript.steps.filter((item) => item.kind === "tool").length,
    };
    if (step.status === "rejected") {
      return blocked("INVESTIGATION_ACTION_REJECTED", step.transcript, usage, operationIds);
    }
  }

  if (usage.model_calls >= request.max_model_calls) {
    return blocked(
      "MODEL_CALL_BUDGET_EXHAUSTED",
      request.investigation.transcript,
      usage,
      operationIds,
    );
  }
  const finalContext = await request.build_final_context(request.investigation.transcript);
  const finalInput = await createCausalAuditAgentFinalChoiceInputV030(
    request.task,
    request.investigation.transcript,
    finalContext.allowlists,
    finalContext.option_source,
    { hash_text: request.hash_text },
  );
  const finalCompletion = await request.completion.complete<CausalAuditFinalDecisionV030>(
    {
      operation_kind: "causal_audit_final",
      call_index: callIndex,
      exact_model_id: request.adapter.exact_model_id,
      prompt_asset_ref: request.adapter.final_prompt_asset_ref,
      input_schema: request.adapter.final_input_schema,
      output_schema: request.adapter.final_output_schema,
      parameters: request.adapter.final_parameters,
      input_json: renderCausalAuditAgentFinalChoiceInputV030(finalInput),
    },
    async (content) => {
      const value = parseOneJson(content);
      if (value === undefined) return { accepted: false, error_code: "FINAL_JSON_INVALID" };
      const translation = await translateFlatCausalAuditFinalDraft(
        value,
        finalInput,
        finalContext.option_source.candidate_context,
        { hash_text: request.hash_text },
      );
      return translation.accepted
        ? { accepted: true, value: translation.decision }
        : { accepted: false, error_code: "FINAL_TRANSLATION_REJECTED" };
    },
  );
  if (finalCompletion.status === "blocked") {
    usage = accountBlockedCompletion(usage, finalCompletion);
    if (finalCompletion.transport_operation_id !== undefined)
      operationIds.push(finalCompletion.transport_operation_id);
    return blocked(
      finalCompletion.error_code,
      request.investigation.transcript,
      usage,
      operationIds,
    );
  }
  operationIds.push(finalCompletion.transport_operation_id);
  usage = nextUsage(usage, finalCompletion);
  return {
    status: "completed",
    decision: finalCompletion.value,
    final_input: finalInput,
    transcript: request.investigation.transcript,
    usage,
    transport_operation_ids: operationIds,
  };
}
