import type { SillyTavernExtensionBindings } from "@narramem/tavern-adapter";
import connectionTestPrompt from "../../../prompts/runtime/NM-P0031_v0.1.0.md";

import {
  activeMemoryApiProfile,
  type MemoryApiSource,
  memoryProxyRequest,
  type NarraMemBetaSettings,
  type NarraMemMemoryApiProfile,
} from "./memory-api-settings.js";

export const NARRAMEM_MEMORY_API_CLIENT_VERSION = "0.3.1" as const;
const SECRETS_READ_PATH = "/api/secrets/read";
const SECRETS_WRITE_PATH = "/api/secrets/write";
const SECRETS_DELETE_PATH = "/api/secrets/delete";
const SECRETS_ROTATE_PATH = "/api/secrets/rotate";
const CHAT_STATUS_PATH = "/api/backends/chat-completions/status";
const CHAT_GENERATE_PATH = "/api/backends/chat-completions/generate";
const CUSTOM_JSON_OBJECT_BODY = "response_format:\n  type: json_object";

const PROVIDER = Object.freeze({
  custom: Object.freeze({ source: "custom", secret_key: "api_key_custom" }),
  deepseek: Object.freeze({ source: "deepseek", secret_key: "api_key_deepseek" }),
} satisfies Record<MemoryApiSource, { readonly source: string; readonly secret_key: string }>);

export interface NarraMemMemoryApiStatus {
  readonly plugin_version: "sillytavern-1.18+";
  readonly source: MemoryApiSource;
  readonly credential_configured: boolean;
  readonly session_dispatches: number;
  readonly concurrency_limit: number;
  readonly automatic_retries: number;
}

export interface NarraMemConnectionTestResult {
  readonly status: "ok";
  readonly source: MemoryApiSource;
  readonly model: string;
  readonly dispatches_used: 1;
}

export class NarraMemMemoryApiError extends Error {
  constructor(
    readonly code:
      | "HOST_TRANSPORT_UNAVAILABLE"
      | "CREDENTIAL_MISSING"
      | "CONFIGURATION_MISSING"
      | "REQUEST_REJECTED"
      | "REQUEST_TIMEOUT"
      | "INVALID_RESPONSE",
    message: string,
    readonly http_status: number | null = null,
  ) {
    super(message);
    this.name = "NarraMemMemoryApiError";
  }
}

export interface NarraMemMemoryApiClientOptions {
  readonly fetch: typeof fetch;
  getRequestHeaders(): Record<string, string>;
  getSettings(): NarraMemBetaSettings;
  setProfileCredentialSecretId(profileId: string, secretId: string): void;
  now?(): number;
  sleep?(milliseconds: number): Promise<void>;
  runWithOriginSlot?<T>(concurrency: number, operation: () => Promise<T>): Promise<T>;
}

interface SecretState {
  readonly id: string;
  readonly value: string;
  readonly label: string;
  readonly active: boolean;
}

interface DispatchLimits {
  readonly min_interval_ms: number;
  readonly max_requests_per_minute: number;
  readonly concurrency: number;
}

interface DispatchJob<T> {
  readonly limits: DispatchLimits;
  readonly operation: () => Promise<T>;
  readonly resolve: (value: T | PromiseLike<T>) => void;
  readonly reject: (reason?: unknown) => void;
}

function plainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function safeProviderToken(value: unknown): string | null {
  return typeof value === "string" && /^[A-Za-z0-9_.-]{1,80}$/u.test(value) ? value : null;
}

function responseErrorMessage(status: number): string {
  return `SillyTavern Memory transport rejected the request with HTTP ${status}`;
}

function secretStates(value: unknown, secretKey: string): readonly SecretState[] {
  if (!plainObject(value)) {
    throw new NarraMemMemoryApiError("INVALID_RESPONSE", "SillyTavern secret state is invalid");
  }
  const states = value[secretKey];
  if (states === null || states === undefined) return [];
  if (
    !Array.isArray(states) ||
    states.some(
      (state) =>
        !plainObject(state) ||
        typeof state.id !== "string" ||
        typeof state.value !== "string" ||
        typeof state.label !== "string" ||
        typeof state.active !== "boolean",
    )
  ) {
    throw new NarraMemMemoryApiError("INVALID_RESPONSE", "SillyTavern secret list is invalid");
  }
  return states as unknown as readonly SecretState[];
}

function extractOpenAiText(value: unknown): string {
  if (plainObject(value) && value.error !== undefined) {
    const errorValue = value.error;
    const errorCode = plainObject(errorValue) ? safeProviderToken(errorValue.code) : null;
    const errorType = plainObject(errorValue) ? safeProviderToken(errorValue.type) : null;
    const classification = [errorCode, errorType].filter((item) => item !== null).join(" / ");
    throw new NarraMemMemoryApiError(
      "REQUEST_REJECTED",
      `Memory API provider returned an error${classification.length > 0 ? ` (${classification})` : ""}`,
    );
  }
  if (!plainObject(value) || !Array.isArray(value.choices) || value.choices.length === 0) {
    throw new NarraMemMemoryApiError("INVALID_RESPONSE", "Memory API response has no choices");
  }
  const choice = value.choices[0];
  if (!plainObject(choice) || !plainObject(choice.message)) {
    throw new NarraMemMemoryApiError("INVALID_RESPONSE", "Memory API response message is invalid");
  }
  const content = choice.message.content;
  if (typeof content === "string" && content.length > 0) return content;
  if (Array.isArray(content)) {
    const text = content
      .filter((part) => plainObject(part) && part.type === "text" && typeof part.text === "string")
      .map((part) => String((part as Record<string, unknown>).text))
      .join("");
    if (text.length > 0) return text;
  }
  throw new NarraMemMemoryApiError("INVALID_RESPONSE", "Memory API response has no text");
}

export function normalizeMemoryApiBase(value: string): string {
  if (value.trim() !== value || value.length === 0) {
    throw new TypeError("Memory API URL must be a non-empty trimmed value");
  }
  const url = new URL(value);
  if (!["http:", "https:"].includes(url.protocol) || url.username || url.password) {
    throw new TypeError("Memory API URL must be an http(s) URL without embedded credentials");
  }
  url.hash = "";
  url.search = "";
  url.pathname = url.pathname.replace(/\/+$/u, "");
  if (url.pathname.endsWith("/chat/completions")) {
    url.pathname = url.pathname.slice(0, -"/chat/completions".length);
  } else if (!url.pathname.endsWith("/v1")) {
    url.pathname = `${url.pathname}/v1`.replace(/^\/+/u, "/");
  }
  return url.toString().replace(/\/$/u, "");
}

export function memoryStatusBody(
  profile: NarraMemMemoryApiProfile,
): Readonly<Record<string, unknown>> {
  const common = {
    chat_completion_source: PROVIDER[profile.source].source,
    secret_id: profile.credential_secret_id,
  };
  return profile.source === "custom"
    ? { ...common, custom_url: normalizeMemoryApiBase(profile.api_url) }
    : common;
}

export function memoryGenerateBody(
  profile: NarraMemMemoryApiProfile,
  input: Readonly<Record<string, unknown>>,
): Readonly<Record<string, unknown>> {
  const common = {
    chat_completion_source: PROVIDER[profile.source].source,
    secret_id: profile.credential_secret_id,
    model: profile.model,
    messages: input.messages,
    stream: false,
  };
  return profile.source === "custom"
    ? {
        ...common,
        custom_url: normalizeMemoryApiBase(profile.api_url),
        custom_include_body: CUSTOM_JSON_OBJECT_BODY,
      }
    : {
        ...common,
        json_schema: {
          name: input.schema_name,
          value: input.json_schema,
          strict: true,
        },
      };
}

function defaultSleep(milliseconds: number): Promise<void> {
  return new Promise((resolve) => globalThis.setTimeout(resolve, milliseconds));
}

async function defaultOriginSlot<T>(concurrency: number, operation: () => Promise<T>): Promise<T> {
  const lockManager = globalThis.navigator?.locks;
  if (lockManager === undefined) return operation();
  for (;;) {
    for (let index = 0; index < concurrency; index += 1) {
      let acquired = false;
      let result: T | undefined;
      let failure: unknown;
      await lockManager.request(
        `narramem-memory-api-slot-${index}`,
        { ifAvailable: true },
        async (lock) => {
          if (lock === null) return;
          acquired = true;
          try {
            result = await operation();
          } catch (error) {
            failure = error;
          }
        },
      );
      if (acquired) {
        if (failure !== undefined) throw failure;
        return result as T;
      }
    }
    await defaultSleep(50);
  }
}

class MemoryDispatchLane {
  private active = 0;
  private readonly queued: DispatchJob<unknown>[] = [];
  private lastDispatchAt = Number.NEGATIVE_INFINITY;
  private recentDispatches: number[] = [];
  dispatches = 0;

  constructor(
    private readonly now: () => number,
    private readonly sleep: (milliseconds: number) => Promise<void>,
    private readonly runWithOriginSlot: <T>(
      concurrency: number,
      operation: () => Promise<T>,
    ) => Promise<T>,
  ) {}

  run<T>(limits: DispatchLimits, operation: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.queued.push({ limits, operation, resolve, reject } as DispatchJob<unknown>);
      this.pump();
    });
  }

  private pump(): void {
    const next = this.queued[0];
    if (next === undefined || this.active >= next.limits.concurrency) return;
    this.queued.shift();
    this.active += 1;
    void this.execute(next).finally(() => {
      this.active -= 1;
      this.pump();
    });
    this.pump();
  }

  private async execute(job: DispatchJob<unknown>): Promise<void> {
    try {
      await this.reserveRate(job.limits);
      job.resolve(await this.runWithOriginSlot(job.limits.concurrency, job.operation));
    } catch (error) {
      job.reject(error);
    }
  }

  private async reserveRate(limits: DispatchLimits): Promise<void> {
    for (;;) {
      const now = this.now();
      this.recentDispatches = this.recentDispatches.filter((timestamp) => now - timestamp < 60_000);
      const intervalWait = Math.max(0, this.lastDispatchAt + limits.min_interval_ms - now);
      const minuteWait =
        limits.max_requests_per_minute > 0 &&
        this.recentDispatches.length >= limits.max_requests_per_minute
          ? Math.max(0, (this.recentDispatches[0] ?? now) + 60_000 - now)
          : 0;
      const wait = Math.max(intervalWait, minuteWait);
      if (wait > 0) {
        await this.sleep(wait);
        continue;
      }
      this.lastDispatchAt = now;
      this.recentDispatches.push(now);
      this.dispatches += 1;
      return;
    }
  }
}

export class NarraMemMemoryApiClient {
  readonly client_version = NARRAMEM_MEMORY_API_CLIENT_VERSION;
  private readonly lane: MemoryDispatchLane;

  constructor(private readonly options: NarraMemMemoryApiClientOptions) {
    this.lane = new MemoryDispatchLane(
      options.now ?? (() => Date.now()),
      options.sleep ?? defaultSleep,
      options.runWithOriginSlot ?? defaultOriginSlot,
    );
  }

  getSessionDispatches(): number {
    return this.lane.dispatches;
  }

  private async post(path: string, body: Readonly<Record<string, unknown>>): Promise<unknown> {
    const timeout = this.options.getSettings().timeout_ms;
    const controller = new AbortController();
    const timer = globalThis.setTimeout(() => controller.abort(), timeout);
    let response: Response;
    try {
      response = await this.options.fetch(path, {
        method: "POST",
        headers: { ...this.options.getRequestHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify(body),
        signal: controller.signal,
      });
    } catch (error) {
      if (controller.signal.aborted) {
        throw new NarraMemMemoryApiError(
          "REQUEST_TIMEOUT",
          "NarraMem Memory API request timed out",
        );
      }
      throw new NarraMemMemoryApiError(
        "HOST_TRANSPORT_UNAVAILABLE",
        `SillyTavern Memory transport is unavailable (${error instanceof Error ? error.name : "network"})`,
      );
    } finally {
      globalThis.clearTimeout(timer);
    }
    let value: unknown;
    if (response.status !== 204) {
      try {
        value = await response.json();
      } catch {
        if (response.ok) {
          throw new NarraMemMemoryApiError(
            "INVALID_RESPONSE",
            "SillyTavern Memory transport returned invalid JSON",
          );
        }
      }
    }
    if (!response.ok) {
      throw new NarraMemMemoryApiError(
        response.status === 401 || response.status === 403
          ? "CREDENTIAL_MISSING"
          : "REQUEST_REJECTED",
        responseErrorMessage(response.status),
        response.status,
      );
    }
    return value;
  }

  private async readSecretStates(
    profile: NarraMemMemoryApiProfile,
  ): Promise<readonly SecretState[]> {
    return secretStates(
      await this.post(SECRETS_READ_PATH, {}),
      PROVIDER[profile.source].secret_key,
    );
  }

  async status(
    profile = activeMemoryApiProfile(this.options.getSettings()),
  ): Promise<NarraMemMemoryApiStatus> {
    const states = await this.readSecretStates(profile);
    const settings = this.options.getSettings();
    return {
      plugin_version: "sillytavern-1.18+",
      source: profile.source,
      credential_configured:
        profile.credential_secret_id.length > 0 &&
        states.some((state) => state.id === profile.credential_secret_id),
      session_dispatches: this.lane.dispatches,
      concurrency_limit: settings.concurrency,
      automatic_retries: settings.retry_count,
    };
  }

  async saveCredential(
    apiKey: string,
    profile = activeMemoryApiProfile(this.options.getSettings()),
  ): Promise<void> {
    if (apiKey.trim() !== apiKey || apiKey.length === 0) {
      throw new TypeError("Memory API key must be a non-empty trimmed value");
    }
    const oldNarraMemId = profile.credential_secret_id;
    const secretKey = PROVIDER[profile.source].secret_key;
    const previousActive = (await this.readSecretStates(profile)).find((state) => state.active);
    const written = await this.post(SECRETS_WRITE_PATH, {
      key: secretKey,
      value: apiKey,
      label: `NarraMem 叙忆 - ${profile.name}`,
    });
    if (!plainObject(written) || typeof written.id !== "string" || written.id.length === 0) {
      throw new NarraMemMemoryApiError(
        "INVALID_RESPONSE",
        "SillyTavern did not return a secret ID",
      );
    }
    const newNarraMemId = written.id;
    this.options.setProfileCredentialSecretId(profile.id, newNarraMemId);
    if (previousActive !== undefined && previousActive.id !== oldNarraMemId) {
      await this.post(SECRETS_ROTATE_PATH, { key: secretKey, id: previousActive.id });
    }
    if (oldNarraMemId.length > 0 && oldNarraMemId !== newNarraMemId) {
      await this.post(SECRETS_DELETE_PATH, { key: secretKey, id: oldNarraMemId });
    }
  }

  async deleteCredential(
    profile = activeMemoryApiProfile(this.options.getSettings()),
  ): Promise<void> {
    if (profile.credential_secret_id.length === 0) return;
    await this.post(SECRETS_DELETE_PATH, {
      key: PROVIDER[profile.source].secret_key,
      id: profile.credential_secret_id,
    });
    this.options.setProfileCredentialSecretId(profile.id, "");
  }

  async listModels(
    profile = activeMemoryApiProfile(this.options.getSettings()),
  ): Promise<readonly string[]> {
    if (profile.credential_secret_id.length === 0) {
      throw new NarraMemMemoryApiError("CREDENTIAL_MISSING", "请先保存 NarraMem Memory API Key");
    }
    const value = await this.post(CHAT_STATUS_PATH, memoryStatusBody(profile));
    const nestedData = plainObject(value) && plainObject(value.data) ? value.data.data : undefined;
    const candidates = Array.isArray(value)
      ? value
      : plainObject(value) && Array.isArray(value.data)
        ? value.data
        : plainObject(value) && Array.isArray(value.models)
          ? value.models
          : Array.isArray(nestedData)
            ? nestedData
            : [];
    return [
      ...new Set(
        candidates
          .filter(
            (item) =>
              plainObject(item) && (typeof item.id === "string" || typeof item.name === "string"),
          )
          .map((item) =>
            String(
              typeof (item as Record<string, unknown>).id === "string"
                ? (item as Record<string, unknown>).id
                : (item as Record<string, unknown>).name,
            ),
          ),
      ),
    ].sort();
  }

  private async generateWithSettings(
    settings: NarraMemBetaSettings,
    request: Parameters<SillyTavernExtensionBindings["generate_raw"]>[0],
    requireEnabled: boolean,
  ): Promise<string> {
    const profile = activeMemoryApiProfile(settings);
    if (
      (requireEnabled && !settings.enabled) ||
      profile.model.length === 0 ||
      (profile.source === "custom" && profile.api_url.length === 0)
    ) {
      throw new NarraMemMemoryApiError(
        "CONFIGURATION_MISSING",
        "NarraMem independent Memory API is not configured",
      );
    }
    if (profile.credential_secret_id.length === 0) {
      throw new NarraMemMemoryApiError("CREDENTIAL_MISSING", "NarraMem Memory API Key is missing");
    }
    const input = memoryProxyRequest(settings, request);
    const limits = input.limits as DispatchLimits;
    return this.lane.run(limits, async () => {
      const value = await this.post(CHAT_GENERATE_PATH, memoryGenerateBody(profile, input));
      return extractOpenAiText(value);
    });
  }

  async generate(
    request: Parameters<SillyTavernExtensionBindings["generate_raw"]>[0],
  ): Promise<string> {
    return this.generateWithSettings(this.options.getSettings(), request, true);
  }

  async sendConnectionTest(): Promise<NarraMemConnectionTestResult> {
    const settings = this.options.getSettings();
    const profile = activeMemoryApiProfile(settings);
    const content = await this.generateWithSettings(
      settings,
      {
        prompt: [
          { role: "system", content: connectionTestPrompt },
          { role: "user", content: JSON.stringify({ expected_status: "ok" }) },
        ],
        responseLength: 0,
        trimNames: false,
        schemaName: "narramem_connection_test_0_1_0",
        jsonSchema: {
          type: "object",
          required: ["status"],
          properties: { status: { const: "ok" } },
          additionalProperties: false,
        },
      },
      false,
    );
    let parsed: unknown;
    try {
      parsed = JSON.parse(content) as unknown;
    } catch {
      throw new NarraMemMemoryApiError(
        "INVALID_RESPONSE",
        "Memory API test response is not valid JSON",
      );
    }
    if (!plainObject(parsed) || parsed.status !== "ok" || Object.keys(parsed).length !== 1) {
      throw new NarraMemMemoryApiError(
        "INVALID_RESPONSE",
        "Memory API test response does not match the strict test schema",
      );
    }
    return { status: "ok", source: profile.source, model: profile.model, dispatches_used: 1 };
  }
}
