import type {
  TavernMemorySetCreateResult,
  TavernMemorySetResolution,
} from "./memory-registry-contracts.js";
import type {
  TavernMutationHint,
  TavernSemanticMetadataNormalizer,
  TavernSourceMessage,
  TavernSourceReconciliationResult,
  TavernSourceScope,
  TavernSourceSnapshot,
} from "./source-snapshot-contracts.js";
import type { TavernArchiveRecord, TavernControlPayload } from "./worldbook-store-contracts.js";

export const TAVERN_CURRENT_ARCHIVE_VERSION = "0.1.0" as const;
export const TAVERN_CURRENT_ARCHIVE_FORMAT = "narramem.tavern-current-archive" as const;
export const TAVERN_SOURCE_MANIFEST_RECORD_KIND = "source_manifest_v1" as const;
export const TAVERN_SOURCE_MESSAGE_RECORD_KIND = "source_message_v1" as const;
export const TAVERN_SOURCE_MANIFEST_RECORD_ID = "source_manifest" as const;
export const TAVERN_CARRIED_SEMANTIC_BASE_VERSION = "0.1.0" as const;
export const TAVERN_CARRIED_SEMANTIC_BASE_RECORD_ID = "carried_semantic_base" as const;
export const TAVERN_CARRIED_SEMANTIC_BASE_RECORD_KIND = "carried_semantic_base_v1" as const;

export interface TavernSourceManifestPayload {
  readonly format: typeof TAVERN_CURRENT_ARCHIVE_FORMAT;
  readonly schema_version: typeof TAVERN_CURRENT_ARCHIVE_VERSION;
  readonly memory_set_id: string;
  readonly scope: TavernSourceScope;
  readonly source_revision: number;
  readonly root_chain_hash: string;
  readonly source_snapshot_checksum: string;
  readonly message_count: number;
}

export interface TavernSourceMessagePayload {
  readonly format: typeof TAVERN_CURRENT_ARCHIVE_FORMAT;
  readonly schema_version: typeof TAVERN_CURRENT_ARCHIVE_VERSION;
  readonly memory_set_id: string;
  readonly source_revision: number;
  readonly source_message: TavernSourceMessage;
}

export interface TavernCarriedSemanticBasePayload {
  readonly version: typeof TAVERN_CARRIED_SEMANTIC_BASE_VERSION;
  readonly memory_set_id: string;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly root_chain_hash: string;
  readonly message_count: number;
}

export interface TavernCurrentArchiveProjection {
  readonly snapshot: TavernSourceSnapshot;
  readonly records: readonly TavernArchiveRecord[];
}

export interface TavernCurrentArchiveCoordinatorOptions {
  readonly max_records_per_segment: number;
  readonly max_segment_utf8_bytes: number;
}

export interface TavernCurrentArchiveAnchorCandidateExpectation {
  readonly control_book_name: string;
  readonly expected_control_checksum: string;
}

export interface TavernCurrentArchiveCreateChoice {
  readonly memory_set_id: string;
  readonly character_revision_hash: string | null;
  /**
   * Exact candidate set the caller saw before choosing a new timeline instead
   * of rebinding one of those candidates. Any drift fails closed.
   */
  readonly expected_anchor_candidates?: readonly TavernCurrentArchiveAnchorCandidateExpectation[];
}

export interface TavernCurrentArchiveRebindChoice {
  readonly control_book_name: string;
  readonly expected_control_checksum: string;
  readonly character_revision_hash: string | null;
}

export interface TavernCurrentArchiveSyncRequest {
  readonly writer_id: string;
  readonly transaction_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly observed_hints: readonly TavernMutationHint[];
  readonly create_if_not_found?: TavernCurrentArchiveCreateChoice;
  readonly confirmed_anchor_rebind?: TavernCurrentArchiveRebindChoice;
  readonly exclusive_recovery_confirmed: boolean;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
  readonly after_durable_phase?: (
    phase:
      | "segments_staged"
      | "pending_recorded"
      | "pointer_committed"
      | "obsolete_collected"
      | "pending_cleared",
  ) => void | Promise<void>;
}

export interface TavernCurrentArchiveActionRequiredResult {
  readonly status: "ACTION_REQUIRED";
  readonly resolution: TavernMemorySetResolution;
  readonly required_action: "CREATE_MEMORY_SET" | "CONFIRM_ANCHOR_CANDIDATE" | "RESOLVE_CONFLICT";
}

export interface TavernCurrentArchiveStableResult {
  readonly status: "SYNCED" | "UNCHANGED";
  readonly resolution: TavernMemorySetResolution;
  readonly memory_set_id: string;
  readonly control_book_name: string;
  readonly control: TavernControlPayload;
  readonly reconciliation: TavernSourceReconciliationResult;
  readonly recovery_action:
    | "NO_ACTION"
    | "ORPHANS_COLLECTED"
    | "STAGING_ABORTED_STALE"
    | "STAGING_COMMITTED"
    | "COMMITTED_CLEANED"
    | "ROLLED_BACK"
    | "REBUILD_REQUIRED"
    | null;
  readonly registry_updated: boolean | null;
  readonly created_memory_set: TavernMemorySetCreateResult | null;
}

export type TavernCurrentArchiveSyncResult =
  | TavernCurrentArchiveActionRequiredResult
  | TavernCurrentArchiveStableResult;

export class TavernCurrentArchiveError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "ACTIVE_ARCHIVE_CORRUPT"
      | "CONFIRMATION_MISMATCH"
      | "SOURCE_CHANGED_DURING_SYNC",
    message: string,
  ) {
    super(message);
    this.name = "TavernCurrentArchiveError";
  }
}
