type JsonSchema = Readonly<Record<string, unknown>>;

const UUID =
  "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}";
const MAX_SAFE_INTEGER = 9_007_199_254_740_991;

const ID_KINDS = [
  "memory_space",
  "branch",
  "source_revision",
  "evidence",
  "scene",
  "episode",
  "event",
  "entity",
  "identity_claim",
  "salience_assessment",
  "state_assertion",
  "state_delta",
  "current_state_view",
  "proposition",
  "epistemic_state",
  "information_transfer",
  "causal_link",
  "narrative_thread",
  "future_impact",
  "interpretation",
  "recall_cue",
  "derivation",
  "change_set",
  "recall_bundle",
  "recall_trace",
  "investigation",
  "transaction",
  "shard",
] as const;

const ref = (name: string): JsonSchema => ({ $ref: `#/$defs/${name}` });
const absoluteRef = (name: string): JsonSchema => ({
  $ref: `https://narramem.dev/schema/catalog-0.1.0.json#/$defs/${name}`,
});
const stringSchema = (options: JsonSchema = {}): JsonSchema => ({ type: "string", ...options });
const numberSchema = (options: JsonSchema = {}): JsonSchema => ({ type: "number", ...options });
const integerSchema = (options: JsonSchema = {}): JsonSchema => ({ type: "integer", ...options });
const enumSchema = (values: readonly string[]): JsonSchema => ({ type: "string", enum: values });
const constSchema = (value: string | boolean): JsonSchema => ({
  type: typeof value === "boolean" ? "boolean" : "string",
  const: value,
});
const arrayOf = (items: JsonSchema, options: JsonSchema = {}): JsonSchema => ({
  type: "array",
  items,
  ...options,
});
const objectSchema = (
  required: readonly string[],
  properties: Readonly<Record<string, JsonSchema>>,
  options: JsonSchema = {},
): JsonSchema => ({
  type: "object",
  additionalProperties: false,
  required,
  properties,
  ...options,
});
const oneOf = (...schemas: readonly JsonSchema[]): JsonSchema => ({ oneOf: schemas });
const anyOf = (...schemas: readonly JsonSchema[]): JsonSchema => ({ anyOf: schemas });
const idSchema = (kind: (typeof ID_KINDS)[number]): JsonSchema =>
  stringSchema({ pattern: `^nm_${kind}_${UUID}$` });

const scopeProperties = {
  memory_space_id: idSchema("memory_space"),
  branch_id: idSchema("branch"),
} as const;

const scopedRecord = (
  required: readonly string[],
  properties: Readonly<Record<string, JsonSchema>>,
): JsonSchema =>
  objectSchema(["memory_space_id", "branch_id", ...required], {
    ...scopeProperties,
    ...properties,
  });

const supportedProperties = {
  evidence: arrayOf(ref("evidence_span")),
  derivation: ref("derivation_meta"),
} as const;

const supportedRecord = (
  required: readonly string[],
  properties: Readonly<Record<string, JsonSchema>>,
): JsonSchema =>
  scopedRecord([...required, "evidence", "derivation"], { ...properties, ...supportedProperties });

const recordIdRefArray = arrayOf(ref("narramem_id"));

const proposalCommonProperties = {
  stage: constSchema("proposal"),
  changeset_id: idSchema("change_set"),
  memory_space_id: idSchema("memory_space"),
  branch_id: idSchema("branch"),
  based_on_revision_id: idSchema("source_revision"),
  unresolved_items: arrayOf(ref("unresolved_item")),
  created_at: stringSchema({ format: "date-time" }),
} as const;

const proposalRequired = [
  "stage",
  "changeset_id",
  "memory_space_id",
  "branch_id",
  "based_on_revision_id",
  "producer",
  "operations",
  "unresolved_items",
  "created_at",
] as const;

function proposalVariant(producer: string, operationSchema: JsonSchema): JsonSchema {
  return objectSchema(proposalRequired, {
    ...proposalCommonProperties,
    producer: constSchema(producer),
    operations: arrayOf(operationSchema),
  });
}

