export type WireSchemaName = (typeof WIRE_SCHEMA_NAMES)[number];

function collectLocalDefinitionRefs(value: unknown, refs: Set<string>): void {
  if (Array.isArray(value)) {
    for (const item of value) {
      collectLocalDefinitionRefs(item, refs);
    }
    return;
  }
  if (typeof value !== "object" || value === null) {
    return;
  }
  for (const [key, nested] of Object.entries(value)) {
    if (key === "$ref" && typeof nested === "string" && nested.startsWith("#/$defs/")) {
      refs.add(nested.slice("#/$defs/".length));
    } else {
      collectLocalDefinitionRefs(nested, refs);
    }
  }
}

/** Builds a self-contained, dependency-pruned Schema for Provider structured output. */
export function createStandaloneWireSchema(name: WireSchemaName): JsonSchema {
  const catalogDefinitions = NARRAMEM_WIRE_SCHEMA_CATALOG.$defs;
  if (typeof catalogDefinitions !== "object" || catalogDefinitions === null) {
    throw new Error("NarraMem wire Schema catalog has no $defs");
  }
  const definitions = catalogDefinitions as Readonly<Record<string, JsonSchema>>;
  const root = definitions[name];
  if (root === undefined) {
    throw new TypeError(`Unknown NarraMem wire Schema: ${name}`);
  }

  const pending = new Set<string>();
  collectLocalDefinitionRefs(root, pending);
  const selected: Record<string, JsonSchema> = {};
  for (const definitionName of pending) {
    const definition = definitions[definitionName];
    if (definition === undefined) {
      throw new Error(`Missing local Schema definition: ${definitionName}`);
    }
    selected[definitionName] = definition;
    collectLocalDefinitionRefs(definition, pending);
  }
  return { ...root, $defs: selected };
}

export function createWireSchemaReference(name: WireSchemaName): JsonSchema {
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: `https://narramem.dev/schema/${name}-0.1.0.json`,
    ...absoluteRef(name),
  };
}
