import type { NarraMemId } from "@narramem/core-domain";

import type { TavernEventSubscription, TavernHostPort } from "./contracts.js";
import type {
  TavernCurrentArchiveAnchorCandidateExpectation,
  TavernCurrentArchiveSyncResult,
} from "./current-archive-contracts.js";
import type { TavernRuntimePromptAsset } from "./extraction-job-contracts.js";
import type {
  TavernInteractionPerformanceListener,
  TavernInteractionPerformanceSample,
  TavernInteractionPerformanceSnapshot,
} from "./interaction-performance-contracts.js";
import type {
  TavernObserverCycleReport,
  TavernObserverRuntime,
  TavernObserverSchedulerConfig,
  TavernObserverSchedulerSnapshot,
} from "./observer-scheduler-contracts.js";
import type {
  TavernBindPrincipalRequest,
  TavernPrincipalBindingInspection,
} from "./principal-binding-contracts.js";
import type {
  TavernRecallReadOnlyQueryRequest,
  TavernRecallReadOnlyQueryResult,
} from "./recall-contracts.js";
import type {
  TavernRecallGenerationBarrierReport,
  TavernRecallGenerationBarrierSnapshot,
} from "./recall-generation-barrier-contracts.js";
import type { TavernRuntimeRecallPromptAsset } from "./recall-prompt-contracts.js";

export const TAVERN_EXTENSION_RUNTIME_VERSION = "0.1.0" as const;
export const TAVERN_EXTENSION_RUNTIME_SLOT_KEY = "narramem.tavern-extension-runtime.v1" as const;

export interface TavernPageLifecyclePort {
  add_listener(event_name: "pagehide" | "pageshow", listener: () => void): void;
  remove_listener(event_name: "pagehide" | "pageshow", listener: () => void): void;
}

export interface TavernExtensionRuntimeExtractionConfig {
  readonly requested_model_id: string;
  /** New user-triggered retry rounds use a fresh durable operation fingerprint. */
  readonly retry_round_id?: string;
  /** Literal build-time raw import of the registered model-specific Markdown body. */
  readonly prompt_body: string;
  readonly allow_candidate_prompt: boolean;
  readonly max_attempts?: number;
  readonly prepare: TavernObserverSchedulerConfig["extraction"]["prepare"];
}

export interface TavernExtensionRuntimeLifecycleConfig {
  readonly requested_model_id: string;
  /** Must match the extraction retry round when a user explicitly retries. */
  readonly retry_round_id?: string;
  /** Literal build-time raw import of the registered model-specific Markdown body. */
  readonly prompt_body: string;
  readonly allow_candidate_prompt: boolean;
  readonly max_attempts?: number;
}

export interface TavernExtensionRuntimeRecallConfig {
  readonly token_budget: number;
  readonly latest_ai_floor_count: number;
  /** Hard upper bound for generation-path Recall work; defaults to 150 ms. */
  readonly max_prepare_ms?: number;
  /** Literal build-time raw import of the registered model-specific Markdown body. */
  readonly prompt_body: string;
  readonly principal_entity_id?: NarraMemId<"entity">;
}

export interface TavernExtensionRuntimeConfig {
  readonly installation_id: string;
  readonly replace_existing: boolean;
  readonly segment_limits: {
    readonly max_records_per_segment: number;
    readonly max_segment_utf8_bytes: number;
  };
  readonly observer: Omit<TavernObserverSchedulerConfig, "extraction" | "lifecycle"> & {
    readonly extraction: TavernExtensionRuntimeExtractionConfig;
    readonly lifecycle?: TavernExtensionRuntimeLifecycleConfig;
  };
  readonly recall: TavernExtensionRuntimeRecallConfig;
  readonly interaction_performance?: {
    readonly max_samples: number;
  };
}

export interface TavernExtensionRuntimeHandle {
  readonly runtime_version: typeof TAVERN_EXTENSION_RUNTIME_VERSION;
  readonly installation_id: string;
  start(): boolean;
  stop(reason?: string): boolean;
  flushNow(): Promise<TavernObserverCycleReport | null>;
  subscribeReports(listener: (report: TavernObserverCycleReport) => void): TavernEventSubscription;
  subscribeRecallReports(
    listener: (report: TavernRecallGenerationBarrierReport) => void,
  ): TavernEventSubscription;
  getSnapshot(): TavernObserverSchedulerSnapshot;
  getRecallSnapshot(): TavernRecallGenerationBarrierSnapshot;
  getInteractionPerformanceSnapshot(): TavernInteractionPerformanceSnapshot;
  subscribeInteractionPerformance(
    listener: TavernInteractionPerformanceListener,
  ): TavernEventSubscription;
  clearInteractionPerformanceSamples(): void;
  inspectPrincipalBinding(): Promise<TavernPrincipalBindingInspection>;
  bindPrincipal(request: TavernBindPrincipalRequest): Promise<TavernPrincipalBindingInspection>;
  assembleReadOnlyQuery(
    request: Pick<
      TavernRecallReadOnlyQueryRequest,
      "query_text" | "expected_authoritative_source_checksum" | "principal_entity_id"
    >,
  ): Promise<TavernRecallReadOnlyQueryResult>;
  resolveMemorySet(choice: TavernExtensionMemorySetChoice): Promise<TavernCurrentArchiveSyncResult>;
  dispose(): boolean;
}

export type TavernExtensionMemorySetChoice =
  | {
      readonly kind: "CREATE_MEMORY_SET";
      readonly memory_set_id?: string;
      readonly character_revision_hash: string | null;
      readonly expected_anchor_candidates?: readonly TavernCurrentArchiveAnchorCandidateExpectation[];
    }
  | {
      readonly kind: "CONFIRM_ANCHOR_CANDIDATE";
      readonly control_book_name: string;
      readonly expected_control_checksum: string;
      readonly character_revision_hash: string | null;
    };

export interface TavernExtensionRuntimeSlot {
  get(): TavernExtensionRuntimeHandle | null;
  set(handle: TavernExtensionRuntimeHandle | null): void;
}

export interface InstallTavernExtensionRuntimeRequest {
  readonly host_port: TavernHostPort;
  readonly config: TavernExtensionRuntimeConfig;
  readonly lifecycle?: TavernPageLifecyclePort;
  readonly observer_runtime?: TavernObserverRuntime;
  readonly slot?: TavernExtensionRuntimeSlot;
  readonly on_report?: (report: TavernObserverCycleReport) => void;
  readonly on_recall_report?: (report: TavernRecallGenerationBarrierReport) => void;
  readonly on_interaction_performance_sample?: (sample: TavernInteractionPerformanceSample) => void;
  /** Optional host gate for automatic pageshow resume; manual start remains available. */
  readonly should_resume_on_pageshow?: () => boolean;
}

export class TavernExtensionRuntimeError extends Error {
  constructor(
    readonly code:
      | "INVALID_CONFIG"
      | "PROMPT_ASSET_INVALID"
      | "BROWSER_LIFECYCLE_UNAVAILABLE"
      | "ALREADY_INSTALLED"
      | "INSTALLATION_SLOT_CORRUPT"
      | "ACTIVATION_FAILED"
      | "READ_ONLY_RECALL_UNAVAILABLE",
    message: string,
  ) {
    super(message);
    this.name = "TavernExtensionRuntimeError";
  }
}

export interface TavernRuntimePromptBuildResult {
  readonly asset: TavernRuntimePromptAsset;
  readonly exact_model_id: string;
}

export interface TavernRuntimeRecallPromptBuildResult {
  readonly asset: TavernRuntimeRecallPromptAsset;
  readonly exact_model_id: string;
}

export interface TavernRuntimeLifecyclePromptBuildResult {
  readonly asset: TavernRuntimePromptAsset;
  readonly exact_model_id: string;
}
