import {
  TAVERN_HOST_PORT_VERSION,
  type TavernEventSubscription,
  type TavernHostPort,
  type TavernMessageRole,
  type TavernMessageSnapshot,
  type TavernStructuredGenerationResult,
  type TavernWorldbookEntry,
  type TavernWorldbookEntryDraft,
} from "./contracts.js";
import { projectNarrativeText } from "./narrative-text-projection.js";

type UnknownRecord = Record<string, unknown>;

export interface SillyTavernChatMessage {
  readonly mes?: string;
  readonly name?: string;
  readonly is_user?: boolean;
  readonly is_system?: boolean;
  readonly send_date?: string | number;
  readonly extra?: Readonly<UnknownRecord>;
  readonly swipe_id?: number;
  readonly swipes?: readonly string[];
  readonly swipe_info?: readonly Readonly<UnknownRecord>[];
}

export interface SillyTavernCharacter {
  readonly name?: string;
  readonly avatar?: string;
}

export interface SillyTavernWorldInfoEntry extends UnknownRecord {
  readonly uid: number;
}

export interface SillyTavernWorldInfoData {
  readonly entries: Record<string, SillyTavernWorldInfoEntry>;
}

export interface SillyTavernEventSource {
  on(event_name: string, listener: (...args: unknown[]) => void | Promise<void>): void;
  removeListener(event_name: string, listener: (...args: unknown[]) => void | Promise<void>): void;
  emit(event_name: string, ...args: unknown[]): Promise<void>;
}

export interface SillyTavernExtensionBindings {
  readonly silly_tavern_version: string;
  get_character_id(): string | number | null | undefined;
  get_character_name(): string | null;
  get_chat_id(): string | null;
  get_chat(): readonly SillyTavernChatMessage[];
  get_narrative_content_tag?(): string;
  get_current_api(): string;
  get_current_model_id(): string;
  readonly event_source: SillyTavernEventSource;
  get_worldbook_names(): readonly string[];
  load_world_info(name: string): Promise<SillyTavernWorldInfoData | null | undefined>;
  load_world_info_fresh?(name: string): Promise<SillyTavernWorldInfoData | null | undefined>;
  create_world_info(name: string): Promise<boolean>;
  save_world_info(name: string, data: SillyTavernWorldInfoData, immediately: true): Promise<void>;
  delete_world_info(name: string): Promise<boolean>;
  with_worldbook_lock?<T>(lock_name: string, operation: () => Promise<T>): Promise<T>;
  readonly new_world_info_entry_template: Readonly<UnknownRecord>;
  set_extension_prompt(
    id: string,
    content: string,
    position: number,
    depth: number,
    should_scan: boolean,
    role: number,
  ): void;
  generate_raw(
    request: {
      readonly prompt: readonly { readonly role: TavernMessageRole; readonly content: string }[];
      readonly responseLength: number;
      readonly trimNames: false;
      readonly schemaName: string;
      readonly jsonSchema: Readonly<Record<string, unknown>>;
    },
    audit: {
      readonly generation_id: string;
      readonly requested_model_id: string;
    },
  ): Promise<string>;
}

export class SillyTavernExtensionHostError extends Error {
  constructor(
    readonly code:
      | "INVALID_HOST_DATA"
      | "WORLDBOOK_NOT_FOUND"
      | "MODEL_MISMATCH"
      | "UNSUPPORTED_MAIN_API"
      | "UNSUPPORTED_PROXY_PRESET",
    message: string,
  ) {
    super(message);
    this.name = "SillyTavernExtensionHostError";
  }
}

const POSITION_AFTER_CHARACTER = 1;
const POSITION_AT_DEPTH = 4;
const EXTENSION_PROMPT_NONE = -1;
const EXTENSION_PROMPT_IN_CHAT = 1;

const ROLE_TO_NATIVE: Readonly<Record<TavernMessageRole, number>> = {
  system: 0,
  user: 1,
  assistant: 2,
};

function requiresFreshWorldbookRead(name: string): boolean {
  return !name.startsWith("NarraMem__ARCHIVE__");
}

const LOGIC_TO_NATIVE = {
  and_any: 0,
  not_all: 1,
  not_any: 2,
  and_all: 3,
} as const;

const NATIVE_TO_LOGIC = ["and_any", "not_all", "not_any", "and_all"] as const;

function toNativeEventName(eventName: string): string {
  // SillyTavern 1.16.0 is inconsistent here: the public event value is the
  // uppercase literal while NarraMem's HostPort keeps canonical lower snake case.
  return eventName === "generation_after_commands" ? "GENERATION_AFTER_COMMANDS" : eventName;
}

function asRecord(value: unknown): UnknownRecord {
  return typeof value === "object" && value !== null ? (value as UnknownRecord) : {};
}

function asStringArray(value: unknown): readonly string[] {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
}

function finiteNumber(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function nullableFiniteNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function toRole(message: SillyTavernChatMessage): TavernMessageRole {
  if (message.is_system === true) return "system";
  return message.is_user === true ? "user" : "assistant";
}

function toMessageSnapshot(
  message: SillyTavernChatMessage,
  messageId: number,
  narrativeContentTag: string,
): TavernMessageSnapshot {
  const extra = asRecord(message.extra);
  const hidden = extra.isSmallSys === true || extra.is_hidden === true;
  const role = toRole(message);
  const narrativeProjection =
    typeof message.mes === "string"
      ? projectNarrativeText(message.mes, role, narrativeContentTag)
      : undefined;
  return {
    message_id: messageId,
    name: typeof message.name === "string" ? message.name : "",
    role,
    is_hidden: hidden,
    ...(typeof message.mes === "string" ? { message: message.mes } : {}),
    ...(narrativeProjection === undefined ? {} : { narrative_projection: narrativeProjection }),
    data: {
      ...(message.send_date === undefined ? {} : { send_date: message.send_date }),
      is_user: message.is_user === true,
      is_system: message.is_system === true,
    },
    extra,
    ...(Number.isInteger(message.swipe_id) ? { swipe_id: message.swipe_id } : {}),
    ...(Array.isArray(message.swipes) ? { swipes: [...message.swipes] } : {}),
    ...(Array.isArray(message.swipe_info) ? { swipes_info: [...message.swipe_info] } : {}),
  };
}

function toTavernEntry(nativeEntry: SillyTavernWorldInfoEntry): TavernWorldbookEntry {
  const native = asRecord(nativeEntry);
  const rawLogic = finiteNumber(native.selectiveLogic, 0);
  const logic = NATIVE_TO_LOGIC[rawLogic] ?? "and_any";
  const position = finiteNumber(native.position, POSITION_AFTER_CHARACTER);
  const nativeRole = finiteNumber(native.role, 0);
  const role: TavernMessageRole =
    nativeRole === 1 ? "user" : nativeRole === 2 ? "assistant" : "system";
  const scanDepth = native.scanDepth;
  return {
    uid: nativeEntry.uid,
    name: typeof native.comment === "string" ? native.comment : "",
    enabled: native.disable !== true,
    content: typeof native.content === "string" ? native.content : "",
    strategy: {
      type: native.constant === true ? "constant" : "selective",
      keys: asStringArray(native.key),
      keys_secondary: {
        logic,
        keys: asStringArray(native.keysecondary),
      },
      scan_depth:
        typeof scanDepth === "number" && Number.isFinite(scanDepth) ? scanDepth : "same_as_global",
    },
    position: {
      type: position === POSITION_AT_DEPTH ? "at_depth" : "after_character_definition",
      role,
      depth: finiteNumber(native.depth, 4),
      order: finiteNumber(native.order, 100),
    },
    probability: finiteNumber(native.probability, 100),
    recursion: {
      prevent_incoming: native.excludeRecursion === true,
      prevent_outgoing: native.preventRecursion === true,
      delay_until: nullableFiniteNumber(native.delayUntilRecursion),
    },
    effect: {
      sticky: nullableFiniteNumber(native.sticky),
      cooldown: nullableFiniteNumber(native.cooldown),
      delay: nullableFiniteNumber(native.delay),
    },
    ...(typeof native.extra === "object" && native.extra !== null
      ? { extra: structuredClone(native.extra) as UnknownRecord }
      : {}),
  };
}

function toNativeEntry(
  entry: TavernWorldbookEntry,
  template: Readonly<UnknownRecord>,
): SillyTavernWorldInfoEntry {
  return {
    ...structuredClone(template),
    uid: entry.uid,
    key: [...entry.strategy.keys],
    keysecondary: [...entry.strategy.keys_secondary.keys],
    comment: entry.name,
    content: entry.content,
    constant: entry.strategy.type === "constant",
    selective: entry.strategy.type === "selective",
    selectiveLogic: LOGIC_TO_NATIVE[entry.strategy.keys_secondary.logic],
    scanDepth: entry.strategy.scan_depth === "same_as_global" ? null : entry.strategy.scan_depth,
    position: entry.position.type === "at_depth" ? POSITION_AT_DEPTH : POSITION_AFTER_CHARACTER,
    role: ROLE_TO_NATIVE[entry.position.role],
    depth: entry.position.depth,
    order: entry.position.order,
    probability: entry.probability,
    disable: !entry.enabled,
    excludeRecursion: entry.recursion.prevent_incoming,
    preventRecursion: entry.recursion.prevent_outgoing,
    delayUntilRecursion: entry.recursion.delay_until,
    sticky: entry.effect.sticky,
    cooldown: entry.effect.cooldown,
    delay: entry.effect.delay,
    ...(entry.extra === undefined ? {} : { extra: structuredClone(entry.extra) }),
  };
}

function buildNativeWorldInfo(
  entries: readonly TavernWorldbookEntry[],
  template: Readonly<UnknownRecord>,
): SillyTavernWorldInfoData {
  return {
    entries: Object.fromEntries(
      entries.map((entry) => [String(entry.uid), toNativeEntry(entry, template)]),
    ),
  };
}

function readNativeEntries(data: SillyTavernWorldInfoData): readonly SillyTavernWorldInfoEntry[] {
  if (typeof data !== "object" || data === null || typeof data.entries !== "object") {
    throw new SillyTavernExtensionHostError(
      "INVALID_HOST_DATA",
      "SillyTavern returned an invalid World Info payload",
    );
  }
  return Object.values(data.entries).sort((left, right) => left.uid - right.uid);
}

export function createSillyTavernExtensionHostPort(
  bindings: SillyTavernExtensionBindings,
): TavernHostPort {
  return {
    port_version: TAVERN_HOST_PORT_VERSION,
    getVersions: () => ({
      silly_tavern: bindings.silly_tavern_version,
      integration: "native_extension",
    }),
    getCurrentIdentity: () => {
      const rawCharacterId = bindings.get_character_id();
      const characterId =
        rawCharacterId === null || rawCharacterId === undefined || rawCharacterId === ""
          ? null
          : String(rawCharacterId);
      return {
        character_id: characterId,
        character_name: bindings.get_character_name(),
        chat_id: bindings.get_chat_id(),
      };
    },
    readCurrentMessages: ({ include_swipes }) =>
      bindings.get_chat().map((message, index) => {
        const snapshot = toMessageSnapshot(
          message,
          index,
          bindings.get_narrative_content_tag?.() ?? "content",
        );
        if (include_swipes) return snapshot;
        const {
          swipe_id: _swipeId,
          swipes: _swipes,
          swipes_info: _swipesInfo,
          ...current
        } = snapshot;
        return current;
      }),
    subscribe: (eventName, listener): TavernEventSubscription => {
      const nativeEventName = toNativeEventName(eventName);
      const wrapped = (...args: unknown[]) => listener(...args);
      bindings.event_source.on(nativeEventName, wrapped);
      let active = true;
      return {
        stop: () => {
          if (!active) return;
          active = false;
          bindings.event_source.removeListener(nativeEventName, wrapped);
        },
      };
    },
    emitCustomEvent: (eventName, ...args) => bindings.event_source.emit(eventName, ...args),
    listWorldbooks: () => [...bindings.get_worldbook_names()],
    readWorldbook: async (name) => {
      const data = await (requiresFreshWorldbookRead(name) &&
      bindings.load_world_info_fresh !== undefined
        ? bindings.load_world_info_fresh(name)
        : bindings.load_world_info(name));
      if (data === null || data === undefined) {
        throw new SillyTavernExtensionHostError(
          "WORLDBOOK_NOT_FOUND",
          `World Info not found: ${name}`,
        );
      }
      return readNativeEntries(data).map(toTavernEntry);
    },
    createWorldbook: (name) => bindings.create_world_info(name),
    replaceWorldbook: async (name, entries) => {
      await bindings.save_world_info(
        name,
        buildNativeWorldInfo(entries, bindings.new_world_info_entry_template),
        true,
      );
    },
    appendWorldbookEntries: async (name, drafts) => {
      const data = await bindings.load_world_info(name);
      if (data === null || data === undefined) {
        throw new SillyTavernExtensionHostError(
          "WORLDBOOK_NOT_FOUND",
          `World Info not found: ${name}`,
        );
      }
      const existing = readNativeEntries(data).map(toTavernEntry);
      let nextUid = existing.reduce((maximum, entry) => Math.max(maximum, entry.uid), -1) + 1;
      const appended = drafts.map(
        (draft: TavernWorldbookEntryDraft): TavernWorldbookEntry => ({
          ...draft,
          uid: nextUid++,
        }),
      );
      const worldbook = [...existing, ...appended];
      await bindings.save_world_info(
        name,
        buildNativeWorldInfo(worldbook, bindings.new_world_info_entry_template),
        true,
      );
      return { worldbook, new_entries: appended };
    },
    deleteWorldbook: (name) => bindings.delete_world_info(name),
    ...(bindings.with_worldbook_lock === undefined
      ? {}
      : {
          withWorldbookExclusiveLock: <T>(
            lockName: string,
            operation: () => Promise<T>,
          ): Promise<T> => bindings.with_worldbook_lock?.(lockName, operation) as Promise<T>,
        }),
    installInjection: (request) => {
      const position =
        request.position === "in_chat" ? EXTENSION_PROMPT_IN_CHAT : EXTENSION_PROMPT_NONE;
      const role = ROLE_TO_NATIVE[request.role];
      bindings.set_extension_prompt(
        request.id,
        request.content,
        position,
        request.depth,
        request.should_scan,
        role,
      );
      let active = true;
      return {
        remove: () => {
          if (!active) return;
          active = false;
          bindings.set_extension_prompt(request.id, "", position, request.depth, false, role);
        },
      };
    },
    generateStructured: async (request): Promise<TavernStructuredGenerationResult> => {
      if (request.target.proxy_preset !== undefined) {
        throw new SillyTavernExtensionHostError(
          "UNSUPPORTED_PROXY_PRESET",
          "The native extension uses the currently selected SillyTavern connection; proxy preset override is unavailable",
        );
      }
      if (bindings.get_current_api() !== "openai") {
        throw new SillyTavernExtensionHostError(
          "UNSUPPORTED_MAIN_API",
          "Strict structured generation currently requires SillyTavern chat completion mode",
        );
      }
      const currentModel = bindings.get_current_model_id();
      if (currentModel !== request.target.requested_model_id) {
        throw new SillyTavernExtensionHostError(
          "MODEL_MISMATCH",
          `Current SillyTavern model ${currentModel} does not match requested exact model ${request.target.requested_model_id}`,
        );
      }
      const content = await bindings.generate_raw(
        {
          prompt: request.messages,
          responseLength: request.target.parameters.max_tokens,
          trimNames: false,
          schemaName: request.json_schema.name,
          jsonSchema: request.json_schema.value,
        },
        {
          generation_id: request.generation_id,
          requested_model_id: request.target.requested_model_id,
        },
      );
      return { kind: "text", content };
    },
    // SillyTavern 1.16.0 exposes only a foreground-global stop hook, which
    // NarraMem must not use for a background task. Returning false keeps the
    // Runner's per-generation local cancellation and stale-result fence active
    // without stopping the user's roleplay response.
    cancelGeneration: () => false,
  };
}
