import type { TavernEventSubscription } from "./contracts.js";
import type { TavernRecallGenerationBarrierReport } from "./recall-generation-barrier-contracts.js";

export const TAVERN_INTERACTION_PERFORMANCE_VERSION = "0.2.0" as const;

export const TAVERN_INTERACTION_PERFORMANCE_EVENT_NAMES = [
  "message_sent",
  "generation_started",
  "stream_token_received",
  "message_received",
  "generation_stopped",
  "generation_ended",
  "chat_id_changed",
] as const;

export interface TavernInteractionPerformanceConfig {
  readonly max_samples: number;
}

export interface TavernInteractionPerformanceRuntime {
  now_ms(): number;
}

export interface TavernInteractionBarrierTiming {
  readonly status: "INJECTION_INSTALLED" | "DEGRADED_NO_INJECTION";
  readonly elapsed_ms: number;
  readonly trigger: Extract<
    TavernRecallGenerationBarrierReport,
    { readonly status: "INJECTION_INSTALLED" | "DEGRADED_NO_INJECTION" }
  >["trigger"];
  readonly degradation_reason?: Extract<
    TavernRecallGenerationBarrierReport,
    { readonly status: "DEGRADED_NO_INJECTION" }
  >["reason"];
}

export type TavernInteractionGenerationType =
  | "normal"
  | "regenerate"
  | "swipe"
  | "quiet"
  | "impersonate"
  | "continue"
  | "unknown";

export interface TavernInteractionPerformanceSample {
  readonly schema_version: typeof TAVERN_INTERACTION_PERFORMANCE_VERSION;
  readonly sequence: number;
  readonly trigger: "USER_MESSAGE" | "OTHER";
  readonly generation_type: TavernInteractionGenerationType;
  readonly outcome:
    | "ENDED"
    | "STOPPED"
    | "SUPERSEDED_BY_NEW_GENERATION"
    | "CHAT_CHANGED"
    | "RUNTIME_STOPPED";
  readonly streaming_first_token_observed: boolean;
  readonly sent_to_generation_started_ms: number | null;
  readonly generation_started_to_first_token_ms: number | null;
  readonly sent_to_first_token_ms: number | null;
  readonly generation_started_to_completion_ms: number | null;
  readonly sent_to_completion_ms: number | null;
  readonly total_generation_lifecycle_ms: number;
  readonly recall_barrier: TavernInteractionBarrierTiming | null;
  readonly content_recorded: false;
  readonly draft_input_observed: false;
  readonly browser_persistent_storage_used: false;
}

export interface TavernInteractionDurationSummary {
  readonly samples: number;
  readonly p50_ms: number | null;
  readonly p95_ms: number | null;
  readonly max_ms: number | null;
}

export interface TavernInteractionPerformanceSnapshot {
  readonly schema_version: typeof TAVERN_INTERACTION_PERFORMANCE_VERSION;
  readonly lifecycle: "idle" | "running" | "stopped" | "disposed";
  readonly max_samples: number;
  readonly active_generation: boolean;
  readonly retained_samples: readonly TavernInteractionPerformanceSample[];
  readonly aggregate: {
    readonly completed_samples: number;
    readonly user_triggered_samples: number;
    readonly user_turn_first_token: TavernInteractionDurationSummary;
    readonly post_commit_first_token: TavernInteractionDurationSummary;
    readonly user_turn_completion: TavernInteractionDurationSummary;
    readonly post_commit_completion: TavernInteractionDurationSummary;
    readonly recall_barrier: TavernInteractionDurationSummary;
    readonly degraded_no_injection_samples: number;
  };
  readonly content_recorded: false;
  readonly draft_input_observed: false;
  readonly browser_persistent_storage_used: false;
}

export type TavernInteractionPerformanceListener = (
  sample: TavernInteractionPerformanceSample,
) => void;

export interface TavernInteractionPerformanceSubscription extends TavernEventSubscription {}

export class TavernInteractionPerformanceError extends Error {
  constructor(
    readonly code: "INVALID_CONFIG" | "INVALID_RUNTIME" | "SUBSCRIPTION_FAILED" | "DISPOSED",
    message: string,
  ) {
    super(message);
    this.name = "TavernInteractionPerformanceError";
  }
}
