import type {
  AuthorizedChangeSet,
  ExtractionCandidateBatch,
  ExtractionClaimPredicateTerm,
  ExtractionEventTypeTerm,
  ExtractionStateKeyTerm,
  HashDigest,
  ModelChangeSetProposal,
  NarrativeExtractionCandidateBatch,
  NarrativeIncrementalCoverageBoundary,
  NarrativeIncrementalExtractionCandidateBatch,
  NarrativeIncrementalExtractionModelInput,
  TemporalExtent,
  ValidationReport,
} from "@narramem/core-domain";
import type { NarrativeIncrementalSemanticRecord } from "@narramem/narrative-compiler";

import type { TavernCoreSourceProjection } from "./core-source-projection.js";
import type { TavernExtractionResponseQualityAudit } from "./extraction-quality-contracts.js";
import type { TavernIncrementalSemanticCoveragePayload } from "./incremental-semantic-coverage-contracts.js";
import type {
  TavernControlCandidate,
  TavernMemorySetResolution,
} from "./memory-registry-contracts.js";
import type { TavernNarrativeLifecycleContinuityBaselinePayload } from "./narrative-lifecycle-contracts.js";
import type {
  TavernSemanticMetadataNormalizer,
  TavernSourceSnapshot,
} from "./source-snapshot-contracts.js";
import type {
  TavernArchiveRecord,
  TavernControlPayload,
  TavernDurableCommitPhase,
} from "./worldbook-store-contracts.js";

export const TAVERN_SEMANTIC_ARCHIVE_VERSION = "0.4.0" as const;
export const TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION = "0.1.0" as const;
export const TAVERN_SEMANTIC_MANIFEST_RECORD_ID = "semantic_manifest" as const;
export const TAVERN_SEMANTIC_MANIFEST_RECORD_KIND = "semantic_manifest_v4" as const;

export interface TavernPrepareExtractionRequest {
  readonly event_type_vocabulary: readonly ExtractionEventTypeTerm[];
  readonly state_key_vocabulary?: readonly ExtractionStateKeyTerm[];
  readonly claim_predicate_vocabulary?: readonly ExtractionClaimPredicateTerm[];
  readonly default_story_time: TemporalExtent;
  readonly created_at: string;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export interface TavernPrepareIncrementalExtractionRequest extends TavernPrepareExtractionRequest {
  /** Maximum authoritative Source messages committed by one semantic chunk. */
  readonly chunk_message_limit: number;
  /** Maximum preceding Source messages supplied as read-only context. */
  readonly context_message_limit: number;
}

export interface TavernExtractionTask {
  readonly task_version: typeof TAVERN_SEMANTIC_ARCHIVE_VERSION;
  readonly task_fingerprint: string;
  readonly resolution: TavernMemorySetResolution;
  readonly candidate: TavernControlCandidate;
  readonly control_checksum: string;
  readonly active_view_id: string;
  readonly source_snapshot: TavernSourceSnapshot;
  readonly source_records: readonly TavernArchiveRecord[];
  readonly known_entity_records: readonly TavernArchiveRecord[];
  readonly core_source: TavernCoreSourceProjection;
  readonly model_input_sha256: string;
  readonly coverage_key_sha256: string;
  readonly causal_continuity_baseline: {
    readonly source_revision_id: string;
    readonly source_checksum: string;
    readonly causal_link_count: number;
  } | null;
  readonly lifecycle_continuity_baseline: TavernNarrativeLifecycleContinuityBaselinePayload | null;
  readonly existing_semantic_manifest: TavernSemanticManifestPayload | null;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export interface TavernSemanticManifestPayload {
  readonly version: typeof TAVERN_SEMANTIC_ARCHIVE_VERSION;
  readonly task_fingerprint: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly model_input_sha256: string;
  readonly coverage_key_sha256: string;
  readonly candidate_batch_checksum: string;
  readonly changeset_id: string;
  readonly model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_contract_version: string;
  readonly prompt_body_sha256: HashDigest;
  readonly parameters_hash: HashDigest;
  readonly validator_version: string;
  readonly quality_audit: TavernExtractionResponseQualityAudit | null;
}

export interface TavernSemanticExtractorDescriptor {
  readonly model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_contract_version: string;
  readonly prompt_body_sha256: HashDigest;
  readonly parameters_hash: HashDigest;
}

export interface TavernSemanticCommitRequest {
  readonly task: TavernExtractionTask;
  readonly candidate_batch: ExtractionCandidateBatch | NarrativeExtractionCandidateBatch;
  readonly extractor: TavernSemanticExtractorDescriptor;
  readonly compilation_key: string;
  readonly compiled_at: string;
  readonly writer_id: string;
  readonly transaction_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly quality_audit?: TavernExtractionResponseQualityAudit;
  readonly after_durable_phase?: (phase: TavernDurableCommitPhase) => void | Promise<void>;
}

export interface TavernSemanticCommitResult {
  readonly control: TavernControlPayload;
  readonly proposal: ModelChangeSetProposal;
  readonly validation_report: ValidationReport & { readonly accepted: true };
  readonly authorized_changeset: AuthorizedChangeSet;
  readonly derived_record_count: number;
  readonly archive_record_count: number;
}

export interface TavernIncrementalExtractionTask {
  readonly task_version: typeof TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION;
  readonly task_fingerprint: string;
  readonly base_task: TavernExtractionTask;
  readonly active_records: readonly TavernArchiveRecord[];
  readonly active_records_checksum: string;
  readonly previous_cursor: TavernIncrementalSemanticCoveragePayload | null;
  readonly boundary: NarrativeIncrementalCoverageBoundary;
  readonly stable_semantic_records: readonly NarrativeIncrementalSemanticRecord[];
  readonly model_input: NarrativeIncrementalExtractionModelInput;
  readonly model_input_sha256: string;
  readonly coverage_key_sha256: string;
}

export interface TavernIncrementalSemanticCommitRequest {
  readonly task: TavernIncrementalExtractionTask;
  readonly candidate_batch: NarrativeIncrementalExtractionCandidateBatch;
  readonly extractor: TavernSemanticExtractorDescriptor;
  readonly compilation_key: string;
  readonly compiled_at: string;
  readonly writer_id: string;
  readonly transaction_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly quality_audit?: TavernExtractionResponseQualityAudit;
  readonly after_durable_phase?: (phase: TavernDurableCommitPhase) => void | Promise<void>;
}

export interface TavernIncrementalSemanticCommitResult extends TavernSemanticCommitResult {
  readonly coverage: TavernIncrementalSemanticCoveragePayload;
  readonly removed_semantic_record_ids: readonly string[];
}

export class TavernSemanticArchiveError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "MEMORY_SET_NOT_EXACT"
      | "NO_ACTIVE_SOURCE"
      | "NO_UNCOVERED_SOURCE"
      | "NO_NARRATIVE_EVIDENCE"
      | "LIFECYCLE_PENDING"
      | "STALE_TASK"
      | "PROPOSAL_REJECTED"
      | "SOURCE_CHANGED_DURING_COMMIT",
    message: string,
  ) {
    super(message);
    this.name = "TavernSemanticArchiveError";
  }
}
