import type {
  CausalCauseRef,
  CausalEffectRef,
  CausalLink,
  ContradictionNotice,
  Episode,
  EpistemicPrincipalRef,
  EpistemicState,
  EventAtom,
  EvidenceItem,
  EvidenceSpan,
  FutureImpact,
  HashDigest,
  InvestigationToolName,
  JsonValue,
  NarraMemId,
  NarrativeThread,
  Proposition,
  Scene,
  StateAssertion,
  StateDelta,
  StateSubjectRef,
  TriggerEvaluation,
} from "@narramem/core-domain";
import { validateWireValue, type WireSchemaName } from "@narramem/core-validator";

import {
  canonicalInvestigationJson,
  type InvestigationRuntimePorts,
  InvestigationToolExecutionError,
} from "./transcript.js";

type CorpusRecord =
  | Scene
  | Episode
  | EventAtom
  | StateAssertion
  | StateDelta
  | Proposition
  | EpistemicState
  | CausalLink
  | NarrativeThread
  | FutureImpact;

export interface ReadonlyMemoryCorpus {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly snapshot_revision_id: NarraMemId<"source_revision">;
  readonly snapshot_fingerprint: HashDigest;
  readonly evidence_items: readonly EvidenceItem[];
  readonly scenes: readonly Scene[];
  readonly episodes: readonly Episode[];
  readonly events: readonly EventAtom[];
  readonly state_assertions: readonly StateAssertion[];
  readonly state_deltas: readonly StateDelta[];
  readonly propositions: readonly Proposition[];
  readonly epistemic_states: readonly EpistemicState[];
  readonly causal_links: readonly CausalLink[];
  readonly narrative_threads: readonly NarrativeThread[];
  readonly future_impacts: readonly FutureImpact[];
  readonly contradiction_notices?: readonly ContradictionNotice[];
}

export interface ReadonlyMemoryCorpusPorts {
  readonly hash_text: (text: string) => Promise<HashDigest>;
  readonly evaluate_trigger?: (
    impact: FutureImpact,
    signal?: AbortSignal,
  ) => Promise<TriggerEvaluation> | TriggerEvaluation;
}

function recordId(record: CorpusRecord): NarraMemId {
  if ("scene_id" in record) return record.scene_id;
  if ("episode_id" in record) return record.episode_id;
  if ("event_id" in record) return record.event_id;
  if ("assertion_id" in record) return record.assertion_id;
  if ("delta_id" in record) return record.delta_id;
  if ("epistemic_id" in record) return record.epistemic_id as NarraMemId<"epistemic_state">;
  if ("proposition_id" in record) return record.proposition_id;
  if ("causal_id" in record) return record.causal_id;
  if ("thread_id" in record) return record.thread_id;
  return record.impact_id;
}

function recordSchema(record: CorpusRecord): WireSchemaName {
  if ("scene_id" in record) return "scene";
  if ("episode_id" in record) return "episode";
  if ("event_id" in record) return "event_atom";
  if ("assertion_id" in record) return "state_assertion";
  if ("delta_id" in record) return "state_delta";
  if ("epistemic_id" in record) return "epistemic_state";
  if ("proposition_id" in record) return "proposition";
  if ("causal_id" in record) return "causal_link";
  if ("thread_id" in record) return "narrative_thread";
  return "future_impact";
}

function allRecords(corpus: ReadonlyMemoryCorpus): CorpusRecord[] {
  return [
    ...corpus.scenes,
    ...corpus.episodes,
    ...corpus.events,
    ...corpus.state_assertions,
    ...corpus.state_deltas,
    ...corpus.propositions,
    ...corpus.epistemic_states,
    ...corpus.causal_links,
    ...corpus.narrative_threads,
    ...corpus.future_impacts,
  ];
}

function asJsonValue(value: unknown): JsonValue {
  const serialized = JSON.stringify(value);
  if (serialized === undefined) {
    throw new InvestigationToolExecutionError("INVESTIGATION_RESULT_NOT_JSON");
  }
  return JSON.parse(serialized) as JsonValue;
}

function uniqueSorted<T extends string>(values: readonly T[]): T[] {
  return [...new Set(values)].sort();
}

function evidenceRefs(record: CorpusRecord): NarraMemId<"evidence">[] {
  const refs: NarraMemId<"evidence">[] = [];
  if ("evidence" in record) refs.push(...record.evidence.map((span) => span.evidence_id));
  if ("support" in record) refs.push(...record.support.map((span) => span.evidence_id));
  if ("counterevidence" in record) {
    refs.push(...record.counterevidence.map((span) => span.evidence_id));
  }
  refs.push(...record.derivation.evidence_refs);
  return uniqueSorted(refs);
}

function assertCorpus(corpus: ReadonlyMemoryCorpus): void {
  const evidenceIds = new Set<string>();
  for (const evidence of corpus.evidence_items) {
    const wire = validateWireValue("evidence_item", evidence);
    if (!wire.valid) {
      throw new TypeError(`Readonly corpus contains invalid Evidence: ${evidence.evidence_id}`);
    }
    if (evidenceIds.has(evidence.evidence_id)) {
      throw new TypeError(`Readonly corpus duplicates Evidence: ${evidence.evidence_id}`);
    }
    evidenceIds.add(evidence.evidence_id);
  }
  const ids = new Set<string>();
  for (const record of allRecords(corpus)) {
    const id = recordId(record);
    const wire = validateWireValue(recordSchema(record), record);
    if (!wire.valid) throw new TypeError(`Readonly corpus contains an invalid record: ${id}`);
    if (
      record.memory_space_id !== corpus.memory_space_id ||
      record.branch_id !== corpus.branch_id
    ) {
      throw new TypeError(`Readonly corpus record belongs to another scope: ${id}`);
    }
    if (ids.has(id)) throw new TypeError(`Readonly corpus duplicates a record: ${id}`);
    ids.add(id);
    for (const evidenceId of evidenceRefs(record)) {
      if (!evidenceIds.has(evidenceId)) {
        throw new TypeError(`Readonly corpus record references absent Evidence: ${id}`);
      }
    }
  }
}

export function getReadonlyMemoryCorpusToolNames(
  corpus: ReadonlyMemoryCorpus,
  ports: ReadonlyMemoryCorpusPorts,
): readonly InvestigationToolName[] {
  assertCorpus(corpus);
  const names: InvestigationToolName[] = [
    "follow_causal_links",
    "get_state_as_of",
    "get_epistemic_state",
    "read_evidence_spans",
    "find_contradictions",
  ];
  if (corpus.episodes.length > 0) names.push("get_episode_context");
  if (corpus.narrative_threads.length > 0) names.push("inspect_thread");
  if (corpus.future_impacts.length > 0 && ports.evaluate_trigger !== undefined) {
    names.push("evaluate_trigger");
  }
  return names.sort();
}

function causalRefKey(reference: CausalCauseRef | CausalEffectRef): string {
  if (reference.kind === "condition") {
    throw new InvestigationToolExecutionError("INVESTIGATION_FREEFORM_CAUSE_FORBIDDEN");
  }
  if (reference.kind === "event") return `event:${reference.event_id}`;
  if (reference.kind === "state_assertion") return `state_assertion:${reference.assertion_id}`;
  if (reference.kind === "state_delta") return `state_delta:${reference.delta_id}`;
  if (reference.kind === "epistemic_state") return `epistemic_state:${reference.epistemic_id}`;
  if (reference.kind === "proposition") return `proposition:${reference.proposition_id}`;
  return `narrative_thread:${reference.thread_id}`;
}

function causalRefId(reference: CausalCauseRef | CausalEffectRef): NarraMemId | undefined {
  if (reference.kind === "condition") return undefined;
  if (reference.kind === "event") return reference.event_id;
  if (reference.kind === "state_assertion") return reference.assertion_id;
  if (reference.kind === "state_delta") return reference.delta_id;
  if (reference.kind === "epistemic_state") return reference.epistemic_id;
  if (reference.kind === "proposition") return reference.proposition_id;
  return reference.thread_id;
}

function sameSubject(left: StateSubjectRef, right: StateSubjectRef): boolean {
  return (
    canonicalInvestigationJson(asJsonValue(left)) === canonicalInvestigationJson(asJsonValue(right))
  );
}

function sameHolder(left: EpistemicPrincipalRef, right: EpistemicPrincipalRef): boolean {
  return (
    canonicalInvestigationJson(asJsonValue(left)) === canonicalInvestigationJson(asJsonValue(right))
  );
}

function boundedRecords(
  records: readonly CorpusRecord[],
  maximum: number,
): { readonly records: readonly CorpusRecord[]; readonly truncated: boolean } {
  const sorted = [...new Map(records.map((record) => [recordId(record), record])).values()].sort(
    (left, right) => recordId(left).localeCompare(recordId(right)),
  );
  return { records: sorted.slice(0, maximum), truncated: sorted.length > maximum };
}

function executionFromRecords(
  result: unknown,
  records: readonly CorpusRecord[],
  additionalEvidence: readonly NarraMemId<"evidence">[] = [],
) {
  return {
    result: asJsonValue(result),
    returned_record_refs: uniqueSorted(records.map(recordId)),
    returned_evidence_refs: uniqueSorted([...records.flatMap(evidenceRefs), ...additionalEvidence]),
  };
}

function resolveJsonPointer(root: JsonValue, pointer: string): JsonValue {
  if (pointer === "") return root;
  if (!pointer.startsWith("/")) {
    throw new InvestigationToolExecutionError("INVESTIGATION_JSON_POINTER_INVALID");
  }
  let current: JsonValue = root;
  for (const rawToken of pointer.slice(1).split("/")) {
    const token = rawToken.replaceAll("~1", "/").replaceAll("~0", "~");
    if (Array.isArray(current)) {
      if (!/^(0|[1-9][0-9]*)$/u.test(token)) {
        throw new InvestigationToolExecutionError("INVESTIGATION_JSON_POINTER_INVALID");
      }
      const nested = current[Number(token)];
      if (nested === undefined) {
        throw new InvestigationToolExecutionError("INVESTIGATION_JSON_POINTER_NOT_FOUND");
      }
      current = nested;
    } else if (current !== null && typeof current === "object") {
      const nested = (current as Readonly<Record<string, JsonValue>>)[token];
      if (nested === undefined) {
        throw new InvestigationToolExecutionError("INVESTIGATION_JSON_POINTER_NOT_FOUND");
      }
      current = nested;
    } else {
      throw new InvestigationToolExecutionError("INVESTIGATION_JSON_POINTER_NOT_FOUND");
    }
  }
  return current;
}

async function readSpan(
  span: EvidenceSpan,
  evidence: EvidenceItem,
  hashText: (text: string) => Promise<HashDigest>,
): Promise<JsonValue> {
  let selected: JsonValue;
  if (span.selector.kind === "text_range") {
    if (evidence.raw_content.kind !== "text") {
      throw new InvestigationToolExecutionError("INVESTIGATION_EVIDENCE_SELECTOR_KIND_MISMATCH");
    }
    const points = [...evidence.raw_content.text];
    if (
      span.selector.start_code_point < 0 ||
      span.selector.end_code_point <= span.selector.start_code_point ||
      span.selector.end_code_point > points.length
    ) {
      throw new InvestigationToolExecutionError("INVESTIGATION_EVIDENCE_RANGE_INVALID");
    }
    selected = points.slice(span.selector.start_code_point, span.selector.end_code_point).join("");
  } else {
    if (evidence.raw_content.kind !== "structured") {
      throw new InvestigationToolExecutionError("INVESTIGATION_EVIDENCE_SELECTOR_KIND_MISMATCH");
    }
    if (span.selector.kind === "json_pointer") {
      selected = resolveJsonPointer(evidence.raw_content.value, span.selector.pointer);
    } else {
      if (
        evidence.raw_content.value === null ||
        typeof evidence.raw_content.value !== "object" ||
        Array.isArray(evidence.raw_content.value)
      ) {
        throw new InvestigationToolExecutionError("INVESTIGATION_FIELD_SET_INVALID");
      }
      const source = evidence.raw_content.value as Readonly<Record<string, JsonValue>>;
      const fields = uniqueSorted(span.selector.fields);
      const selectedObject: Record<string, JsonValue> = {};
      for (const field of fields) {
        const value = source[field];
        if (value === undefined) {
          throw new InvestigationToolExecutionError("INVESTIGATION_FIELD_SET_NOT_FOUND");
        }
        selectedObject[field] = value;
      }
      selected = selectedObject;
    }
  }
  const serialized = typeof selected === "string" ? selected : canonicalInvestigationJson(selected);
  const digest = await hashText(serialized);
  if (digest.algorithm !== span.quote_hash.algorithm || digest.value !== span.quote_hash.value) {
    throw new InvestigationToolExecutionError("INVESTIGATION_EVIDENCE_SPAN_HASH_MISMATCH");
  }
  return selected;
}

export function createReadonlyMemoryCorpusRuntimePorts(
  corpus: ReadonlyMemoryCorpus,
  corpusPorts: ReadonlyMemoryCorpusPorts,
): InvestigationRuntimePorts {
  assertCorpus(corpus);
  const records = allRecords(corpus);
  const recordsById = new Map(records.map((record) => [recordId(record), record]));
  const evidenceById = new Map(
    corpus.evidence_items.map((evidence) => [evidence.evidence_id, evidence]),
  );
  const available = new Set(getReadonlyMemoryCorpusToolNames(corpus, corpusPorts));

  return {
    hash_text: corpusPorts.hash_text,
    execute_readonly_tool: async (action, context) => {
      if (!available.has(action.tool)) {
        throw new InvestigationToolExecutionError("INVESTIGATION_TOOL_UNAVAILABLE");
      }
      if (context.signal?.aborted) {
        throw new InvestigationToolExecutionError("INVESTIGATION_CANCELLED");
      }
      const maxRecords = context.limits.max_record_refs_per_result;
      switch (action.tool) {
        case "get_episode_context": {
          const episode = corpus.episodes.find((item) => item.episode_id === action.episode_id);
          if (episode === undefined) {
            throw new InvestigationToolExecutionError("INVESTIGATION_EPISODE_NOT_FOUND");
          }
          const relatedIds = new Set<NarraMemId>([
            episode.episode_id,
            ...episode.scene_ids,
            ...episode.event_ids,
            ...episode.context.before_state_refs,
            ...(episode.context.goal_state_refs ?? []),
            ...episode.outcome_refs,
            ...episode.causal_refs,
            ...episode.narrative_thread_refs,
          ]);
          const bounded = boundedRecords(
            [...relatedIds].flatMap((id) => {
              const record = recordsById.get(id);
              return record === undefined ? [] : [record];
            }),
            maxRecords,
          );
          return executionFromRecords(
            { records: bounded.records, truncated: bounded.truncated },
            bounded.records,
          );
        }
        case "follow_causal_links": {
          const startKey = causalRefKey(action.from);
          let frontier = new Set([startKey]);
          const selectedLinks: CausalLink[] = [];
          const selectedLinkIds = new Set<string>();
          const selectedEndpointIds = new Set<NarraMemId>();
          let truncated = false;
          for (let depth = 0; depth < action.max_depth && frontier.size > 0; depth += 1) {
            const next = new Set<string>();
            for (const link of [...corpus.causal_links].sort((left, right) =>
              left.causal_id.localeCompare(right.causal_id),
            )) {
              if (selectedLinkIds.has(link.causal_id)) continue;
              const inputs = action.direction === "successors" ? link.cause_refs : link.effect_refs;
              if (!inputs.some((reference) => frontier.has(causalRefKey(reference)))) continue;
              const outputs =
                action.direction === "successors" ? link.effect_refs : link.cause_refs;
              if (selectedLinks.length + selectedEndpointIds.size >= maxRecords) {
                truncated = true;
                break;
              }
              selectedLinks.push(link);
              selectedLinkIds.add(link.causal_id);
              for (const reference of outputs) {
                if (reference.kind === "condition") continue;
                next.add(causalRefKey(reference));
                const id = causalRefId(reference);
                if (id !== undefined && recordsById.has(id)) selectedEndpointIds.add(id);
              }
            }
            if (truncated) break;
            frontier = next;
          }
          const bounded = boundedRecords(
            [
              ...selectedLinks,
              ...[...selectedEndpointIds].flatMap((id) => {
                const record = recordsById.get(id);
                return record === undefined ? [] : [record];
              }),
            ],
            maxRecords,
          );
          return executionFromRecords(
            {
              direction: action.direction,
              requested_max_depth: action.max_depth,
              records: bounded.records,
              truncated: truncated || bounded.truncated,
            },
            bounded.records,
          );
        }
        case "get_state_as_of": {
          const matching = [
            ...corpus.state_assertions.filter(
              (record) =>
                sameSubject(record.subject, action.subject) &&
                action.state_keys.includes(record.state_key),
            ),
            ...corpus.state_deltas.filter(
              (record) =>
                sameSubject(record.subject, action.subject) &&
                action.state_keys.includes(record.state_key),
            ),
          ];
          const bounded = boundedRecords(matching, maxRecords);
          return executionFromRecords(
            {
              as_of_revision_id: corpus.snapshot_revision_id,
              records: bounded.records,
              truncated: bounded.truncated,
            },
            bounded.records,
          );
        }
        case "get_epistemic_state": {
          const propositionFilter =
            action.proposition_ids === undefined ? undefined : new Set(action.proposition_ids);
          const states = corpus.epistemic_states.filter(
            (record) =>
              sameHolder(record.holder, action.holder) &&
              (propositionFilter === undefined || propositionFilter.has(record.proposition_id)),
          );
          const propositionIds = new Set(states.map((state) => state.proposition_id));
          const matching = [
            ...states,
            ...corpus.propositions.filter((record) => propositionIds.has(record.proposition_id)),
          ];
          const bounded = boundedRecords(matching, maxRecords);
          return executionFromRecords(
            { records: bounded.records, truncated: bounded.truncated },
            bounded.records,
          );
        }
        case "inspect_thread": {
          const thread = corpus.narrative_threads.find(
            (item) => item.thread_id === action.thread_id,
          );
          if (thread === undefined) {
            throw new InvestigationToolExecutionError("INVESTIGATION_THREAD_NOT_FOUND");
          }
          const relatedIds = new Set<NarraMemId>([
            thread.thread_id,
            ...thread.opened_by,
            ...thread.development_refs,
            ...(thread.resolution_refs ?? []),
          ]);
          const bounded = boundedRecords(
            [...relatedIds].flatMap((id) => {
              const record = recordsById.get(id);
              return record === undefined ? [] : [record];
            }),
            maxRecords,
          );
          return executionFromRecords(
            { records: bounded.records, truncated: bounded.truncated },
            bounded.records,
          );
        }
        case "evaluate_trigger": {
          const impact = corpus.future_impacts.find((item) => item.impact_id === action.impact_id);
          if (impact === undefined) {
            throw new InvestigationToolExecutionError("INVESTIGATION_IMPACT_NOT_FOUND");
          }
          if (corpusPorts.evaluate_trigger === undefined) {
            throw new InvestigationToolExecutionError("INVESTIGATION_TOOL_UNAVAILABLE");
          }
          const evaluation = await corpusPorts.evaluate_trigger(impact, context.signal);
          const wire = validateWireValue("trigger_evaluation", evaluation);
          if (
            !wire.valid ||
            evaluation.impact_id !== impact.impact_id ||
            evaluation.evaluated_at_revision_id !== corpus.snapshot_revision_id ||
            evaluation.persistent_state_unchanged !== true
          ) {
            throw new InvestigationToolExecutionError("INVESTIGATION_TRIGGER_RESULT_INVALID");
          }
          return executionFromRecords({ impact, evaluation }, [impact]);
        }
        case "read_evidence_spans": {
          const selected = [];
          for (const span of action.spans) {
            const evidence = evidenceById.get(span.evidence_id);
            if (evidence === undefined) {
              throw new InvestigationToolExecutionError("INVESTIGATION_EVIDENCE_NOT_FOUND");
            }
            selected.push({
              span,
              content: await readSpan(span, evidence, corpusPorts.hash_text),
              source_kind: evidence.source_kind,
              source_order: evidence.source_order,
              authority: evidence.authority,
              reliability_hint: evidence.reliability_hint,
              visibility_hint: evidence.visibility_hint ?? null,
            });
          }
          return {
            result: asJsonValue({ spans: selected }),
            returned_record_refs: [],
            returned_evidence_refs: uniqueSorted(action.spans.map((span) => span.evidence_id)),
          };
        }
        case "find_contradictions": {
          const selectedIds = new Set(action.record_refs);
          for (const id of selectedIds) {
            if (!recordsById.has(id)) {
              throw new InvestigationToolExecutionError("INVESTIGATION_RECORD_NOT_FOUND");
            }
          }
          const counterevidenceRecords = records.filter((record) => {
            if (!selectedIds.has(recordId(record))) return false;
            return "counterevidence" in record && record.counterevidence.length > 0;
          });
          const inspectedRecords = [...selectedIds].map(
            (id) => recordsById.get(id) as CorpusRecord,
          );
          const bounded = boundedRecords(
            [...inspectedRecords, ...counterevidenceRecords],
            maxRecords,
          );
          const boundedIds = new Set(bounded.records.map(recordId));
          const boundedCounterevidence = counterevidenceRecords.filter((record) =>
            boundedIds.has(recordId(record)),
          );
          const notices = (corpus.contradiction_notices ?? []).filter((notice) =>
            notice.record_refs.some((id) => boundedIds.has(id)),
          );
          return executionFromRecords(
            {
              inspected_record_refs: uniqueSorted(
                inspectedRecords.filter((record) => boundedIds.has(recordId(record))).map(recordId),
              ),
              counterevidence_records: boundedCounterevidence,
              notices,
              truncated: bounded.truncated,
            },
            bounded.records,
            notices.flatMap((notice) =>
              notice.record_refs.flatMap((id) => {
                const record = recordsById.get(id);
                return record === undefined ? [] : evidenceRefs(record);
              }),
            ),
          );
        }
      }
    },
  };
}
