import type { CausalAuditAgentTaskSeed, ReadonlyMemoryCorpus } from "@narramem/agent-runtime";
import {
  type AuthorizedChangeSet,
  type CausalAuditCandidateCauseRef,
  type CausalAuditCandidateEffectRef,
  type CausalLink,
  createSha256Digest,
  type ExtractorDescriptor,
  getNarraMemIdKind,
  type NarraMemId,
  type NarraMemIdKind,
  type NarrativeThread,
  type ValidationReport,
} from "@narramem/core-domain";
import {
  type CausalAuditCandidateValidationContext,
  validateCausalAuditCandidateBatch,
  validateChangeSetProposal,
  validateWireValue,
} from "@narramem/core-validator";
import {
  CAUSAL_AUDIT_COMPILER_VERSION,
  CausalAuditCompilationError,
  compileCausalAuditCandidateBatch,
} from "@narramem/narrative-compiler";
import type { TavernCausalAuditTaskSeed } from "./causal-audit-task-mapping.js";
import { createDeterministicNarraMemId } from "./core-source-projection.js";
import { canonicalJson, sha256HexUtf8 } from "./worldbook-codec.js";
import type { TavernArchiveRecord } from "./worldbook-store-contracts.js";

export const TAVERN_CAUSAL_AUDIT_CANDIDATE_TASK_VERSION = "0.1.0" as const;
export const TAVERN_CAUSAL_AUDIT_COMMITTER_VERSION = "tavern-causal-audit-committer@0.1.0" as const;
export const TAVERN_CAUSAL_AUDIT_POSITIVE_READINESS_VERSION = "0.1.0" as const;
const MAX_SELECTED_RECORDS = 256;
const MAX_SELECTED_EVIDENCE = 256;

type CandidateRecord =
  | ReadonlyMemoryCorpus["events"][number]
  | ReadonlyMemoryCorpus["state_assertions"][number]
  | ReadonlyMemoryCorpus["state_deltas"][number]
  | ReadonlyMemoryCorpus["propositions"][number]
  | ReadonlyMemoryCorpus["epistemic_states"][number]
  | NarrativeThread;

export interface TavernCausalAuditCandidateSelection {
  readonly reviewed_record_refs: readonly NarraMemId[];
  readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
}

export interface TavernCausalAuditCandidateTask {
  readonly task_version: typeof TAVERN_CAUSAL_AUDIT_CANDIDATE_TASK_VERSION;
  readonly task_id: NarraMemId<"investigation">;
  readonly seed: TavernCausalAuditTaskSeed;
  readonly corpus: ReadonlyMemoryCorpus;
  readonly evidence_items: ReadonlyMemoryCorpus["evidence_items"];
  readonly allowed_cause_refs: readonly CausalAuditCandidateCauseRef[];
  readonly allowed_effect_refs: readonly CausalAuditCandidateEffectRef[];
  readonly allowed_holder_entity_ids: readonly NarraMemId<"entity">[];
  readonly record_evidence_refs: readonly {
    readonly record_id: NarraMemId;
    readonly evidence_ids: readonly NarraMemId<"evidence">[];
  }[];
  readonly known_record_ids: readonly NarraMemId[];
  readonly validation_context: CausalAuditCandidateValidationContext;
}

export interface TavernCausalAuditAuthorizationOptions {
  readonly extractor: ExtractorDescriptor;
  readonly compilation_key: string;
  readonly authorized_at: string;
}

export interface TavernCausalAuditIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export type TavernCausalAuditAuthorizationResult =
  | {
      readonly status: "authorized";
      readonly candidate_artifact_sha256: string;
      readonly proposal: Awaited<ReturnType<typeof compileCausalAuditCandidateBatch>>["proposal"];
      readonly validation_report: ValidationReport & { readonly accepted: true };
      readonly authorized_changeset: AuthorizedChangeSet;
      readonly causal_links: readonly CausalLink[];
      readonly issues: readonly [];
    }
  | {
      readonly status: "rejected";
      readonly validation_report?: ValidationReport;
      readonly issues: readonly TavernCausalAuditIssue[];
    };

export interface TavernCausalAuditPositiveReadiness {
  readonly readiness_version: typeof TAVERN_CAUSAL_AUDIT_POSITIVE_READINESS_VERSION;
  readonly status: "STRUCTURALLY_READY" | "BLOCKED";
  readonly readiness_fingerprint: string;
  readonly finding_quote_option_count: number;
  readonly initial_cause_event_option_count: number;
  readonly initial_effect_event_option_count: number;
  readonly finding_anchor_effect_event_count: number;
  readonly prior_distinct_evidence_event_pair_count: number;
  readonly uncovered_prior_distinct_evidence_event_pair_count: number;
  readonly existing_pair_causal_link_count: number;
  readonly blocker_codes: readonly string[];
  readonly raw_story_text_recorded: false;
}

function issue(code: string, path: string, message: string): TavernCausalAuditIssue {
  return { code, path, message };
}

function recordId(record: CandidateRecord): NarraMemId {
  if ("event_id" in record) return record.event_id;
  if ("assertion_id" in record) return record.assertion_id;
  if ("delta_id" in record) return record.delta_id;
  if ("epistemic_id" in record) return record.epistemic_id;
  if ("proposition_id" in record) return record.proposition_id;
  return record.thread_id;
}

function candidateRecords(corpus: ReadonlyMemoryCorpus): readonly CandidateRecord[] {
  return [
    ...corpus.events,
    ...corpus.state_assertions,
    ...corpus.state_deltas,
    ...corpus.propositions,
    ...corpus.epistemic_states,
    ...corpus.narrative_threads,
  ];
}

function evidenceRefs(record: CandidateRecord): readonly NarraMemId<"evidence">[] {
  const refs = [...record.derivation.evidence_refs];
  if ("evidence" in record) refs.push(...record.evidence.map((span) => span.evidence_id));
  if ("support" in record) refs.push(...record.support.map((span) => span.evidence_id));
  if ("counterevidence" in record) {
    refs.push(...record.counterevidence.map((span) => span.evidence_id));
  }
  return [...new Set(refs)].sort();
}

function causeRef(record: CandidateRecord): CausalAuditCandidateCauseRef {
  if ("event_id" in record) return { kind: "event", event_id: record.event_id };
  if ("assertion_id" in record) {
    return { kind: "state_assertion", assertion_id: record.assertion_id };
  }
  if ("delta_id" in record) return { kind: "state_delta", delta_id: record.delta_id };
  if ("epistemic_id" in record) {
    return { kind: "epistemic_state", epistemic_id: record.epistemic_id };
  }
  if ("proposition_id" in record) {
    return { kind: "proposition", proposition_id: record.proposition_id };
  }
  return { kind: "narrative_thread", thread_id: record.thread_id };
}

function effectRef(record: CandidateRecord): CausalAuditCandidateEffectRef | undefined {
  if ("event_id" in record) return { kind: "event", event_id: record.event_id };
  if ("delta_id" in record) return { kind: "state_delta", delta_id: record.delta_id };
  if ("epistemic_id" in record) {
    return { kind: "epistemic_state", epistemic_id: record.epistemic_id };
  }
  if ("thread_id" in record) {
    return { kind: "narrative_thread", thread_id: record.thread_id };
  }
  return undefined;
}

function holderIds(record: CandidateRecord): readonly NarraMemId<"entity">[] {
  if ("event_id" in record) return [...record.actor_ids, ...(record.patient_ids ?? [])];
  if ("subject" in record) {
    return record.subject.kind === "entity"
      ? [record.subject.entity_id]
      : record.subject.kind === "relation"
        ? record.subject.participant_ids
        : [];
  }
  if ("epistemic_id" in record) {
    return record.holder.kind === "entity" ? [record.holder.entity_id] : [];
  }
  if ("claim" in record) {
    return record.claim.arguments.flatMap((argument) =>
      argument.kind === "entity" ? [argument.entity_id] : [],
    );
  }
  return [];
}

function endpointKey(reference: CausalAuditCandidateCauseRef | CausalAuditCandidateEffectRef) {
  if (reference.kind === "event") return `event:${reference.event_id}`;
  if (reference.kind === "state_assertion") return `state_assertion:${reference.assertion_id}`;
  if (reference.kind === "state_delta") return `state_delta:${reference.delta_id}`;
  if (reference.kind === "epistemic_state") return `epistemic_state:${reference.epistemic_id}`;
  if (reference.kind === "proposition") return `proposition:${reference.proposition_id}`;
  return `narrative_thread:${reference.thread_id}`;
}

function eventStrictlyPrecedes(
  cause: ReadonlyMemoryCorpus["events"][number],
  effect: ReadonlyMemoryCorpus["events"][number],
): boolean {
  const causeStart = cause.source_range.start;
  const effectStart = effect.source_range.start;
  if (causeStart.ordinal !== effectStart.ordinal) return causeStart.ordinal < effectStart.ordinal;
  if (causeStart.component !== effectStart.component) {
    return causeStart.component < effectStart.component;
  }
  const causeSequence = cause.story_time.sequence_index;
  const effectSequence = effect.story_time.sequence_index;
  return (
    causeSequence !== undefined && effectSequence !== undefined && causeSequence < effectSequence
  );
}

function existingEventPair(
  corpus: ReadonlyMemoryCorpus,
  causeEventId: NarraMemId<"event">,
  effectEventId: NarraMemId<"event">,
): boolean {
  return corpus.causal_links.some(
    (link) =>
      link.cause_refs.some(
        (reference) => reference.kind === "event" && reference.event_id === causeEventId,
      ) &&
      link.effect_refs.some(
        (reference) => reference.kind === "event" && reference.event_id === effectEventId,
      ),
  );
}

/**
 * Content-free diagnostic witness for binding a real-host positive Candidate test.
 * It proves only that the trusted initial window contains a cue-covering quote and
 * at least one earlier, separately evidenced Event -> Event option pair. It does
 * not authorize a causal claim or replace the model/validator decision.
 */
export async function evaluateTavernCausalAuditPositiveReadiness(
  task: TavernCausalAuditCandidateTask,
): Promise<TavernCausalAuditPositiveReadiness> {
  const findingEvidence = task.evidence_items.find(
    (evidence) => evidence.evidence_id === task.seed.finding.evidence_id,
  );
  const findingText =
    findingEvidence?.raw_content.kind === "text" ? findingEvidence.raw_content.text : null;
  const findingQuoteAvailable =
    findingText !== null &&
    [...findingText]
      .slice(task.seed.finding.start_code_point, task.seed.finding.end_code_point)
      .join("") === task.seed.finding.cue;
  const eventsById = new Map(task.corpus.events.map((event) => [event.event_id, event]));
  const allowedCauseIds = task.allowed_cause_refs.flatMap((reference) =>
    reference.kind === "event" ? [reference.event_id] : [],
  );
  const allowedEffectIds = task.allowed_effect_refs.flatMap((reference) =>
    reference.kind === "event" ? [reference.event_id] : [],
  );
  const findingAnchorEffects = allowedEffectIds.flatMap((eventId) => {
    const event = eventsById.get(eventId);
    return event !== undefined && evidenceRefs(event).includes(task.seed.finding.evidence_id)
      ? [event]
      : [];
  });
  const availableEvidence = new Set(task.evidence_items.map((evidence) => evidence.evidence_id));
  const pairs = allowedCauseIds.flatMap((causeEventId) => {
    const cause = eventsById.get(causeEventId);
    if (cause === undefined) return [];
    const causeEvidenceIds = evidenceRefs(cause).filter(
      (evidenceId) =>
        evidenceId !== task.seed.finding.evidence_id && availableEvidence.has(evidenceId),
    );
    if (causeEvidenceIds.length === 0) return [];
    return findingAnchorEffects.flatMap((effect) =>
      cause.event_id !== effect.event_id && eventStrictlyPrecedes(cause, effect)
        ? [
            {
              cause_event_id: cause.event_id,
              effect_event_id: effect.event_id,
              cause_evidence_fingerprints: task.evidence_items
                .filter((evidence) => causeEvidenceIds.includes(evidence.evidence_id))
                .map((evidence) => evidence.content_fingerprint.value)
                .sort(),
              finding_evidence_fingerprint: findingEvidence?.content_fingerprint.value ?? null,
              existing_link: existingEventPair(task.corpus, cause.event_id, effect.event_id),
            },
          ]
        : [],
    );
  });
  const uncoveredPairs = pairs.filter((pair) => !pair.existing_link);
  const blockerCodes = [
    ...(findingQuoteAvailable ? [] : ["FINDING_QUOTE_OPTION_ABSENT"]),
    ...(allowedCauseIds.length > 0 ? [] : ["INITIAL_CAUSE_EVENT_OPTION_ABSENT"]),
    ...(allowedEffectIds.length > 0 ? [] : ["INITIAL_EFFECT_EVENT_OPTION_ABSENT"]),
    ...(findingAnchorEffects.length > 0 ? [] : ["FINDING_ANCHOR_EFFECT_EVENT_ABSENT"]),
    ...(pairs.length > 0 ? [] : ["PRIOR_DISTINCT_EVIDENCE_EVENT_PAIR_ABSENT"]),
    ...(pairs.length === 0 || uncoveredPairs.length > 0
      ? []
      : ["ALL_STRUCTURAL_EVENT_PAIRS_ALREADY_LINKED"]),
  ];
  const fingerprint = await sha256HexUtf8(
    canonicalJson({
      readiness_version: TAVERN_CAUSAL_AUDIT_POSITIVE_READINESS_VERSION,
      task_seed_id: task.seed.task_seed_id,
      snapshot_fingerprint: task.corpus.snapshot_fingerprint,
      finding: {
        evidence_id: task.seed.finding.evidence_id,
        cue: task.seed.finding.cue,
        start_code_point: task.seed.finding.start_code_point,
        end_code_point: task.seed.finding.end_code_point,
        finding_evidence_fingerprint: findingEvidence?.content_fingerprint.value ?? null,
      },
      pairs,
      blocker_codes: blockerCodes,
    }),
  );
  return {
    readiness_version: TAVERN_CAUSAL_AUDIT_POSITIVE_READINESS_VERSION,
    status: blockerCodes.length === 0 ? "STRUCTURALLY_READY" : "BLOCKED",
    readiness_fingerprint: fingerprint,
    finding_quote_option_count: findingQuoteAvailable ? 1 : 0,
    initial_cause_event_option_count: allowedCauseIds.length,
    initial_effect_event_option_count: allowedEffectIds.length,
    finding_anchor_effect_event_count: findingAnchorEffects.length,
    prior_distinct_evidence_event_pair_count: pairs.length,
    uncovered_prior_distinct_evidence_event_pair_count: uncoveredPairs.length,
    existing_pair_causal_link_count: pairs.length - uncoveredPairs.length,
    blocker_codes: blockerCodes,
    raw_story_text_recorded: false,
  };
}

function knownRecordIds(records: readonly TavernArchiveRecord[]): NarraMemId[] {
  const ids: NarraMemId[] = [];
  for (const record of records) {
    const kind = getNarraMemIdKind(record.record_id);
    if (kind === undefined) continue;
    if (kind === "entity") {
      const wire = validateWireValue("entity", record.payload);
      if (
        !wire.valid ||
        (record.payload as { readonly entity_id?: unknown }).entity_id !== record.record_id
      ) {
        throw new TypeError(`Tavern archive contains an invalid Entity: ${record.record_id}`);
      }
    }
    ids.push(record.record_id as NarraMemId);
  }
  return [...new Set(ids)].sort();
}

export function createTavernCausalAuditAgentSeed(
  taskId: NarraMemId<"investigation">,
  seed: TavernCausalAuditTaskSeed,
  corpus: ReadonlyMemoryCorpus,
): CausalAuditAgentTaskSeed {
  const records = candidateRecords(corpus);
  const anchors = records.filter((record) =>
    evidenceRefs(record).includes(seed.finding.evidence_id),
  );
  const selected = new Map<NarraMemId, CandidateRecord>(
    anchors.map((record) => [recordId(record), record]),
  );
  const anchorEventIds = new Set(
    anchors.flatMap((record) => ("event_id" in record ? [record.event_id] : [])),
  );
  corpus.events.forEach((event, index) => {
    if (!anchorEventIds.has(event.event_id)) return;
    for (const prior of corpus.events.slice(Math.max(0, index - 4), index)) {
      selected.set(prior.event_id, prior);
    }
  });
  const selectedRecords = [...selected.values()]
    .sort((left, right) => recordId(left).localeCompare(recordId(right)))
    .slice(0, 32);
  const selectedEvidenceIds = new Set<NarraMemId<"evidence">>([
    seed.finding.evidence_id,
    ...selectedRecords.flatMap(evidenceRefs),
  ]);
  const selectedEvidence = corpus.evidence_items
    .filter((evidence) => selectedEvidenceIds.has(evidence.evidence_id))
    .slice(0, 64);
  if (!selectedEvidence.some((evidence) => evidence.evidence_id === seed.finding.evidence_id)) {
    throw new TypeError("Tavern Agent finding Evidence is absent from the active archive");
  }
  return {
    task_id: taskId,
    source_revision_id: corpus.snapshot_revision_id,
    finding: {
      code: seed.finding.code,
      evidence_id: seed.finding.evidence_id,
      cue: seed.finding.cue,
      start_code_point: seed.finding.start_code_point,
      end_code_point: seed.finding.end_code_point,
    },
    seed_context: JSON.parse(
      canonicalJson({ records: selectedRecords, evidence: selectedEvidence }),
    ),
    seed_record_refs: selectedRecords.map(recordId),
    seed_evidence_refs: selectedEvidence.map((evidence) => evidence.evidence_id),
  };
}

export function createTavernCausalAuditCandidateTask(
  taskId: NarraMemId<"investigation">,
  seed: TavernCausalAuditTaskSeed,
  corpus: ReadonlyMemoryCorpus,
  archiveRecords: readonly TavernArchiveRecord[],
  selection: TavernCausalAuditCandidateSelection,
): TavernCausalAuditCandidateTask {
  if (
    selection.reviewed_record_refs.length > MAX_SELECTED_RECORDS ||
    selection.reviewed_evidence_refs.length > MAX_SELECTED_EVIDENCE
  ) {
    throw new TypeError("Tavern Causal Audit reviewed selection exceeds its fixed window");
  }
  if (corpus.snapshot_revision_id !== seed.source_revision_id) {
    throw new TypeError("Tavern Causal Audit Candidate task is stale");
  }
  const records = candidateRecords(corpus);
  const recordsById = new Map(records.map((record) => [recordId(record), record]));
  const selectedIds = new Set<NarraMemId>(selection.reviewed_record_refs);
  for (const record of records) {
    if (evidenceRefs(record).includes(seed.finding.evidence_id)) selectedIds.add(recordId(record));
  }
  const selectedRecords = [...selectedIds]
    .map((id) => recordsById.get(id))
    .filter((record): record is CandidateRecord => record !== undefined)
    .sort((left, right) => recordId(left).localeCompare(recordId(right)));
  if (selectedRecords.length !== selectedIds.size) {
    throw new TypeError("Tavern Causal Audit selection references an inactive Candidate record");
  }
  const selectedEvidenceIds = new Set<NarraMemId<"evidence">>([
    seed.finding.evidence_id,
    ...selection.reviewed_evidence_refs,
    ...selectedRecords.flatMap(evidenceRefs),
  ]);
  const evidenceItems = corpus.evidence_items.filter((evidence) =>
    selectedEvidenceIds.has(evidence.evidence_id),
  );
  if (evidenceItems.length !== selectedEvidenceIds.size) {
    throw new TypeError("Tavern Causal Audit selection references inactive Evidence");
  }
  const knownIds = knownRecordIds(archiveRecords);
  const knownEntities = new Set(
    knownIds.filter((id): id is NarraMemId<"entity"> => getNarraMemIdKind(id) === "entity"),
  );
  const holders = [...new Set(selectedRecords.flatMap(holderIds))]
    .filter((id) => knownEntities.has(id))
    .sort();
  const causes = selectedRecords
    .map(causeRef)
    .sort((left, right) => endpointKey(left).localeCompare(endpointKey(right)));
  const effects = selectedRecords
    .flatMap((record) => {
      const reference = effectRef(record);
      return reference === undefined ? [] : [reference];
    })
    .sort((left, right) => endpointKey(left).localeCompare(endpointKey(right)));
  const recordEvidenceRefs = selectedRecords.map((record) => ({
    record_id: recordId(record),
    evidence_ids: evidenceRefs(record),
  }));
  const validationContext: CausalAuditCandidateValidationContext = {
    task_id: taskId,
    active_revision_id: corpus.snapshot_revision_id,
    finding: {
      evidence_id: seed.finding.evidence_id,
      cue: seed.finding.cue,
      start_code_point: seed.finding.start_code_point,
      end_code_point: seed.finding.end_code_point,
    },
    evidence_items: evidenceItems,
    allowed_cause_refs: causes,
    allowed_effect_refs: effects,
    allowed_holder_entity_ids: holders,
    record_evidence_refs: recordEvidenceRefs,
  };
  return {
    task_version: TAVERN_CAUSAL_AUDIT_CANDIDATE_TASK_VERSION,
    task_id: taskId,
    seed,
    corpus,
    evidence_items: evidenceItems,
    allowed_cause_refs: causes,
    allowed_effect_refs: effects,
    allowed_holder_entity_ids: holders,
    record_evidence_refs: recordEvidenceRefs,
    known_record_ids: knownIds,
    validation_context: validationContext,
  };
}

async function deterministicPorts(
  candidate: ReturnType<typeof validateCausalAuditCandidateBatch> & { readonly accepted: true },
  task: TavernCausalAuditCandidateTask,
  options: TavernCausalAuditAuthorizationOptions,
) {
  const allocations = new Map<string, NarraMemId>();
  const add = async <Kind extends NarraMemIdKind>(kind: Kind, key: string) => {
    allocations.set(key, await createDeterministicNarraMemId(kind, key));
  };
  for (const link of candidate.candidate.causal_links) {
    const stableKey = `${task.corpus.snapshot_revision_id}:${options.compilation_key}:causal:${link.candidate_key}`;
    await add("causal_link", stableKey);
    await add("derivation", `${stableKey}:derivation`);
  }
  await add(
    "change_set",
    `${task.corpus.snapshot_revision_id}:${options.compilation_key}:causal-audit-change-set`,
  );
  return {
    allocate_id: <Kind extends NarraMemIdKind>(kind: Kind, stableKey: string) => {
      const value = allocations.get(stableKey);
      if (value === undefined || getNarraMemIdKind(value) !== kind) {
        throw new TypeError(`Unregistered deterministic Tavern ${kind} allocation`);
      }
      return value as NarraMemId<Kind>;
    },
    hash_text: async (text: string) => createSha256Digest(await sha256HexUtf8(text)),
    now: () => options.authorized_at,
  };
}

export async function authorizeTavernCausalAuditCandidate(
  task: TavernCausalAuditCandidateTask,
  candidateValue: unknown,
  options: TavernCausalAuditAuthorizationOptions,
): Promise<TavernCausalAuditAuthorizationResult> {
  const semantic = validateCausalAuditCandidateBatch(candidateValue, task.validation_context);
  if (!semantic.accepted) {
    return {
      status: "rejected",
      issues: semantic.issues.map((item) => issue(`TAVERN_${item.code}`, item.path, item.message)),
    };
  }
  let compiled: Awaited<ReturnType<typeof compileCausalAuditCandidateBatch>>;
  try {
    compiled = await compileCausalAuditCandidateBatch(
      semantic.candidate,
      {
        ...task.validation_context,
        memory_space_id: task.corpus.memory_space_id,
        branch_id: task.corpus.branch_id,
        compilation_key: options.compilation_key,
        extractor: options.extractor,
      },
      await deterministicPorts(semantic, task, options),
    );
  } catch (error) {
    return {
      status: "rejected",
      issues:
        error instanceof CausalAuditCompilationError
          ? error.codes.map((code) => issue(`TAVERN_${code}`, "/", error.message))
          : [
              issue(
                "TAVERN_CAUSAL_AUDIT_COMPILATION_FAILED",
                "/",
                error instanceof Error ? error.message : "Unknown Tavern compilation failure",
              ),
            ],
    };
  }
  const report = validateChangeSetProposal(compiled.proposal, {
    memory_space_id: task.corpus.memory_space_id,
    branch_id: task.corpus.branch_id,
    active_revision_id: task.corpus.snapshot_revision_id,
    known_evidence_ids: task.corpus.evidence_items.map((evidence) => evidence.evidence_id),
    known_records: task.known_record_ids.map((recordIdValue) => ({
      record_id: recordIdValue,
      memory_space_id: task.corpus.memory_space_id,
      branch_id: task.corpus.branch_id,
    })),
  });
  if (!report.accepted) {
    return {
      status: "rejected",
      validation_report: report,
      issues: report.issues.map((item) =>
        issue(
          `TAVERN_CAUSAL_AUDIT_CORE_${item.code}`,
          item.operation_index === undefined ? "/" : `/operations/${item.operation_index}`,
          item.message,
        ),
      ),
    };
  }
  const acceptedReport = { ...report, accepted: true as const };
  const policyHash = createSha256Digest(
    await sha256HexUtf8(
      canonicalJson({
        committer_version: TAVERN_CAUSAL_AUDIT_COMMITTER_VERSION,
        compiler_version: CAUSAL_AUDIT_COMPILER_VERSION,
        task_seed_id: task.seed.task_seed_id,
        source_checksum: task.seed.source_checksum,
        allowed_operations: ["add_derived:causal_link"],
      }),
    ),
  );
  const authorized: AuthorizedChangeSet = {
    stage: "authorized",
    changeset_id: compiled.proposal.changeset_id,
    memory_space_id: compiled.proposal.memory_space_id,
    branch_id: compiled.proposal.branch_id,
    based_on_revision_id: compiled.proposal.based_on_revision_id,
    producer: "agent",
    operations: compiled.proposal.operations,
    validation_report: acceptedReport,
    authorization: {
      committer_version: TAVERN_CAUSAL_AUDIT_COMMITTER_VERSION,
      policy_hash: policyHash,
      authorized_at: options.authorized_at,
    },
  };
  const wire = validateWireValue("authorized_change_set", authorized);
  if (!wire.valid) {
    return {
      status: "rejected",
      validation_report: acceptedReport,
      issues: wire.errors.map((item) =>
        issue(
          "TAVERN_CAUSAL_AUDIT_AUTHORIZED_CHANGESET_INVALID",
          item.instancePath || "/",
          item.message ?? "invalid",
        ),
      ),
    };
  }
  return {
    status: "authorized",
    candidate_artifact_sha256: compiled.candidate_artifact_sha256.value,
    proposal: compiled.proposal,
    validation_report: acceptedReport,
    authorized_changeset: authorized,
    causal_links: compiled.causal_links,
    issues: [],
  };
}
