import type {
  CausalAuditFinalDecision,
  CausalAuditFinalDecisionV030,
  CausalAuditFinalHandoff,
  InvestigationStopReason,
  NarraMemId,
} from "@narramem/core-domain";

import type { CausalAuditCandidateValidationContext } from "./validate-causal-audit-candidate.js";
import { validateCausalAuditFinalDecision } from "./validate-causal-audit-final-decision.js";
import { validateWireValue } from "./wire-schema-registry.js";

export interface CausalAuditFinalDecisionValidationContextV030 {
  readonly task_id: string;
  readonly active_revision_id: NarraMemId<"source_revision">;
  readonly finding_evidence_id: NarraMemId<"evidence">;
  readonly handoff: CausalAuditFinalHandoff;
  readonly allowed_reviewed_record_refs: readonly NarraMemId[];
  readonly allowed_reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
  readonly candidate_context: CausalAuditCandidateValidationContext;
}

export interface CausalAuditFinalDecisionValidationIssueV030 {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export type CausalAuditFinalDecisionValidationResultV030 =
  | {
      readonly accepted: true;
      readonly decision: CausalAuditFinalDecisionV030;
      readonly issues: readonly [];
    }
  | {
      readonly accepted: false;
      readonly issues: readonly CausalAuditFinalDecisionValidationIssueV030[];
    };

function handoffBindingValid(handoff: CausalAuditFinalHandoff): boolean {
  switch (handoff.kind) {
    case "model_declared_sufficient":
      return handoff.execution_stop_reason === "sufficient_evidence";
    case "model_declared_no_progress":
      return handoff.execution_stop_reason === "no_progress";
    case "investigation_window_complete":
      return (
        handoff.execution_stop_reason === "step_budget_exhausted" ||
        handoff.execution_stop_reason === "tool_budget_exhausted"
      );
    case "runtime_failure":
      return (
        handoff.execution_stop_reason !== "sufficient_evidence" &&
        handoff.execution_stop_reason !== "no_progress"
      );
  }
}

function legacySemanticStopReason(handoff: CausalAuditFinalHandoff): InvestigationStopReason {
  return handoff.kind === "investigation_window_complete"
    ? "sufficient_evidence"
    : handoff.execution_stop_reason;
}

function asV020Decision(decision: CausalAuditFinalDecisionV030): CausalAuditFinalDecision {
  return decision.decision === "candidate"
    ? { ...decision, contract_version: "0.2.0" }
    : { ...decision, contract_version: "0.2.0" };
}

/**
 * v0.3 keeps all v0.2 evidence and Candidate checks, but authorizes a final
 * decision after either an explicit model stop or a bounded successful read
 * window. A neutral window handoff is not treated as a budget failure.
 */
export function validateCausalAuditFinalDecisionV030(
  value: unknown,
  context: CausalAuditFinalDecisionValidationContextV030,
): CausalAuditFinalDecisionValidationResultV030 {
  const wire = validateWireValue("causal_audit_final_decision_v030", value);
  if (!wire.valid) {
    return {
      accepted: false,
      issues: wire.errors.map((error) => ({
        code: "CAUSAL_AUDIT_FINAL_DECISION_V030_SCHEMA_INVALID",
        path: error.instancePath || "/",
        message: error.message ?? "invalid",
      })),
    };
  }
  if (!handoffBindingValid(context.handoff)) {
    return {
      accepted: false,
      issues: [
        {
          code: "CAUSAL_AUDIT_FINAL_HANDOFF_BINDING_INVALID",
          path: "/handoff",
          message: "Final handoff kind does not match the trusted executor stop reason",
        },
      ],
    };
  }

  const decision = value as CausalAuditFinalDecisionV030;
  const legacy = validateCausalAuditFinalDecision(asV020Decision(decision), {
    task_id: context.task_id,
    active_revision_id: context.active_revision_id,
    finding_evidence_id: context.finding_evidence_id,
    stop_reason: legacySemanticStopReason(context.handoff),
    allowed_reviewed_record_refs: context.allowed_reviewed_record_refs,
    allowed_reviewed_evidence_refs: context.allowed_reviewed_evidence_refs,
    candidate_context: context.candidate_context,
  });
  const issues: CausalAuditFinalDecisionValidationIssueV030[] = legacy.accepted
    ? []
    : [...legacy.issues];
  if (decision.decision === "unresolved") {
    const runtimeBudgetFailure =
      context.handoff.kind === "runtime_failure" &&
      [
        "step_budget_exhausted",
        "tool_budget_exhausted",
        "token_budget_exhausted",
        "latency_budget_exhausted",
      ].includes(context.handoff.execution_stop_reason);
    if (decision.reason_code === "investigation_budget_exhausted" && !runtimeBudgetFailure) {
      issues.push({
        code: "CAUSAL_AUDIT_UNRESOLVED_BUDGET_REASON_WITHOUT_RUNTIME_FAILURE",
        path: "/reason_code",
        message: "Budget exhaustion may only describe a trusted Runtime budget failure",
      });
    }
    const runtimeToolFailure =
      context.handoff.kind === "runtime_failure" &&
      context.handoff.execution_stop_reason === "tool_error";
    if (decision.reason_code === "tool_result_incomplete" && !runtimeToolFailure) {
      issues.push({
        code: "CAUSAL_AUDIT_UNRESOLVED_TOOL_REASON_WITHOUT_RUNTIME_FAILURE",
        path: "/reason_code",
        message: "Tool-result failure may only describe a trusted Runtime tool error",
      });
    }
  }
  return issues.length === 0
    ? { accepted: true, decision, issues: [] }
    : { accepted: false, issues };
}
