import {
  type CausalAuditCandidateBatch,
  type CausalAuditCandidateCauseRef,
  type CausalAuditCandidateEffectRef,
  type CausalLink,
  type DerivationMeta,
  type EvidenceItem,
  type EvidenceSpan,
  type ExtractorDescriptor,
  getNarraMemIdKind,
  type HashDigest,
  isHashDigest,
  isIsoInstant,
  type ModelChangeSetProposal,
  type NarraMemId,
  type NarraMemIdKind,
} from "@narramem/core-domain";
import {
  type CausalAuditCandidateValidationContext,
  validateCausalAuditCandidateBatch,
} from "@narramem/core-validator";

export const CAUSAL_AUDIT_COMPILER_VERSION = "0.1.0" as const;

export interface CausalAuditCompilerContext extends CausalAuditCandidateValidationContext {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  /** Trusted namespace; never copied from Agent output. */
  readonly compilation_key: string;
  readonly extractor: ExtractorDescriptor;
}

export interface CausalAuditCompilerPorts {
  readonly allocate_id: <Kind extends NarraMemIdKind>(
    kind: Kind,
    stable_key: string,
  ) => NarraMemId<Kind>;
  readonly hash_text: (text: string) => Promise<HashDigest>;
  readonly now: () => string;
}

export interface CompiledCausalAuditCandidate {
  readonly candidate_artifact_sha256: HashDigest;
  readonly proposal: ModelChangeSetProposal;
  readonly causal_links: readonly CausalLink[];
}

export class CausalAuditCompilationError extends Error {
  constructor(
    message: string,
    readonly codes: readonly string[],
  ) {
    super(message);
    this.name = "CausalAuditCompilationError";
  }
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.entries(value as Readonly<Record<string, unknown>>)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, nested]) => `${JSON.stringify(key)}:${canonicalJson(nested)}`)
    .join(",")}}`;
}

function assertAllocatedId<Kind extends NarraMemIdKind>(
  kind: Kind,
  value: NarraMemId<Kind>,
): NarraMemId<Kind> {
  if (getNarraMemIdKind(value) !== kind) {
    throw new CausalAuditCompilationError(`ID allocator returned the wrong kind for ${kind}`, [
      "CAUSAL_AUDIT_COMPILER_ID_KIND_INVALID",
    ]);
  }
  return value;
}

function findOccurrence(text: string, quote: string, requestedOccurrence: number): number {
  let searchFrom = 0;
  let occurrence = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) break;
    if (occurrence === requestedOccurrence) return index;
    occurrence += 1;
    searchFrom = index + Math.max(1, quote.length);
  }
  throw new CausalAuditCompilationError("Validated Evidence quote could not be anchored", [
    "CAUSAL_AUDIT_COMPILER_QUOTE_NOT_FOUND",
  ]);
}

function codePointOffset(text: string, codeUnitOffset: number): number {
  return [...text.slice(0, codeUnitOffset)].length;
}

async function anchorQuote(
  quote: CausalAuditCandidateBatch["causal_links"][number]["evidence_quotes"][number],
  evidenceById: ReadonlyMap<string, EvidenceItem>,
  ports: CausalAuditCompilerPorts,
): Promise<EvidenceSpan> {
  const evidence = evidenceById.get(quote.evidence_id);
  if (evidence === undefined || evidence.raw_content.kind !== "text") {
    throw new CausalAuditCompilationError("Validated Evidence source disappeared", [
      "CAUSAL_AUDIT_COMPILER_EVIDENCE_MISSING",
    ]);
  }
  const startCodeUnit = findOccurrence(
    evidence.raw_content.text,
    quote.quote,
    quote.occurrence ?? 0,
  );
  const endCodeUnit = startCodeUnit + quote.quote.length;
  const quoteHash = await ports.hash_text(quote.quote);
  if (!isHashDigest(quoteHash)) {
    throw new CausalAuditCompilationError("Hash port returned an invalid digest", [
      "CAUSAL_AUDIT_COMPILER_HASH_INVALID",
    ]);
  }
  return {
    evidence_id: quote.evidence_id,
    selector: {
      kind: "text_range",
      start_code_point: codePointOffset(evidence.raw_content.text, startCodeUnit),
      end_code_point: codePointOffset(evidence.raw_content.text, endCodeUnit),
    },
    quote_hash: quoteHash,
    support_role: quote.support_role,
  };
}

function causeId(reference: CausalAuditCandidateCauseRef): NarraMemId {
  switch (reference.kind) {
    case "event":
      return reference.event_id;
    case "state_assertion":
      return reference.assertion_id;
    case "state_delta":
      return reference.delta_id;
    case "epistemic_state":
      return reference.epistemic_id;
    case "proposition":
      return reference.proposition_id;
    case "narrative_thread":
      return reference.thread_id;
  }
}

function effectId(reference: CausalAuditCandidateEffectRef): NarraMemId {
  switch (reference.kind) {
    case "event":
      return reference.event_id;
    case "state_delta":
      return reference.delta_id;
    case "epistemic_state":
      return reference.epistemic_id;
    case "narrative_thread":
      return reference.thread_id;
  }
}

function unique<T>(values: readonly T[]): T[] {
  return [...new Set(values)];
}

export async function compileCausalAuditCandidateBatch(
  value: unknown,
  context: CausalAuditCompilerContext,
  ports: CausalAuditCompilerPorts,
): Promise<CompiledCausalAuditCandidate> {
  const validation = validateCausalAuditCandidateBatch(value, context);
  if (!validation.accepted) {
    throw new CausalAuditCompilationError(
      "Causal audit candidate failed validation",
      validation.issues.map((item) => item.code),
    );
  }
  if (
    context.compilation_key.length === 0 ||
    context.compilation_key !== context.compilation_key.trim()
  ) {
    throw new CausalAuditCompilationError(
      "Trusted compilation key must be a non-empty exact value",
      ["CAUSAL_AUDIT_COMPILER_NAMESPACE_INVALID"],
    );
  }
  const createdAt = ports.now();
  if (!isIsoInstant(createdAt)) {
    throw new CausalAuditCompilationError("Clock port returned a non-ISO instant", [
      "CAUSAL_AUDIT_COMPILER_CLOCK_INVALID",
    ]);
  }
  const candidateArtifactSha256 = await ports.hash_text(canonicalJson(validation.candidate));
  if (!isHashDigest(candidateArtifactSha256)) {
    throw new CausalAuditCompilationError("Hash port returned an invalid candidate digest", [
      "CAUSAL_AUDIT_COMPILER_HASH_INVALID",
    ]);
  }
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const causalLinks = await Promise.all(
    validation.candidate.causal_links.map(async (candidate) => {
      const spans = await Promise.all(
        candidate.evidence_quotes.map((quote) => anchorQuote(quote, evidenceById, ports)),
      );
      const support = spans.filter((span) => span.support_role !== "contradiction");
      const counterevidence = spans.filter((span) => span.support_role === "contradiction");
      const holder =
        candidate.attribution.kind === "character_belief"
          ? { kind: "entity" as const, entity_id: candidate.attribution.holder_entity_id }
          : undefined;
      const dependencyRefs = unique<NarraMemId>([
        ...candidate.cause_refs.map(causeId),
        ...candidate.effect_refs.map(effectId),
        ...(holder === undefined ? [] : [holder.entity_id]),
      ]);
      const stableKey = `${context.active_revision_id}:${context.compilation_key}:causal:${candidate.candidate_key}`;
      const derivation: DerivationMeta = {
        derivation_id: assertAllocatedId(
          "derivation",
          ports.allocate_id("derivation", `${stableKey}:derivation`),
        ),
        input_revision_id: context.active_revision_id,
        evidence_refs: unique(spans.map((span) => span.evidence_id)),
        dependency_refs: dependencyRefs,
        extractor: context.extractor,
        validator_version: CAUSAL_AUDIT_COMPILER_VERSION,
        created_at: createdAt,
      };
      const record: CausalLink = {
        causal_id: assertAllocatedId("causal_link", ports.allocate_id("causal_link", stableKey)),
        memory_space_id: context.memory_space_id,
        branch_id: context.branch_id,
        cause_refs: candidate.cause_refs,
        effect_refs: candidate.effect_refs,
        relation: candidate.relation,
        mechanism: candidate.mechanism,
        scope: candidate.attribution.kind,
        ...(holder === undefined ? {} : { holder }),
        necessity: candidate.necessity,
        strength: candidate.strength,
        ...(candidate.persistence === undefined ? {} : { persistence: candidate.persistence }),
        support,
        counterevidence,
        confidence: { level: "high", basis: "text_explicit" },
        derivation,
      };
      return record;
    }),
  );
  const proposal: ModelChangeSetProposal = {
    stage: "proposal",
    changeset_id: assertAllocatedId(
      "change_set",
      ports.allocate_id(
        "change_set",
        `${context.active_revision_id}:${context.compilation_key}:causal-audit-change-set`,
      ),
    ),
    memory_space_id: context.memory_space_id,
    branch_id: context.branch_id,
    based_on_revision_id: context.active_revision_id,
    producer: "agent",
    operations: causalLinks.map((record) => ({ op: "add_derived" as const, record })),
    unresolved_items: [],
    created_at: createdAt,
  };
  return {
    candidate_artifact_sha256: candidateArtifactSha256,
    proposal,
    causal_links: causalLinks,
  };
}
