import type {
  CandidateEvidenceQuote,
  EvidenceItem,
  FlatDraftQuote,
  FlatNarrativeExtractionDraft,
  NarraMemId,
  NarrativeExtractionCandidateBatch,
} from "@narramem/core-domain";

export const EXPLICIT_CAUSAL_COMPLETENESS_POLICY_VERSION = "0.1.0" as const;

export interface ExplicitCausalCompletenessFinding {
  readonly code: "EXPLICIT_CAUSAL_CUE_UNCOVERED";
  readonly evidence_id: NarraMemId<"evidence">;
  readonly cue: string;
  readonly start_code_point: number;
  readonly end_code_point: number;
  readonly message: string;
}

export interface ExplicitCausalCompletenessReport {
  readonly policy_version: typeof EXPLICIT_CAUSAL_COMPLETENESS_POLICY_VERSION;
  readonly findings: readonly ExplicitCausalCompletenessFinding[];
}

interface QuoteLike {
  readonly evidence_id: NarraMemId<"evidence">;
  readonly quote: string;
  readonly occurrence?: number;
}

const CAUSAL_CUES = [
  "as a result",
  "therefore",
  "because",
  "caused",
  "causes",
  "led to",
  "正因为",
  "因此",
  "因而",
  "所以",
  "从而",
  "导致",
  "造成",
  "使得",
] as const;

function quoteRanges(text: string): readonly { readonly start: number; readonly end: number }[] {
  const ranges: { start: number; end: number }[] = [];
  let smartStart: number | undefined;
  let asciiStart: number | undefined;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (character === "“") {
      smartStart = index;
    } else if (character === "”" && smartStart !== undefined) {
      ranges.push({ start: smartStart, end: index + 1 });
      smartStart = undefined;
    } else if (character === '"' && text[index - 1] !== "\\") {
      if (asciiStart === undefined) asciiStart = index;
      else {
        ranges.push({ start: asciiStart, end: index + 1 });
        asciiStart = undefined;
      }
    }
  }
  return ranges;
}

function isInsideRange(
  start: number,
  end: number,
  ranges: readonly { readonly start: number; readonly end: number }[],
): boolean {
  return ranges.some((range) => start >= range.start && end <= range.end);
}

function occurrences(text: string, needle: string): readonly number[] {
  const indexes: number[] = [];
  let from = 0;
  while (from <= text.length) {
    const index = text.indexOf(needle, from);
    if (index < 0) break;
    indexes.push(index);
    from = index + Math.max(1, needle.length);
  }
  return indexes;
}

function occurrenceIndex(text: string, quote: QuoteLike): number | undefined {
  return occurrences(text, quote.quote)[quote.occurrence ?? 0];
}

function codePointOffset(text: string, codeUnitOffset: number): number {
  return [...text.slice(0, codeUnitOffset)].length;
}

export function evaluateExplicitCausalCompleteness(
  evidenceItems: readonly EvidenceItem[],
  causalQuotes: readonly QuoteLike[],
): ExplicitCausalCompletenessReport {
  const findings: ExplicitCausalCompletenessFinding[] = [];
  for (const evidence of evidenceItems) {
    if (evidence.raw_content.kind !== "text") continue;
    const text = evidence.raw_content.text;
    const quoted = quoteRanges(text);
    const coverage = causalQuotes.flatMap((candidateQuote) => {
      if (candidateQuote.evidence_id !== evidence.evidence_id) return [];
      const start = occurrenceIndex(text, candidateQuote);
      return start === undefined ? [] : [{ start, end: start + candidateQuote.quote.length }];
    });
    const occupied = new Set<number>();
    for (const cue of CAUSAL_CUES) {
      const source = /[A-Za-z]/.test(cue) ? text.toLocaleLowerCase("en-US") : text;
      for (const start of occurrences(source, cue)) {
        const end = start + cue.length;
        if (isInsideRange(start, end, quoted)) continue;
        if (coverage.some((range) => start >= range.start && end <= range.end)) continue;
        if ([...occupied].some((index) => index >= start && index < end)) continue;
        for (let index = start; index < end; index += 1) occupied.add(index);
        findings.push({
          code: "EXPLICIT_CAUSAL_CUE_UNCOVERED",
          evidence_id: evidence.evidence_id,
          cue: text.slice(start, end),
          start_code_point: codePointOffset(text, start),
          end_code_point: codePointOffset(text, end),
          message: "Explicit causal cue is not covered by any Causal candidate evidence quote",
        });
      }
    }
  }
  return {
    policy_version: EXPLICIT_CAUSAL_COMPLETENESS_POLICY_VERSION,
    findings: findings.sort(
      (left, right) =>
        left.evidence_id.localeCompare(right.evidence_id) ||
        left.start_code_point - right.start_code_point ||
        left.cue.localeCompare(right.cue),
    ),
  };
}

export function evaluateFlatDraftCausalCompleteness(
  draft: FlatNarrativeExtractionDraft,
  evidenceItems: readonly EvidenceItem[],
): ExplicitCausalCompletenessReport {
  return evaluateExplicitCausalCompleteness(
    evidenceItems,
    draft.causals.flatMap((causal) => causal.quotes as readonly FlatDraftQuote[]),
  );
}

export function evaluateNarrativeCandidateCausalCompleteness(
  batch: NarrativeExtractionCandidateBatch,
  evidenceItems: readonly EvidenceItem[],
): ExplicitCausalCompletenessReport {
  return evaluateExplicitCausalCompleteness(
    evidenceItems,
    batch.causal_links.flatMap(
      (causal) => causal.evidence_quotes as readonly CandidateEvidenceQuote[],
    ),
  );
}
