import type { TavernHostPort } from "@narramem/tavern-adapter";

import {
  collectNarraMemCoreDataExport,
  downloadJson,
  type NarraMemDiagnosticExportEntry,
} from "./beta-data-export.js";
import { type NarraMemMemoryApiClient, NarraMemMemoryApiError } from "./memory-api-client.js";
import {
  activeMemoryApiProfile,
  DEEPSEEK_OFFICIAL_ENDPOINT,
  MEMORY_PROMPT_PROFILES,
  type MemoryApiSource,
  type MemoryPromptProfileId,
  type NarraMemBetaSettings,
  type NarraMemBetaSettingsStore,
  type NarraMemMemoryApiProfile,
  promptProfileLabel,
  resolvedMemoryPromptProfile,
} from "./memory-api-settings.js";

const PANEL_ID = "narramem-beta-settings";

export interface NarraMemTaskDisplayState {
  readonly status: "idle" | "running" | "success" | "failed";
  readonly stage: "idle" | "source_sync" | "extraction" | "lifecycle" | "recall";
  readonly error_type: string | null;
  readonly error_code: string | null;
  readonly last_failure_at: string | null;
  readonly round_attempts: number;
  readonly round_max_calls: number;
  readonly cumulative_calls: number;
  readonly manual_retry_available: boolean;
}

export interface NarraMemBetaSettingsPanel {
  refreshStatus(): Promise<void>;
  open(): void;
}

export interface NarraMemBetaSettingsPanelOptions {
  readonly version: string;
  readonly port: TavernHostPort;
  readonly settingsStore: NarraMemBetaSettingsStore;
  readonly apiClient: NarraMemMemoryApiClient;
  getRuntimeState(): Readonly<Record<string, unknown>>;
  getTaskState(): NarraMemTaskDisplayState;
  getDiagnostics(): readonly NarraMemDiagnosticExportEntry[];
  onConfigurationChanged(): void;
  onManualRetry(): Promise<void>;
}

function field(labelText: string, control: HTMLElement, note?: string): HTMLLabelElement {
  const label = document.createElement("label");
  label.className = "flex-container flexFlowColumn narramem-field";
  const title = document.createElement("span");
  title.textContent = labelText;
  label.append(title, control);
  if (note !== undefined) {
    const small = document.createElement("small");
    small.textContent = note;
    label.append(small);
  }
  return label;
}

function textInput(value: string, placeholder = ""): HTMLInputElement {
  const input = document.createElement("input");
  input.type = "text";
  input.value = value;
  input.placeholder = placeholder;
  input.className = "text_pole";
  return input;
}

function numberInput(value: number, minimum: number, maximum?: number): HTMLInputElement {
  const input = document.createElement("input");
  input.type = "number";
  input.value = String(value);
  input.min = String(minimum);
  if (maximum !== undefined) input.max = String(maximum);
  input.step = "1";
  input.className = "text_pole";
  return input;
}

function button(text: string, className = ""): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.className = `menu_button ${className}`.trim();
  element.textContent = text;
  return element;
}

function actionRow(...controls: HTMLElement[]): HTMLDivElement {
  const row = document.createElement("div");
  row.className = "narramem-action-row";
  row.append(...controls);
  return row;
}

function checkedRow(
  text: string,
  checked: boolean,
): { readonly label: HTMLLabelElement; readonly input: HTMLInputElement } {
  const label = document.createElement("label");
  label.className = "checkbox_label";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = checked;
  const caption = document.createElement("span");
  caption.textContent = text;
  label.append(input, caption);
  return { label, input };
}

function integerValue(input: HTMLInputElement): number {
  return Number.parseInt(input.value, 10);
}

function exportFilename(kind: "diagnostics" | "core"): string {
  const timestamp = new Date().toISOString().replace(/[:.]/gu, "-");
  return `narramem-${kind}-${timestamp}.json`;
}

function errorLabel(error: unknown): string {
  if (error instanceof NarraMemMemoryApiError) {
    return `${error.name} · ${error.code}${error.http_status === null ? "" : ` · HTTP ${error.http_status}`} · ${error.message}`;
  }
  return error instanceof Error ? error.name : "UnknownError";
}

function stageLabel(stage: NarraMemTaskDisplayState["stage"]): string {
  return {
    idle: "等待任务",
    source_sync: "同步当前聊天",
    extraction: "抽取／重新总结",
    lifecycle: "因果与叙事生命周期",
    recall: "召回",
  }[stage];
}

export function installNarraMemBetaSettingsPanel(
  options: NarraMemBetaSettingsPanelOptions,
): NarraMemBetaSettingsPanel {
  document.getElementById(PANEL_ID)?.remove();
  const initial = options.settingsStore.get();
  const root = document.createElement("div");
  root.id = PANEL_ID;
  root.className = "extension_container";

  const drawer = document.createElement("div");
  drawer.className = "inline-drawer";
  const drawerHeader = document.createElement("div");
  drawerHeader.className = "inline-drawer-toggle inline-drawer-header";
  const heading = document.createElement("b");
  heading.textContent = `NarraMem 叙忆（内测 ${options.version}）`;
  const drawerIcon = document.createElement("div");
  drawerIcon.className = "inline-drawer-icon fa-solid fa-circle-chevron-down down";
  drawerHeader.append(heading, drawerIcon);

  const content = document.createElement("div");
  content.className = "inline-drawer-content narramem-settings-stack";
  content.style.display = "none";
  const boundary = document.createElement("small");
  boundary.textContent =
    "NarraMem 使用独立的 Memory API、Key、模型与 Prompt；只复用酒馆的安全存储和 Provider 适配，不调用当前聊天 API、模型、预设或角色卡生成链。";
  const automaticScope = document.createElement("div");
  automaticScope.className = "narramem-information-box";
  automaticScope.textContent =
    "无需手动绑定：打开或切换聊天时，NarraMem 按当前聊天记录 ID 自动选择唯一记忆空间，并从当前角色卡自动识别角色。";
  const enabled = checkedRow("启用 NarraMem 自动记忆", initial.enabled);

  const connectionStatus = document.createElement("div");
  connectionStatus.className = "narramem-status-card";
  connectionStatus.setAttribute("role", "status");
  connectionStatus.textContent = "正在读取独立 Memory API 状态……";

  const profileSelect = document.createElement("select");
  profileSelect.className = "text_pole";
  const newProfile = button("新建");
  const renameProfile = button("重命名");
  const deleteProfile = button("删除");
  const profileBlock = document.createElement("div");
  profileBlock.className = "narramem-profile-grid";
  profileBlock.append(profileSelect, newProfile, renameProfile, deleteProfile);

  const apiSource = document.createElement("select");
  apiSource.className = "text_pole";
  for (const [value, label] of [
    ["custom", "自定义（兼容 OpenAI）"],
    ["deepseek", "DeepSeek"],
  ] as const) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    apiSource.append(option);
  }

  const apiUrl = textInput("", "https://example.com/v1");
  apiUrl.setAttribute("autocomplete", "url");
  const apiUrlField = field(
    "服务器 URL",
    apiUrl,
    "与酒馆 Custom Chat Completion 相同：可填根地址、/v1 或完整 /chat/completions。",
  );
  const deepSeekEndpoint = document.createElement("div");
  deepSeekEndpoint.className = "narramem-information-box";
  deepSeekEndpoint.textContent = `DeepSeek 使用 SillyTavern 1.18 原生适配和固定官方端点 ${DEEPSEEK_OFFICIAL_ENDPOINT}，这里不提供 Custom URL。`;

  const credential = document.createElement("input");
  credential.type = "password";
  credential.className = "text_pole";
  credential.placeholder = "填写新 API Key（已保存的 Key 不会回显）";
  credential.autocomplete = "off";
  const credentialStatus = document.createElement("small");
  credentialStatus.textContent = "未读取";
  const saveCredential = button("保存 / 替换 Key");
  const deleteCredential = button("删除 Key");
  const credentialBlock = document.createElement("div");
  credentialBlock.className = "flex-container flexFlowColumn narramem-section";
  credentialBlock.append(
    field(
      "API Key",
      credential,
      "作为本配置的独立条目保存在本机 SillyTavern 当前用户 secrets.json；扩展只保存 opaque 条目 ID，永不读取或回显原值。",
    ),
    credentialStatus,
    actionRow(saveCredential, deleteCredential),
  );

  const modelList = document.createElement("datalist");
  modelList.id = "narramem-memory-models";
  const model = textInput("", "模型 ID");
  model.setAttribute("list", modelList.id);
  const promptRoute = document.createElement("div");
  promptRoute.className = "narramem-information-box";
  const narrativeContentTag = textInput(initial.narrative_content_tag, "content");
  narrativeContentTag.setAttribute("autocomplete", "off");

  const saveSettings = button("保存配置", "narramem-primary-action");
  const connectModels = button("连接并读取模型", "narramem-primary-action");
  const sendTest = button("发送测试消息（消耗 1 次调用）", "narramem-primary-action");
  const primaryActions = document.createElement("div");
  primaryActions.className = "narramem-primary-actions";
  primaryActions.append(saveSettings, connectModels, sendTest);

  const taskStatus = document.createElement("div");
  taskStatus.className = "narramem-status-card";
  const retryManual = button("重新抽取");
  retryManual.hidden = true;
  const taskBlock = document.createElement("div");
  taskBlock.className = "narramem-section";
  taskBlock.append(taskStatus, retryManual);

  const concurrency = numberInput(initial.concurrency, 1, 16);
  const retryCount = numberInput(initial.retry_count, 0, 2);
  const timeout = numberInput(initial.timeout_ms, 1_000, 900_000);
  const promptOverride = document.createElement("select");
  promptOverride.className = "text_pole";
  const automaticPrompt = document.createElement("option");
  automaticPrompt.value = "";
  automaticPrompt.textContent = "自动匹配（推荐）";
  promptOverride.append(automaticPrompt);
  for (const profile of MEMORY_PROMPT_PROFILES) {
    const option = document.createElement("option");
    option.value = profile.id;
    option.textContent = profile.label;
    promptOverride.append(option);
  }
  const headSystem = document.createElement("textarea");
  headSystem.className = "text_pole";
  headSystem.rows = 5;
  headSystem.value = initial.head_system;
  const tailMessage = document.createElement("textarea");
  tailMessage.className = "text_pole";
  tailMessage.rows = 5;
  tailMessage.value = initial.tail_message;
  const materialAcknowledgement = document.createElement("textarea");
  materialAcknowledgement.className = "text_pole";
  materialAcknowledgement.rows = 4;
  materialAcknowledgement.value = initial.material_acknowledgement;
  const prefill = checkedRow(
    "启用最终 Assistant 预填充；关闭后，资料收到确认改为 System",
    initial.assistant_prefill_enabled,
  );
  const advanced = document.createElement("details");
  const advancedSummary = document.createElement("summary");
  advancedSummary.textContent = "附加参数与高级设置";
  const advancedBody = document.createElement("div");
  advancedBody.className = "flex-container flexFlowColumn narramem-section";
  advancedBody.append(
    field("并发数", concurrency, "默认 1；只限制 NarraMem 后台模型任务。"),
    field(
      "自动重试次数",
      retryCount,
      "默认 1；首次调用失败后追加 1 次。可设 0～2，因此单轮最多调用 1～3 次。",
    ),
    field("请求超时（毫秒）", timeout),
    field(
      "兼容 Prompt 覆盖",
      promptOverride,
      "通常保持自动。只有实际模型名无法识别时才选择；这是兼容覆盖，不是第二个模型。",
    ),
    field(
      "破限头部（System）",
      headSystem,
      "与现有 NarraMem 模型专属任务正文组合为第一条可信 System。",
    ),
    field(
      "身份确认消息",
      tailMessage,
      "位于可信 System 之后、资料 User 之前；不是最终输出预填充。",
    ),
    prefill.label,
    field(
      "资料收到确认",
      materialAcknowledgement,
      "位于资料 User 之后、最终严格 JSON User 规则之前；关闭预填充时角色改为 System。",
    ),
    document.createTextNode(
      "不会发送最大上下文、最大回复、会话调用上限、温度或 Top P；均使用模型／服务端默认值。",
    ),
  );
  advanced.append(advancedSummary, advancedBody);

  const exportSection = document.createElement("details");
  const exportSummary = document.createElement("summary");
  exportSummary.textContent = "日志与核心数据导出";
  const privacyWarning = document.createElement("div");
  privacyWarning.className = "narramem-privacy-warning";
  privacyWarning.textContent =
    "隐私警告：核心数据可能包含聊天原文、角色信息、世界状态、因果证据和会话标识。请只发送给你信任的人。导出不包含 API 地址、API Key、secret ID 或 Prompt 正文。";
  const privacyAck = checkedRow("我理解核心数据文件可能包含聊天记录等隐私内容", false);
  const downloadDiagnostics = button("下载诊断日志（不含核心记忆）");
  const downloadCore = button("下载核心数据 + 日志");
  downloadCore.disabled = true;
  privacyAck.input.addEventListener("change", () => {
    downloadCore.disabled = !privacyAck.input.checked;
  });
  exportSection.append(
    exportSummary,
    privacyWarning,
    privacyAck.label,
    actionRow(downloadDiagnostics, downloadCore),
  );

  content.append(
    boundary,
    automaticScope,
    enabled.label,
    field("API 配置", profileBlock),
    field("接口来源", apiSource),
    apiUrlField,
    deepSeekEndpoint,
    credentialBlock,
    field("模型", model),
    modelList,
    promptRoute,
    field(
      "AI 正文标签",
      narrativeContentTag,
      "默认 content。只读取最后一个完整 <标签>…</标签> 内的 AI 正文，删除其中 HTML 注释并丢弃标签外内容；用户发言不受影响。",
    ),
    primaryActions,
    connectionStatus,
    taskBlock,
    advanced,
    exportSection,
  );
  drawer.append(drawerHeader, content);
  root.append(drawer);
  (document.getElementById("extensions_settings") ?? document.body).append(root);

  let busy = false;

  const renderProfiles = (): void => {
    const settings = options.settingsStore.get();
    profileSelect.replaceChildren();
    for (const profile of settings.profiles) {
      const option = document.createElement("option");
      option.value = profile.id;
      option.textContent = profile.name;
      profileSelect.append(option);
    }
    profileSelect.value = settings.active_profile_id;
    deleteProfile.disabled = settings.profiles.length <= 1;
  };

  const renderSource = (): void => {
    const deepseek = apiSource.value === "deepseek";
    apiUrlField.hidden = deepseek;
    deepSeekEndpoint.hidden = !deepseek;
  };

  const currentOverride = (): MemoryPromptProfileId | null =>
    promptOverride.value.length === 0 ? null : (promptOverride.value as MemoryPromptProfileId);

  const formProfile = (): NarraMemMemoryApiProfile => {
    const stored = activeMemoryApiProfile(options.settingsStore.get());
    const nextSource = apiSource.value as MemoryApiSource;
    return {
      ...stored,
      source: nextSource,
      api_url: nextSource === "custom" ? apiUrl.value.trim() : "",
      model: model.value.trim(),
      credential_secret_id: stored.source === nextSource ? stored.credential_secret_id : "",
      prompt_profile_override: currentOverride(),
    };
  };

  const renderPromptRoute = (): void => {
    const profile = formProfile();
    const resolved = resolvedMemoryPromptProfile(profile);
    if (resolved === null) {
      promptRoute.textContent =
        "未识别当前模型对应的 NarraMem 专用 Prompt。请打开“附加参数与高级设置”选择兼容 Prompt；在此之前自动记忆保持暂停。";
      promptRoute.dataset.state = "warning";
      return;
    }
    promptRoute.textContent = `${profile.prompt_profile_override === null ? "已根据模型自动匹配" : "已使用高级兼容覆盖"}：${promptProfileLabel(resolved)}`;
    promptRoute.dataset.state = "ok";
  };

  const loadActiveProfile = (): void => {
    const profile = activeMemoryApiProfile(options.settingsStore.get());
    apiSource.value = profile.source;
    apiUrl.value = profile.api_url;
    model.value = profile.model;
    promptOverride.value = profile.prompt_profile_override ?? "";
    credential.value = "";
    renderSource();
    renderPromptRoute();
  };

  const persistForm = async (): Promise<NarraMemBetaSettings> => {
    const previous = activeMemoryApiProfile(options.settingsStore.get());
    const nextProfile = formProfile();
    if (previous.source !== nextProfile.source && previous.credential_secret_id.length > 0) {
      await options.apiClient.deleteCredential(previous);
    }
    options.settingsStore.updateActiveProfile(nextProfile);
    const next = options.settingsStore.patch({
      enabled: enabled.input.checked,
      narrative_content_tag: narrativeContentTag.value,
      head_system: headSystem.value,
      tail_message: tailMessage.value,
      material_acknowledgement: materialAcknowledgement.value,
      assistant_prefill_enabled: prefill.input.checked,
      concurrency: integerValue(concurrency),
      retry_count: integerValue(retryCount),
      timeout_ms: integerValue(timeout),
      min_interval_ms: 0,
      max_requests_per_minute: 0,
    });
    options.onConfigurationChanged();
    narrativeContentTag.value = next.narrative_content_tag;
    renderProfiles();
    loadActiveProfile();
    return next;
  };

  const renderTaskState = (): void => {
    const state = options.getTaskState();
    const statusText = {
      idle: "等待",
      running: "运行中",
      success: "成功",
      failed: "失败",
    }[state.status];
    const failure =
      state.status === "failed"
        ? ` · 错误 ${state.error_type ?? "UnknownError"}${state.error_code === null ? "" : ` / ${state.error_code}`} · 最后失败 ${state.last_failure_at ?? "未知"}`
        : "";
    taskStatus.textContent = `记忆任务：${statusText} · 阶段 ${stageLabel(state.stage)} · 本轮 ${state.round_attempts}/${state.round_max_calls} 次 · 累计 ${state.cumulative_calls} 次${failure}`;
    retryManual.hidden = !state.manual_retry_available;
    retryManual.disabled = state.status === "running" || busy;
  };

  const setBusy = (value: boolean): void => {
    busy = value;
    for (const control of [
      saveSettings,
      connectModels,
      sendTest,
      saveCredential,
      deleteCredential,
      newProfile,
      renameProfile,
      deleteProfile,
      profileSelect,
      narrativeContentTag,
    ]) {
      control.disabled = value;
    }
    if (!value) deleteProfile.disabled = options.settingsStore.get().profiles.length <= 1;
    renderTaskState();
  };

  const refreshStatus = async (preserveConnectionStatus = false): Promise<void> => {
    renderTaskState();
    try {
      const profile = activeMemoryApiProfile(options.settingsStore.get());
      const next = await options.apiClient.status(profile);
      credentialStatus.textContent = next.credential_configured
        ? "Key 已配置（值不回显）"
        : "未配置 Key";
      deleteCredential.disabled = busy || !next.credential_configured;
      const runtimeState = options.getRuntimeState();
      const active = runtimeState.runtime_active === true ? "运行中" : "未运行";
      if (!preserveConnectionStatus) {
        connectionStatus.textContent = `本地安全传输可用 · ${profile.source === "deepseek" ? "DeepSeek" : "Custom"} · Runtime ${active} · 页面累计模型调用 ${next.session_dispatches} 次 · 并发 ${next.concurrency_limit} · 单轮自动重试 ${next.automatic_retries} 次`;
      }
    } catch (error) {
      credentialStatus.textContent = "无法读取 Key 状态";
      deleteCredential.disabled = true;
      if (!preserveConnectionStatus) {
        connectionStatus.textContent = `本地密钥／传输状态读取失败：${errorLabel(error)}`;
      }
    }
  };

  renderProfiles();
  loadActiveProfile();
  renderTaskState();

  apiSource.addEventListener("change", () => {
    if (apiSource.value === "deepseek") {
      model.value = "deepseek-v4-flash";
    }
    renderSource();
    renderPromptRoute();
  });
  model.addEventListener("input", renderPromptRoute);
  promptOverride.addEventListener("change", renderPromptRoute);

  profileSelect.addEventListener("change", () => {
    options.settingsStore.selectProfile(profileSelect.value);
    loadActiveProfile();
    options.onConfigurationChanged();
    void refreshStatus();
  });
  newProfile.addEventListener("click", () => {
    const name = globalThis.prompt(
      "新配置名称",
      `配置 ${options.settingsStore.get().profiles.length + 1}`,
    );
    if (name === null) return;
    options.settingsStore.createProfile(name, apiSource.value as MemoryApiSource);
    renderProfiles();
    loadActiveProfile();
    options.onConfigurationChanged();
    void refreshStatus();
  });
  renameProfile.addEventListener("click", () => {
    const current = activeMemoryApiProfile(options.settingsStore.get());
    const name = globalThis.prompt("重命名 API 配置", current.name);
    if (name === null) return;
    options.settingsStore.renameActiveProfile(name);
    renderProfiles();
  });
  deleteProfile.addEventListener("click", () => {
    const current = activeMemoryApiProfile(options.settingsStore.get());
    if (!globalThis.confirm(`删除 API 配置“${current.name}”？对应 NarraMem Key 也会删除。`)) return;
    setBusy(true);
    void options.apiClient
      .deleteCredential(current)
      .then(() => {
        options.settingsStore.deleteActiveProfile();
        renderProfiles();
        loadActiveProfile();
        options.onConfigurationChanged();
        connectionStatus.textContent = "API 配置已删除。";
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `删除配置失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });

  saveSettings.addEventListener("click", () => {
    setBusy(true);
    connectionStatus.textContent = "正在保存配置……";
    void persistForm()
      .then(() => {
        connectionStatus.textContent = "配置已保存；记忆运行时会自动重载。";
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `保存失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });
  saveCredential.addEventListener("click", () => {
    const value = credential.value.trim();
    if (value.length === 0) {
      credentialStatus.textContent = "请先填写新的 API Key";
      return;
    }
    setBusy(true);
    void persistForm()
      .then(() => options.apiClient.saveCredential(value))
      .then(() => {
        credential.value = "";
        credentialStatus.textContent = "Key 已保存；原值不会回显";
        options.onConfigurationChanged();
      })
      .catch((error: unknown) => {
        credentialStatus.textContent = `保存失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });
  deleteCredential.addEventListener("click", () => {
    if (!globalThis.confirm("确定删除当前配置的 NarraMem 独立 Memory API Key？")) return;
    setBusy(true);
    void options.apiClient
      .deleteCredential()
      .then(() => {
        credentialStatus.textContent = "Key 已删除";
        options.onConfigurationChanged();
      })
      .catch((error: unknown) => {
        credentialStatus.textContent = `删除失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });
  connectModels.addEventListener("click", () => {
    setBusy(true);
    connectionStatus.textContent = "正在连接并读取模型列表；不会触发模型生成……";
    const before = options.getTaskState().cumulative_calls;
    void persistForm()
      .then(() => options.apiClient.listModels())
      .then((models) => {
        modelList.replaceChildren();
        for (const id of models) {
          const option = document.createElement("option");
          option.value = id;
          modelList.append(option);
        }
        const after = options.getTaskState().cumulative_calls;
        connectionStatus.textContent =
          models.length > 0
            ? `连接成功，读取到 ${models.length} 个模型；生成调用 ${before}→${after}（应保持不变）。`
            : `连接成功，但接口未提供模型列表；可手动填写模型。生成调用 ${before}→${after}（应保持不变）。`;
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `连接失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });
  sendTest.addEventListener("click", () => {
    if (
      !globalThis.confirm(
        "发送一次真实 NarraMem strict Schema 测试消息？会消耗 1 次模型调用，但不会写记忆或隐藏楼层。",
      )
    )
      return;
    setBusy(true);
    connectionStatus.textContent = "正在发送测试消息（消耗 1 次调用）……";
    void persistForm()
      .then(() => options.apiClient.sendConnectionTest())
      .then((result) => {
        connectionStatus.textContent = `测试成功：${result.source} / ${result.model}；消耗 ${result.dispatches_used} 次调用；未写记忆。`;
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `测试失败：${errorLabel(error)}；未写记忆。`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });
  retryManual.addEventListener("click", () => {
    if (
      !globalThis.confirm(
        "开启新的手动重新抽取轮次？新轮次会重新获得所配置的自动重试额度并消耗模型调用。",
      )
    )
      return;
    setBusy(true);
    void options
      .onManualRetry()
      .then(() => {
        connectionStatus.textContent = "已启动新的手动重新抽取轮次。";
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `重新抽取启动失败：${errorLabel(error)}`;
      })
      .finally(() => {
        setBusy(false);
        void refreshStatus(true);
      });
  });

  downloadDiagnostics.addEventListener("click", () => {
    downloadJson(exportFilename("diagnostics"), {
      format: "narramem.tavern-beta-diagnostics",
      exported_at: new Date().toISOString(),
      privacy: {
        api_configuration_included: false,
        api_key_included: false,
        credential_value_included: false,
      },
      runtime_state: options.getRuntimeState(),
      diagnostics: options.getDiagnostics(),
    });
  });
  downloadCore.addEventListener("click", () => {
    if (!privacyAck.input.checked) return;
    if (
      !globalThis.confirm("此文件可能包含聊天记录、角色身份、世界状态与因果证据。确认下载到本机？")
    )
      return;
    downloadCore.disabled = true;
    connectionStatus.textContent = "正在从当前世界书读取并校验核心记忆……";
    void collectNarraMemCoreDataExport({
      port: options.port,
      settings: options.settingsStore.get(),
      runtime_state: options.getRuntimeState(),
      diagnostics: options.getDiagnostics(),
    })
      .then((value) => {
        downloadJson(exportFilename("core"), value);
        connectionStatus.textContent = `核心数据已导出：${value.memory.records.length} 条记录；API 配置与 Key 未包含。`;
      })
      .catch((error: unknown) => {
        connectionStatus.textContent = `核心数据导出失败：${errorLabel(error)}`;
      })
      .finally(() => {
        downloadCore.disabled = !privacyAck.input.checked;
      });
  });

  const open = (): void => {
    const hostDrawerContent = document.querySelector<HTMLElement>("#rm_extensions_block");
    if (hostDrawerContent?.classList.contains("closedDrawer")) {
      document.querySelector<HTMLElement>("#extensions-settings-button .drawer-icon")?.click();
    }
    content.style.display = "flex";
    drawerIcon.classList.remove("down");
    drawerIcon.classList.add("up");
    globalThis.requestAnimationFrame(() => {
      root.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  };

  void refreshStatus();
  return { refreshStatus, open };
}
