import type { NarraMemId } from "@narramem/core-domain";

import type { TavernCausalAuditActivationMode } from "./causal-audit-execution-policy.js";
import type { TavernCausalAuditTaskSeed } from "./causal-audit-task-mapping.js";

export const TAVERN_CAUSAL_AUDIT_TASK_STORE_VERSION = "0.2.0" as const;
export const TAVERN_CAUSAL_AUDIT_TASK_STORE_FORMAT = "narramem.tavern-causal-audit-tasks" as const;

export type TavernCausalAuditTaskPriority = "low" | "normal" | "high" | "critical";

export type TavernCausalAuditTaskStatus =
  | "pending"
  | "leased"
  | "proposal_pending_validation"
  | "resolved"
  | "unresolved"
  | "stale"
  | "cancelled"
  | "failed";

export interface TavernCausalAuditTaskBudget {
  readonly max_attempts: number;
  readonly max_model_calls: number;
  readonly max_tool_calls: number;
  readonly max_input_tokens: number;
  readonly lease_duration_ms: number;
}

export interface TavernCausalAuditTaskUsage {
  readonly attempts_used: number;
  readonly model_calls_used: number;
  readonly tool_calls_used: number;
  readonly input_tokens_used: number;
}

export interface TavernCausalAuditTaskLease {
  readonly lease_id: string;
  readonly worker_id: string;
  readonly leased_at: string;
  readonly expires_at: string;
}

export type TavernCausalAuditTaskResolution =
  | {
      readonly kind: "candidate_proposed";
      readonly candidate_contract_version: string;
      readonly candidate_artifact_sha256: string;
    }
  | {
      readonly kind: "candidate_committed";
      readonly candidate_contract_version: string;
      readonly candidate_artifact_sha256: string;
      readonly authorized_changeset_id: NarraMemId<"change_set">;
    }
  | { readonly kind: "no_supported_causal"; readonly reason_code: string }
  | { readonly kind: "unresolved"; readonly reason_code: string };

/** Scheduling state only. The finding remains authoritative in semantic_manifest_v4. */
export interface TavernCausalAuditTaskStateRecord {
  readonly task_seed_id: string;
  readonly finding_fingerprint: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly semantic_task_fingerprint: string;
  readonly source_response_sha256: string;
  readonly finding_policy_version: string;
  readonly priority: TavernCausalAuditTaskPriority;
  readonly budget: TavernCausalAuditTaskBudget;
  readonly usage: TavernCausalAuditTaskUsage;
  readonly status: TavernCausalAuditTaskStatus;
  readonly created_at: string;
  readonly updated_at: string;
  readonly record_version: number;
  readonly lease?: TavernCausalAuditTaskLease;
  readonly resolution?: TavernCausalAuditTaskResolution;
  readonly last_error_code?: string;
  readonly terminal_reason?: string;
}

export interface TavernCausalAuditExecutionPreference {
  readonly activation_mode: TavernCausalAuditActivationMode;
  readonly unattended_opt_in_acknowledged: boolean;
  readonly updated_at: string;
}

export interface TavernCausalAuditTaskStorePayload {
  readonly format: typeof TAVERN_CAUSAL_AUDIT_TASK_STORE_FORMAT;
  readonly schema_version: typeof TAVERN_CAUSAL_AUDIT_TASK_STORE_VERSION;
  readonly memory_set_id: string;
  readonly execution_preference: TavernCausalAuditExecutionPreference;
  readonly tasks: readonly TavernCausalAuditTaskStateRecord[];
  readonly checksum: string;
}

export interface TavernCausalAuditTaskStoreReconcileRequest {
  readonly expected_checksum: string;
  readonly current_seeds: readonly TavernCausalAuditTaskSeed[];
  readonly priority: TavernCausalAuditTaskPriority;
  readonly task_budget: TavernCausalAuditTaskBudget;
  readonly execution_preference: TavernCausalAuditExecutionPreference;
  readonly max_terminal_history: number;
  readonly reconciled_at: string;
}

export interface TavernCausalAuditTaskStoreReconcileResult {
  readonly payload: TavernCausalAuditTaskStorePayload;
  readonly created_task_seed_ids: readonly string[];
  readonly stale_task_seed_ids: readonly string[];
  readonly recovered_task_seed_ids: readonly string[];
  readonly suppressed_task_seed_ids: readonly string[];
  readonly pruned_terminal_task_seed_ids: readonly string[];
}

export interface ClaimTavernCausalAuditTaskRequest {
  readonly expected_checksum: string;
  readonly worker_id: string;
  readonly claimed_at: string;
  readonly execution_trigger: "manual" | "idle_opt_in";
}

export type ClaimTavernCausalAuditTaskResult =
  | {
      readonly status: "claimed";
      readonly payload: TavernCausalAuditTaskStorePayload;
      readonly task: TavernCausalAuditTaskStateRecord;
    }
  | { readonly status: "none"; readonly payload: TavernCausalAuditTaskStorePayload };

export interface TavernCausalAuditAttemptUsage {
  readonly model_calls: number;
  readonly tool_calls: number;
  readonly input_tokens: number;
}

export type TavernCausalAuditAttemptOutcome =
  | Extract<
      TavernCausalAuditTaskResolution,
      { readonly kind: "candidate_proposed" | "no_supported_causal" | "unresolved" }
    >
  | { readonly kind: "retryable_failure"; readonly error_code: string };

export interface CompleteTavernCausalAuditTaskRequest {
  readonly expected_checksum: string;
  readonly task_seed_id: string;
  readonly lease_id: string;
  readonly current_seed: TavernCausalAuditTaskSeed | null;
  readonly completed_at: string;
  readonly usage: TavernCausalAuditAttemptUsage;
  readonly outcome: TavernCausalAuditAttemptOutcome;
}

export type CompleteTavernCausalAuditTaskResult = {
  readonly status:
    | "completed"
    | "proposal_pending_validation"
    | "retry_pending"
    | "failed"
    | "stale";
  readonly payload: TavernCausalAuditTaskStorePayload;
  readonly task: TavernCausalAuditTaskStateRecord;
};

export interface FinalizeTavernCausalAuditCandidateRequest {
  readonly expected_checksum: string;
  readonly expected_record_version: number;
  readonly task_seed_id: string;
  readonly current_seed: TavernCausalAuditTaskSeed | null;
  readonly finalized_at: string;
  readonly outcome:
    | {
        readonly kind: "accepted";
        readonly authorized_changeset_id: NarraMemId<"change_set">;
      }
    | {
        readonly kind: "rejected";
        readonly error_code: string;
        readonly retryable: boolean;
      };
}

export type FinalizeTavernCausalAuditCandidateResult = {
  readonly status: "resolved" | "retry_pending" | "failed" | "stale";
  readonly payload: TavernCausalAuditTaskStorePayload;
  readonly task: TavernCausalAuditTaskStateRecord;
};

export class TavernCausalAuditTaskStoreError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "STORE_NOT_FOUND"
      | "STORE_CORRUPT"
      | "WRITE_CONFLICT"
      | "TASK_NOT_FOUND"
      | "LEASE_MISMATCH"
      | "RECORD_VERSION_MISMATCH",
    message: string,
  ) {
    super(message);
    this.name = "TavernCausalAuditTaskStoreError";
  }
}
