const TASK_PRIORITY_RANK = { low: 0, normal: 1, high: 2, critical: 3 } as const;

export interface TavernCausalAuditManualTaskCandidate {
  readonly task_seed_id: string;
  readonly status: string;
  readonly priority: keyof typeof TASK_PRIORITY_RANK;
  readonly created_at: string;
  readonly usage: { readonly attempts_used: number };
  readonly budget: { readonly max_attempts: number };
}

export interface TavernCausalAuditExecutionPreferenceLike {
  readonly activation_mode: "disabled" | "manual" | "idle_opt_in";
  readonly unattended_opt_in_acknowledged: boolean;
  readonly updated_at: string;
}

/** Keeps an already-manual durable preference byte-stable across observational preflights. */
export function selectTavernCausalAuditManualPreference(
  existing: TavernCausalAuditExecutionPreferenceLike | null,
  updatedAt: string,
): TavernCausalAuditExecutionPreferenceLike {
  if (existing?.activation_mode === "manual" && existing.unattended_opt_in_acknowledged === false) {
    return existing;
  }
  return {
    activation_mode: "manual",
    unattended_opt_in_acknowledged: false,
    updated_at: updatedAt,
  };
}

/** Mirrors the frozen Task Store claim order without mutating its historical implementation. */
export function selectNextTavernCausalAuditManualTaskSeed(
  tasks: readonly TavernCausalAuditManualTaskCandidate[],
): string | null {
  return (
    [...tasks]
      .filter(
        (task) => task.status === "pending" && task.usage.attempts_used < task.budget.max_attempts,
      )
      .sort(
        (left, right) =>
          TASK_PRIORITY_RANK[right.priority] - TASK_PRIORITY_RANK[left.priority] ||
          left.created_at.localeCompare(right.created_at) ||
          left.task_seed_id.localeCompare(right.task_seed_id),
      )[0]?.task_seed_id ?? null
  );
}
