import { createWireSchemaReference } from "./wire-schema-catalog.js";
import { validateWireValue, type WireValidationResult } from "./wire-schema-registry.js";

export const CHANGE_SET_PROPOSAL_ENVELOPE_SCHEMA = createWireSchemaReference("change_set_proposal");

export type EnvelopeValidationResult = WireValidationResult;

export function validateChangeSetProposalEnvelope(value: unknown): EnvelopeValidationResult {
  return validateWireValue("change_set_proposal", value);
}
