export const TAVERN_CAUSAL_AUDIT_INVESTIGATION_HARNESS_VERSION = "0.1.0" as const;
export const TAVERN_CAUSAL_AUDIT_INVESTIGATION_VERSION = "0.2.0" as const;

export interface TavernCausalAuditInvestigationHarnessOptions {
  /** This slice has no scheduler. Explicit acknowledgement prevents accidental auto-start. */
  readonly activation: "manual_readonly_test_only";
  readonly max_steps: number;
  readonly limits: InvestigationRuntimeLimits;
}

type DecodedRecords = {
  readonly memorySpaces: readonly MemorySpace[];
  readonly sourceRevisions: readonly SourceRevision[];
  readonly evidence: readonly EvidenceItem[];
  readonly scenes: readonly Scene[];
  readonly episodes: readonly Episode[];
  readonly events: readonly EventAtom[];
  readonly stateAssertions: readonly StateAssertion[];
  readonly stateDeltas: readonly StateDelta[];
  readonly propositions: readonly Proposition[];
  readonly epistemicStates: readonly EpistemicState[];
  readonly causalLinks: readonly CausalLink[];
  readonly narrativeThreads: readonly NarrativeThread[];
  readonly futureImpacts: readonly FutureImpact[];
};

const CORE_RECORD_KINDS = {
  core_memory_space_v1: ["memory_space", "memorySpaces", "memory_space_id"],
  core_source_revision_v1: ["source_revision", "sourceRevisions", "revision_id"],
  core_evidence_v1: ["evidence_item", "evidence", "evidence_id"],
  core_scene_v1: ["scene", "scenes", "scene_id"],
  core_episode_v1: ["episode", "episodes", "episode_id"],
  core_event_v1: ["event_atom", "events", "event_id"],
  core_state_assertion_v1: ["state_assertion", "stateAssertions", "assertion_id"],
  core_state_delta_v1: ["state_delta", "stateDeltas", "delta_id"],
  core_proposition_v1: ["proposition", "propositions", "proposition_id"],
  core_epistemic_state_v1: ["epistemic_state", "epistemicStates", "epistemic_id"],
  core_causal_link_v1: ["causal_link", "causalLinks", "causal_id"],
  core_narrative_thread_v1: ["narrative_thread", "narrativeThreads", "thread_id"],
  core_future_impact_v1: ["future_impact", "futureImpacts", "impact_id"],
} as const satisfies Readonly<
  Record<string, readonly [WireSchemaName, keyof DecodedRecords, string]>
>;

function payloadRecordId(value: unknown, idField: string): string | undefined {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return undefined;
  const id = (value as Readonly<Record<string, unknown>>)[idField];
  return typeof id === "string" ? id : undefined;
}

function decodeCoreRecords(records: readonly TavernArchiveRecord[]): DecodedRecords {
  const decoded: Record<keyof DecodedRecords, unknown[]> = {
    memorySpaces: [],
    sourceRevisions: [],
    evidence: [],
    scenes: [],
    episodes: [],
    events: [],
    stateAssertions: [],
    stateDeltas: [],
    propositions: [],
    epistemicStates: [],
    causalLinks: [],
    narrativeThreads: [],
    futureImpacts: [],
  };
  const seen = new Set<string>();
  for (const record of records) {
    const descriptor = Object.hasOwn(CORE_RECORD_KINDS, record.record_kind)
      ? CORE_RECORD_KINDS[record.record_kind as keyof typeof CORE_RECORD_KINDS]
      : undefined;
    if (descriptor === undefined) continue;
    if (seen.has(record.record_id)) {
      throw new TypeError(`Tavern Agent archive duplicates a Core record: ${record.record_id}`);
    }
    const [schemaName, collection, idField] = descriptor;
    const wire = validateWireValue(schemaName, record.payload);
    if (!wire.valid || payloadRecordId(record.payload, idField) !== record.record_id) {
      throw new TypeError(`Tavern Agent archive contains invalid ${record.record_kind}`);
    }
    seen.add(record.record_id);
    decoded[collection].push(record.payload);
  }
  return decoded as unknown as DecodedRecords;
}

export async function createTavernCausalAuditReadonlyCorpus(
  seed: TavernCausalAuditTaskSeed,
  records: readonly TavernArchiveRecord[],
): Promise<ReadonlyMemoryCorpus> {
  const decoded = decodeCoreRecords(records);
  const memorySpaces = decoded.memorySpaces.filter(
    (memorySpace) =>
      memorySpace.host_kind === "tavern" &&
      memorySpace.active_source_revision_id === seed.source_revision_id,
  );
  const revisions = decoded.sourceRevisions.filter(
    (revision) => revision.revision_id === seed.source_revision_id && revision.status === "active",
  );
  const memorySpace = memorySpaces[0];
  const revision = revisions[0];
  if (
    memorySpaces.length !== 1 ||
    revisions.length !== 1 ||
    memorySpace === undefined ||
    revision === undefined ||
    revision.memory_space_id !== memorySpace.memory_space_id ||
    revision.branch_id !== memorySpace.branch_id
  ) {
    throw new TypeError("Tavern Agent archive does not contain one exact active Core scope");
  }
  const archiveFingerprint = await sha256HexUtf8(
    canonicalJson({
      harness_version: TAVERN_CAUSAL_AUDIT_INVESTIGATION_HARNESS_VERSION,
      task_seed_id: seed.task_seed_id,
      memory_set_id: seed.memory_set_id,
      source_revision_id: seed.source_revision_id,
      source_checksum: seed.source_checksum,
      semantic_task_fingerprint: seed.semantic_task_fingerprint,
      core_records: records
        .filter((record) => Object.hasOwn(CORE_RECORD_KINDS, record.record_kind))
        .map((record) => ({
          record_id: record.record_id,
          record_kind: record.record_kind,
          payload: record.payload,
        }))
        .sort((left, right) => left.record_id.localeCompare(right.record_id)),
    }),
  );
  return {
    memory_space_id: memorySpace.memory_space_id,
    branch_id: memorySpace.branch_id,
    snapshot_revision_id: revision.revision_id,
    snapshot_fingerprint: createSha256Digest(archiveFingerprint),
    evidence_items: decoded.evidence,
    scenes: decoded.scenes,
    episodes: decoded.episodes,
    events: decoded.events,
    state_assertions: decoded.stateAssertions,
    state_deltas: decoded.stateDeltas,
    propositions: decoded.propositions,
    epistemic_states: decoded.epistemicStates,
    causal_links: decoded.causalLinks,
    narrative_threads: decoded.narrativeThreads,
    future_impacts: decoded.futureImpacts,
  };
}

function corpusPorts(): ReadonlyMemoryCorpusPorts {
  return {
    hash_text: async (text) => createSha256Digest(await sha256HexUtf8(text)),
  };
}

export class TavernCausalAuditReadonlyInvestigationHarness {
  readonly harness_version = TAVERN_CAUSAL_AUDIT_INVESTIGATION_HARNESS_VERSION;
  readonly execution_policy = "manual_readonly_test_only" as const;
  readonly persistent_state_unchanged = true as const;
  readonly seed: TavernCausalAuditTaskSeed;
  readonly frozen_corpus: ReadonlyMemoryCorpus;
  private readonly runtimePorts: ReturnType<typeof createReadonlyMemoryCorpusRuntimePorts>;
  private transcriptValue: InvestigationTranscript;

  private constructor(
    seed: TavernCausalAuditTaskSeed,
    corpus: ReadonlyMemoryCorpus,
    investigationId: InvestigationTranscript["investigation_id"],
    options: TavernCausalAuditInvestigationHarnessOptions,
  ) {
    this.seed = seed;
    this.frozen_corpus = corpus;
    const ports = corpusPorts();
    this.runtimePorts = createReadonlyMemoryCorpusRuntimePorts(corpus, ports);
    this.transcriptValue = createInvestigationTranscript({
      investigation_id: investigationId,
      control: {
        trust_boundary: "trusted_control",
        snapshot_revision_id: corpus.snapshot_revision_id,
        allowed_tools: getReadonlyMemoryCorpusToolNames(corpus, ports),
        max_steps: options.max_steps,
        memory_space_id: corpus.memory_space_id,
        branch_id: corpus.branch_id,
      },
      snapshot_fingerprint: corpus.snapshot_fingerprint,
      limits: options.limits,
    });
  }

  static async create(
    seed: TavernCausalAuditTaskSeed,
    records: readonly TavernArchiveRecord[],
    options: TavernCausalAuditInvestigationHarnessOptions,
  ): Promise<TavernCausalAuditReadonlyInvestigationHarness> {
    if (options.activation !== "manual_readonly_test_only") {
      throw new TypeError("Tavern Causal Audit Agent remains unscheduled");
    }
    const corpus = await createTavernCausalAuditReadonlyCorpus(seed, records);
    const investigationId = await createDeterministicNarraMemId(
      "investigation",
      `causal-audit-harness:${seed.task_seed_id}`,
    );
    return new TavernCausalAuditReadonlyInvestigationHarness(
      seed,
      corpus,
      investigationId,
      options,
    );
  }

  get transcript(): InvestigationTranscript {
    return this.transcriptValue;
  }

  async execute(
    action: unknown,
    currentSeed: TavernCausalAuditTaskSeed,
    currentRecords: readonly TavernArchiveRecord[],
    signal?: AbortSignal,
  ): Promise<InvestigationStepResult> {
    const currentCorpus = await createTavernCausalAuditReadonlyCorpus(currentSeed, currentRecords);
    const identity =
      currentSeed.memory_set_id === this.seed.memory_set_id &&
      currentSeed.task_seed_id === this.seed.task_seed_id
        ? {
            revision_id: currentCorpus.snapshot_revision_id,
            fingerprint: currentCorpus.snapshot_fingerprint,
          }
        : {
            revision_id: currentCorpus.snapshot_revision_id,
            fingerprint: createSha256Digest(
              await sha256HexUtf8("tavern-investigation-foreign-seed"),
            ),
          };
    const result = await executeInvestigationStep(
      this.transcriptValue,
      action,
      identity,
      this.runtimePorts,
      signal,
    );
    if (result.status !== "rejected") this.transcriptValue = result.transcript;
    return result;
  }
}

export interface TavernCausalAuditInvestigationOptions {
  readonly max_steps: number;
  readonly limits: InvestigationRuntimeLimits;
}

export interface TavernCausalAuditInvestigationSelection {
  readonly reviewed_record_refs: readonly NarraMemId[];
  readonly reviewed_evidence_refs: readonly NarraMemId<"evidence">[];
}

export async function deriveTavernCausalAuditSelectionFromTranscript(
  transcript: InvestigationTranscript,
): Promise<TavernCausalAuditInvestigationSelection> {
  const issues = await verifyInvestigationTranscript(transcript, async (text) =>
    createSha256Digest(await sha256HexUtf8(text)),
  );
  if (issues.length > 0) {
    throw new TypeError(
      `Cannot derive Tavern Candidate selection from invalid transcript: ${issues[0]?.code}`,
    );
  }
  const recordRefs = transcript.steps.flatMap((step) =>
    step.kind === "tool" && step.observation.status === "ok"
      ? step.observation.returned_record_refs
      : [],
  );
  const evidenceRefs = transcript.steps.flatMap((step) =>
    step.kind === "tool" && step.observation.status === "ok"
      ? step.observation.returned_evidence_refs
      : [],
  );
  const candidateKinds = new Set([
    "event",
    "state_assertion",
    "state_delta",
    "epistemic_state",
    "proposition",
    "narrative_thread",
  ]);
  return {
    reviewed_record_refs: [...new Set(recordRefs)]
      .filter((id) => {
        const kind = getNarraMemIdKind(id);
        return kind !== undefined && candidateKinds.has(kind);
      })
      .sort(),
    reviewed_evidence_refs: [...new Set(evidenceRefs)].sort(),
  };
}

/** Production read-only investigation. Scheduling authorization remains in the Task Store claim. */
export class TavernCausalAuditReadonlyInvestigation {
  readonly investigation_version = TAVERN_CAUSAL_AUDIT_INVESTIGATION_VERSION;
  readonly seed: TavernCausalAuditTaskSeed;
  readonly frozen_corpus: ReadonlyMemoryCorpus;
  private readonly runtimePorts: ReturnType<typeof createReadonlyMemoryCorpusRuntimePorts>;
  private transcriptValue: InvestigationTranscript;

  private constructor(
    seed: TavernCausalAuditTaskSeed,
    corpus: ReadonlyMemoryCorpus,
    investigationId: InvestigationTranscript["investigation_id"],
    options: TavernCausalAuditInvestigationOptions,
  ) {
    this.seed = seed;
    this.frozen_corpus = corpus;
    const ports = corpusPorts();
    this.runtimePorts = createReadonlyMemoryCorpusRuntimePorts(corpus, ports);
    const remainingToolCalls = options.limits.max_tool_calls;
    if (
      !Number.isSafeInteger(options.max_steps) ||
      options.max_steps < 1 ||
      options.max_steps > 64 ||
      !Number.isSafeInteger(remainingToolCalls) ||
      remainingToolCalls < 0 ||
      remainingToolCalls > options.max_steps
    ) {
      throw new TypeError("Invalid production Tavern investigation bounds");
    }
    this.transcriptValue = createInvestigationTranscript({
      investigation_id: investigationId,
      control: {
        trust_boundary: "trusted_control",
        snapshot_revision_id: corpus.snapshot_revision_id,
        allowed_tools: getReadonlyMemoryCorpusToolNames(corpus, ports),
        max_steps: options.max_steps,
        memory_space_id: corpus.memory_space_id,
        branch_id: corpus.branch_id,
      },
      snapshot_fingerprint: corpus.snapshot_fingerprint,
      limits: options.limits,
    });
  }

  static async create(
    seed: TavernCausalAuditTaskSeed,
    task: TavernCausalAuditTaskStateRecord,
    records: readonly TavernArchiveRecord[],
    options: TavernCausalAuditInvestigationOptions,
  ): Promise<TavernCausalAuditReadonlyInvestigation> {
    if (
      task.status !== "leased" ||
      task.lease === undefined ||
      task.task_seed_id !== seed.task_seed_id ||
      task.source_revision_id !== seed.source_revision_id ||
      task.source_checksum !== seed.source_checksum ||
      task.semantic_task_fingerprint !== seed.semantic_task_fingerprint ||
      task.source_response_sha256 !== seed.source_response_sha256 ||
      task.finding_policy_version !== seed.policy_version
    ) {
      throw new TypeError("Production Tavern investigation requires the exact leased seed");
    }
    const corpus = await createTavernCausalAuditReadonlyCorpus(seed, records);
    return new TavernCausalAuditReadonlyInvestigation(
      seed,
      corpus,
      await createTavernCausalAuditAgentTaskId(seed),
      options,
    );
  }

  get transcript(): InvestigationTranscript {
    return this.transcriptValue;
  }

  async execute(
    action: unknown,
    currentSeed: TavernCausalAuditTaskSeed | null,
    currentRecords: readonly TavernArchiveRecord[],
    signal?: AbortSignal,
  ): Promise<InvestigationStepResult> {
    const exactSeed =
      currentSeed !== null &&
      currentSeed.memory_set_id === this.seed.memory_set_id &&
      currentSeed.task_seed_id === this.seed.task_seed_id &&
      currentSeed.source_checksum === this.seed.source_checksum &&
      currentSeed.semantic_task_fingerprint === this.seed.semantic_task_fingerprint;
    const currentCorpus = exactSeed
      ? await createTavernCausalAuditReadonlyCorpus(currentSeed, currentRecords)
      : null;
    const identity =
      currentCorpus === null
        ? {
            revision_id: this.frozen_corpus.snapshot_revision_id,
            fingerprint: createSha256Digest(
              await sha256HexUtf8("tavern-investigation-foreign-or-stale-seed"),
            ),
          }
        : {
            revision_id: currentCorpus.snapshot_revision_id,
            fingerprint: currentCorpus.snapshot_fingerprint,
          };
    const result = await executeInvestigationStep(
      this.transcriptValue,
      action,
      identity,
      this.runtimePorts,
      signal,
    );
    if (result.status !== "rejected") this.transcriptValue = result.transcript;
    return result;
  }
}
