import type {
  CausalCauseRef,
  CausalEffectRef,
  InvestigationAction,
  InvestigationTranscript,
  JsonValue,
  NarraMemId,
} from "@narramem/core-domain";

import type { ReadonlyMemoryCorpus } from "./memory-corpus.js";
import type { CausalAuditAgentTaskSeed } from "./model-turn.js";
import { canonicalInvestigationJson } from "./transcript.js";

export const CAUSAL_AUDIT_PROGRESSIVE_FRONTIER_VERSION = "0.1.0" as const;
export const CAUSAL_AUDIT_PROGRESSIVE_FRONTIER_MAX_ACTIONS = 24 as const;

type CorpusRecord =
  | ReadonlyMemoryCorpus["scenes"][number]
  | ReadonlyMemoryCorpus["episodes"][number]
  | ReadonlyMemoryCorpus["events"][number]
  | ReadonlyMemoryCorpus["state_assertions"][number]
  | ReadonlyMemoryCorpus["state_deltas"][number]
  | ReadonlyMemoryCorpus["propositions"][number]
  | ReadonlyMemoryCorpus["epistemic_states"][number]
  | ReadonlyMemoryCorpus["causal_links"][number]
  | ReadonlyMemoryCorpus["narrative_threads"][number]
  | ReadonlyMemoryCorpus["future_impacts"][number];

function recordId(record: CorpusRecord): NarraMemId {
  if ("scene_id" in record) return record.scene_id;
  if ("episode_id" in record) return record.episode_id;
  if ("event_id" in record) return record.event_id;
  if ("assertion_id" in record) return record.assertion_id;
  if ("delta_id" in record) return record.delta_id;
  if ("proposition_id" in record) return record.proposition_id;
  if ("epistemic_id" in record) return record.epistemic_id as NarraMemId<"epistemic_state">;
  if ("causal_id" in record) return record.causal_id;
  if ("thread_id" in record) return record.thread_id;
  return record.impact_id;
}

function allRecords(corpus: ReadonlyMemoryCorpus): readonly CorpusRecord[] {
  return [
    ...corpus.scenes,
    ...corpus.episodes,
    ...corpus.events,
    ...corpus.state_assertions,
    ...corpus.state_deltas,
    ...corpus.propositions,
    ...corpus.epistemic_states,
    ...corpus.causal_links,
    ...corpus.narrative_threads,
    ...corpus.future_impacts,
  ];
}

function actionKey(action: InvestigationAction): string {
  return canonicalInvestigationJson(action as unknown as JsonValue);
}

function episodeRelatedRecordIds(
  episode: ReadonlyMemoryCorpus["episodes"][number],
): readonly NarraMemId[] {
  return [
    episode.episode_id,
    ...episode.scene_ids,
    ...episode.event_ids,
    ...episode.context.before_state_refs,
    ...(episode.context.goal_state_refs ?? []),
    ...episode.outcome_refs,
    ...episode.causal_refs,
    ...episode.narrative_thread_refs,
  ];
}

function causalReference(
  record: CorpusRecord,
): Exclude<CausalCauseRef | CausalEffectRef, { readonly kind: "condition" }> | undefined {
  if ("event_id" in record) return { kind: "event", event_id: record.event_id };
  if ("assertion_id" in record) {
    return { kind: "state_assertion", assertion_id: record.assertion_id };
  }
  if ("delta_id" in record) return { kind: "state_delta", delta_id: record.delta_id };
  if ("epistemic_id" in record) {
    return { kind: "epistemic_state", epistemic_id: record.epistemic_id };
  }
  if ("proposition_id" in record) {
    return { kind: "proposition", proposition_id: record.proposition_id };
  }
  if ("thread_id" in record) {
    return { kind: "narrative_thread", thread_id: record.thread_id };
  }
  return undefined;
}

function stableJson(value: unknown): string {
  return canonicalInvestigationJson(value as JsonValue);
}

/**
 * Builds a bounded, relevance-frontier action catalog without reading a Gold decision or a scripted
 * action. The frontier grows only from task anchors and records/evidence returned by the verified
 * transcript, so a large unrelated Evidence corpus cannot crowd out later investigation tools.
 */
export function enumerateCausalAuditProgressiveFrontierActions(
  corpus: ReadonlyMemoryCorpus,
  task: CausalAuditAgentTaskSeed,
  transcript: InvestigationTranscript,
): readonly InvestigationAction[] {
  if (transcript.status !== "investigating") {
    throw new TypeError("Progressive Causal Audit frontier requires an investigating transcript");
  }
  if (
    task.task_id !== transcript.investigation_id ||
    task.source_revision_id !== transcript.control.snapshot_revision_id ||
    corpus.snapshot_revision_id !== transcript.control.snapshot_revision_id
  ) {
    throw new TypeError("Progressive Causal Audit frontier scope does not match the transcript");
  }

  const allowed = new Set(transcript.control.allowed_tools);
  const priorActionKeys = new Set(transcript.steps.map((step) => actionKey(step.action)));
  const selected = new Map<string, InvestigationAction>();
  const add = (action: InvestigationAction) => {
    const key = actionKey(action);
    if (priorActionKeys.has(key) || selected.has(key)) return;
    selected.set(key, action);
  };
  const addBounded = (actions: readonly InvestigationAction[], maximum: number) => {
    for (const action of [...actions]
      .sort((left, right) => actionKey(left).localeCompare(actionKey(right)))
      .slice(0, maximum)) {
      add(action);
    }
  };

  add({ tool: "stop", reason: "sufficient_evidence" });
  add({ tool: "stop", reason: "no_progress" });

  const observations = transcript.steps.flatMap((step) =>
    step.kind === "tool" ? [step.observation] : [],
  );
  const reviewedRecordIds = new Set<NarraMemId>([
    ...task.seed_record_refs,
    ...observations.flatMap((observation) => observation.returned_record_refs),
  ]);
  const reviewedEvidenceIds = new Set<NarraMemId<"evidence">>([
    ...task.seed_evidence_refs,
    ...observations.flatMap((observation) => observation.returned_evidence_refs),
  ]);
  const records = allRecords(corpus);
  const recordsById = new Map(records.map((record) => [recordId(record), record]));
  const reviewedRecords = [...reviewedRecordIds]
    .flatMap((id) => {
      const record = recordsById.get(id);
      return record === undefined ? [] : [record];
    })
    .sort((left, right) => recordId(left).localeCompare(recordId(right)));

  const completeContradictions = (corpus.contradiction_notices ?? []).filter(
    (notice) =>
      notice.record_refs.length > 0 &&
      notice.record_refs.every((recordReference) => reviewedRecordIds.has(recordReference)),
  );

  const relevantEpisodes = corpus.episodes.filter((episode) => {
    const recordOverlap = episodeRelatedRecordIds(episode).some((id) => reviewedRecordIds.has(id));
    const evidenceOverlap = episode.evidence.some((span) =>
      reviewedEvidenceIds.has(span.evidence_id),
    );
    return recordOverlap || evidenceOverlap;
  });
  if (allowed.has("get_episode_context") && completeContradictions.length === 0) {
    addBounded(
      relevantEpisodes.map((episode) => ({
        tool: "get_episode_context" as const,
        episode_id: episode.episode_id,
      })),
      4,
    );
  }

  if (allowed.has("find_contradictions")) {
    const exactContradictionActions = completeContradictions.map((notice) => ({
      tool: "find_contradictions" as const,
      record_refs: notice.record_refs,
    }));
    if (exactContradictionActions.length > 0) {
      addBounded(exactContradictionActions, 2);
    } else if (
      relevantEpisodes.every((episode) =>
        priorActionKeys.has(
          actionKey({ tool: "get_episode_context", episode_id: episode.episode_id }),
        ),
      )
    ) {
      const eligibleIds = reviewedRecords
        .map((record) => causalReference(record))
        .filter((reference) => reference !== undefined)
        .map((reference) => {
          if (reference.kind === "event") return reference.event_id;
          if (reference.kind === "state_assertion") return reference.assertion_id;
          if (reference.kind === "state_delta") return reference.delta_id;
          if (reference.kind === "epistemic_state") return reference.epistemic_id;
          if (reference.kind === "proposition") return reference.proposition_id;
          return reference.thread_id;
        })
        .slice(0, 16);
      if (eligibleIds.length > 0) {
        add({ tool: "find_contradictions", record_refs: eligibleIds });
      }
    }
  }

  if (allowed.has("get_state_as_of")) {
    const groups = new Map<
      string,
      {
        subject: ReadonlyMemoryCorpus["state_assertions"][number]["subject"];
        stateKeys: Set<string>;
      }
    >();
    for (const record of reviewedRecords) {
      if (!("assertion_id" in record) && !("delta_id" in record)) continue;
      const key = stableJson(record.subject);
      const existing = groups.get(key) ?? { subject: record.subject, stateKeys: new Set<string>() };
      existing.stateKeys.add(record.state_key);
      groups.set(key, existing);
    }
    addBounded(
      [...groups.values()].map((group) => ({
        tool: "get_state_as_of" as const,
        subject: group.subject,
        state_keys: [...group.stateKeys].sort(),
      })),
      2,
    );
  }

  if (allowed.has("get_epistemic_state")) {
    const groups = new Map<
      string,
      {
        holder: ReadonlyMemoryCorpus["epistemic_states"][number]["holder"];
        propositionIds: Set<NarraMemId<"proposition">>;
      }
    >();
    for (const record of reviewedRecords) {
      if (!("epistemic_id" in record)) continue;
      const key = stableJson(record.holder);
      const existing = groups.get(key) ?? {
        holder: record.holder,
        propositionIds: new Set<NarraMemId<"proposition">>(),
      };
      existing.propositionIds.add(record.proposition_id);
      groups.set(key, existing);
    }
    addBounded(
      [...groups.values()].map((group) => ({
        tool: "get_epistemic_state" as const,
        holder: group.holder,
        proposition_ids: [...group.propositionIds].sort(),
      })),
      2,
    );
  }

  if (allowed.has("inspect_thread")) {
    addBounded(
      reviewedRecords.flatMap((record) =>
        "thread_id" in record
          ? [{ tool: "inspect_thread" as const, thread_id: record.thread_id }]
          : [],
      ),
      2,
    );
  }

  if (allowed.has("evaluate_trigger")) {
    addBounded(
      reviewedRecords.flatMap((record) =>
        "impact_id" in record
          ? [{ tool: "evaluate_trigger" as const, impact_id: record.impact_id }]
          : [],
      ),
      2,
    );
  }

  if (allowed.has("read_evidence_spans")) {
    const evidenceActions = corpus.evidence_items.flatMap((evidence) => {
      if (!reviewedEvidenceIds.has(evidence.evidence_id) || evidence.raw_content.kind !== "text") {
        return [];
      }
      const length = [...evidence.raw_content.text].length;
      if (length === 0) return [];
      return [
        {
          tool: "read_evidence_spans" as const,
          spans: [
            {
              evidence_id: evidence.evidence_id,
              selector: {
                kind: "text_range" as const,
                start_code_point: 0,
                end_code_point: length,
              },
              quote_hash: evidence.content_fingerprint,
              support_role: "context" as const,
            },
          ],
        },
      ];
    });
    addBounded(evidenceActions, 4);
  }

  if (allowed.has("follow_causal_links")) {
    const traversalActions = reviewedRecords.flatMap((record): InvestigationAction[] => {
      const reference = causalReference(record);
      if (reference === undefined) return [];
      return [
        { tool: "follow_causal_links", from: reference, direction: "predecessors", max_depth: 1 },
        { tool: "follow_causal_links", from: reference, direction: "successors", max_depth: 1 },
      ];
    });
    addBounded(traversalActions, 4);
  }

  const actions = [...selected.values()];
  if (actions.length > CAUSAL_AUDIT_PROGRESSIVE_FRONTIER_MAX_ACTIONS) {
    throw new TypeError("Progressive Causal Audit frontier exceeded its fixed action budget");
  }
  return actions;
}
