import type { FlatNarrativeLifecycleDraftV020 } from "@narramem/core-domain";

import type { TavernRuntimePromptAsset } from "./extraction-job-contracts.js";
import type {
  TavernNarrativeLifecycleCommitResult,
  TavernNarrativeLifecycleSpec,
} from "./narrative-lifecycle-contracts.js";

export const TAVERN_NARRATIVE_LIFECYCLE_JOB_VERSION = "0.2.0" as const;

export interface TavernNarrativeLifecycleJobRequest {
  readonly job_id: string;
  /** Optional safe token that creates a new durable user-requested attempt round. */
  readonly retry_round_id?: string;
  readonly requested_model_id: string;
  readonly proxy_preset?: string;
  readonly runtime_prompt_assets: readonly TavernRuntimePromptAsset[];
  readonly allow_candidate_prompt: boolean;
  readonly max_attempts?: number;
  readonly compiled_at: string;
  readonly writer_id: string;
  readonly build_id: string;
}

export interface TavernNarrativeLifecycleJobAudit {
  readonly job_version: typeof TAVERN_NARRATIVE_LIFECYCLE_JOB_VERSION;
  readonly job_id: string;
  readonly adapter_id: string;
  readonly requested_model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_asset_ref: string;
  readonly prompt_body_sha256: string;
  readonly input_schema: "flat_narrative_lifecycle_model_input_v020";
  readonly output_schema: "flat_narrative_lifecycle_draft_v020";
  readonly parameters_sha256: string;
  readonly max_attempts: number;
}

export type TavernNarrativeLifecycleJobResult =
  | {
      readonly status: "ALREADY_CURRENT";
      readonly audit: TavernNarrativeLifecycleJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly lifecycle_task_fingerprint: string;
    }
  | {
      readonly status: "COMMITTED";
      readonly audit: TavernNarrativeLifecycleJobAudit;
      readonly memory_set_id: string;
      readonly source_revision_id: string;
      readonly response_sha256: string;
      readonly response_utf8_bytes: number;
      readonly attempt_count: number;
      readonly draft: FlatNarrativeLifecycleDraftV020;
      readonly spec: TavernNarrativeLifecycleSpec;
      readonly unresolved_item_count: number;
      readonly commit: TavernNarrativeLifecycleCommitResult;
    }
  | {
      readonly status: "CANCELLED" | "SUPERSEDED";
      readonly job_id: string;
      readonly reason: string;
      readonly host_cancel_requested: boolean;
    }
  | {
      readonly status: "STALE";
      readonly job_id: string;
      readonly reason: "STALE_TASK" | "SOURCE_CHANGED_DURING_COMMIT";
    };

export interface TavernNarrativeLifecycleCancellationReport {
  readonly reason: string;
  readonly generation_id: string | null;
  readonly host_cancel_requested: boolean;
}

export class TavernNarrativeLifecycleJobError extends Error {
  constructor(
    readonly code:
      | "INVALID_REQUEST"
      | "UNSUPPORTED_MODEL"
      | "PROMPT_ASSET_INVALID"
      | "CANDIDATE_PROMPT_NOT_ALLOWED"
      | "HOST_GENERATION_UNAVAILABLE"
      | "GENERATION_FAILED"
      | "GENERATION_TOOL_CALLS"
      | "RESPONSE_JSON_INVALID"
      | "RESPONSE_SCHEMA_INVALID"
      | "ATTEMPTS_EXHAUSTED"
      | "ATTEMPT_STATUS_UNKNOWN"
      | "ATTEMPT_LEDGER_BLOCKED",
    message: string,
  ) {
    super(message);
    this.name = "TavernNarrativeLifecycleJobError";
  }
}
