import type { HashDigest } from "@narramem/core-domain";
import { isHashDigest } from "@narramem/core-domain";

export const AGENT_TRANSPORT_OPERATION_VERSION = "0.1.0" as const;

export const AGENT_TRANSPORT_OPERATION_STATUSES = [
  "ready",
  "dispatch_reserved",
  "in_flight",
  "response_attested",
  "awaiting_retry_authorization",
  "suspended_unknown",
  "completed",
  "failed",
  "cancelled",
  "conflicted",
] as const;

export type AgentTransportOperationStatus = (typeof AGENT_TRANSPORT_OPERATION_STATUSES)[number];

export type AgentTransportProviderIdempotency =
  | {
      readonly capability: "provider_attested";
      /** Hash only. A secret or raw provider header value must never enter the ledger. */
      readonly key_sha256: HashDigest;
    }
  | {
      readonly capability: "provider_unverified" | "provider_unsupported";
    };

export interface AgentTransportRequestDescriptor {
  readonly operation_kind: string;
  readonly task_id: string;
  readonly source_revision_id: string;
  readonly scope_fingerprint: HashDigest;
  readonly provider_id: string;
  readonly requested_model_id: string;
  readonly prompt_asset_refs: readonly string[];
  readonly request_sha256: HashDigest;
  readonly request_utf8_bytes: number;
  readonly provider_idempotency: AgentTransportProviderIdempotency;
}

export interface AgentTransportResponseArtifact {
  readonly artifact_ref: string;
  readonly content_sha256: HashDigest;
  readonly utf8_bytes: number;
}

export interface AgentTransportResponseAttestation {
  readonly attestation_id: string;
  readonly attempt_id: string;
  readonly received_at: string;
  readonly transport_kind: "http_response" | "host_generation_result";
  readonly response_artifact: AgentTransportResponseArtifact;
  readonly http_status?: number;
  readonly provider_request_id?: string;
  readonly response_model?: string;
  readonly input_tokens?: number;
  readonly output_tokens?: number;
}

export type AgentTransportAttemptStatus =
  | "dispatch_reserved"
  | "in_flight"
  | "response_attested"
  | "definitive_failure"
  | "unknown_outcome"
  | "response_committed"
  | "response_rejected";

export interface AgentTransportAttemptFailure {
  readonly kind: "definitive_not_dispatched" | "unknown_after_dispatch";
  readonly error_code: string;
  readonly observed_at: string;
}

export interface AgentTransportAttemptRecord {
  readonly attempt_id: string;
  readonly attempt_number: number;
  readonly status: AgentTransportAttemptStatus;
  readonly reserved_at: string;
  readonly dispatched_at?: string;
  readonly failure?: AgentTransportAttemptFailure;
  readonly response_attestations: readonly AgentTransportResponseAttestation[];
  readonly rejection_code?: string;
}

export interface AgentTransportRetryAuthorization {
  readonly authorization_id: string;
  readonly authorizer: "automatic_policy" | "user" | "operator";
  readonly authorized_at: string;
  readonly reason_code: string;
  readonly from_attempt_id: string;
  readonly next_attempt_number: number;
  readonly duplicate_dispatch_risk_acknowledged: boolean;
}

export interface AgentTransportConflict {
  readonly detected_at: string;
  readonly code: "DIVERGENT_ATTESTATION_ID" | "MULTIPLE_DISTINCT_RESPONSES";
  readonly attempt_id: string;
  readonly attestation_ids: readonly string[];
}

export interface AgentTransportOperationRecord {
  readonly contract_version: typeof AGENT_TRANSPORT_OPERATION_VERSION;
  readonly operation_id: string;
  readonly request: AgentTransportRequestDescriptor;
  readonly max_attempts: number;
  readonly status: AgentTransportOperationStatus;
  readonly integrity: "clean" | "conflicted";
  readonly attempts: readonly AgentTransportAttemptRecord[];
  readonly retry_authorizations: readonly AgentTransportRetryAuthorization[];
  readonly conflicts: readonly AgentTransportConflict[];
  readonly selected_attestation_id?: string;
  readonly created_at: string;
  readonly updated_at: string;
  readonly record_version: number;
  readonly terminal_reason?: string;
}

export interface CreateAgentTransportOperationRequest {
  readonly operation_id: string;
  readonly request: AgentTransportRequestDescriptor;
  readonly max_attempts: number;
  readonly created_at: string;
}

export type AgentTransportTransitionStatus =
  | "applied"
  | "duplicate"
  | "late_duplicate"
  | "late_conflict";

export interface AgentTransportTransitionResult {
  readonly status: AgentTransportTransitionStatus;
  readonly operation: AgentTransportOperationRecord;
}

const OPERATION_ID_PATTERN = /^agent_op_[a-f0-9]{64}$/u;
const ATTEMPT_ID_PATTERN = /^agent_attempt_[a-f0-9]{64}$/u;
const ATTESTATION_ID_PATTERN = /^agent_response_[a-f0-9]{64}$/u;
const AUTHORIZATION_ID_PATTERN = /^agent_retry_[a-f0-9]{64}$/u;
const CODE_PATTERN = /^[A-Z][A-Z0-9_]{0,127}$/u;

const clone = <T>(value: T): T => structuredClone(value);

function assertTimestamp(value: string, field: string): void {
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed) || new Date(parsed).toISOString() !== value) {
    throw new TypeError(`${field} must be a canonical UTC ISO timestamp`);
  }
}

function assertBoundedInteger(value: number, field: string, minimum = 0): void {
  if (!Number.isSafeInteger(value) || value < minimum) {
    throw new TypeError(`${field} must be a safe integer >= ${minimum}`);
  }
}

function assertSafeId(value: string, field: string): void {
  const bounded = value.length > 0 && value.length <= 256 && value === value.trim();
  const printable = [...value].every((character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    return codePoint > 0x1f && codePoint !== 0x7f;
  });
  if (!bounded || !printable) throw new TypeError(`${field} must be a bounded exact identifier`);
}

function sameDigest(left: HashDigest, right: HashDigest): boolean {
  return left.algorithm === right.algorithm && left.value === right.value;
}

function sameAttestation(
  left: AgentTransportResponseAttestation,
  right: AgentTransportResponseAttestation,
): boolean {
  return (
    left.attestation_id === right.attestation_id &&
    left.attempt_id === right.attempt_id &&
    left.received_at === right.received_at &&
    left.transport_kind === right.transport_kind &&
    left.response_artifact.artifact_ref === right.response_artifact.artifact_ref &&
    sameDigest(left.response_artifact.content_sha256, right.response_artifact.content_sha256) &&
    left.response_artifact.utf8_bytes === right.response_artifact.utf8_bytes &&
    left.http_status === right.http_status &&
    left.provider_request_id === right.provider_request_id &&
    left.response_model === right.response_model &&
    left.input_tokens === right.input_tokens &&
    left.output_tokens === right.output_tokens
  );
}

function sameResponseContent(
  left: AgentTransportResponseAttestation,
  right: AgentTransportResponseAttestation,
): boolean {
  return (
    sameDigest(left.response_artifact.content_sha256, right.response_artifact.content_sha256) &&
    left.response_artifact.utf8_bytes === right.response_artifact.utf8_bytes
  );
}

function activeAttempt(operation: AgentTransportOperationRecord): AgentTransportAttemptRecord {
  const attempt = operation.attempts.at(-1);
  if (attempt === undefined) throw new TypeError("Agent transport operation has no active attempt");
  return attempt;
}

function replaceAttempt(
  operation: AgentTransportOperationRecord,
  attempt: AgentTransportAttemptRecord,
): readonly AgentTransportAttemptRecord[] {
  return operation.attempts.map((item) =>
    item.attempt_id === attempt.attempt_id ? attempt : item,
  );
}

function update(
  operation: AgentTransportOperationRecord,
  fields: Partial<AgentTransportOperationRecord>,
  at: string,
): AgentTransportOperationRecord {
  const next = {
    ...operation,
    ...fields,
    updated_at: at,
    record_version: operation.record_version + 1,
  };
  assertAgentTransportOperation(next);
  return next;
}

function assertAttestation(attestation: AgentTransportResponseAttestation): void {
  if (
    !ATTESTATION_ID_PATTERN.test(attestation.attestation_id) ||
    !ATTEMPT_ID_PATTERN.test(attestation.attempt_id)
  ) {
    throw new TypeError("Response attestation IDs are invalid");
  }
  assertTimestamp(attestation.received_at, "received_at");
  assertSafeId(attestation.response_artifact.artifact_ref, "artifact_ref");
  if (!isHashDigest(attestation.response_artifact.content_sha256)) {
    throw new TypeError("Response artifact requires a sha256 digest");
  }
  assertBoundedInteger(attestation.response_artifact.utf8_bytes, "response utf8 bytes");
  if (
    attestation.transport_kind === "http_response" &&
    (attestation.http_status === undefined ||
      !Number.isSafeInteger(attestation.http_status) ||
      attestation.http_status < 100 ||
      attestation.http_status > 599)
  ) {
    throw new TypeError("HTTP response attestation requires a valid status");
  }
  if (
    attestation.transport_kind === "host_generation_result" &&
    attestation.http_status !== undefined
  ) {
    throw new TypeError("Host generation attestation must not invent an HTTP status");
  }
  for (const [field, value] of [
    ["provider_request_id", attestation.provider_request_id],
    ["response_model", attestation.response_model],
  ] as const) {
    if (value !== undefined) assertSafeId(value, field);
  }
  for (const [field, value] of [
    ["input_tokens", attestation.input_tokens],
    ["output_tokens", attestation.output_tokens],
  ] as const) {
    if (value !== undefined) assertBoundedInteger(value, field);
  }
}

export function assertAgentTransportOperation(operation: AgentTransportOperationRecord): void {
  if (
    operation.contract_version !== AGENT_TRANSPORT_OPERATION_VERSION ||
    !OPERATION_ID_PATTERN.test(operation.operation_id) ||
    !AGENT_TRANSPORT_OPERATION_STATUSES.includes(operation.status)
  ) {
    throw new TypeError("Invalid Agent transport operation identity or status");
  }
  if (
    !isHashDigest(operation.request.scope_fingerprint) ||
    !isHashDigest(operation.request.request_sha256)
  ) {
    throw new TypeError("Agent transport request requires scope and request digests");
  }
  for (const [field, value] of [
    ["operation_kind", operation.request.operation_kind],
    ["task_id", operation.request.task_id],
    ["source_revision_id", operation.request.source_revision_id],
    ["provider_id", operation.request.provider_id],
    ["requested_model_id", operation.request.requested_model_id],
  ] as const) {
    assertSafeId(value, field);
  }
  if (
    new Set(operation.request.prompt_asset_refs).size !== operation.request.prompt_asset_refs.length
  ) {
    throw new TypeError("Prompt asset references must be unique");
  }
  for (const reference of operation.request.prompt_asset_refs)
    assertSafeId(reference, "prompt_asset_ref");
  assertBoundedInteger(operation.request.request_utf8_bytes, "request_utf8_bytes");
  assertBoundedInteger(operation.max_attempts, "max_attempts", 1);
  if (operation.max_attempts > 100 || operation.attempts.length > operation.max_attempts) {
    throw new TypeError("Agent transport attempt budget is invalid");
  }
  if (
    operation.request.provider_idempotency.capability === "provider_attested" &&
    !isHashDigest(operation.request.provider_idempotency.key_sha256)
  ) {
    throw new TypeError("Attested provider idempotency requires a hashed key");
  }
  assertTimestamp(operation.created_at, "created_at");
  assertTimestamp(operation.updated_at, "updated_at");
  assertBoundedInteger(operation.record_version, "record_version");
  if (operation.integrity === "clean" && operation.conflicts.length > 0) {
    throw new TypeError("A clean transport operation cannot retain conflicts");
  }
  if (operation.integrity === "conflicted" && operation.conflicts.length === 0) {
    throw new TypeError("A conflicted transport operation requires conflict evidence");
  }
  const attemptIds = new Set<string>();
  const attestationIds = new Set<string>();
  for (const [index, attempt] of operation.attempts.entries()) {
    if (
      !ATTEMPT_ID_PATTERN.test(attempt.attempt_id) ||
      attempt.attempt_number !== index + 1 ||
      attemptIds.has(attempt.attempt_id)
    ) {
      throw new TypeError("Transport attempts must have unique sequential identities");
    }
    attemptIds.add(attempt.attempt_id);
    assertTimestamp(attempt.reserved_at, "reserved_at");
    if (attempt.dispatched_at !== undefined)
      assertTimestamp(attempt.dispatched_at, "dispatched_at");
    if (attempt.failure !== undefined) {
      assertTimestamp(attempt.failure.observed_at, "failure.observed_at");
      if (!CODE_PATTERN.test(attempt.failure.error_code)) {
        throw new TypeError("Transport failure requires a bounded error code");
      }
    }
    if (attempt.rejection_code !== undefined && !CODE_PATTERN.test(attempt.rejection_code)) {
      throw new TypeError("Transport response rejection requires a bounded error code");
    }
    for (const attestation of attempt.response_attestations) {
      assertAttestation(attestation);
      if (
        attestation.attempt_id !== attempt.attempt_id ||
        attestationIds.has(attestation.attestation_id)
      ) {
        throw new TypeError("Response attestation is duplicated or bound to the wrong attempt");
      }
      attestationIds.add(attestation.attestation_id);
    }
  }
  for (const [index, authorization] of operation.retry_authorizations.entries()) {
    if (
      !AUTHORIZATION_ID_PATTERN.test(authorization.authorization_id) ||
      authorization.next_attempt_number !== index + 2 ||
      operation.attempts[index]?.attempt_id !== authorization.from_attempt_id ||
      !CODE_PATTERN.test(authorization.reason_code)
    ) {
      throw new TypeError("Retry authorizations must form an exact attempt lineage");
    }
    assertTimestamp(authorization.authorized_at, "authorized_at");
  }
  if (
    operation.selected_attestation_id !== undefined &&
    !attestationIds.has(operation.selected_attestation_id)
  ) {
    throw new TypeError("Selected response attestation does not exist");
  }
  if (operation.status === "completed" && operation.selected_attestation_id === undefined) {
    throw new TypeError("Completed transport operation requires a selected attestation");
  }
}

export function createAgentTransportOperation(
  request: CreateAgentTransportOperationRequest,
): AgentTransportOperationRecord {
  const operation: AgentTransportOperationRecord = {
    contract_version: AGENT_TRANSPORT_OPERATION_VERSION,
    operation_id: request.operation_id,
    request: clone(request.request),
    max_attempts: request.max_attempts,
    status: "ready",
    integrity: "clean",
    attempts: [],
    retry_authorizations: [],
    conflicts: [],
    created_at: request.created_at,
    updated_at: request.created_at,
    record_version: 0,
  };
  assertAgentTransportOperation(operation);
  return operation;
}

export function reserveAgentTransportAttempt(
  operation: AgentTransportOperationRecord,
  request: { readonly attempt_id: string; readonly reserved_at: string },
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(request.reserved_at, "reserved_at");
  if (!ATTEMPT_ID_PATTERN.test(request.attempt_id)) throw new TypeError("Invalid attempt ID");
  const existing = operation.attempts.find((item) => item.attempt_id === request.attempt_id);
  if (existing !== undefined) {
    if (existing.reserved_at !== request.reserved_at)
      throw new TypeError("Attempt ID content drift");
    return { status: "duplicate", operation: clone(operation) };
  }
  if (operation.status !== "ready" || operation.integrity !== "clean") {
    throw new TypeError("Only a clean ready operation can reserve a dispatch attempt");
  }
  const attemptNumber = operation.attempts.length + 1;
  if (attemptNumber > operation.max_attempts)
    throw new TypeError("Transport attempt budget exhausted");
  if (
    attemptNumber > 1 &&
    operation.retry_authorizations.at(-1)?.next_attempt_number !== attemptNumber
  ) {
    throw new TypeError("A retry attempt requires an exact durable authorization");
  }
  const attempt: AgentTransportAttemptRecord = {
    attempt_id: request.attempt_id,
    attempt_number: attemptNumber,
    status: "dispatch_reserved",
    reserved_at: request.reserved_at,
    response_attestations: [],
  };
  const next = update(
    operation,
    { status: "dispatch_reserved", attempts: [...operation.attempts, attempt] },
    request.reserved_at,
  );
  return { status: "applied", operation: next };
}

export function markAgentTransportAttemptDispatched(
  operation: AgentTransportOperationRecord,
  request: { readonly attempt_id: string; readonly dispatched_at: string },
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(request.dispatched_at, "dispatched_at");
  const attempt = activeAttempt(operation);
  if (attempt.attempt_id !== request.attempt_id)
    throw new TypeError("Dispatch attempt is not current");
  if (attempt.status === "in_flight") {
    if (attempt.dispatched_at !== request.dispatched_at)
      throw new TypeError("Dispatch timestamp drift");
    return { status: "duplicate", operation: clone(operation) };
  }
  if (operation.status !== "dispatch_reserved" || attempt.status !== "dispatch_reserved") {
    throw new TypeError("Only a durably reserved attempt can be dispatched");
  }
  const nextAttempt = {
    ...attempt,
    status: "in_flight" as const,
    dispatched_at: request.dispatched_at,
  };
  return {
    status: "applied",
    operation: update(
      operation,
      { status: "in_flight", attempts: replaceAttempt(operation, nextAttempt) },
      request.dispatched_at,
    ),
  };
}

function addConflict(
  operation: AgentTransportOperationRecord,
  attempt: AgentTransportAttemptRecord,
  attestation: AgentTransportResponseAttestation,
  code: AgentTransportConflict["code"],
  appendAttestation = true,
): AgentTransportOperationRecord {
  const nextAttempt = {
    ...attempt,
    response_attestations: appendAttestation
      ? [...attempt.response_attestations, clone(attestation)]
      : attempt.response_attestations,
  };
  const conflict: AgentTransportConflict = {
    detected_at: attestation.received_at,
    code,
    attempt_id: attempt.attempt_id,
    attestation_ids: nextAttempt.response_attestations.map((item) => item.attestation_id).sort(),
  };
  return update(
    operation,
    {
      status: operation.status === "completed" ? "completed" : "conflicted",
      integrity: "conflicted",
      attempts: replaceAttempt(operation, nextAttempt),
      conflicts: [...operation.conflicts, conflict],
    },
    attestation.received_at,
  );
}

export function attestAgentTransportResponse(
  operation: AgentTransportOperationRecord,
  attestation: AgentTransportResponseAttestation,
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertAttestation(attestation);
  const attempt = operation.attempts.find((item) => item.attempt_id === attestation.attempt_id);
  if (attempt === undefined)
    throw new TypeError("Response attestation references an unknown attempt");
  const sameId = operation.attempts
    .flatMap((item) => item.response_attestations)
    .find((item) => item.attestation_id === attestation.attestation_id);
  if (sameId !== undefined) {
    if (!sameAttestation(sameId, attestation)) {
      const next = addConflict(operation, attempt, attestation, "DIVERGENT_ATTESTATION_ID", false);
      return { status: "late_conflict", operation: next };
    }
    return { status: "duplicate", operation: clone(operation) };
  }
  const selected = operation.attempts
    .flatMap((item) => item.response_attestations)
    .find((item) => item.attestation_id === operation.selected_attestation_id);
  if (selected !== undefined) {
    if (sameResponseContent(selected, attestation)) {
      return { status: "late_duplicate", operation: clone(operation) };
    }
    const next = addConflict(operation, attempt, attestation, "MULTIPLE_DISTINCT_RESPONSES");
    return { status: "late_conflict", operation: next };
  }
  const existingDistinct = operation.attempts
    .flatMap((item) => item.response_attestations)
    .find((item) => !sameResponseContent(item, attestation));
  const newerAttemptExists = operation.attempts.some(
    (item) => item.attempt_number > attempt.attempt_number,
  );
  if (existingDistinct !== undefined || newerAttemptExists) {
    const next = addConflict(operation, attempt, attestation, "MULTIPLE_DISTINCT_RESPONSES");
    return { status: "late_conflict", operation: next };
  }
  if (
    attempt.status !== "dispatch_reserved" &&
    attempt.status !== "in_flight" &&
    attempt.status !== "unknown_outcome"
  ) {
    throw new TypeError("Attempt cannot accept a response attestation in its current state");
  }
  const nextAttempt: AgentTransportAttemptRecord = {
    ...attempt,
    status: "response_attested",
    response_attestations: [...attempt.response_attestations, clone(attestation)],
  };
  return {
    status: "applied",
    operation: update(
      operation,
      {
        status: "response_attested",
        attempts: replaceAttempt(operation, nextAttempt),
      },
      attestation.received_at,
    ),
  };
}

export function recordAgentTransportFailure(
  operation: AgentTransportOperationRecord,
  request: {
    readonly attempt_id: string;
    readonly kind: AgentTransportAttemptFailure["kind"];
    readonly error_code: string;
    readonly observed_at: string;
  },
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(request.observed_at, "observed_at");
  if (!CODE_PATTERN.test(request.error_code)) throw new TypeError("Invalid transport error code");
  const attempt = activeAttempt(operation);
  if (attempt.attempt_id !== request.attempt_id)
    throw new TypeError("Failure attempt is not current");
  if (
    attempt.failure?.kind === request.kind &&
    attempt.failure.error_code === request.error_code &&
    attempt.failure.observed_at === request.observed_at
  ) {
    return { status: "duplicate", operation: clone(operation) };
  }
  if (attempt.status !== "dispatch_reserved" && attempt.status !== "in_flight") {
    throw new TypeError("Only an uncompleted dispatch can record a transport failure");
  }
  if (request.kind === "definitive_not_dispatched" && attempt.status !== "dispatch_reserved") {
    throw new TypeError("A dispatched attempt cannot be certified as not dispatched");
  }
  const exhausted = attempt.attempt_number >= operation.max_attempts;
  const nextAttempt: AgentTransportAttemptRecord = {
    ...attempt,
    status: request.kind === "unknown_after_dispatch" ? "unknown_outcome" : "definitive_failure",
    failure: {
      kind: request.kind,
      error_code: request.error_code,
      observed_at: request.observed_at,
    },
  };
  return {
    status: "applied",
    operation: update(
      operation,
      {
        status:
          request.kind === "unknown_after_dispatch"
            ? "suspended_unknown"
            : exhausted
              ? "failed"
              : "awaiting_retry_authorization",
        attempts: replaceAttempt(operation, nextAttempt),
        ...(exhausted ? { terminal_reason: "ATTEMPT_BUDGET_EXHAUSTED" } : {}),
      },
      request.observed_at,
    ),
  };
}

export function recoverAgentTransportOperation(
  operation: AgentTransportOperationRecord,
  recoveredAt: string,
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(recoveredAt, "recovered_at");
  if (operation.status !== "dispatch_reserved" && operation.status !== "in_flight") {
    return { status: "duplicate", operation: clone(operation) };
  }
  const attempt = activeAttempt(operation);
  const nextAttempt: AgentTransportAttemptRecord = {
    ...attempt,
    status: "unknown_outcome",
    failure: {
      kind: "unknown_after_dispatch",
      error_code: "PROCESS_RECOVERED_WITH_UNATTESTED_DISPATCH",
      observed_at: recoveredAt,
    },
  };
  return {
    status: "applied",
    operation: update(
      operation,
      { status: "suspended_unknown", attempts: replaceAttempt(operation, nextAttempt) },
      recoveredAt,
    ),
  };
}

export function authorizeAgentTransportRetry(
  operation: AgentTransportOperationRecord,
  authorization: AgentTransportRetryAuthorization,
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  if (!AUTHORIZATION_ID_PATTERN.test(authorization.authorization_id)) {
    throw new TypeError("Invalid retry authorization ID");
  }
  assertTimestamp(authorization.authorized_at, "authorized_at");
  if (!CODE_PATTERN.test(authorization.reason_code))
    throw new TypeError("Invalid retry reason code");
  const duplicate = operation.retry_authorizations.find(
    (item) => item.authorization_id === authorization.authorization_id,
  );
  if (duplicate !== undefined) {
    if (
      duplicate.authorizer !== authorization.authorizer ||
      duplicate.authorized_at !== authorization.authorized_at ||
      duplicate.reason_code !== authorization.reason_code ||
      duplicate.from_attempt_id !== authorization.from_attempt_id ||
      duplicate.next_attempt_number !== authorization.next_attempt_number ||
      duplicate.duplicate_dispatch_risk_acknowledged !==
        authorization.duplicate_dispatch_risk_acknowledged
    ) {
      throw new TypeError("Retry authorization ID content drift");
    }
    return { status: "duplicate", operation: clone(operation) };
  }
  if (
    operation.status !== "awaiting_retry_authorization" &&
    operation.status !== "suspended_unknown"
  ) {
    throw new TypeError("Operation is not awaiting retry authorization");
  }
  const attempt = activeAttempt(operation);
  if (
    authorization.from_attempt_id !== attempt.attempt_id ||
    authorization.next_attempt_number !== attempt.attempt_number + 1 ||
    authorization.next_attempt_number > operation.max_attempts
  ) {
    throw new TypeError("Retry authorization does not match the attempt lineage or budget");
  }
  const unknown = attempt.status === "unknown_outcome";
  const providerSafe = operation.request.provider_idempotency.capability === "provider_attested";
  if (unknown && authorization.authorizer === "automatic_policy" && !providerSafe) {
    throw new TypeError(
      "Automatic retry of an unknown dispatch requires attested provider idempotency",
    );
  }
  if (unknown && !providerSafe && !authorization.duplicate_dispatch_risk_acknowledged) {
    throw new TypeError("Unknown dispatch retry requires explicit duplicate-risk acknowledgement");
  }
  return {
    status: "applied",
    operation: update(
      operation,
      {
        status: "ready",
        retry_authorizations: [...operation.retry_authorizations, clone(authorization)],
      },
      authorization.authorized_at,
    ),
  };
}

export function commitAgentTransportResponse(
  operation: AgentTransportOperationRecord,
  request: {
    readonly attestation_id: string;
    readonly committed_at: string;
  },
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(request.committed_at, "committed_at");
  if (
    operation.status === "completed" &&
    operation.selected_attestation_id === request.attestation_id
  ) {
    return { status: "duplicate", operation: clone(operation) };
  }
  if (operation.status !== "response_attested" || operation.integrity !== "clean") {
    throw new TypeError("Only one clean attested response can be committed");
  }
  const attempt = operation.attempts.find((item) =>
    item.response_attestations.some(
      (attestation) => attestation.attestation_id === request.attestation_id,
    ),
  );
  if (attempt?.status !== "response_attested") {
    throw new TypeError("Committed response attestation is not available");
  }
  const nextAttempt = { ...attempt, status: "response_committed" as const };
  return {
    status: "applied",
    operation: update(
      operation,
      {
        status: "completed",
        attempts: replaceAttempt(operation, nextAttempt),
        selected_attestation_id: request.attestation_id,
        terminal_reason: "RESPONSE_COMMITTED",
      },
      request.committed_at,
    ),
  };
}

export function rejectAgentTransportResponse(
  operation: AgentTransportOperationRecord,
  request: {
    readonly attestation_id: string;
    readonly error_code: string;
    readonly rejected_at: string;
  },
): AgentTransportTransitionResult {
  assertAgentTransportOperation(operation);
  assertTimestamp(request.rejected_at, "rejected_at");
  if (!CODE_PATTERN.test(request.error_code)) throw new TypeError("Invalid rejection error code");
  if (operation.status !== "response_attested") {
    throw new TypeError("Only an attested response can be rejected");
  }
  const attempt = operation.attempts.find((item) =>
    item.response_attestations.some(
      (attestation) => attestation.attestation_id === request.attestation_id,
    ),
  );
  if (attempt?.status !== "response_attested") {
    throw new TypeError("Rejected response attestation is not available");
  }
  const exhausted = attempt.attempt_number >= operation.max_attempts;
  const nextAttempt: AgentTransportAttemptRecord = {
    ...attempt,
    status: "response_rejected",
    rejection_code: request.error_code,
  };
  return {
    status: "applied",
    operation: update(
      operation,
      {
        status: exhausted ? "failed" : "awaiting_retry_authorization",
        attempts: replaceAttempt(operation, nextAttempt),
        ...(exhausted ? { terminal_reason: "ATTEMPT_BUDGET_EXHAUSTED" } : {}),
      },
      request.rejected_at,
    ),
  };
}
