import {
  type ChangeProducer,
  DERIVED_RECORD_KINDS,
  getNarraMemIdKind,
  isHashDigest,
  isOperationAllowedForProducer,
  type NarraMemId,
  type ValidationIssue,
  type ValidationReport,
} from "@narramem/core-domain";

import { validateChangeSetProposalEnvelope } from "./proposal-schema.js";

const VALIDATOR_VERSION = "0.1.0";

type UnknownRecord = Readonly<Record<string, unknown>>;

export interface KnownRecordScope {
  readonly record_id: NarraMemId;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
}

export interface ChangeSetValidationContext {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly active_revision_id: NarraMemId<"source_revision">;
  readonly known_evidence_ids: readonly NarraMemId<"evidence">[];
  readonly known_records: readonly KnownRecordScope[];
}

function isRecord(value: unknown): value is UnknownRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function asString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function asStringArray(value: unknown): readonly string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string") ? value : [];
}

function collectRecordEvidenceSpanIds(record: UnknownRecord): readonly string[] {
  const ids: string[] = [];
  for (const field of ["evidence", "support", "counterevidence", "identity_evidence"] as const) {
    const spans = record[field];
    if (!Array.isArray(spans)) {
      continue;
    }
    for (const span of spans) {
      if (isRecord(span) && typeof span.evidence_id === "string") {
        ids.push(span.evidence_id);
      }
    }
  }
  return ids;
}

function issue(
  code: string,
  message: string,
  operation_index?: number,
  record_ref?: NarraMemId,
): ValidationIssue {
  return {
    code,
    severity: "error",
    ...(operation_index === undefined ? {} : { operation_index }),
    ...(record_ref === undefined ? {} : { record_ref }),
    message,
  };
}

const derivedIdFields = [
  "scene_id",
  "episode_id",
  "event_id",
  "entity_id",
  "identity_claim_id",
  "assessment_id",
  "assertion_id",
  "delta_id",
  "view_id",
  "epistemic_id",
  "proposition_id",
  "transfer_id",
  "causal_id",
  "thread_id",
  "impact_id",
  "interpretation_id",
  "cue_id",
] as const;

function getDerivedRecordId(record: UnknownRecord): NarraMemId | undefined {
  for (const field of derivedIdFields) {
    const value = record[field];
    if (typeof value === "string" && getNarraMemIdKind(value) !== undefined) {
      return value as NarraMemId;
    }
  }

  return undefined;
}

function getOperationRecord(operation: UnknownRecord): UnknownRecord | undefined {
  if (operation.op === "add_derived") {
    return isRecord(operation.record) ? operation.record : undefined;
  }
  if (operation.op === "supersede_derived") {
    return isRecord(operation.replacement) ? operation.replacement : undefined;
  }
  return undefined;
}

function collectPlannedEvidenceIds(operations: readonly unknown[]): Set<string> {
  const ids = new Set<string>();
  for (const operation of operations) {
    if (!isRecord(operation) || operation.op !== "add_evidence" || !isRecord(operation.evidence)) {
      continue;
    }
    const evidenceId = asString(operation.evidence.evidence_id);
    if (evidenceId !== undefined) {
      ids.add(evidenceId);
    }
  }
  return ids;
}

function collectRemovedEvidenceIds(operations: readonly unknown[]): Set<string> {
  const ids = new Set<string>();
  for (const operation of operations) {
    if (!isRecord(operation) || operation.op !== "remove_evidence") {
      continue;
    }
    const evidenceId = asString(operation.evidence_id);
    if (evidenceId !== undefined) {
      ids.add(evidenceId);
    }
  }
  return ids;
}

function validateDerivedRecord(
  record: UnknownRecord,
  operationIndex: number,
  proposal: UnknownRecord,
  availableEvidenceIds: ReadonlySet<string>,
  removedEvidenceIds: ReadonlySet<string>,
  knownRecordScopes: ReadonlyMap<string, KnownRecordScope>,
  plannedRecordIds: ReadonlySet<string>,
): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const recordId = getDerivedRecordId(record);

  if (recordId === undefined) {
    issues.push(
      issue(
        "DERIVED_RECORD_ID_MISSING",
        "Derived record has no recognized typed ID",
        operationIndex,
      ),
    );
    return issues;
  }

  if (
    record.memory_space_id !== proposal.memory_space_id ||
    record.branch_id !== proposal.branch_id
  ) {
    issues.push(
      issue(
        "RECORD_SCOPE_MISMATCH",
        "Derived record memory space and branch must match the proposal scope",
        operationIndex,
        recordId,
      ),
    );
  }

  if (!isRecord(record.derivation)) {
    issues.push(
      issue(
        "DERIVATION_MISSING",
        "Derived record must include DerivationMeta",
        operationIndex,
        recordId,
      ),
    );
    return issues;
  }

  if (record.derivation.input_revision_id !== proposal.based_on_revision_id) {
    issues.push(
      issue(
        "DERIVATION_REVISION_MISMATCH",
        "Derivation input revision must equal the proposal snapshot revision",
        operationIndex,
        recordId,
      ),
    );
  }

  const evidenceRefs = asStringArray(record.derivation.evidence_refs);
  const dependencyRefs = asStringArray(record.derivation.dependency_refs);
  const recordKind = getNarraMemIdKind(recordId);
  const isProjection = recordKind === "current_state_view" || recordKind === "recall_cue";

  if (evidenceRefs.length === 0 && (!isProjection || dependencyRefs.length === 0)) {
    issues.push(
      issue(
        "UNSUPPORTED_DERIVATION",
        "Semantic records require evidence; projections require evidence or a supported dependency",
        operationIndex,
        recordId,
      ),
    );
  }

  for (const evidenceRef of evidenceRefs) {
    if (!availableEvidenceIds.has(evidenceRef) || removedEvidenceIds.has(evidenceRef)) {
      issues.push(
        issue(
          "EVIDENCE_NOT_CURRENT",
          "Derivation references evidence that is absent or removed by this proposal",
          operationIndex,
          recordId,
        ),
      );
    }
  }

  for (const spanEvidenceId of collectRecordEvidenceSpanIds(record)) {
    if (!evidenceRefs.includes(spanEvidenceId)) {
      issues.push(
        issue(
          "EVIDENCE_PROVENANCE_GAP",
          "Every record EvidenceSpan must also appear in DerivationMeta evidence_refs",
          operationIndex,
          recordId,
        ),
      );
    }
    if (!availableEvidenceIds.has(spanEvidenceId) || removedEvidenceIds.has(spanEvidenceId)) {
      issues.push(
        issue(
          "EVIDENCE_SPAN_NOT_CURRENT",
          "Record EvidenceSpan references evidence that is absent or being removed",
          operationIndex,
          recordId,
        ),
      );
    }
  }

  for (const dependencyRef of dependencyRefs) {
    const knownScope = knownRecordScopes.get(dependencyRef);
    if (knownScope === undefined && !plannedRecordIds.has(dependencyRef)) {
      issues.push(
        issue(
          "DEPENDENCY_UNKNOWN",
          `Derivation dependency ${dependencyRef} is neither current nor added by this proposal`,
          operationIndex,
          recordId,
        ),
      );
      continue;
    }
    if (
      knownScope !== undefined &&
      (knownScope.memory_space_id !== proposal.memory_space_id ||
        knownScope.branch_id !== proposal.branch_id)
    ) {
      issues.push(
        issue(
          "DEPENDENCY_SCOPE_MISMATCH",
          "Derivation cannot depend on a record from another memory space or branch",
          operationIndex,
          recordId,
        ),
      );
    }
  }

  if (recordKind === "future_impact") {
    const effects = Array.isArray(record.possible_effects) ? record.possible_effects : [];
    if (effects.length === 0) {
      issues.push(
        issue(
          "FUTURE_IMPACT_EFFECTS_MISSING",
          "FutureImpact must contain at least one hypothetical effect candidate",
          operationIndex,
          recordId,
        ),
      );
    }
    for (const effect of effects) {
      if (
        !isRecord(effect) ||
        effect.epistemic_status !== "hypothetical" ||
        "event_id" in effect ||
        "delta_id" in effect ||
        "assertion_id" in effect
      ) {
        issues.push(
          issue(
            "FUTURE_IMPACT_AS_FACT",
            "FutureImpact effects must remain hypothetical and cannot contain fact-record IDs",
            operationIndex,
            recordId,
          ),
        );
      }
    }

    if (record.state === "realized" || record.state === "surfaced") {
      const directEvidence = Array.isArray(record.evidence)
        ? record.evidence.some((span) => isRecord(span) && span.support_role === "direct")
        : false;
      if (!directEvidence) {
        issues.push(
          issue(
            "FUTURE_IMPACT_ADVANCED_WITHOUT_DIRECT_EVIDENCE",
            "A surfaced or realized impact requires direct evidence from accepted host truth",
            operationIndex,
            recordId,
          ),
        );
      }
    }
  }

  if (recordKind === "causal_link") {
    const mechanism = typeof record.mechanism === "string" ? record.mechanism.trim() : "";
    const causeRefs = Array.isArray(record.cause_refs) ? record.cause_refs : [];
    const effectRefs = Array.isArray(record.effect_refs) ? record.effect_refs : [];
    const support = Array.isArray(record.support) ? record.support : [];
    if (mechanism.length === 0 || causeRefs.length === 0 || effectRefs.length === 0) {
      issues.push(
        issue(
          "CAUSAL_STRUCTURE_INCOMPLETE",
          "CausalLink requires cause, effect, and an explicit non-empty mechanism",
          operationIndex,
          recordId,
        ),
      );
    }
    if (support.length === 0) {
      issues.push(
        issue(
          "CAUSAL_SUPPORT_MISSING",
          "Temporal proximity or co-occurrence is not enough; CausalLink requires support spans",
          operationIndex,
          recordId,
        ),
      );
    }
    if (record.scope === "character_belief" && !isRecord(record.holder)) {
      issues.push(
        issue(
          "CAUSAL_BELIEF_HOLDER_MISSING",
          "A character_belief CausalLink must identify the epistemic holder",
          operationIndex,
          recordId,
        ),
      );
    }
    if (record.scope !== "character_belief" && record.holder !== undefined) {
      issues.push(
        issue(
          "CAUSAL_HOLDER_SCOPE_INVALID",
          "Only character_belief CausalLink records may carry a holder",
          operationIndex,
          recordId,
        ),
      );
    }
  }

  return issues;
}

export function validateChangeSetProposal(
  value: unknown,
  context: ChangeSetValidationContext,
): ValidationReport {
  const envelopeResult = validateChangeSetProposalEnvelope(value);
  if (!envelopeResult.valid || !isRecord(value)) {
    const firstErrors = envelopeResult.errors
      .slice(0, 12)
      .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`);
    const omittedCount = Math.max(0, envelopeResult.errors.length - firstErrors.length);
    return {
      validator_version: VALIDATOR_VERSION,
      checked_revision_id: context.active_revision_id,
      accepted: false,
      issues: [
        issue(
          "SCHEMA_INVALID",
          `Full 0.1.0 wire schema rejected the proposal: ${firstErrors.join("; ")}${
            omittedCount === 0 ? "" : `; ${omittedCount} additional schema errors omitted`
          }`,
        ),
      ],
    };
  }

  const issues: ValidationIssue[] = [];
  const operations = Array.isArray(value.operations) ? value.operations : [];
  const producer = value.producer as ChangeProducer;

  for (const [field, expectedKind] of [
    ["changeset_id", "change_set"],
    ["memory_space_id", "memory_space"],
    ["branch_id", "branch"],
    ["based_on_revision_id", "source_revision"],
  ] as const) {
    if (getNarraMemIdKind(value[field]) !== expectedKind) {
      issues.push(issue("ID_KIND_MISMATCH", `${field} must be a ${expectedKind} NarraMem ID`));
    }
  }

  if (value.memory_space_id !== context.memory_space_id || value.branch_id !== context.branch_id) {
    issues.push(
      issue("PROPOSAL_SCOPE_MISMATCH", "Proposal scope does not match validation context"),
    );
  }
  if (value.based_on_revision_id !== context.active_revision_id) {
    issues.push(issue("STALE_REVISION", "Proposal is not based on the active source revision"));
  }

  const availableEvidenceIds = new Set<string>(context.known_evidence_ids);
  for (const evidenceId of collectPlannedEvidenceIds(operations)) {
    availableEvidenceIds.add(evidenceId);
  }
  const removedEvidenceIds = collectRemovedEvidenceIds(operations);
  const knownRecordScopes = new Map<string, KnownRecordScope>(
    context.known_records.map((item) => [item.record_id, item]),
  );
  const plannedRecordIds = new Set<string>();

  for (const operation of operations) {
    if (!isRecord(operation)) {
      continue;
    }
    const record = getOperationRecord(operation);
    if (record !== undefined) {
      const recordId = getDerivedRecordId(record);
      if (recordId !== undefined) {
        plannedRecordIds.add(recordId);
      }
    }
  }

  operations.forEach((operation, operationIndex) => {
    if (!isRecord(operation) || typeof operation.op !== "string") {
      issues.push(
        issue("OPERATION_INVALID", "Operation must be an object with an op", operationIndex),
      );
      return;
    }

    if (
      !isOperationAllowedForProducer(
        producer,
        operation.op as Parameters<typeof isOperationAllowedForProducer>[1],
      )
    ) {
      issues.push(
        issue(
          "PRODUCER_OPERATION_FORBIDDEN",
          `Producer ${producer} is not allowed to perform ${operation.op}`,
          operationIndex,
        ),
      );
    }

    const record = getOperationRecord(operation);
    if (
      (operation.op === "add_derived" || operation.op === "supersede_derived") &&
      record === undefined
    ) {
      issues.push(
        issue(
          "OPERATION_PAYLOAD_INVALID",
          `${operation.op} requires a derived record payload`,
          operationIndex,
        ),
      );
    }
    if (record !== undefined) {
      issues.push(
        ...validateDerivedRecord(
          record,
          operationIndex,
          value,
          availableEvidenceIds,
          removedEvidenceIds,
          knownRecordScopes,
          plannedRecordIds,
        ),
      );
    }

    if (operation.op === "invalidate_derived" || operation.op === "supersede_derived") {
      const targetId = asString(operation.target_id);
      const targetKind = getNarraMemIdKind(targetId);
      if (targetKind === undefined) {
        issues.push(
          issue(
            "TARGET_ID_INVALID",
            `${operation.op} requires a valid typed target_id`,
            operationIndex,
          ),
        );
      }
      if (targetKind === "entity" || targetKind === "identity_claim") {
        issues.push(
          issue(
            "IDENTITY_MUTATION_FORBIDDEN",
            "Entity and IdentityClaim records cannot be invalidated by model proposals",
            operationIndex,
            targetId as NarraMemId,
          ),
        );
      }
      const targetScope = targetId === undefined ? undefined : knownRecordScopes.get(targetId);
      if (
        targetScope !== undefined &&
        (targetScope.memory_space_id !== value.memory_space_id ||
          targetScope.branch_id !== value.branch_id)
      ) {
        issues.push(
          issue(
            "TARGET_SCOPE_MISMATCH",
            "Mutation target belongs to another memory space or branch",
            operationIndex,
            targetId as NarraMemId,
          ),
        );
      }
    }

    if (operation.op === "delete_derived_closure") {
      const targetIds = asStringArray(operation.target_ids);
      const rootEvidenceIds = asStringArray(operation.root_evidence_ids);
      if (
        targetIds.length === 0 ||
        rootEvidenceIds.length === 0 ||
        !isHashDigest(operation.closure_hash)
      ) {
        issues.push(
          issue(
            "DEPENDENCY_CLOSURE_PROOF_INVALID",
            "Physical derived deletion requires targets, root evidence, and a valid closure hash",
            operationIndex,
          ),
        );
      }
      for (const targetId of targetIds) {
        const targetKind = getNarraMemIdKind(targetId);
        const targetScope = knownRecordScopes.get(targetId);
        if (
          targetKind === undefined ||
          !(DERIVED_RECORD_KINDS as readonly string[]).includes(targetKind) ||
          targetScope === undefined
        ) {
          issues.push(
            issue(
              "DEPENDENCY_CLOSURE_TARGET_INVALID",
              "Closure deletion target must be a known derived record",
              operationIndex,
            ),
          );
          continue;
        }
        if (
          targetScope.memory_space_id !== value.memory_space_id ||
          targetScope.branch_id !== value.branch_id
        ) {
          issues.push(
            issue(
              "DEPENDENCY_CLOSURE_SCOPE_MISMATCH",
              "Closure deletion cannot cross memory space or branch",
              operationIndex,
              targetId as NarraMemId,
            ),
          );
        }
      }
      for (const rootEvidenceId of rootEvidenceIds) {
        if (!availableEvidenceIds.has(rootEvidenceId)) {
          issues.push(
            issue(
              "DEPENDENCY_CLOSURE_ROOT_UNKNOWN",
              "Closure root must reference current or reconciled evidence",
              operationIndex,
            ),
          );
        }
      }
    }
  });

  return {
    validator_version: VALIDATOR_VERSION,
    checked_revision_id: context.active_revision_id,
    accepted: issues.length === 0,
    issues,
  };
}
