import {
  checksumJson,
  type TavernArchiveRecord,
  type TavernControlPayload,
  type TavernFullSnapshotCommitRequest,
  type TavernHostPort,
  type TavernJsonValue,
  TavernWorldbookSnapshotStore,
  TavernWorldbookStoreError,
  type TavernWorldbookStoreOptions,
} from "@narramem/tavern-adapter";

export const TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION = "0.1.0" as const;

const MAX_RECORDS_PER_SEGMENT = 32;
const MAX_SEGMENT_UTF8_BYTES = 350_000;
const HEAP_PEAK_DELTA_LIMIT_BYTES = 96 * 1024 * 1024;
const HEAP_SAMPLE_INTERVAL_MS = 25;

const PROFILE_IDS = {
  count: "stress_r1t002_count_v1",
  bytes: "stress_r1t002_bytes_v1",
  scale: "stress_r1t002_scale_v1",
  scale_optimized: "stress_r1t002_scale_v2",
  scale_64: "stress_r1t002_scale64_v3",
  scale_cached_archive: "stress_r1t002_scalecache_v4",
  count_single_archive: "stress_r1t002_countsingle_v5",
  bytes_single_archive: "stress_r1t002_bytessingle_v5",
  scale_single_archive: "stress_r1t002_scalesingle_v5",
  scale_append_result: "stress_r1t002_scaleappend_v6",
  recovery: "stress_r1t002_recovery_v1",
  recovery_single_archive: "stress_r1t002_recoverysingle_v5",
  concurrency: "stress_r1t002_concurrency_v1",
  concurrency_single_archive: "stress_r1t002_concurrencysingle_v5",
} as const;

type StressProfile = keyof typeof PROFILE_IDS;

export type TavernWorldbookStressCommand =
  | "WORLDBOOK_STRESS_PREFLIGHT"
  | "WORLDBOOK_STRESS_RUN_COUNT"
  | "WORLDBOOK_STRESS_RUN_BYTES"
  | "WORLDBOOK_STRESS_RUN_SCALE"
  | "WORLDBOOK_STRESS_RUN_SCALE_OPTIMIZED"
  | "WORLDBOOK_STRESS_RUN_SCALE_64"
  | "WORLDBOOK_STRESS_RUN_SCALE_CACHED_ARCHIVE"
  | "WORLDBOOK_STRESS_RUN_SCALE_SINGLE_ARCHIVE"
  | "WORLDBOOK_STRESS_RUN_SCALE_APPEND_RESULT"
  | "WORLDBOOK_STRESS_START_RECOVERY"
  | "WORLDBOOK_STRESS_RECOVER_AFTER_REFRESH"
  | "WORLDBOOK_STRESS_INIT_CONCURRENCY"
  | "WORLDBOOK_STRESS_PREPARE_STALE_WRITER"
  | "WORLDBOOK_STRESS_COMMIT_PRIMARY_WRITER"
  | "WORLDBOOK_STRESS_COMMIT_STALE_WRITER"
  | "WORLDBOOK_STRESS_VERIFY_ALL"
  | "WORLDBOOK_STRESS_PREPARE_CLEANUP"
  | "WORLDBOOK_STRESS_EXECUTE_PREPARED_CLEANUP";

interface BrowserPersistenceSnapshot {
  readonly local_storage_narramem_keys: number | null;
  readonly session_storage_narramem_keys: number | null;
  readonly indexed_db_narramem_databases: number | null;
  readonly cache_storage_narramem_caches: number | null;
}

interface HeapMeasurement {
  readonly available: boolean;
  readonly before_bytes: number | null;
  readonly peak_bytes: number | null;
  readonly after_operation_bytes: number | null;
  readonly peak_delta_bytes: number | null;
  readonly gate: "PASS" | "FAIL" | "UNAVAILABLE";
}

interface SnapshotMetrics {
  readonly memory_set_id: string;
  readonly commit_sequence: number;
  readonly view_id: string;
  readonly source_revision: number;
  readonly source_checksum: string;
  readonly segment_count: number;
  readonly segment_record_counts: readonly number[];
  readonly segment_utf8_bytes: readonly number[];
  readonly total_segment_utf8_bytes: number;
  readonly reconstructed_record_count: number;
  readonly first_record_id: string | null;
  readonly last_record_id: string | null;
  readonly record_order_checksum: string;
  readonly pending_transaction: false;
}

type MemoryPerformance = Performance & {
  readonly memory?: {
    readonly usedJSHeapSize: number;
  };
};

function now(): number {
  return performance.now();
}

function readHeapBytes(): number | null {
  const value = (performance as MemoryPerformance).memory?.usedJSHeapSize;
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

async function measureHeap<T>(operation: () => Promise<T>): Promise<{
  readonly result: T;
  readonly heap: HeapMeasurement;
}> {
  const before = readHeapBytes();
  let peak = before;
  const sample = (): void => {
    const value = readHeapBytes();
    if (value !== null && (peak === null || value > peak)) peak = value;
  };
  const timer = globalThis.setInterval(sample, HEAP_SAMPLE_INTERVAL_MS);
  try {
    const result = await operation();
    sample();
    const afterOperation = readHeapBytes();
    const peakDelta = before === null || peak === null ? null : Math.max(0, peak - before);
    return {
      result,
      heap: {
        available: before !== null && peak !== null && afterOperation !== null,
        before_bytes: before,
        peak_bytes: peak,
        after_operation_bytes: afterOperation,
        peak_delta_bytes: peakDelta,
        gate:
          peakDelta === null
            ? "UNAVAILABLE"
            : peakDelta <= HEAP_PEAK_DELTA_LIMIT_BYTES
              ? "PASS"
              : "FAIL",
      },
    };
  } finally {
    globalThis.clearInterval(timer);
  }
}

function countMatchingStorageKeys(storage: Storage): number {
  let count = 0;
  for (let index = 0; index < storage.length; index += 1) {
    const key = storage.key(index);
    if (key?.toLowerCase().includes("narramem")) count += 1;
  }
  return count;
}

async function readBrowserPersistence(): Promise<BrowserPersistenceSnapshot> {
  let indexedDbCount: number | null = null;
  let cacheCount: number | null = null;
  try {
    if (typeof indexedDB !== "undefined" && typeof indexedDB.databases === "function") {
      indexedDbCount = (await indexedDB.databases()).filter((item) =>
        item.name?.toLowerCase().includes("narramem"),
      ).length;
    }
  } catch {
    indexedDbCount = null;
  }
  try {
    if (typeof caches !== "undefined") {
      cacheCount = (await caches.keys()).filter((name) =>
        name.toLowerCase().includes("narramem"),
      ).length;
    }
  } catch {
    cacheCount = null;
  }
  return {
    local_storage_narramem_keys:
      typeof localStorage === "undefined" ? null : countMatchingStorageKeys(localStorage),
    session_storage_narramem_keys:
      typeof sessionStorage === "undefined" ? null : countMatchingStorageKeys(sessionStorage),
    indexed_db_narramem_databases: indexedDbCount,
    cache_storage_narramem_caches: cacheCount,
  };
}

function recordsFor(
  profile: Exclude<StressProfile, "concurrency">,
): readonly TavernArchiveRecord[] {
  const input =
    profile === "count"
      ? { count: 33, filler: "count-boundary" }
      : profile === "count_single_archive"
        ? { count: 65, filler: "count-boundary-64" }
        : profile === "bytes" || profile === "bytes_single_archive"
          ? { count: 3, filler: "界".repeat(60_000) }
          : profile === "scale" ||
              profile === "scale_optimized" ||
              profile === "scale_64" ||
              profile === "scale_cached_archive" ||
              profile === "scale_single_archive" ||
              profile === "scale_append_result"
            ? { count: 1_001, filler: "S".repeat(4_096) }
            : { count: 65, filler: "refresh-recovery" };
  return Array.from(
    { length: input.count },
    (_, ordinal): TavernArchiveRecord => ({
      record_id: `${profile}_${ordinal.toString().padStart(4, "0")}`,
      record_kind: "diagnostic_synthetic",
      payload: {
        protocol: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
        profile,
        ordinal,
        filler: input.filler,
      } satisfies TavernJsonValue,
    }),
  );
}

function concurrencyRecords(writer: "primary" | "stale"): readonly TavernArchiveRecord[] {
  return [
    {
      record_id: `concurrency_${writer}`,
      record_kind: "diagnostic_synthetic",
      payload: {
        protocol: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
        profile: "concurrency",
        writer,
      },
    },
  ];
}

function controlBookName(profile: StressProfile): string {
  return `NarraMem__CONTROL__${PROFILE_IDS[profile]}`;
}

function segmentBookPrefix(profile: StressProfile): string {
  return `NarraMem__ARCHIVE__${PROFILE_IDS[profile]}__`;
}

function maxRecordsPerSegment(profile: StressProfile): number {
  return profile === "scale_64" ||
    profile === "scale_cached_archive" ||
    profile === "scale_single_archive" ||
    profile === "scale_append_result" ||
    profile === "count_single_archive" ||
    profile === "bytes_single_archive" ||
    profile === "recovery_single_archive" ||
    profile === "concurrency_single_archive"
    ? 64
    : MAX_RECORDS_PER_SEGMENT;
}

async function storeOptions(profile: StressProfile): Promise<TavernWorldbookStoreOptions> {
  const memorySetId = PROFILE_IDS[profile];
  const anchorHash = await checksumJson({
    protocol: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
    memory_set_id: memorySetId,
  });
  return {
    memory_set_id: memorySetId,
    control_book_name: controlBookName(profile),
    segment_book_prefix: segmentBookPrefix(profile),
    initial_identity_anchor: {
      identity_version: "0.1.0",
      character_locator: { host_character_id: `diagnostic_${profile}` },
      chat_locator: { host_chat_id: `diagnostic_${profile}` },
      chat_anchor_hash: anchorHash,
      character_revision_hash: null,
    },
    max_records_per_segment: maxRecordsPerSegment(profile),
    max_segment_utf8_bytes: MAX_SEGMENT_UTF8_BYTES,
  };
}

async function buildCommitRequest(
  store: TavernWorldbookSnapshotStore,
  profile: StressProfile,
  suffix: string,
  records: readonly TavernArchiveRecord[],
): Promise<TavernFullSnapshotCommitRequest> {
  const control = await store.readControl();
  return {
    transaction_id: `tx_${profile}_${suffix}`,
    writer_id: `writer_${suffix}`,
    build_id: `build_${profile}_${suffix}`,
    view_id: `view_${profile}_${suffix}`,
    source_revision: 1,
    source_checksum: await checksumJson(records),
    expected_commit_sequence: control.commit_sequence,
    expected_view_id: control.active_view?.view_id ?? null,
    records,
  };
}

async function snapshotMetrics(
  store: TavernWorldbookSnapshotStore,
  control: TavernControlPayload,
): Promise<SnapshotMetrics> {
  if (control.active_view === null || control.pending_transaction !== null) {
    throw new Error("Stress snapshot is not a fully committed active view");
  }
  const records = await store.readActiveSnapshot();
  const ids = records.map((record) => record.record_id);
  return {
    memory_set_id: control.memory_set_id,
    commit_sequence: control.commit_sequence,
    view_id: control.active_view.view_id,
    source_revision: control.active_view.source_revision,
    source_checksum: control.active_view.source_checksum,
    segment_count: control.active_view.segments.length,
    segment_record_counts: control.active_view.segments.map((segment) => segment.record_count),
    segment_utf8_bytes: control.active_view.segments.map((segment) => segment.utf8_bytes),
    total_segment_utf8_bytes: control.active_view.segments.reduce(
      (total, segment) => total + segment.utf8_bytes,
      0,
    ),
    reconstructed_record_count: records.length,
    first_record_id: ids[0] ?? null,
    last_record_id: ids.at(-1) ?? null,
    record_order_checksum: await checksumJson(ids),
    pending_transaction: false,
  };
}

function assertNoExistingProfileBooks(port: TavernHostPort, profile: StressProfile): void {
  const names = port.listWorldbooks();
  const control = controlBookName(profile);
  const prefix = segmentBookPrefix(profile);
  const collisions = names.filter((name) => name === control || name.startsWith(prefix));
  if (collisions.length > 0) {
    throw new Error(`Stress profile ${profile} already exists; refusing to overwrite`);
  }
}

function listStressProfileBooks(port: TavernHostPort): readonly string[] {
  const names = port.listWorldbooks();
  const matches = (Object.keys(PROFILE_IDS) as StressProfile[]).flatMap((profile) => {
    const control = controlBookName(profile);
    const prefix = segmentBookPrefix(profile);
    return names.filter((name) => name === control || name.startsWith(prefix));
  });
  return [...new Set(matches)].sort();
}

export class TavernWorldbookStressDiagnostic {
  private preparedStaleRequest: TavernFullSnapshotCommitRequest | null = null;
  private preparedCleanupBooks: readonly string[] | null = null;

  constructor(private readonly port: TavernHostPort) {}

  async execute(command: TavernWorldbookStressCommand): Promise<unknown> {
    switch (command) {
      case "WORLDBOOK_STRESS_PREFLIGHT":
        return this.preflight();
      case "WORLDBOOK_STRESS_RUN_COUNT":
        return this.runProfile("count_single_archive");
      case "WORLDBOOK_STRESS_RUN_BYTES":
        return this.runProfile("bytes_single_archive");
      case "WORLDBOOK_STRESS_RUN_SCALE":
        return this.runProfile("scale");
      case "WORLDBOOK_STRESS_RUN_SCALE_OPTIMIZED":
        return this.runProfile("scale_optimized");
      case "WORLDBOOK_STRESS_RUN_SCALE_64":
        return this.runProfile("scale_64");
      case "WORLDBOOK_STRESS_RUN_SCALE_CACHED_ARCHIVE":
        return this.runProfile("scale_cached_archive");
      case "WORLDBOOK_STRESS_RUN_SCALE_SINGLE_ARCHIVE":
        return this.runProfile("scale_single_archive");
      case "WORLDBOOK_STRESS_RUN_SCALE_APPEND_RESULT":
        return this.runProfile("scale_append_result");
      case "WORLDBOOK_STRESS_START_RECOVERY":
        return this.startRecovery();
      case "WORLDBOOK_STRESS_RECOVER_AFTER_REFRESH":
        return this.recoverAfterRefresh();
      case "WORLDBOOK_STRESS_INIT_CONCURRENCY":
        return this.initializeConcurrency();
      case "WORLDBOOK_STRESS_PREPARE_STALE_WRITER":
        return this.prepareStaleWriter();
      case "WORLDBOOK_STRESS_COMMIT_PRIMARY_WRITER":
        return this.commitPrimaryWriter();
      case "WORLDBOOK_STRESS_COMMIT_STALE_WRITER":
        return this.commitStaleWriter();
      case "WORLDBOOK_STRESS_VERIFY_ALL":
        return this.verifyAll();
      case "WORLDBOOK_STRESS_PREPARE_CLEANUP":
        return this.prepareCleanup();
      case "WORLDBOOK_STRESS_EXECUTE_PREPARED_CLEANUP":
        return this.executePreparedCleanup();
    }
  }

  private async preflight(): Promise<unknown> {
    const collisions = listStressProfileBooks(this.port);
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      host: this.port.getVersions(),
      exact_profile_ids: PROFILE_IDS,
      max_records_per_segment: MAX_RECORDS_PER_SEGMENT,
      candidate_max_records_per_segment: 64,
      max_segment_utf8_bytes: MAX_SEGMENT_UTF8_BYTES,
      heap_peak_delta_limit_bytes: HEAP_PEAK_DELTA_LIMIT_BYTES,
      cross_tab_lock_available: this.port.withWorldbookExclusiveLock !== undefined,
      existing_test_books: collisions,
      browser_persistence: await readBrowserPersistence(),
      external_model_calls: 0,
      prompt_changes: 0,
      user_worldbooks_modified: false,
    };
  }

  private async runProfile(
    profile:
      | "count"
      | "bytes"
      | "scale"
      | "scale_optimized"
      | "scale_64"
      | "scale_cached_archive"
      | "count_single_archive"
      | "bytes_single_archive"
      | "scale_single_archive"
      | "scale_append_result",
  ): Promise<unknown> {
    assertNoExistingProfileBooks(this.port, profile);
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    const records = recordsFor(profile);
    const persistenceBefore = await readBrowserPersistence();
    const initializedAt = now();
    await store.initialize();
    const initializeMs = now() - initializedAt;
    const request = await buildCommitRequest(store, profile, "primary", records);
    const commitAt = now();
    const measured = await measureHeap(() => store.commitFullSnapshot(request));
    const commitMs = now() - commitAt;
    const verifyAt = now();
    const metrics = await snapshotMetrics(store, measured.result.control);
    const verifyMs = now() - verifyAt;
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      initialize_ms: initializeMs,
      commit_ms: commitMs,
      verify_ms: verifyMs,
      metrics,
      heap: measured.heap,
      browser_persistence_before: persistenceBefore,
      browser_persistence_after: await readBrowserPersistence(),
      external_model_calls: 0,
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async startRecovery(): Promise<unknown> {
    const profile = "recovery_single_archive" as const;
    assertNoExistingProfileBooks(this.port, profile);
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    await store.initialize();
    const records = recordsFor(profile);
    const request = await buildCommitRequest(store, profile, "interrupted", records);
    let simulatedStopObserved = false;
    try {
      await store.commitFullSnapshot({
        ...request,
        after_durable_phase: (phase) => {
          if (phase === "pending_recorded") {
            throw new Error("stress-simulated-refresh-after-pending-recorded");
          }
        },
      });
    } catch (error) {
      simulatedStopObserved =
        error instanceof Error &&
        error.message === "stress-simulated-refresh-after-pending-recorded";
      if (!simulatedStopObserved) throw error;
    }
    const control = await store.readControl();
    if (control.pending_transaction?.phase !== "staging_verified") {
      throw new Error("Recovery stress did not stop at staging_verified");
    }
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      simulated_stop_observed: simulatedStopObserved,
      control_checksum: control.checksum,
      commit_sequence: control.commit_sequence,
      active_view_id: control.active_view?.view_id ?? null,
      pending_phase: control.pending_transaction.phase,
      target_view_id: control.pending_transaction.target_view.view_id,
      target_segment_count: control.pending_transaction.target_view.segments.length,
      next_action: "REAL_PAGE_REFRESH_THEN_WORLDBOOK_STRESS_RECOVER_AFTER_REFRESH",
      external_model_calls: 0,
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async recoverAfterRefresh(): Promise<unknown> {
    const profile = "recovery_single_archive" as const;
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    const control = await store.readControl();
    const pending = control.pending_transaction;
    if (pending === null) throw new Error("No pending recovery transaction exists");
    const result = await store.recover({
      current_source_revision: pending.target_view.source_revision,
      current_source_checksum: pending.target_view.source_checksum,
      exclusive_writer_confirmed: true,
    });
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      recovery_action: result.action,
      metrics: await snapshotMetrics(store, result.control),
      external_model_calls: 0,
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async initializeConcurrency(): Promise<unknown> {
    const profile = "concurrency_single_archive" as const;
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    const control = await store.initialize();
    if (control.commit_sequence !== 0 || control.active_view !== null) {
      throw new Error("Concurrency stress namespace is not at the initial base");
    }
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      control_checksum: control.checksum,
      commit_sequence: control.commit_sequence,
      cross_tab_lock_available: this.port.withWorldbookExclusiveLock !== undefined,
    };
  }

  private async prepareStaleWriter(): Promise<unknown> {
    const profile = "concurrency_single_archive" as const;
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    const request = await buildCommitRequest(store, profile, "stale", concurrencyRecords("stale"));
    if (request.expected_commit_sequence !== 0 || request.expected_view_id !== null) {
      throw new Error("Stale writer must be frozen from the initial Control base");
    }
    this.preparedStaleRequest = request;
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      prepared: true,
      transaction_id: request.transaction_id,
      expected_commit_sequence: request.expected_commit_sequence,
      expected_view_id: request.expected_view_id,
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async commitPrimaryWriter(): Promise<unknown> {
    const profile = "concurrency_single_archive" as const;
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    const request = await buildCommitRequest(
      store,
      profile,
      "primary",
      concurrencyRecords("primary"),
    );
    const result = await store.commitFullSnapshot(request);
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      writer: "primary",
      metrics: await snapshotMetrics(store, result.control),
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async commitStaleWriter(): Promise<unknown> {
    const profile = "concurrency_single_archive" as const;
    const request = this.preparedStaleRequest;
    if (request === null) throw new Error("No stale writer request is prepared in this tab");
    const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
    let errorCode: string | null = null;
    try {
      await store.commitFullSnapshot(request);
    } catch (error) {
      if (error instanceof TavernWorldbookStoreError) errorCode = error.code;
      else throw error;
    }
    if (errorCode !== "STALE_BASE") {
      throw new Error(`Expected STALE_BASE from writer B; received ${errorCode ?? "success"}`);
    }
    const stalePrefix = `${segmentBookPrefix(profile)}${request.transaction_id}`;
    const staleBooks = this.port.listWorldbooks().filter((name) => name.startsWith(stalePrefix));
    if (staleBooks.length > 0) throw new Error("Stale writer created segment books");
    const control = await store.readControl();
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profile,
      writer: "stale",
      rejected_error_code: errorCode,
      stale_segment_books: staleBooks,
      metrics: await snapshotMetrics(store, control),
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async verifyAll(): Promise<unknown> {
    const profiles = Object.keys(PROFILE_IDS) as StressProfile[];
    const results: Record<string, unknown> = {};
    for (const profile of profiles) {
      const store = new TavernWorldbookSnapshotStore(this.port, await storeOptions(profile));
      try {
        const control = await store.readControl();
        results[profile] =
          control.pending_transaction === null && control.active_view !== null
            ? await snapshotMetrics(store, control)
            : {
                memory_set_id: control.memory_set_id,
                commit_sequence: control.commit_sequence,
                active_view_id: control.active_view?.view_id ?? null,
                pending_phase: control.pending_transaction?.phase ?? null,
              };
      } catch (error) {
        results[profile] = {
          unavailable: true,
          error_name: error instanceof Error ? error.name : "UnknownError",
        };
      }
    }
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      profiles: results,
      browser_persistence: await readBrowserPersistence(),
      external_model_calls: 0,
      content_recorded_in_diagnostic_response: false,
    };
  }

  private async prepareCleanup(): Promise<unknown> {
    const targets = listStressProfileBooks(this.port);
    this.preparedCleanupBooks = targets;
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      prepared: true,
      planned_book_count: targets.length,
      planned_book_names_checksum: await checksumJson(targets),
      exact_profile_ids: PROFILE_IDS,
      user_worldbooks_included: false,
      next_action: "WORLDBOOK_STRESS_EXECUTE_PREPARED_CLEANUP",
    };
  }

  private async executePreparedCleanup(): Promise<unknown> {
    const prepared = this.preparedCleanupBooks;
    if (prepared === null) throw new Error("No worldbook stress cleanup plan is prepared");
    const current = listStressProfileBooks(this.port);
    if (
      prepared.length !== current.length ||
      prepared.some((bookName, index) => current[index] !== bookName)
    ) {
      this.preparedCleanupBooks = null;
      throw new Error("Worldbook stress cleanup plan is stale; prepare it again");
    }
    let deleted = 0;
    try {
      for (const bookName of prepared) {
        if (!(await this.port.deleteWorldbook(bookName))) {
          throw new Error(`Failed to delete prepared stress worldbook ${bookName}`);
        }
        deleted += 1;
      }
    } finally {
      this.preparedCleanupBooks = null;
    }
    const remaining = listStressProfileBooks(this.port);
    if (remaining.length > 0) {
      throw new Error("Prepared stress worldbooks remain after cleanup");
    }
    return {
      protocol_version: TAVERN_WORLDBOOK_STRESS_PROTOCOL_VERSION,
      deleted_book_count: deleted,
      remaining_test_book_count: 0,
      browser_persistence: await readBrowserPersistence(),
      user_worldbooks_modified: false,
      content_recorded_in_diagnostic_response: false,
    };
  }
}
