import { createSha256Digest, type ExtractionCandidateBatch } from "@narramem/core-domain";
import { evaluateExplicitCausalCompleteness } from "@narramem/narrative-compiler";
import {
  canonicalJson,
  projectTavernCausalAuditTaskSeeds,
  readTavernSemanticManifestFromArchive,
  sha256HexUtf8,
  TavernCurrentArchiveCoordinator,
  type TavernHostPort,
  TavernMemoryRegistry,
  type TavernMessageSnapshot,
  TavernSemanticArchiveService,
  TavernWorldbookSnapshotStore,
} from "@narramem/tavern-adapter";

export const TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_VERSION = "0.2.0" as const;
export const TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_MODEL_ID =
  "narramem-controlled-fixture-no-provider" as const;
export const TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_PROMPT_CONTRACT =
  "controlled-fixture-no-prompt@0.2.0" as const;
const SEGMENT_LIMITS = {
  max_records_per_segment: 64,
  max_segment_utf8_bytes: 350_000,
} as const;
const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";
const CAUSAL_CUES = ["正因为", "因此", "因而", "所以", "从而", "导致", "造成", "使得"];

export async function hasCurrentTavernCausalAuditPositiveFixture(
  port: TavernHostPort,
): Promise<boolean> {
  try {
    const resolution = await new TavernMemoryRegistry(port).resolveCurrentMemorySet();
    if (resolution.status !== "EXACT" || resolution.selected === null) return false;
    const selected = resolution.selected;
    const archive = await new TavernWorldbookSnapshotStore(port, {
      memory_set_id: selected.control.memory_set_id,
      control_book_name: selected.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${selected.control.memory_set_id}__`,
      initial_identity_anchor: selected.control.identity_anchor,
      ...SEGMENT_LIMITS,
    }).readActiveSnapshot();
    const manifest = readTavernSemanticManifestFromArchive(archive);
    if (manifest === null) return false;
    const emptyPromptSha256 = await sha256HexUtf8("");
    const zeroCallParametersSha256 = await sha256HexUtf8(
      canonicalJson({ external_model_calls: 0 }),
    );
    return (
      manifest.model_id === TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_MODEL_ID &&
      manifest.prompt_contract_version === TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_PROMPT_CONTRACT &&
      manifest.prompt_body_sha256.value === emptyPromptSha256 &&
      manifest.parameters_hash.value === zeroCallParametersSha256
    );
  } catch {
    return false;
  }
}

export interface TavernCausalAuditPositiveFixtureOptions {
  readonly port: TavernHostPort;
  readonly now?: () => string;
  readonly allocate_memory_set_id?: () => string;
}

export interface TavernCausalAuditPositiveFixtureResult {
  readonly fixture_version: typeof TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_VERSION;
  readonly status: "COMMITTED";
  readonly memory_set_id: string;
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly semantic_task_fingerprint: string;
  readonly candidate_batch_sha256: string;
  readonly quality_finding_count: number;
  readonly causal_seed_count: number;
  readonly event_count_created: 2;
  readonly causal_link_count_created: 0;
  readonly derived_record_count: number;
  readonly archive_record_count: number;
  readonly external_model_calls: 0;
  readonly content_recorded: false;
  readonly browser_persistent_storage_used: false;
}

function targetMessages(messages: readonly TavernMessageSnapshot[]) {
  const visible = messages.filter(
    (message) => !message.is_hidden && (message.role === "user" || message.role === "assistant"),
  );
  const effect = visible.at(-1);
  const cause = visible.at(-2);
  const causeText = cause?.message;
  const effectText = effect?.message;
  if (
    cause?.role !== "user" ||
    effect?.role !== "assistant" ||
    typeof causeText !== "string" ||
    typeof effectText !== "string" ||
    causeText.trim().length === 0 ||
    effectText.trim().length === 0
  ) {
    throw new TypeError(
      "Controlled positive fixture requires the final two visible messages to be user then assistant",
    );
  }
  if (!CAUSAL_CUES.some((cue) => effectText.includes(cue))) {
    throw new TypeError("Controlled positive fixture effect message has no supported causal cue");
  }
  return { cause, effect, causeText, effectText };
}

function idPrefix(kind: string, nonce: string): string {
  return `positive_fixture_${kind}_${nonce}`;
}

export class TavernCausalAuditPositiveFixtureDiagnostic {
  private readonly now: () => string;
  private readonly allocateMemorySetId: () => string;

  constructor(private readonly options: TavernCausalAuditPositiveFixtureOptions) {
    this.now = options.now ?? (() => new Date().toISOString());
    this.allocateMemorySetId =
      options.allocate_memory_set_id ?? (() => `memory_${globalThis.crypto.randomUUID()}`);
  }

  async prepare(): Promise<TavernCausalAuditPositiveFixtureResult> {
    const messages = this.options.port.readCurrentMessages({ include_swipes: false });
    const { cause, effect, causeText, effectText } = targetMessages(messages);
    const identity = this.options.port.getCurrentIdentity();
    if (identity.character_id === null || identity.chat_id === null) {
      throw new TypeError("Controlled positive fixture requires one active character chat");
    }
    const nonce = (
      await sha256HexUtf8(
        canonicalJson({
          fixture_version: TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_VERSION,
          identity,
          cause_message_id: cause.message_id,
          effect_message_id: effect.message_id,
          cause_sha256: await sha256HexUtf8(causeText),
          effect_sha256: await sha256HexUtf8(effectText),
        }),
      )
    ).slice(0, 24);
    const coordinator = new TavernCurrentArchiveCoordinator(this.options.port, SEGMENT_LIMITS);
    const syncRequest = {
      writer_id: idPrefix("source_writer", nonce),
      transaction_id: idPrefix("source_tx", nonce),
      build_id: idPrefix("source_build", nonce),
      view_id: idPrefix("source_view", nonce),
      observed_hints: [],
      exclusive_recovery_confirmed: true,
    } as const;
    let synced = await coordinator.sync(syncRequest);
    if (synced.status === "ACTION_REQUIRED") {
      if (
        synced.required_action !== "CREATE_MEMORY_SET" &&
        synced.required_action !== "CONFIRM_ANCHOR_CANDIDATE"
      ) {
        throw new TypeError(`Controlled positive fixture cannot resolve ${synced.required_action}`);
      }
      synced = await coordinator.sync({
        ...syncRequest,
        create_if_not_found: {
          memory_set_id: this.allocateMemorySetId(),
          character_revision_hash: null,
          ...(synced.resolution.candidates.length === 0
            ? {}
            : {
                expected_anchor_candidates: synced.resolution.candidates.map((candidate) => ({
                  control_book_name: candidate.control_book_name,
                  expected_control_checksum: candidate.control.checksum,
                })),
              }),
        },
      });
    }
    if (synced.status === "ACTION_REQUIRED") {
      throw new TypeError("Controlled positive fixture did not establish an exact Memory Set");
    }
    const semantic = new TavernSemanticArchiveService(this.options.port, SEGMENT_LIMITS);
    const task = await semantic.prepareExtraction({
      // Keep this identical to the product Runtime's extraction prepare
      // contract. A different vocabulary changes the semantic task
      // fingerprint and would make the resumed Runtime replace the fixture.
      event_type_vocabulary: [],
      default_story_time: {
        granularity: "scene",
        certainty: "relative",
        sequence_index: 0,
      },
      created_at: this.now(),
    });
    if (task.existing_semantic_manifest !== null) {
      throw new TypeError(
        "Controlled positive fixture refuses to overwrite an existing semantic archive",
      );
    }
    const causeEvidence = task.core_source.evidence_items.find(
      (evidence) =>
        evidence.raw_content.kind === "text" &&
        evidence.source_order.ordinal === cause.message_id &&
        evidence.source_order.component === 0,
    );
    const effectEvidence = task.core_source.evidence_items.find(
      (evidence) =>
        evidence.raw_content.kind === "text" &&
        evidence.source_order.ordinal === effect.message_id &&
        evidence.source_order.component === 0,
    );
    if (
      causeEvidence?.raw_content.kind !== "text" ||
      effectEvidence?.raw_content.kind !== "text" ||
      causeEvidence.raw_content.text !== causeText ||
      effectEvidence.raw_content.text !== effectText
    ) {
      throw new TypeError("Controlled positive fixture could not bind exact source Evidence");
    }
    const storyTime = {
      granularity: "scene",
      certainty: "relative",
      sequence_index: cause.message_id,
    } as const;
    const candidateBatch: ExtractionCandidateBatch = {
      contract_version: "0.1.0",
      source_revision_id: task.core_source.source_revision.revision_id,
      entities: [],
      scenes: [
        {
          candidate_key: "controlled_fixture_scene",
          source_evidence_ids: [causeEvidence.evidence_id, effectEvidence.evidence_id],
          story_time: storyTime,
          location_refs: [],
          participant_refs: [],
          focalizers: [],
          atmosphere_labels: [],
          boundary_reason: "受控正向事务夹具中的连续原因与后果",
          support_level: "explicit",
        },
      ],
      events: [
        {
          candidate_key: "controlled_fixture_cause_event",
          scene_candidate_key: "controlled_fixture_scene",
          event_type: "controlled_fixture_cause",
          actor_refs: [],
          patient_refs: [],
          action_or_occurrence: causeText,
          location_refs: [],
          story_time: storyTime,
          intentionality: "intentional",
          evidence_quotes: [
            {
              evidence_id: causeEvidence.evidence_id,
              quote: causeText,
              support_role: "direct",
            },
          ],
          support_level: "explicit",
        },
        {
          candidate_key: "controlled_fixture_effect_event",
          scene_candidate_key: "controlled_fixture_scene",
          event_type: "controlled_fixture_effect",
          actor_refs: [],
          patient_refs: [],
          action_or_occurrence: effectText,
          location_refs: [],
          story_time: { ...storyTime, sequence_index: effect.message_id },
          intentionality: "unknown",
          evidence_quotes: [
            {
              evidence_id: effectEvidence.evidence_id,
              quote: effectText,
              support_role: "direct",
            },
          ],
          support_level: "explicit",
        },
      ],
      unresolved_items: [],
    };
    const candidateBatchSha256 = await sha256HexUtf8(canonicalJson(candidateBatch));
    const completeness = evaluateExplicitCausalCompleteness([causeEvidence, effectEvidence], []);
    if (completeness.findings.length === 0) {
      throw new TypeError("Controlled positive fixture produced no uncovered causal finding");
    }
    const committed = await semantic.commitCandidateBatch({
      task,
      candidate_batch: candidateBatch,
      extractor: {
        model_id: TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_MODEL_ID,
        model_identity_assurance: "requested_not_attested",
        prompt_contract_version: TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_PROMPT_CONTRACT,
        prompt_body_sha256: createSha256Digest(await sha256HexUtf8("")),
        parameters_hash: createSha256Digest(
          await sha256HexUtf8(canonicalJson({ external_model_calls: 0 })),
        ),
      },
      compilation_key: idPrefix("compilation", nonce),
      compiled_at: this.now(),
      writer_id: idPrefix("semantic_writer", nonce),
      transaction_id: idPrefix("semantic_tx", nonce),
      build_id: idPrefix("semantic_build", nonce),
      view_id: idPrefix("semantic_view", nonce),
      quality_audit: {
        quality_audit_version: "0.1.0",
        source_response_sha256: candidateBatchSha256,
        flat_draft_quarantine: null,
        causal_completeness: completeness,
      },
    });
    const resolution = await new TavernMemoryRegistry(this.options.port).resolveCurrentMemorySet();
    if (resolution.status !== "EXACT" || resolution.selected === null) {
      throw new TypeError("Controlled positive fixture lost its exact Memory Set after commit");
    }
    const selected = resolution.selected;
    const store = new TavernWorldbookSnapshotStore(this.options.port, {
      memory_set_id: selected.control.memory_set_id,
      control_book_name: selected.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${selected.control.memory_set_id}__`,
      initial_identity_anchor: selected.control.identity_anchor,
      ...SEGMENT_LIMITS,
    });
    const archive = await store.readActiveSnapshot();
    const manifest = readTavernSemanticManifestFromArchive(archive);
    if (manifest === null) {
      throw new TypeError("Controlled positive fixture semantic manifest is missing after commit");
    }
    const seeds = await projectTavernCausalAuditTaskSeeds(selected.control.memory_set_id, manifest);
    return {
      fixture_version: TAVERN_CAUSAL_AUDIT_POSITIVE_FIXTURE_VERSION,
      status: "COMMITTED",
      memory_set_id: selected.control.memory_set_id,
      source_revision_id: manifest.source_revision_id,
      source_checksum: manifest.source_checksum,
      semantic_task_fingerprint: manifest.task_fingerprint,
      candidate_batch_sha256: candidateBatchSha256,
      quality_finding_count: completeness.findings.length,
      causal_seed_count: seeds.length,
      event_count_created: 2,
      causal_link_count_created: 0,
      derived_record_count: committed.derived_record_count,
      archive_record_count: committed.archive_record_count,
      external_model_calls: 0,
      content_recorded: false,
      browser_persistent_storage_used: false,
    };
  }
}
