function isDiagnosticCommand(command: string): command is TavernExtensionDiagnosticCommand {
  return (
    DIAGNOSTIC_COMMANDS.has(command as TavernExtensionDiagnosticCommand) ||
    parseManualCausalAuditCommand(command) !== null
  );
}

function installDynamicDiagnosticCommands(value: unknown): void {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return;
  const tasks = (value as { readonly tasks?: unknown }).tasks;
  if (!Array.isArray(tasks)) return;
  const select = document.getElementById(DIAGNOSTIC_REQUEST_ELEMENT_ID);
  if (!(select instanceof HTMLSelectElement)) return;
  for (const task of tasks) {
    if (task === null || typeof task !== "object" || Array.isArray(task)) continue;
    const command = (task as { readonly manual_command?: unknown }).manual_command;
    if (typeof command !== "string" || parseManualCausalAuditCommand(command) === null) continue;
    DIAGNOSTIC_COMMANDS.add(command as TavernExtensionDiagnosticCommand);
    if ([...select.options].some((option) => option.value === command)) continue;
    const option = document.createElement("option");
    option.value = command;
    option.textContent = command;
    select.append(option);
  }
}

interface TavernDiagnosticEntry {
  readonly at: string;
  readonly type: string;
  readonly detail: Readonly<Record<string, unknown>>;
}

type DiagnosticHost = typeof globalThis & {
  __NARRAMEM_DIAGNOSTICS__?: TavernDiagnosticEntry[];
};

function recordDiagnostic(type: string, detail: Readonly<Record<string, unknown>>): void {
  const host = globalThis as DiagnosticHost;
  const entries = host.__NARRAMEM_DIAGNOSTICS__ ?? [];
  entries.push({ at: new Date().toISOString(), type, detail });
  if (entries.length > DIAGNOSTIC_LIMIT) entries.splice(0, entries.length - DIAGNOSTIC_LIMIT);
  host.__NARRAMEM_DIAGNOSTICS__ = entries;
  let element = document.getElementById(DIAGNOSTIC_ELEMENT_ID);
  if (element === null) {
    element = document.createElement("script");
    element.id = DIAGNOSTIC_ELEMENT_ID;
    element.setAttribute("type", "application/json");
    document.documentElement.append(element);
  }
  element.textContent = JSON.stringify(entries);
}

function installDiagnosticCommandBridge(control: TavernExtensionDiagnosticControl): void {
  const writeResponse = (value: Readonly<Record<string, unknown>>): void => {
    let element = document.getElementById(DIAGNOSTIC_RESPONSE_ELEMENT_ID);
    if (element === null) {
      element = document.createElement("script");
      element.id = DIAGNOSTIC_RESPONSE_ELEMENT_ID;
      element.setAttribute("type", "application/json");
      document.documentElement.append(element);
    }
    element.textContent = JSON.stringify(value);
  };
  const runCommand = (requestId: string, command: TavernExtensionDiagnosticCommand): void => {
    void executeTavernExtensionDiagnosticCommand(control, command).then(
      (result) => {
        installDynamicDiagnosticCommands(result);
        writeResponse({ request_id: requestId, ok: true, command, result });
        recordDiagnostic("diagnostic_command", { command, ok: true });
      },
      (error: unknown) => {
        writeResponse({
          request_id: requestId,
          ok: false,
          command,
          error_name: error instanceof Error ? error.name : "UnknownError",
          error_message: error instanceof Error ? error.message : "Diagnostic command failed",
        });
        recordDiagnostic("diagnostic_command", {
          command,
          ok: false,
          error_name: error instanceof Error ? error.name : "UnknownError",
        });
      },
    );
  };
  document.addEventListener(DIAGNOSTIC_COMMAND_EVENT, (event) => {
    const detail = (event as CustomEvent<unknown>).detail;
    if (detail === null || typeof detail !== "object" || Array.isArray(detail)) return;
    const request = detail as { readonly request_id?: unknown; readonly command?: unknown };
    if (
      typeof request.request_id !== "string" ||
      !/^[A-Za-z0-9_-]{1,64}$/u.test(request.request_id) ||
      typeof request.command !== "string" ||
      !isDiagnosticCommand(request.command)
    ) {
      return;
    }
    runCommand(request.request_id, request.command as TavernExtensionDiagnosticCommand);
  });
  document.getElementById(DIAGNOSTIC_REQUEST_ELEMENT_ID)?.remove();
  const requestElement = document.createElement("select");
  requestElement.id = DIAGNOSTIC_REQUEST_ELEMENT_ID;
  requestElement.tabIndex = -1;
  requestElement.setAttribute("aria-label", "NarraMem diagnostic command bridge");
  requestElement.style.cssText =
    "position:fixed;left:0;top:0;width:1px;height:1px;margin:0;padding:0;border:0;opacity:0.001;pointer-events:none;z-index:2147483647";
  const idleOption = document.createElement("option");
  idleOption.value = "";
  idleOption.textContent = "READY";
  requestElement.append(idleOption);
  for (const command of DIAGNOSTIC_COMMANDS) {
    const option = document.createElement("option");
    option.value = command;
    option.textContent = command;
    requestElement.append(option);
  }
  document.documentElement.append(requestElement);
  let commandSequence = 0;
  const observeRequest = (): void => {
    const command = requestElement.value;
    requestElement.value = "";
    if (!isDiagnosticCommand(command)) return;
    commandSequence += 1;
    runCommand(
      `select_${commandSequence.toString(36)}_${Date.now().toString(36)}`,
      command as TavernExtensionDiagnosticCommand,
    );
  };
  requestElement.addEventListener("change", observeRequest);
  writeResponse({
    request_id: "bootstrap",
    ok: true,
    command: "READY",
    result: control.getState(),
  });
}

