async function bootstrap(): Promise<void> {
  const version = await readSillyTavernVersion();
  recordDiagnostic("bootstrap", { silly_tavern_version: version });
  const context = getContext();
  await ensureActiveCharacterIdentity(context);
  const settingsStore = new NarraMemBetaSettingsStore({
    extensionSettings: context.extensionSettings,
    saveSettingsDebounced: () => context.saveSettingsDebounced(),
  });
  let taskState: NarraMemTaskDisplayState = {
    status: "idle",
    stage: "idle",
    error_type: null,
    error_code: null,
    last_failure_at: null,
    round_attempts: 0,
    round_max_calls: settingsStore.get().retry_count + 1,
    cumulative_calls: 0,
    manual_retry_available: false,
  };
  let settingsPanel: NarraMemBetaSettingsPanel | null = null;
  let manualRetryRound = 0;
  let activeRetryRoundId: string | undefined;
  const refreshTaskDisplay = (): void => {
    void settingsPanel?.refreshStatus();
  };
  const memoryApiClient = new NarraMemMemoryApiClient({
    fetch: (input, init) => globalThis.fetch(input, init),
    getRequestHeaders,
    getSettings: () => settingsStore.get(),
    setProfileCredentialSecretId: (profileId, credentialSecretId) => {
      settingsStore.updateProfile(profileId, { credential_secret_id: credentialSecretId });
    },
  });
  const updateGenerationState = (state: {
    readonly status: "running" | "success" | "failed";
    readonly generation_id: string;
    readonly error_type?: string;
    readonly error_code?: string;
  }): void => {
    const attempt = Number.parseInt(/_a([0-9]+)$/u.exec(state.generation_id)?.[1] ?? "0", 10);
    const stage = state.generation_id.includes("_lifecycle_") ? "lifecycle" : "extraction";
    taskState = {
      ...taskState,
      status: state.status,
      stage,
      error_type: state.status === "failed" ? (state.error_type ?? "UnknownError") : null,
      error_code: state.status === "failed" ? (state.error_code ?? "GENERATION_FAILED") : null,
      last_failure_at:
        state.status === "failed" ? new Date().toISOString() : taskState.last_failure_at,
      round_attempts: Math.max(taskState.round_attempts, attempt),
      round_max_calls: settingsStore.get().retry_count + 1,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
      manual_retry_available: false,
    };
    refreshTaskDisplay();
  };
  const port = createSillyTavernExtensionHostPort(
    makeBindings(version, settingsStore, memoryApiClient, updateGenerationState),
  );
  const causalAuditDiagnostic = new TavernCausalAuditDiagnostic({
    port,
    get_current_model_id: () => memoryAdapterModelId(settingsStore.get()),
    count_tokens: getTokenCountAsync,
  });
  const diagnosticControl = new TavernExtensionDiagnosticControl(port, 200, causalAuditDiagnostic);
  (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[
    Symbol.for(NARRAMEM_EXTENSION_DIAGNOSTIC_CONTROL_SYMBOL)
  ] = diagnosticControl;
  installDiagnosticCommandBridge(diagnosticControl);
  recordDiagnostic("diagnostic_control_ready", {
    control_version: diagnosticControl.control_version,
    product_runtime_count: 1,
    content_recorded: false,
  });
  let runtime: TavernExtensionRuntimeHandle | null = null;
  const checkpointEvaluationControl = new TavernCheckpointEvaluationControl(
    () => runtime,
    (audit) => recordDiagnostic("checkpoint_evaluation", { ...audit }),
  );
  (globalThis as typeof globalThis & Record<PropertyKey, unknown>)[
    Symbol.for(NARRAMEM_CHECKPOINT_EVALUATION_CONTROL_SYMBOL)
  ] = checkpointEvaluationControl;
  recordDiagnostic("checkpoint_evaluation_control_ready", {
    control_version: checkpointEvaluationControl.control_version,
    transport: "in_memory_symbol_only",
    product_recall_service_count: 1,
    content_recorded: false,
    dom_bridge_used: false,
  });
  let installedModel: string | null = null;
  let installedSignature: string | null = null;
  let automaticCreatePending = false;
  let reconfigureTail: Promise<void> = Promise.resolve();
  let floorVisibilityTail: Promise<void> = Promise.resolve();
  const automaticPrincipalBinding = createAutomaticPrincipalBinding(() => runtime);

  const scheduleCompletedFloorVisibility = (report: TavernObserverCycleReport): void => {
    const contextNow = getContext();
    const plan = planFloorVisibility(report, contextNow.chat);
    if (plan === null) return;
    const chatId = contextNow.getCurrentChatId();
    const applyLatestVisibility = async (): Promise<void> => {
      const latestContext = getContext();
      if (chatId === null || latestContext.getCurrentChatId() !== chatId) return;
      const latestPlan = planFloorVisibility(report, latestContext.chat);
      if (latestPlan === null) return;
      const result = await applyFloorVisibilityPlan(
        latestContext.chat,
        latestPlan,
        hideChatMessageRange,
      );
      recordDiagnostic("completed_memory_floors_hidden", {
        covered_message_count: latestPlan.covered_message_count,
        hidden_through_message_id: result.hidden_through,
        protected_ai_floor_count: latestPlan.protected_ai_message_ids.length,
        unhidden_ai_count: result.unhidden_ai_count,
        content_recorded: false,
      });
    };
    floorVisibilityTail = floorVisibilityTail
      .then(applyLatestVisibility, applyLatestVisibility)
      .catch((error: unknown) => {
        recordDiagnostic("completed_memory_floor_hiding_failed", {
          error_name: error instanceof Error ? error.name : "UnknownError",
          content_recorded: false,
        });
        logError(error);
      });
  };

  const reconfigure = async (): Promise<void> => {
    const settings = settingsStore.get();
    let exactModelId: string;
    try {
      exactModelId = memoryAdapterModelId(settings);
    } catch (error) {
      taskState = {
        ...taskState,
        status: "failed",
        stage: "idle",
        error_type: error instanceof Error ? error.name : "UnknownError",
        error_code: "PROMPT_ROUTE_REQUIRED",
        last_failure_at: new Date().toISOString(),
        manual_retry_available: false,
      };
      refreshTaskDisplay();
      return;
    }
    let credentialConfigured = false;
    try {
      credentialConfigured = (await memoryApiClient.status()).credential_configured;
    } catch (error) {
      recordDiagnostic("memory_api_backend_unavailable", {
        error_name: error instanceof Error ? error.name : "UnknownError",
        content_recorded: false,
      });
    }
    const signature = JSON.stringify({
      settings,
      credential_configured: credentialConfigured,
      retry_round_id: activeRetryRoundId ?? null,
    });
    const controlledFixtureActive = await hasCurrentTavernCausalAuditPositiveFixture(port);
    if (runtime !== null && installedSignature === signature) {
      if (controlledFixtureActive && diagnosticControl.getState().arm !== "paused") {
        diagnosticControl.pause();
        recordDiagnostic("controlled_fixture_auto_quiesce", {
          fixture_version: "0.2.0",
          trigger: "chat_reconfigure",
          content_recorded: false,
        });
      }
      return;
    }
    diagnosticControl.setRuntime(null);
    runtime?.dispose();
    runtime = null;
    installedModel = null;
    installedSignature = null;
    if (!memoryApiConfigured(settings, credentialConfigured)) {
      console.info("[NarraMem] Memory Runtime paused until independent API settings are complete");
      return;
    }
    const prompts = MODEL_PROMPTS[exactModelId];
    if (prompts === undefined) {
      console.warn(`[NarraMem] Unsupported exact model; memory runtime paused: ${exactModelId}`);
      return;
    }
    if (controlledFixtureActive) {
      diagnosticControl.pause();
      recordDiagnostic("controlled_fixture_auto_quiesce", {
        fixture_version: "0.2.0",
        trigger: "runtime_install",
        content_recorded: false,
      });
    }
    let nextRuntime: TavernExtensionRuntimeHandle | null = null;
    nextRuntime = await installTavernExtensionRuntime({
      host_port: port,
      config: {
        installation_id: "narramem",
        replace_existing: true,
        segment_limits: {
          max_records_per_segment: 64,
          max_segment_utf8_bytes: 350_000,
        },
        observer: {
          debounce_ms: 750,
          max_sync_attempts: 2,
          writer_id: WRITER_ID,
          build_id: EXTENSION_BUILD_ID,
          exclusive_recovery_confirmed: false,
          extraction: {
            requested_model_id: exactModelId,
            ...(activeRetryRoundId === undefined ? {} : { retry_round_id: activeRetryRoundId }),
            prompt_body: prompts.extraction,
            allow_candidate_prompt: true,
            max_attempts: settings.retry_count + 1,
            prepare: {
              chunk_message_limit: 20,
              context_message_limit: 8,
              event_type_vocabulary: [],
              default_story_time: {
                granularity: "scene",
                certainty: "relative",
                sequence_index: 0,
              },
            },
          },
          ...(prompts.lifecycle === undefined
            ? {}
            : {
                lifecycle: {
                  requested_model_id: exactModelId,
                  ...(activeRetryRoundId === undefined
                    ? {}
                    : { retry_round_id: activeRetryRoundId }),
                  prompt_body: prompts.lifecycle,
                  allow_candidate_prompt: true,
                  max_attempts: settings.retry_count + 1,
                },
              }),
        },
        recall: {
          token_budget: 4096,
          latest_ai_floor_count: 4,
          max_prepare_ms: 150,
          prompt_body: prompts.recall,
        },
        interaction_performance: { max_samples: 200 },
      },
      on_report: (report) => {
        logObserverReport(report);
        if (report.status === "EXTRACTION_FINISHED") {
          taskState = {
            ...taskState,
            status: "success",
            stage: report.lifecycle === undefined ? "extraction" : "lifecycle",
            error_type: null,
            error_code: null,
            cumulative_calls: memoryApiClient.getSessionDispatches(),
            manual_retry_available: false,
          };
          refreshTaskDisplay();
          void automaticPrincipalBinding.refresh();
          scheduleCompletedFloorVisibility(report);
        }
        if (report.status === "FAILED") {
          taskState = {
            ...taskState,
            status: "failed",
            stage:
              report.phase === "SOURCE_SYNC"
                ? "source_sync"
                : report.phase === "LIFECYCLE"
                  ? "lifecycle"
                  : "extraction",
            error_type: report.error_name,
            error_code: report.error_code ?? "TASK_FAILED",
            last_failure_at: report.completed_at,
            cumulative_calls: memoryApiClient.getSessionDispatches(),
            manual_retry_available: true,
          };
          refreshTaskDisplay();
        }
        if (
          report.status !== "ACTION_REQUIRED" ||
          !reportRequiresAutomaticCreate(report) ||
          automaticCreatePending
        )
          return;
        const activeRuntime = nextRuntime;
        if (activeRuntime === null) return;
        automaticCreatePending = true;
        void activeRuntime
          .resolveMemorySet({
            kind: "CREATE_MEMORY_SET",
            character_revision_hash: null,
            ...(report.sync.required_action === "CONFIRM_ANCHOR_CANDIDATE"
              ? {
                  expected_anchor_candidates: report.sync.resolution.candidates.map(
                    (candidate) => ({
                      control_book_name: candidate.control_book_name,
                      expected_control_checksum: candidate.control.checksum,
                    }),
                  ),
                }
              : {}),
          })
          .catch(logError)
          .finally(() => {
            automaticCreatePending = false;
          });
      },
      on_recall_report: logRecallReport,
      on_interaction_performance_sample: (sample) => {
        logInteractionPerformanceSample(sample);
        diagnosticControl.notifyRuntimePerformanceSample();
      },
    });
    runtime = nextRuntime;
    diagnosticControl.setRuntime(nextRuntime);
    installedModel = exactModelId;
    installedSignature = signature;
    recordDiagnostic("runtime_active", { requested_model_id: exactModelId });
    console.info(`[NarraMem] Native extension runtime active: ${exactModelId}`);
    await automaticPrincipalBinding.refresh();
  };

  const scheduleReconfigure = (): void => {
    reconfigureTail = reconfigureTail.then(reconfigure, reconfigure);
    void reconfigureTail.catch(logError);
  };

  const runManualRetry = async (): Promise<void> => {
    if (taskState.status === "running") throw new Error("记忆任务仍在运行");
    manualRetryRound += 1;
    activeRetryRoundId = `manual_${Date.now().toString(36)}_${manualRetryRound}`;
    taskState = {
      status: "running",
      stage: "source_sync",
      error_type: null,
      error_code: null,
      last_failure_at: taskState.last_failure_at,
      round_attempts: 0,
      round_max_calls: settingsStore.get().retry_count + 1,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
      manual_retry_available: false,
    };
    refreshTaskDisplay();
    const retry = async (): Promise<void> => {
      installedSignature = null;
      await reconfigure();
      if (runtime === null) {
        throw new Error("NarraMem 运行时尚未就绪，请检查 API、模型与 Prompt 配置");
      }
      await runtime.flushNow();
    };
    reconfigureTail = reconfigureTail.then(retry, retry);
    try {
      await reconfigureTail;
    } catch (error) {
      taskState = {
        ...taskState,
        status: "failed",
        error_type: error instanceof Error ? error.name : "UnknownError",
        error_code: "MANUAL_RETRY_START_FAILED",
        last_failure_at: new Date().toISOString(),
        cumulative_calls: memoryApiClient.getSessionDispatches(),
        manual_retry_available: true,
      };
      refreshTaskDisplay();
      throw error;
    }
  };

  settingsPanel = installNarraMemBetaSettingsPanel({
    version: "0.4.0-beta.7",
    port,
    settingsStore,
    apiClient: memoryApiClient,
    getRuntimeState: () => ({
      runtime_active: runtime !== null,
      adapter_model_id: installedModel,
      diagnostic_arm: diagnosticControl.getState().arm,
    }),
    getTaskState: () => ({
      ...taskState,
      cumulative_calls: memoryApiClient.getSessionDispatches(),
      round_max_calls: settingsStore.get().retry_count + 1,
    }),
    getDiagnostics: () => [...((globalThis as DiagnosticHost).__NARRAMEM_DIAGNOSTICS__ ?? [])],
    onConfigurationChanged: scheduleReconfigure,
    onManualRetry: runManualRetry,
  });

  const installMessageQuickEntry = (messageId?: unknown): void => {
    const selector =
      typeof messageId === "number" && Number.isSafeInteger(messageId) && messageId >= 0
        ? `#chat .mes[mesid="${messageId}"]`
        : "#chat .mes";
    for (const message of document.querySelectorAll<HTMLElement>(selector)) {
      const actions = message.querySelector<HTMLElement>(".extraMesButtons");
      if (actions === null || actions.querySelector(`.${MESSAGE_QUICK_ENTRY_CLASS}`) !== null)
        continue;
      const quickEntry = document.createElement("div");
      quickEntry.className = `mes_button fa-solid fa-brain ${MESSAGE_QUICK_ENTRY_CLASS}`;
      quickEntry.title = "打开 NarraMem 叙忆";
      quickEntry.setAttribute("aria-label", "打开 NarraMem 叙忆");
      quickEntry.setAttribute("role", "button");
      quickEntry.tabIndex = 0;
      const openPanel = (event: Event): void => {
        event.preventDefault();
        event.stopPropagation();
        settingsPanel?.open();
      };
      quickEntry.addEventListener("click", openPanel);
      quickEntry.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") openPanel(event);
      });
      actions.append(quickEntry);
    }
  };

  let quickEntryInstallQueued = false;
  const scheduleQuickEntryInstall = (): void => {
    if (quickEntryInstallQueued) return;
    quickEntryInstallQueued = true;
    globalThis.requestAnimationFrame(() => {
      quickEntryInstallQueued = false;
      installMessageQuickEntry();
    });
  };

  context.eventSource.on(
    requireEventName(context.eventTypes, "CHARACTER_MESSAGE_RENDERED"),
    installMessageQuickEntry,
  );
  context.eventSource.on(
    requireEventName(context.eventTypes, "USER_MESSAGE_RENDERED"),
    installMessageQuickEntry,
  );
  const chat = document.querySelector<HTMLElement>("#chat");
  if (chat !== null) {
    const quickEntryObserver = new MutationObserver(scheduleQuickEntryInstall);
    quickEntryObserver.observe(chat, { childList: true, subtree: true });
  }
  scheduleQuickEntryInstall();
  globalThis.setTimeout(scheduleQuickEntryInstall, 500);

  const reconfigureForChatChange = async (): Promise<void> => {
    await new Promise<void>((resolve) => globalThis.setTimeout(resolve, 250));
    await ensureActiveCharacterIdentity(getContext());
    const previousRuntime = runtime;
    await reconfigure();
    if (runtime !== null && runtime === previousRuntime) {
      if (diagnosticControl.getState().arm === "runtime") {
        runtime.stop("host_chat_changed");
        runtime.start();
        recordDiagnostic("runtime_chat_restarted", {
          requested_model_id: installedModel,
        });
        console.info(`[NarraMem] Runtime restarted for active chat: ${installedModel}`);
      } else {
        runtime.stop("host_chat_changed_non_runtime_arm");
        recordDiagnostic("runtime_chat_restart_suppressed", {
          requested_model_id: installedModel,
          diagnostic_arm: diagnosticControl.getState().arm,
        });
      }
    }
    await automaticPrincipalBinding.refresh();
    installMessageQuickEntry();
    await settingsPanel?.refreshStatus();
  };

  const scheduleChatReconfigure = (): void => {
    reconfigureTail = reconfigureTail.then(reconfigureForChatChange, reconfigureForChatChange);
    void reconfigureTail.catch(logError);
  };

  context.eventSource.on(
    requireEventName(context.eventTypes, "CHAT_CHANGED"),
    scheduleChatReconfigure,
  );
  scheduleReconfigure();
}

const context = getContext();
let bootstrapStarted = false;
const startBootstrap = (): void => {
  if (bootstrapStarted) return;
  bootstrapStarted = true;
  void bootstrap().catch(logError);
};
recordDiagnostic("module_loaded", { document_ready_state: document.readyState });
context.eventSource.on(requireEventName(context.eventTypes, "APP_READY"), startBootstrap);
if (document.readyState === "complete") {
  queueMicrotask(startBootstrap);
} else {
  globalThis.addEventListener("load", startBootstrap, { once: true });
}
