import { createSha256Digest, type FlatNarrativeLifecycleDraftV020 } from "@narramem/core-domain";
import { createStandaloneWireSchema, validateWireValue } from "@narramem/core-validator";

import type { TavernHostPort, TavernStructuredGenerationResult } from "./contracts.js";
import { TavernExtractionAttemptWorldbookStore } from "./extraction-attempt-ledger.js";
import type { TavernExtractionAttemptTaskRecord } from "./extraction-attempt-ledger-contracts.js";
import type { TavernRuntimePromptAsset } from "./extraction-job-contracts.js";
import { TavernNarrativeLifecycleService } from "./narrative-lifecycle.js";
import { compileFlatNarrativeLifecycleDraft } from "./narrative-lifecycle-candidate.js";
import { TavernNarrativeLifecycleError } from "./narrative-lifecycle-contracts.js";
import {
  TAVERN_NARRATIVE_LIFECYCLE_JOB_VERSION,
  type TavernNarrativeLifecycleCancellationReport,
  type TavernNarrativeLifecycleJobAudit,
  TavernNarrativeLifecycleJobError,
  type TavernNarrativeLifecycleJobRequest,
  type TavernNarrativeLifecycleJobResult,
} from "./narrative-lifecycle-job-contracts.js";
import {
  resolveTavernNarrativeLifecycleModelAdapter,
  type TavernNarrativeLifecycleModelAdapter,
} from "./narrative-lifecycle-model-adapter.js";
import { canonicalJson, sha256HexUtf8, utf8ByteLength } from "./worldbook-codec.js";

const JOB_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/u;
const SHA256_PATTERN = /^[0-9a-f]{64}$/u;

interface ActiveGeneration {
  readonly sequence: number;
  readonly generation_id: string;
  readonly cancel_local: (reason: string, hostCancelRequested: boolean) => void;
}

interface LocalCancellation {
  readonly reason: string;
  readonly host_cancel_requested: boolean;
}

function assertRequest(request: TavernNarrativeLifecycleJobRequest): void {
  if (
    !JOB_ID_PATTERN.test(request.job_id) ||
    (request.retry_round_id !== undefined && !JOB_ID_PATTERN.test(request.retry_round_id)) ||
    request.writer_id.length === 0 ||
    request.build_id.length === 0 ||
    (request.max_attempts !== undefined &&
      (!Number.isInteger(request.max_attempts) ||
        request.max_attempts < 1 ||
        request.max_attempts > 3)) ||
    (request.proxy_preset !== undefined &&
      (request.proxy_preset.length === 0 || request.proxy_preset !== request.proxy_preset.trim()))
  ) {
    throw new TavernNarrativeLifecycleJobError(
      "INVALID_REQUEST",
      "Lifecycle job requires safe IDs, 1-3 attempts, and an exact optional proxy preset",
    );
  }
}

async function verifyPromptAsset(
  asset: TavernRuntimePromptAsset,
  adapter: TavernNarrativeLifecycleModelAdapter,
  allowCandidate: boolean,
): Promise<void> {
  const actualRef = `${asset.prompt_id}@${asset.semantic_version}`;
  if (
    asset.prompt_asset_ref !== actualRef ||
    actualRef !== adapter.prompt_asset_ref ||
    asset.message_role !== "system" ||
    asset.position !== "independent_model_call.system" ||
    asset.variables.length !== 0 ||
    asset.input_schema !== adapter.input_schema ||
    asset.output_schema !== adapter.output_schema ||
    asset.provider_scope !== `model-family:${adapter.family}` ||
    asset.body_sha256 !== adapter.prompt_body_sha256 ||
    asset.body.length === 0 ||
    asset.body.startsWith("\uFEFF") ||
    asset.body.includes("\r") ||
    asset.body.includes("{{NARRAMEM:") ||
    !SHA256_PATTERN.test(asset.body_sha256) ||
    (await sha256HexUtf8(asset.body)) !== asset.body_sha256
  ) {
    throw new TavernNarrativeLifecycleJobError(
      "PROMPT_ASSET_INVALID",
      `Lifecycle Prompt descriptor does not match exact adapter route ${adapter.prompt_asset_ref}`,
    );
  }
  if (asset.status === "candidate" && !allowCandidate) {
    throw new TavernNarrativeLifecycleJobError(
      "CANDIDATE_PROMPT_NOT_ALLOWED",
      `Candidate Prompt ${adapter.prompt_asset_ref} requires experimental opt-in`,
    );
  }
}

export class TavernNarrativeLifecycleJobRunner {
  private readonly lifecycle: Pick<TavernNarrativeLifecycleService, "prepare" | "commit">;
  private queue: Promise<void> = Promise.resolve();
  private latestSequence = 0;
  private latestReason = "initial";
  private active: ActiveGeneration | null = null;

  constructor(
    private readonly port: TavernHostPort,
    segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
    lifecycle?: Pick<TavernNarrativeLifecycleService, "prepare" | "commit">,
  ) {
    this.lifecycle = lifecycle ?? new TavernNarrativeLifecycleService(port, segmentLimits);
  }

  runLatest(
    request: TavernNarrativeLifecycleJobRequest,
  ): Promise<TavernNarrativeLifecycleJobResult> {
    const sequence = this.supersede("newer_lifecycle_job").sequence;
    const result = this.queue.then(
      () => this.execute(sequence, request),
      () => this.execute(sequence, request),
    );
    this.queue = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  invalidateCurrent(reason: string): TavernNarrativeLifecycleCancellationReport {
    if (reason.trim().length === 0) {
      throw new TavernNarrativeLifecycleJobError(
        "INVALID_REQUEST",
        "Lifecycle cancellation reason cannot be empty",
      );
    }
    return this.supersede(reason).report;
  }

  private supersede(reason: string): {
    readonly sequence: number;
    readonly report: TavernNarrativeLifecycleCancellationReport;
  } {
    this.latestSequence += 1;
    this.latestReason = reason;
    const generationId = this.active?.generation_id ?? null;
    const hostCancelRequested =
      generationId === null ? false : (this.port.cancelGeneration?.(generationId) ?? false);
    this.active?.cancel_local(reason, hostCancelRequested);
    return {
      sequence: this.latestSequence,
      report: { reason, generation_id: generationId, host_cancel_requested: hostCancelRequested },
    };
  }

  private cancellation(sequence: number, jobId: string): TavernNarrativeLifecycleJobResult | null {
    if (sequence === this.latestSequence) return null;
    return {
      status: this.latestReason === "newer_lifecycle_job" ? "SUPERSEDED" : "CANCELLED",
      job_id: jobId,
      reason: this.latestReason,
      host_cancel_requested: false,
    };
  }

  private async execute(
    sequence: number,
    request: TavernNarrativeLifecycleJobRequest,
  ): Promise<TavernNarrativeLifecycleJobResult> {
    const queuedCancellation = this.cancellation(sequence, request.job_id);
    if (queuedCancellation !== null) return queuedCancellation;
    assertRequest(request);
    let adapter: TavernNarrativeLifecycleModelAdapter;
    try {
      adapter = resolveTavernNarrativeLifecycleModelAdapter(request.requested_model_id);
    } catch (error) {
      throw new TavernNarrativeLifecycleJobError(
        "UNSUPPORTED_MODEL",
        error instanceof Error ? error.message : "Unsupported exact lifecycle model",
      );
    }
    const assets = request.runtime_prompt_assets.filter(
      (asset) => asset.prompt_asset_ref === adapter.prompt_asset_ref,
    );
    if (assets.length !== 1) {
      throw new TavernNarrativeLifecycleJobError(
        "PROMPT_ASSET_INVALID",
        `Exact lifecycle adapter requires one Prompt asset: ${adapter.prompt_asset_ref}`,
      );
    }
    const promptAsset = assets[0] as TavernRuntimePromptAsset;
    await verifyPromptAsset(promptAsset, adapter, request.allow_candidate_prompt);
    const parametersSha256 = await sha256HexUtf8(
      canonicalJson({
        adapter_id: adapter.adapter_id,
        requested_model_id: adapter.exact_model_id,
        proxy_preset: request.proxy_preset ?? null,
        request_parameters: adapter.request_parameters,
        prompt_asset_ref: adapter.prompt_asset_ref,
        prompt_body_sha256: promptAsset.body_sha256,
        input_schema: adapter.input_schema,
        output_schema: adapter.output_schema,
      }),
    );
    const maxAttempts = request.max_attempts ?? 2;
    const audit: TavernNarrativeLifecycleJobAudit = {
      job_version: TAVERN_NARRATIVE_LIFECYCLE_JOB_VERSION,
      job_id: request.job_id,
      adapter_id: adapter.adapter_id,
      requested_model_id: adapter.exact_model_id,
      model_identity_assurance: "requested_not_attested",
      prompt_asset_ref: adapter.prompt_asset_ref,
      prompt_body_sha256: promptAsset.body_sha256,
      input_schema: adapter.input_schema,
      output_schema: adapter.output_schema,
      parameters_sha256: parametersSha256,
      max_attempts: maxAttempts,
    };
    const task = await this.lifecycle.prepare();
    const modelInputSha256 = await sha256HexUtf8(canonicalJson(task.model_input));
    const operationFingerprint = await sha256HexUtf8(
      canonicalJson({
        operation_contract: "narramem.tavern-narrative-lifecycle-operation/0.2.0",
        semantic_task_fingerprint: task.task_fingerprint,
        source_revision_id: task.model_input.source_revision_id,
        source_checksum: task.source_snapshot.checksum,
        model_input_sha256: modelInputSha256,
        requested_model_id: adapter.exact_model_id,
        prompt_asset_ref: adapter.prompt_asset_ref,
        prompt_body_sha256: promptAsset.body_sha256,
        parameters_sha256: parametersSha256,
        max_attempts: maxAttempts,
        retry_round_id: request.retry_round_id ?? null,
      }),
    );
    const attemptStore = new TavernExtractionAttemptWorldbookStore(this.port, task.memory_set_id);
    const existing = task.existing_manifest;
    if (
      existing !== null &&
      existing.source_revision_id === task.model_input.source_revision_id &&
      existing.source_checksum === task.source_snapshot.checksum &&
      existing.semantic_changeset_id === task.semantic_changeset_id &&
      existing.model_id === adapter.exact_model_id &&
      existing.model_identity_assurance === "requested_not_attested" &&
      existing.prompt_contract_version === adapter.prompt_asset_ref &&
      existing.prompt_body_sha256.value === promptAsset.body_sha256 &&
      existing.parameters_hash.value === parametersSha256
    ) {
      await attemptStore.reconcileCommittedIfPresent(
        operationFingerprint,
        new Date().toISOString(),
      );
      return {
        status: "ALREADY_CURRENT",
        audit,
        memory_set_id: task.memory_set_id,
        source_revision_id: task.model_input.source_revision_id,
        lifecycle_task_fingerprint: task.task_fingerprint,
      };
    }
    if (this.port.generateStructured === undefined || this.port.cancelGeneration === undefined) {
      throw new TavernNarrativeLifecycleJobError(
        "HOST_GENERATION_UNAVAILABLE",
        "Tavern HostPort must provide structured generation and per-ID cancellation",
      );
    }
    const attemptDescriptor = {
      operation_fingerprint: operationFingerprint,
      semantic_task_fingerprint: task.task_fingerprint,
      source_revision_id: task.model_input.source_revision_id,
      source_checksum: task.source_snapshot.checksum,
      model_input_sha256: modelInputSha256,
      requested_model_id: adapter.exact_model_id,
      prompt_asset_ref: adapter.prompt_asset_ref,
      prompt_body_sha256: promptAsset.body_sha256,
      parameters_sha256: parametersSha256,
      max_attempts: maxAttempts,
      created_at: new Date().toISOString(),
    } as const;
    const opened = await attemptStore.openTask(attemptDescriptor, new Date().toISOString());
    let attemptTask: TavernExtractionAttemptTaskRecord = opened.task;
    if (attemptTask.status !== "ready") {
      const code =
        attemptTask.status === "exhausted"
          ? "ATTEMPTS_EXHAUSTED"
          : attemptTask.status === "suspended_unknown"
            ? "ATTEMPT_STATUS_UNKNOWN"
            : "ATTEMPT_LEDGER_BLOCKED";
      throw new TavernNarrativeLifecycleJobError(
        code,
        `Lifecycle operation ${operationFingerprint.slice(0, 12)} is blocked by durable attempt status ${attemptTask.status}`,
      );
    }

    const settleResponseRejection = async (
      generationId: string,
      startedAtMs: number,
      content: string,
      errorCode:
        | "GENERATION_TOOL_CALLS"
        | "RESPONSE_JSON_INVALID"
        | "RESPONSE_SCHEMA_INVALID"
        | "LIFECYCLE_CONTINUITY_UNEXPLAINED",
    ): Promise<void> => {
      const settled = await attemptStore.recordFailure(operationFingerprint, generationId, {
        status: "retryable_failure",
        settled_at: new Date().toISOString(),
        elapsed_ms: Math.max(0, Date.now() - startedAtMs),
        error_code: errorCode,
        response_sha256: await sha256HexUtf8(content),
        response_utf8_bytes: utf8ByteLength(content),
      });
      attemptTask = settled.task;
      if (attemptTask.status === "exhausted") {
        throw new TavernNarrativeLifecycleJobError(
          "ATTEMPTS_EXHAUSTED",
          `Lifecycle exhausted ${attemptTask.max_attempts} attempts; last rejection: ${errorCode}`,
        );
      }
    };

    while (attemptTask.status === "ready") {
      const loopCancellation = this.cancellation(sequence, request.job_id);
      if (loopCancellation !== null) return loopCancellation;
      const attemptNumber = attemptTask.attempts.length + 1;
      const generationId = `narramem_lifecycle_${request.job_id}_a${attemptNumber}`;
      const startedAtMs = Date.now();
      attemptTask = (
        await attemptStore.beginAttempt(
          operationFingerprint,
          generationId,
          new Date(startedAtMs).toISOString(),
        )
      ).task;
      let cancelLocal: (reason: string, hostCancelRequested: boolean) => void = () => undefined;
      const localCancellation = new Promise<LocalCancellation>((resolve) => {
        cancelLocal = (reason, hostCancelRequested) =>
          resolve({ reason, host_cancel_requested: hostCancelRequested });
      });
      this.active = { sequence, generation_id: generationId, cancel_local: cancelLocal };
      let generation: Promise<TavernStructuredGenerationResult>;
      try {
        generation = this.port.generateStructured({
          generation_id: generationId,
          target: {
            requested_model_id: adapter.exact_model_id,
            ...(request.proxy_preset === undefined ? {} : { proxy_preset: request.proxy_preset }),
            parameters: adapter.request_parameters,
            identity_assurance: "requested_not_attested",
          },
          messages: [
            { role: "system", content: promptAsset.body },
            { role: "user", content: canonicalJson(task.model_input) },
          ],
          prompt_asset_refs: [adapter.prompt_asset_ref],
          json_schema: {
            name: "narramem_flat_narrative_lifecycle_draft_0_2_0",
            value: createStandaloneWireSchema(adapter.output_schema),
            strict: true,
          },
          should_silence: true,
          should_stream: false,
          max_chat_history: 0,
        });
      } catch (error) {
        if (this.active?.sequence === sequence) this.active = null;
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: "unknown_after_dispatch",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: "GENERATION_FAILED",
        });
        throw new TavernNarrativeLifecycleJobError(
          "GENERATION_FAILED",
          error instanceof Error ? error.message : "Lifecycle structured generation failed",
        );
      }
      generation.catch(() => undefined);
      let outcome:
        | { readonly kind: "generation"; readonly result: TavernStructuredGenerationResult }
        | { readonly kind: "cancelled"; readonly cancellation: LocalCancellation };
      try {
        outcome = await Promise.race([
          generation.then((result) => ({ kind: "generation" as const, result })),
          localCancellation.then((cancellation) => ({ kind: "cancelled" as const, cancellation })),
        ]);
      } catch {
        const superseded = sequence !== this.latestSequence;
        const failed = await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: superseded
            ? this.latestReason === "newer_lifecycle_job"
              ? "superseded"
              : "cancelled"
            : "retryable_failure",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: superseded
            ? this.latestReason === "newer_lifecycle_job"
              ? "SUPERSEDED"
              : "CANCELLED"
            : "GENERATION_FAILED",
        });
        attemptTask = failed.task;
        if (superseded) {
          return {
            status: this.latestReason === "newer_lifecycle_job" ? "SUPERSEDED" : "CANCELLED",
            job_id: request.job_id,
            reason: this.latestReason,
            host_cancel_requested: false,
          };
        }
        if (attemptTask.status === "exhausted") {
          throw new TavernNarrativeLifecycleJobError(
            "ATTEMPTS_EXHAUSTED",
            `Lifecycle exhausted ${attemptTask.max_attempts} attempts after provider failures`,
          );
        }
        continue;
      } finally {
        if (this.active?.sequence === sequence) this.active = null;
      }
      if (outcome.kind === "cancelled") {
        let settledResponse: TavernStructuredGenerationResult | undefined;
        if (!outcome.cancellation.host_cancel_requested) {
          settledResponse = await generation.catch(() => undefined);
        }
        const content = settledResponse?.content;
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status:
            outcome.cancellation.reason === "newer_lifecycle_job" ? "superseded" : "cancelled",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code:
            outcome.cancellation.reason === "newer_lifecycle_job" ? "SUPERSEDED" : "CANCELLED",
          host_cancel_requested: outcome.cancellation.host_cancel_requested,
          ...(content === undefined
            ? {}
            : {
                response_sha256: await sha256HexUtf8(content),
                response_utf8_bytes: utf8ByteLength(content),
              }),
        });
        return {
          status:
            outcome.cancellation.reason === "newer_lifecycle_job" ? "SUPERSEDED" : "CANCELLED",
          job_id: request.job_id,
          reason: outcome.cancellation.reason,
          host_cancel_requested: outcome.cancellation.host_cancel_requested,
        };
      }
      const content = outcome.result.content;
      if (outcome.result.kind !== "text") {
        await settleResponseRejection(generationId, startedAtMs, content, "GENERATION_TOOL_CALLS");
        continue;
      }
      const responseSha256 = await sha256HexUtf8(content);
      let value: unknown;
      try {
        value = JSON.parse(content) as unknown;
      } catch {
        await settleResponseRejection(generationId, startedAtMs, content, "RESPONSE_JSON_INVALID");
        continue;
      }
      const wire = validateWireValue(adapter.output_schema, value);
      if (!wire.valid) {
        await settleResponseRejection(
          generationId,
          startedAtMs,
          content,
          "RESPONSE_SCHEMA_INVALID",
        );
        continue;
      }
      const draft = value as FlatNarrativeLifecycleDraftV020;
      let compilation: Awaited<ReturnType<typeof compileFlatNarrativeLifecycleDraft>>;
      try {
        compilation = await compileFlatNarrativeLifecycleDraft(
          draft,
          task.model_input,
          task.memory_set_id,
        );
      } catch {
        await settleResponseRejection(
          generationId,
          startedAtMs,
          content,
          "RESPONSE_SCHEMA_INVALID",
        );
        continue;
      }
      const responseCancellation = this.cancellation(sequence, request.job_id);
      if (responseCancellation !== null) {
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: responseCancellation.status === "SUPERSEDED" ? "superseded" : "cancelled",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: responseCancellation.status,
          response_sha256: responseSha256,
          response_utf8_bytes: utf8ByteLength(content),
        });
        return responseCancellation;
      }
      let commit: Awaited<ReturnType<typeof this.lifecycle.commit>>;
      try {
        commit = await this.lifecycle.commit({
          task,
          spec: compilation.spec,
          extractor: {
            model_id: adapter.exact_model_id,
            model_identity_assurance: "requested_not_attested",
            prompt_contract_version: adapter.prompt_asset_ref,
            prompt_body_sha256: createSha256Digest(promptAsset.body_sha256),
            parameters_hash: createSha256Digest(parametersSha256),
          },
          compiled_at: request.compiled_at,
          writer_id: request.writer_id,
          transaction_id: `tx_lifecycle_${operationFingerprint.slice(0, 32)}`,
          build_id: request.build_id,
          view_id: `view_lifecycle_${operationFingerprint.slice(0, 32)}`,
        });
      } catch (error) {
        if (
          error instanceof TavernNarrativeLifecycleError &&
          error.code === "LIFECYCLE_CONTINUITY_UNEXPLAINED"
        ) {
          await settleResponseRejection(
            generationId,
            startedAtMs,
            content,
            "LIFECYCLE_CONTINUITY_UNEXPLAINED",
          );
          continue;
        }
        if (
          error instanceof TavernNarrativeLifecycleError &&
          (error.code === "STALE_TASK" || error.code === "SOURCE_CHANGED_DURING_COMMIT")
        ) {
          await attemptStore.recordFailure(operationFingerprint, generationId, {
            status: "superseded",
            settled_at: new Date().toISOString(),
            elapsed_ms: Math.max(0, Date.now() - startedAtMs),
            error_code: error.code,
            response_sha256: responseSha256,
            response_utf8_bytes: utf8ByteLength(content),
          });
          return { status: "STALE", job_id: request.job_id, reason: error.code };
        }
        await attemptStore.recordFailure(operationFingerprint, generationId, {
          status: "terminal_failure",
          settled_at: new Date().toISOString(),
          elapsed_ms: Math.max(0, Date.now() - startedAtMs),
          error_code: "LIFECYCLE_COMMIT_FAILED",
          diagnostic_codes:
            error instanceof TavernNarrativeLifecycleError ? [error.code] : ["UNCLASSIFIED_ERROR"],
          response_sha256: responseSha256,
          response_utf8_bytes: utf8ByteLength(content),
        });
        throw error;
      }
      const committed = await attemptStore.recordCommitted(operationFingerprint, generationId, {
        committed_at: new Date().toISOString(),
        elapsed_ms: Math.max(0, Date.now() - startedAtMs),
        response_sha256: responseSha256,
        response_utf8_bytes: utf8ByteLength(content),
      });
      return {
        status: "COMMITTED",
        audit,
        memory_set_id: task.memory_set_id,
        source_revision_id: task.model_input.source_revision_id,
        response_sha256: responseSha256,
        response_utf8_bytes: utf8ByteLength(content),
        attempt_count: committed.task.attempts.length,
        draft,
        spec: compilation.spec,
        unresolved_item_count: compilation.unresolved_items.length,
        commit,
      };
    }
    throw new TavernNarrativeLifecycleJobError(
      "ATTEMPT_LEDGER_BLOCKED",
      `Lifecycle operation cannot continue from durable status ${attemptTask.status}`,
    );
  }
}
