import type {
  TavernCurrentArchiveSyncRequest,
  TavernCurrentArchiveSyncResult,
} from "./current-archive-contracts.js";
import type {
  TavernExtractionCancellationReport,
  TavernExtractionJobRequest,
  TavernExtractionJobResult,
  TavernRuntimePromptAsset,
} from "./extraction-job-contracts.js";
import type {
  TavernNarrativeLifecycleCancellationReport,
  TavernNarrativeLifecycleJobRequest,
  TavernNarrativeLifecycleJobResult,
} from "./narrative-lifecycle-job-contracts.js";
import type { TavernPrepareIncrementalExtractionRequest } from "./semantic-archive-contracts.js";
import type { TavernMutationHint } from "./source-snapshot-contracts.js";

export const TAVERN_OBSERVER_SCHEDULER_VERSION = "0.6.0" as const;

export const TAVERN_OBSERVER_EVENT_NAMES = [
  "message_swiped",
  "message_sent",
  "message_received",
  "message_edited",
  "message_deleted",
  "message_updated",
  "message_swipe_deleted",
  "chat_id_changed",
  "generation_started",
  "generation_stopped",
  "generation_ended",
] as const;

export type TavernObserverEventName = (typeof TAVERN_OBSERVER_EVENT_NAMES)[number];

export interface TavernObserverExtractionConfig {
  readonly requested_model_id: string;
  readonly retry_round_id?: string;
  readonly proxy_preset?: string;
  readonly runtime_prompt_assets: readonly TavernRuntimePromptAsset[];
  readonly allow_candidate_prompt: boolean;
  readonly max_attempts?: number;
  readonly prepare: Omit<TavernPrepareIncrementalExtractionRequest, "created_at">;
}

export interface TavernObserverSchedulerConfig {
  readonly debounce_ms: number;
  readonly max_sync_attempts: number;
  readonly writer_id: string;
  readonly build_id: string;
  readonly exclusive_recovery_confirmed: boolean;
  readonly extraction: TavernObserverExtractionConfig;
  readonly lifecycle?: Omit<TavernObserverExtractionConfig, "prepare">;
}

export interface TavernObserverRuntime {
  now_iso(): string;
  next_token(): string;
  set_timer(callback: () => void, delay_ms: number): unknown;
  clear_timer(handle: unknown): void;
}

export interface TavernObserverStartOptions {
  /** One-shot authorization for the initial catch-up created by an explicit Runtime re-arm. */
  readonly cancelled_attempt_recovery?: "explicit_runtime_rearm";
}

export interface TavernObserverCurrentArchiveService {
  sync(request: TavernCurrentArchiveSyncRequest): Promise<TavernCurrentArchiveSyncResult>;
}

export interface TavernObserverExtractionJobService {
  runLatest(request: TavernExtractionJobRequest): Promise<TavernExtractionJobResult>;
  invalidateCurrent(reason: string): TavernExtractionCancellationReport;
}

export interface TavernObserverNarrativeLifecycleJobService {
  runLatest(
    request: TavernNarrativeLifecycleJobRequest,
  ): Promise<TavernNarrativeLifecycleJobResult>;
  invalidateCurrent(reason: string): TavernNarrativeLifecycleCancellationReport;
}

export type TavernObserverMainGenerationTrigger = "generation_after_commands" | "message_sent";

export interface TavernObserverBatchDescriptor {
  readonly cycle_id: string;
  readonly sequence: number;
  readonly observed_hints: readonly TavernMutationHint[];
  readonly extraction_requested: boolean;
  readonly cancelled_attempt_recovery?: "explicit_runtime_rearm";
  readonly started_at: string;
}

export type TavernObserverRecallPreparation =
  | {
      readonly status: "COMMITTED_COVERAGE_READY";
      readonly sequence: number;
      readonly extraction_audit: Extract<
        TavernExtractionJobResult,
        { readonly status: "COMMITTED" | "ALREADY_CURRENT" }
      >["audit"];
      readonly cancellation: TavernExtractionCancellationReport;
    }
  | {
      readonly status: "NO_COMMITTED_COVERAGE";
      readonly sequence: number;
      readonly cancellation: TavernExtractionCancellationReport;
    };

export type TavernObserverCycleReport =
  | {
      readonly status: "ACTION_REQUIRED";
      readonly batch: TavernObserverBatchDescriptor;
      readonly completed_at: string;
      readonly sync_attempts: number;
      readonly sync: Extract<
        TavernCurrentArchiveSyncResult,
        { readonly status: "ACTION_REQUIRED" }
      >;
    }
  | {
      readonly status: "SOURCE_STABLE";
      readonly batch: TavernObserverBatchDescriptor;
      readonly completed_at: string;
      readonly sync_attempts: number;
      readonly extraction_skipped: "SOURCE_ONLY_EVENT" | "MAIN_GENERATION_ACTIVE";
      readonly sync: Extract<
        TavernCurrentArchiveSyncResult,
        { readonly status: "SYNCED" | "UNCHANGED" }
      >;
    }
  | {
      readonly status: "EXTRACTION_FINISHED";
      readonly batch: TavernObserverBatchDescriptor;
      readonly completed_at: string;
      readonly sync_attempts: number;
      readonly sync: Extract<
        TavernCurrentArchiveSyncResult,
        { readonly status: "SYNCED" | "UNCHANGED" }
      >;
      readonly extraction: TavernExtractionJobResult;
      readonly lifecycle?: TavernNarrativeLifecycleJobResult;
    }
  | {
      readonly status: "SUPERSEDED";
      readonly batch: TavernObserverBatchDescriptor;
      readonly completed_at: string;
      readonly sync_attempts: number;
      readonly stage: "SOURCE_SYNC" | "EXTRACTION" | "LIFECYCLE";
      readonly extraction?: TavernExtractionJobResult;
      readonly lifecycle?: TavernNarrativeLifecycleJobResult;
    }
  | {
      readonly status: "FAILED";
      readonly batch: TavernObserverBatchDescriptor;
      readonly completed_at: string;
      readonly sync_attempts: number;
      readonly phase: "SOURCE_SYNC" | "EXTRACTION" | "LIFECYCLE";
      readonly error_name: string;
      readonly error_message: string;
      readonly error_code?: string;
      readonly extraction?: TavernExtractionJobResult;
    };

export interface TavernObserverSchedulerSnapshot {
  readonly scheduler_version: typeof TAVERN_OBSERVER_SCHEDULER_VERSION;
  readonly lifecycle: "idle" | "running" | "stopped" | "disposed";
  readonly latest_sequence: number;
  readonly main_generation_active: boolean;
  readonly timer_pending: boolean;
  readonly cycle_in_flight: boolean;
  readonly pending_hints: readonly TavernMutationHint[];
  readonly pending_extraction_requested: boolean;
  readonly committed_coverage_available: boolean;
  readonly last_cancellation: TavernExtractionCancellationReport | null;
  readonly last_report: TavernObserverCycleReport | null;
}

export class TavernObserverSchedulerError extends Error {
  constructor(
    readonly code: "INVALID_CONFIG" | "INVALID_RUNTIME" | "SUBSCRIPTION_FAILED" | "DISPOSED",
    message: string,
  ) {
    super(message);
    this.name = "TavernObserverSchedulerError";
  }
}
