import {
  type AgentTransportOperationRecord,
  type AgentTransportRetryAuthorization,
  assertAgentTransportOperation,
  attestAgentTransportResponse,
  authorizeAgentTransportRetry,
  commitAgentTransportResponse,
  createAgentTransportOperation,
  markAgentTransportAttemptDispatched,
  recordAgentTransportFailure,
  recoverAgentTransportOperation,
  rejectAgentTransportResponse,
  reserveAgentTransportAttempt,
} from "@narramem/agent-runtime";
import { createSha256Digest } from "@narramem/core-domain";

import {
  TAVERN_AGENT_TRANSPORT_STORE_FORMAT,
  TAVERN_AGENT_TRANSPORT_STORE_VERSION,
  type TavernAgentTransportResponseArtifactRecord,
  TavernAgentTransportStoreError,
  type TavernAgentTransportStorePayload,
} from "./agent-transport-worldbook-contracts.js";
import type { TavernCausalAuditTaskStateRecord } from "./causal-audit-task-store-contracts.js";
import type {
  TavernHostPort,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import { canonicalJson, checksumJson, sha256HexUtf8, utf8ByteLength } from "./worldbook-codec.js";

const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const SHA256_PATTERN = /^[a-f0-9]{64}$/u;

type StoreState = {
  readonly entry: TavernWorldbookEntry;
  readonly payload: TavernAgentTransportStorePayload;
};

export interface CreateTavernAgentTransportOperationRequest {
  readonly expected_checksum: string;
  readonly task: Pick<
    TavernCausalAuditTaskStateRecord,
    "task_seed_id" | "source_revision_id" | "source_checksum" | "status" | "lease"
  >;
  readonly operation_kind: string;
  readonly call_index: number;
  readonly provider_route_id: string;
  readonly requested_model_id: string;
  readonly prompt_asset_refs: readonly string[];
  readonly request_sha256: string;
  readonly request_utf8_bytes: number;
  readonly max_attempts: number;
  readonly created_at: string;
}

const clone = <T>(value: T): T => structuredClone(value);
const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function entryDraft(content: string): TavernWorldbookEntryDraft {
  return {
    name: "NarraMem Agent Transport Ledger",
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 0, order: 0 },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: { narramem: { record_kind: "agent_transport_store" } },
  };
}

function assertEntry(entry: TavernWorldbookEntry): void {
  if (
    !Number.isSafeInteger(entry.uid) ||
    entry.uid < 0 ||
    entry.enabled ||
    entry.strategy.type !== "constant" ||
    entry.strategy.keys.length !== 0 ||
    !entry.recursion.prevent_incoming ||
    !entry.recursion.prevent_outgoing
  ) {
    throw new TavernAgentTransportStoreError(
      "STORE_CORRUPT",
      "Tavern Agent transport entry safety settings changed",
    );
  }
}

function assertArtifact(
  value: unknown,
): asserts value is TavernAgentTransportResponseArtifactRecord {
  if (
    !isObject(value) ||
    typeof value.artifact_ref !== "string" ||
    !/^tavern-response-[a-f0-9]{64}$/u.test(value.artifact_ref) ||
    typeof value.content_sha256 !== "string" ||
    !SHA256_PATTERN.test(value.content_sha256) ||
    typeof value.utf8_bytes !== "number" ||
    !Number.isSafeInteger(value.utf8_bytes) ||
    value.utf8_bytes < 0 ||
    typeof value.content !== "string" ||
    utf8ByteLength(value.content) !== value.utf8_bytes
  ) {
    throw new TavernAgentTransportStoreError("STORE_CORRUPT", "Invalid response artifact");
  }
}

async function encodePayload(
  memorySetId: string,
  operations: readonly AgentTransportOperationRecord[],
  artifacts: readonly TavernAgentTransportResponseArtifactRecord[],
): Promise<TavernAgentTransportStorePayload> {
  const sortedOperations = [...operations]
    .map(clone)
    .sort((left, right) => left.operation_id.localeCompare(right.operation_id));
  const sortedArtifacts = [...artifacts]
    .map(clone)
    .sort((left, right) => left.artifact_ref.localeCompare(right.artifact_ref));
  for (const operation of sortedOperations) assertAgentTransportOperation(operation);
  for (const artifact of sortedArtifacts) {
    assertArtifact(artifact);
    if ((await sha256HexUtf8(artifact.content)) !== artifact.content_sha256) {
      throw new TavernAgentTransportStoreError(
        "STORE_CORRUPT",
        "Response artifact content hash mismatch",
      );
    }
  }
  if (
    new Set(sortedOperations.map((item) => item.operation_id)).size !== sortedOperations.length ||
    new Set(sortedArtifacts.map((item) => item.artifact_ref)).size !== sortedArtifacts.length
  ) {
    throw new TavernAgentTransportStoreError(
      "INVALID_INPUT",
      "Agent transport operations and artifacts must be unique",
    );
  }
  const unsigned = {
    format: TAVERN_AGENT_TRANSPORT_STORE_FORMAT,
    schema_version: TAVERN_AGENT_TRANSPORT_STORE_VERSION,
    memory_set_id: memorySetId,
    operations: sortedOperations,
    response_artifacts: sortedArtifacts,
  };
  return { ...unsigned, checksum: await checksumJson(unsigned) };
}

async function parsePayload(
  content: string,
  memorySetId: string,
): Promise<TavernAgentTransportStorePayload> {
  let value: unknown;
  try {
    value = JSON.parse(content);
  } catch {
    throw new TavernAgentTransportStoreError("STORE_CORRUPT", "Transport store is not JSON");
  }
  if (
    !isObject(value) ||
    value.format !== TAVERN_AGENT_TRANSPORT_STORE_FORMAT ||
    value.schema_version !== TAVERN_AGENT_TRANSPORT_STORE_VERSION ||
    value.memory_set_id !== memorySetId ||
    !Array.isArray(value.operations) ||
    !Array.isArray(value.response_artifacts) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernAgentTransportStoreError("STORE_CORRUPT", "Invalid transport store payload");
  }
  const operations = value.operations as unknown as AgentTransportOperationRecord[];
  const artifacts = value.response_artifacts as unknown[];
  try {
    for (const operation of operations) assertAgentTransportOperation(operation);
    for (const artifact of artifacts) assertArtifact(artifact);
  } catch (error) {
    throw new TavernAgentTransportStoreError(
      "STORE_CORRUPT",
      error instanceof Error ? error.message : "Transport payload validation failed",
    );
  }
  const payload = value as unknown as TavernAgentTransportStorePayload;
  const { checksum: _checksum, ...unsigned } = payload;
  if ((await checksumJson(unsigned)) !== payload.checksum) {
    throw new TavernAgentTransportStoreError("STORE_CORRUPT", "Transport store checksum mismatch");
  }
  for (const artifact of payload.response_artifacts) {
    if ((await sha256HexUtf8(artifact.content)) !== artifact.content_sha256) {
      throw new TavernAgentTransportStoreError(
        "STORE_CORRUPT",
        "Response artifact content hash mismatch",
      );
    }
  }
  return payload;
}

export function tavernAgentTransportBookName(memorySetId: string): string {
  if (!SAFE_MEMORY_SET_PATTERN.test(memorySetId)) {
    throw new TavernAgentTransportStoreError("INVALID_INPUT", "Invalid memory_set_id");
  }
  return `NarraMem__AGENT_TRANSPORT__${memorySetId}`;
}

async function operationId(
  memorySetId: string,
  request: CreateTavernAgentTransportOperationRequest,
): Promise<string> {
  return `agent_op_${await sha256HexUtf8(
    canonicalJson({
      runtime: "tavern",
      memory_set_id: memorySetId,
      task_seed_id: request.task.task_seed_id,
      source_revision_id: request.task.source_revision_id,
      source_checksum: request.task.source_checksum,
      operation_kind: request.operation_kind,
      call_index: request.call_index,
      provider_route_id: request.provider_route_id,
      requested_model_id: request.requested_model_id,
      prompt_asset_refs: [...request.prompt_asset_refs],
      request_sha256: request.request_sha256,
    }),
  )}`;
}

async function nextAttemptId(operation: AgentTransportOperationRecord): Promise<string> {
  return `agent_attempt_${await sha256HexUtf8(
    canonicalJson({
      operation_id: operation.operation_id,
      attempt_number: operation.attempts.length + 1,
    }),
  )}`;
}

export class TavernAgentTransportWorldbookStore {
  readonly book_name: string;
  private writerTail: Promise<void> = Promise.resolve();

  constructor(
    private readonly port: TavernHostPort,
    readonly memory_set_id: string,
  ) {
    this.book_name = tavernAgentTransportBookName(memory_set_id);
  }

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writerTail.then(operation, operation);
    this.writerTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async read(): Promise<TavernAgentTransportStorePayload | null> {
    return (await this.readState())?.payload ?? null;
  }

  initialize(): Promise<TavernAgentTransportStorePayload> {
    return this.enqueue(async () => {
      const existing = await this.readState();
      if (existing !== null) return existing.payload;
      if (!(await this.port.createWorldbook(this.book_name))) {
        const raced = await this.readState();
        if (raced !== null) return raced.payload;
        throw new TavernAgentTransportStoreError(
          "WRITE_CONFLICT",
          "Agent transport World Book creation collided",
        );
      }
      const payload = await encodePayload(this.memory_set_id, [], []);
      const appended = await this.port.appendWorldbookEntries(this.book_name, [
        entryDraft(canonicalJson(payload)),
      ]);
      if (appended.new_entries.length !== 1) {
        throw new TavernAgentTransportStoreError(
          "WRITE_CONFLICT",
          "Agent transport initialization did not create one entry",
        );
      }
      const verified = await this.read();
      if (verified?.checksum !== payload.checksum) {
        throw new TavernAgentTransportStoreError(
          "WRITE_CONFLICT",
          "Agent transport initialization read-back mismatch",
        );
      }
      return verified;
    });
  }

  create(request: CreateTavernAgentTransportOperationRequest): Promise<{
    readonly status: "created" | "duplicate";
    readonly payload: TavernAgentTransportStorePayload;
    readonly operation: AgentTransportOperationRecord;
  }> {
    return this.enqueue(async () => {
      if (
        request.task.status !== "leased" ||
        request.task.lease === undefined ||
        !Number.isSafeInteger(request.call_index) ||
        request.call_index < 0 ||
        !SHA256_PATTERN.test(request.request_sha256)
      ) {
        throw new TavernAgentTransportStoreError(
          "INVALID_INPUT",
          "Tavern transport creation requires a leased task, call index, and request hash",
        );
      }
      const state = await this.requireExpected(request.expected_checksum);
      const id = await operationId(this.memory_set_id, request);
      const existing = state.payload.operations.find((item) => item.operation_id === id);
      if (existing !== undefined) {
        return { status: "duplicate", payload: state.payload, operation: clone(existing) };
      }
      const operation = createAgentTransportOperation({
        operation_id: id,
        request: {
          operation_kind: request.operation_kind,
          task_id: request.task.task_seed_id,
          source_revision_id: request.task.source_revision_id,
          scope_fingerprint: createSha256Digest(request.task.source_checksum),
          provider_id: request.provider_route_id,
          requested_model_id: request.requested_model_id,
          prompt_asset_refs: [...request.prompt_asset_refs],
          request_sha256: createSha256Digest(request.request_sha256),
          request_utf8_bytes: request.request_utf8_bytes,
          provider_idempotency: { capability: "provider_unverified" },
        },
        max_attempts: request.max_attempts,
        created_at: request.created_at,
      });
      const payload = await this.write(
        state,
        [...state.payload.operations, operation],
        state.payload.response_artifacts,
      );
      return { status: "created", payload, operation: clone(operation) };
    });
  }

  reserve(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    reservedAt: string,
  ): Promise<{
    readonly payload: TavernAgentTransportStorePayload;
    readonly operation: AgentTransportOperationRecord;
  }> {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) =>
        reserveAgentTransportAttempt(operation, {
          attempt_id: await nextAttemptId(operation),
          reserved_at: reservedAt,
        }).operation,
    );
  }

  markDispatched(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    dispatchedAt: string,
  ) {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) => {
        const attempt = operation.attempts.at(-1);
        if (attempt === undefined) {
          throw new TavernAgentTransportStoreError("INVALID_INPUT", "No reserved attempt exists");
        }
        return markAgentTransportAttemptDispatched(operation, {
          attempt_id: attempt.attempt_id,
          dispatched_at: dispatchedAt,
        }).operation;
      },
    );
  }

  recordFailure(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    request: {
      readonly kind: "definitive_not_dispatched" | "unknown_after_dispatch";
      readonly error_code: string;
      readonly observed_at: string;
    },
  ) {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) => {
        const attempt = operation.attempts.at(-1);
        if (attempt === undefined) {
          throw new TavernAgentTransportStoreError("INVALID_INPUT", "No current attempt exists");
        }
        return recordAgentTransportFailure(operation, {
          attempt_id: attempt.attempt_id,
          ...request,
        }).operation;
      },
    );
  }

  recoverInterrupted(expectedChecksum: string, recoveredAt: string) {
    return this.enqueue(async () => {
      const state = await this.requireExpected(expectedChecksum);
      const operations = state.payload.operations.map(
        (operation) => recoverAgentTransportOperation(operation, recoveredAt).operation,
      );
      const changed = operations.some(
        (operation, index) =>
          operation.record_version !== state.payload.operations[index]?.record_version,
      );
      const payload = changed
        ? await this.write(state, operations, state.payload.response_artifacts)
        : state.payload;
      return {
        payload,
        recovered_operation_ids: operations
          .filter(
            (operation, index) =>
              operation.record_version !== state.payload.operations[index]?.record_version,
          )
          .map((operation) => operation.operation_id),
      };
    });
  }

  authorizeRetry(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    request: Omit<AgentTransportRetryAuthorization, "authorization_id">,
  ) {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) => {
        const authorizationId = `agent_retry_${await sha256HexUtf8(
          canonicalJson({ operation_id: operation.operation_id, ...request }),
        )}`;
        return authorizeAgentTransportRetry(operation, {
          ...request,
          authorization_id: authorizationId,
        }).operation;
      },
    );
  }

  attestHostResponse(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    response: { readonly content: string; readonly received_at: string },
  ) {
    return this.enqueue(async () => {
      const state = await this.requireExpected(expectedChecksum);
      const operation = this.requireOperation(state, operationIdValue, expectedRecordVersion);
      const attempt = operation.attempts.at(-1);
      if (attempt === undefined) {
        throw new TavernAgentTransportStoreError("INVALID_INPUT", "No current attempt exists");
      }
      const contentSha256 = await sha256HexUtf8(response.content);
      const artifactRef = `tavern-response-${contentSha256}`;
      const existingArtifact = state.payload.response_artifacts.find(
        (item) => item.artifact_ref === artifactRef,
      );
      if (existingArtifact !== undefined && existingArtifact.content !== response.content) {
        throw new TavernAgentTransportStoreError(
          "STORE_CORRUPT",
          "Content-addressed Tavern response artifact drifted",
        );
      }
      const artifact: TavernAgentTransportResponseArtifactRecord = existingArtifact ?? {
        artifact_ref: artifactRef,
        content_sha256: contentSha256,
        utf8_bytes: utf8ByteLength(response.content),
        content: response.content,
      };
      const attestationId = `agent_response_${await sha256HexUtf8(
        canonicalJson({
          attempt_id: attempt.attempt_id,
          received_at: response.received_at,
          content_sha256: contentSha256,
        }),
      )}`;
      const next = attestAgentTransportResponse(operation, {
        attestation_id: attestationId,
        attempt_id: attempt.attempt_id,
        received_at: response.received_at,
        transport_kind: "host_generation_result",
        response_artifact: {
          artifact_ref: artifactRef,
          content_sha256: createSha256Digest(contentSha256),
          utf8_bytes: artifact.utf8_bytes,
        },
      }).operation;
      const operations = state.payload.operations.map((item) =>
        item.operation_id === operationIdValue ? next : item,
      );
      const artifacts =
        existingArtifact === undefined
          ? [...state.payload.response_artifacts, artifact]
          : state.payload.response_artifacts;
      const payload = await this.write(state, operations, artifacts);
      return { payload, operation: clone(next), artifact: clone(artifact) };
    });
  }

  commitResponse(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    attestationId: string,
    committedAt: string,
  ) {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) =>
        commitAgentTransportResponse(operation, {
          attestation_id: attestationId,
          committed_at: committedAt,
        }).operation,
    );
  }

  rejectResponse(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    attestationId: string,
    errorCode: string,
    rejectedAt: string,
  ) {
    return this.mutate(
      expectedChecksum,
      operationIdValue,
      expectedRecordVersion,
      async (operation) =>
        rejectAgentTransportResponse(operation, {
          attestation_id: attestationId,
          error_code: errorCode,
          rejected_at: rejectedAt,
        }).operation,
    );
  }

  compact(expectedChecksum: string, maxTerminalHistory: number) {
    return this.enqueue(async () => {
      if (
        !Number.isSafeInteger(maxTerminalHistory) ||
        maxTerminalHistory < 0 ||
        maxTerminalHistory > 10_000
      ) {
        throw new TavernAgentTransportStoreError(
          "INVALID_INPUT",
          "Agent transport terminal history limit must be between 0 and 10000",
        );
      }
      const state = await this.requireExpected(expectedChecksum);
      const terminal = new Set(["completed", "failed", "cancelled"]);
      const active = state.payload.operations.filter((item) => !terminal.has(item.status));
      const retainedTerminal = state.payload.operations
        .filter((item) => terminal.has(item.status))
        .sort(
          (left, right) =>
            right.updated_at.localeCompare(left.updated_at) ||
            right.operation_id.localeCompare(left.operation_id),
        )
        .slice(0, maxTerminalHistory);
      const retained = [...active, ...retainedTerminal];
      const activeArtifactRefs = new Set(
        active.flatMap((operation) =>
          operation.attempts.flatMap((attempt) =>
            attempt.response_attestations.map(
              (attestation) => attestation.response_artifact.artifact_ref,
            ),
          ),
        ),
      );
      const artifacts = state.payload.response_artifacts.filter((artifact) =>
        activeArtifactRefs.has(artifact.artifact_ref),
      );
      const removedOperationIds = state.payload.operations
        .filter(
          (operation) => !retained.some((item) => item.operation_id === operation.operation_id),
        )
        .map((operation) => operation.operation_id);
      const removedArtifactRefs = state.payload.response_artifacts
        .filter((artifact) => !activeArtifactRefs.has(artifact.artifact_ref))
        .map((artifact) => artifact.artifact_ref);
      const payload =
        removedOperationIds.length === 0 && removedArtifactRefs.length === 0
          ? state.payload
          : await this.write(state, retained, artifacts);
      return {
        payload,
        removed_operation_ids: removedOperationIds,
        removed_artifact_refs: removedArtifactRefs,
      };
    });
  }

  async readArtifact(artifactRef: string): Promise<string> {
    const payload = await this.read();
    const artifact = payload?.response_artifacts.find((item) => item.artifact_ref === artifactRef);
    if (artifact === undefined) {
      throw new TavernAgentTransportStoreError(
        "ARTIFACT_NOT_FOUND",
        "Tavern Agent response artifact does not exist",
      );
    }
    return artifact.content;
  }

  private mutate(
    expectedChecksum: string,
    operationIdValue: string,
    expectedRecordVersion: number,
    transition: (
      operation: AgentTransportOperationRecord,
    ) => Promise<AgentTransportOperationRecord>,
  ) {
    return this.enqueue(async () => {
      const state = await this.requireExpected(expectedChecksum);
      const operation = this.requireOperation(state, operationIdValue, expectedRecordVersion);
      const next = await transition(clone(operation));
      const operations = state.payload.operations.map((item) =>
        item.operation_id === operationIdValue ? next : item,
      );
      const payload = await this.write(state, operations, state.payload.response_artifacts);
      return { payload, operation: clone(next) };
    });
  }

  private requireOperation(
    state: StoreState,
    operationIdValue: string,
    expectedRecordVersion: number,
  ): AgentTransportOperationRecord {
    const operation = state.payload.operations.find(
      (item) => item.operation_id === operationIdValue,
    );
    if (operation === undefined) {
      throw new TavernAgentTransportStoreError(
        "OPERATION_NOT_FOUND",
        "Tavern Agent transport operation does not exist",
      );
    }
    if (operation.record_version !== expectedRecordVersion) {
      throw new TavernAgentTransportStoreError(
        "RECORD_VERSION_MISMATCH",
        "Tavern Agent transport mutation requires the current record version",
      );
    }
    return operation;
  }

  private async readState(): Promise<StoreState | null> {
    if (!this.port.listWorldbooks().includes(this.book_name)) return null;
    const entries = await this.port.readWorldbook(this.book_name);
    const entry = entries[0];
    if (entries.length !== 1 || entry === undefined) {
      throw new TavernAgentTransportStoreError(
        "STORE_CORRUPT",
        "Agent transport World Book must contain exactly one entry",
      );
    }
    assertEntry(entry);
    return { entry, payload: await parsePayload(entry.content, this.memory_set_id) };
  }

  private async requireExpected(expectedChecksum: string): Promise<StoreState> {
    const state = await this.readState();
    if (state === null) {
      throw new TavernAgentTransportStoreError(
        "STORE_NOT_FOUND",
        "Agent transport World Book is not initialized",
      );
    }
    if (state.payload.checksum !== expectedChecksum) {
      throw new TavernAgentTransportStoreError(
        "WRITE_CONFLICT",
        "Agent transport World Book checksum changed",
      );
    }
    return state;
  }

  private async write(
    state: StoreState,
    operations: readonly AgentTransportOperationRecord[],
    artifacts: readonly TavernAgentTransportResponseArtifactRecord[],
  ): Promise<TavernAgentTransportStorePayload> {
    const current = await this.readState();
    if (
      current === null ||
      current.entry.uid !== state.entry.uid ||
      current.payload.checksum !== state.payload.checksum
    ) {
      throw new TavernAgentTransportStoreError(
        "WRITE_CONFLICT",
        "Agent transport World Book changed before commit",
      );
    }
    const payload = await encodePayload(this.memory_set_id, operations, artifacts);
    await this.port.replaceWorldbook(this.book_name, [
      { ...entryDraft(canonicalJson(payload)), uid: state.entry.uid },
    ]);
    const verified = await this.readState();
    if (verified?.payload.checksum !== payload.checksum) {
      throw new TavernAgentTransportStoreError(
        "WRITE_CONFLICT",
        "Agent transport World Book read-back mismatch",
      );
    }
    return verified.payload;
  }
}
