import {
  createNarraMemId,
  createSha256Digest,
  type Entity,
  type EvidenceItem,
  type ExtractionClaimPredicateTerm,
  type ExtractionEventTypeTerm,
  type ExtractionKnownEntity,
  type ExtractionStateKeyTerm,
  type HashDigest,
  type MemorySpace,
  type NarraMemId,
  type NarraMemIdKind,
  type NarrativeExtractionModelInput,
  type SourceRevision,
  type TemporalExtent,
} from "@narramem/core-domain";

import type { TavernSourceSnapshot } from "./source-snapshot-contracts.js";
import { checksumJson, sha256HexUtf8 } from "./worldbook-codec.js";

export const TAVERN_CORE_SOURCE_PROJECTION_VERSION = "0.2.0" as const;

export interface TavernCoreSourceProjectionRequest {
  readonly snapshot: TavernSourceSnapshot;
  readonly known_entities: readonly ExtractionKnownEntity[];
  readonly event_type_vocabulary: readonly ExtractionEventTypeTerm[];
  readonly state_key_vocabulary?: readonly ExtractionStateKeyTerm[];
  readonly claim_predicate_vocabulary?: readonly ExtractionClaimPredicateTerm[];
  readonly default_story_time: TemporalExtent;
  readonly created_at: string;
  /** Inclusive model/projection cutoff; the SourceRevision identity still binds the full snapshot. */
  readonly message_end_ordinal?: number;
}

export interface TavernCoreSourceProjection {
  readonly projection_version: typeof TAVERN_CORE_SOURCE_PROJECTION_VERSION;
  readonly memory_space: MemorySpace;
  readonly source_revision: SourceRevision;
  readonly evidence_items: readonly EvidenceItem[];
  readonly source_entities: readonly Entity[];
  readonly model_input: NarrativeExtractionModelInput;
}

function uuidV8FromSha256(hex: string): string {
  const chars = hex.slice(0, 32).split("");
  chars[12] = "8";
  chars[16] = "8";
  const normalized = chars.join("");
  return `${normalized.slice(0, 8)}-${normalized.slice(8, 12)}-${normalized.slice(
    12,
    16,
  )}-${normalized.slice(16, 20)}-${normalized.slice(20, 32)}`;
}

export async function createDeterministicNarraMemId<Kind extends NarraMemIdKind>(
  kind: Kind,
  namespace: string,
): Promise<NarraMemId<Kind>> {
  return createNarraMemId(kind, uuidV8FromSha256(await sha256HexUtf8(namespace)));
}

export const sha256DigestUtf8 = async (text: string): Promise<HashDigest> =>
  createSha256Digest(await sha256HexUtf8(text));

type NarrativeParticipantRole = "user" | "assistant";

interface ParticipantEvidence {
  readonly label: string;
  readonly evidence: EvidenceItem;
  readonly quote_hash: HashDigest;
}

function isNarrativeParticipantRole(role: string): role is NarrativeParticipantRole {
  return role === "user" || role === "assistant";
}

export async function projectTavernCoreSource(
  request: TavernCoreSourceProjectionRequest,
): Promise<TavernCoreSourceProjection> {
  const { snapshot } = request;
  const memorySpaceId = await createDeterministicNarraMemId(
    "memory_space",
    `tavern-memory-space:${snapshot.memory_set_id}`,
  );
  const branchId = await createDeterministicNarraMemId(
    "branch",
    `tavern-branch:${snapshot.memory_set_id}:main`,
  );
  const revisionId = await createDeterministicNarraMemId(
    "source_revision",
    `tavern-source-revision:${snapshot.memory_set_id}:${snapshot.checksum}`,
  );
  const participantEntityIds = new Map<NarrativeParticipantRole, Entity["entity_id"]>();
  for (const role of ["user", "assistant"] as const) {
    participantEntityIds.set(
      role,
      await createDeterministicNarraMemId(
        "entity",
        `tavern-narrative-participant:${snapshot.memory_set_id}:${role}`,
      ),
    );
  }
  const evidenceItems: EvidenceItem[] = [];
  const participantEvidence = new Map<NarrativeParticipantRole, ParticipantEvidence[]>();
  for (const message of snapshot.messages) {
    if (
      request.message_end_ordinal !== undefined &&
      message.message_id_at_capture > request.message_end_ordinal
    ) {
      continue;
    }
    if (message.narrative_text === null || message.narrative_text.length === 0) continue;
    const participantRole = isNarrativeParticipantRole(message.role) ? message.role : null;
    const participantEntityId =
      participantRole === null ? undefined : participantEntityIds.get(participantRole);
    evidenceItems.push({
      evidence_id: await createDeterministicNarraMemId(
        "evidence",
        `tavern-evidence:${snapshot.memory_set_id}:${message.source_unit_id}`,
      ),
      revision_id: revisionId,
      source_kind: "chat_message",
      locator: {
        host_kind: "tavern",
        source_type: "current_message",
        external_id: message.source_unit_id,
        path: `message/${message.message_id_at_capture}`,
        revision_hint: snapshot.checksum,
        metadata: {
          role: message.role,
          has_swipes: message.has_swipes,
        },
      },
      source_order: { ordinal: message.message_id_at_capture, component: 0 },
      speaker_or_emitter: {
        ...(participantEntityId === undefined ? {} : { entity_id: participantEntityId }),
        external_id: `${message.role}:${message.speaker_name}`,
        label: message.speaker_name,
      },
      raw_content: { kind: "text", text: message.narrative_text },
      content_fingerprint: createSha256Digest(message.content_fingerprint),
      authority: "accepted_text",
      reliability_hint: "presumed",
      visibility_hint: { mode: "unknown" },
    });
    if (participantEntityId === undefined || message.speaker_name.trim().length === 0) continue;
    const metadataValue = {
      external_id: `${message.role}:${message.speaker_name}`,
      label: message.speaker_name,
      role: message.role,
    } as const;
    const metadataFingerprint = createSha256Digest(await checksumJson(metadataValue));
    const metadataEvidence: EvidenceItem = {
      evidence_id: await createDeterministicNarraMemId(
        "evidence",
        `tavern-speaker-metadata:${snapshot.memory_set_id}:${message.source_unit_id}`,
      ),
      revision_id: revisionId,
      source_kind: "metadata",
      locator: {
        host_kind: "tavern",
        source_type: "current_message_speaker_metadata",
        external_id: message.source_unit_id,
        path: `message/${message.message_id_at_capture}/speaker_or_emitter`,
        revision_hint: snapshot.checksum,
        metadata: { role: message.role },
      },
      source_order: { ordinal: message.message_id_at_capture, component: 1 },
      speaker_or_emitter: {
        entity_id: participantEntityId,
        external_id: metadataValue.external_id,
        label: metadataValue.label,
      },
      raw_content: { kind: "structured", value: metadataValue },
      content_fingerprint: metadataFingerprint,
      authority: "script_confirmed",
      reliability_hint: "authoritative",
      visibility_hint: { mode: "unknown" },
    };
    evidenceItems.push(metadataEvidence);
    if (participantRole === null) continue;
    const accumulated = participantEvidence.get(participantRole) ?? [];
    accumulated.push({
      label: message.speaker_name,
      evidence: metadataEvidence,
      quote_hash: metadataFingerprint,
    });
    participantEvidence.set(participantRole, accumulated);
  }
  const scopeFingerprint = createSha256Digest(
    await checksumJson({
      memory_set_id: snapshot.memory_set_id,
      character_id: snapshot.scope.character_id,
      chat_id: snapshot.scope.chat_id,
    }),
  );
  const memorySpace: MemorySpace = {
    memory_space_id: memorySpaceId,
    host_kind: "tavern",
    subject_scope: {
      kind: "character_chat",
      host_locator: {
        character_id: snapshot.scope.character_id,
        chat_id: snapshot.scope.chat_id,
        memory_set_id: snapshot.memory_set_id,
      },
      fingerprint: scopeFingerprint,
    },
    branch_id: branchId,
    schema_version: "0.1.0",
    active_source_revision_id: revisionId,
  };
  const sourceEntities: Entity[] = [];
  for (const role of ["user", "assistant"] as const) {
    const occurrences = participantEvidence.get(role) ?? [];
    const latest = occurrences.at(-1);
    const entityId = participantEntityIds.get(role);
    if (latest === undefined || entityId === undefined) continue;
    const spans = occurrences.map(({ evidence, quote_hash }) => ({
      evidence_id: evidence.evidence_id,
      selector: {
        kind: "field_set" as const,
        fields: ["external_id", "label", "role"],
      },
      quote_hash,
      support_role: "direct" as const,
    }));
    const aliasLabels = [...new Set(occurrences.map((item) => item.label))]
      .filter((label) => label !== latest.label)
      .sort((left, right) => left.localeCompare(right));
    sourceEntities.push({
      memory_space_id: memorySpaceId,
      branch_id: branchId,
      entity_id: entityId,
      entity_type: "character",
      canonical_label: latest.label,
      aliases: aliasLabels.map((label) => ({
        label,
        evidence: occurrences.flatMap((item, index) => {
          const span = spans[index];
          return item.label === label && span !== undefined ? [span] : [];
        }),
      })),
      identity_evidence: spans,
      merge_status: "resolved",
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-narrative-participant:${revisionId}:${entityId}`,
        ),
        input_revision_id: revisionId,
        evidence_refs: occurrences.map((item) => item.evidence.evidence_id),
        dependency_refs: [],
        extractor: { kind: "rule" },
        validator_version: "tavern-speaker-metadata-projection@0.1.0",
        created_at: request.created_at,
      },
    });
  }
  const lastOrder = evidenceItems.at(-1)?.source_order ?? { ordinal: 0, component: 0 };
  const sourceRevision: SourceRevision = {
    revision_id: revisionId,
    memory_space_id: memorySpaceId,
    branch_id: branchId,
    source_cutoff: lastOrder,
    snapshot_fingerprint: createSha256Digest(snapshot.checksum),
    created_at: request.created_at,
    status: "active",
  };
  const knownEntities = new Map(request.known_entities.map((entity) => [entity.entity_id, entity]));
  for (const entity of sourceEntities) {
    knownEntities.set(entity.entity_id, {
      entity_id: entity.entity_id,
      entity_type: entity.entity_type,
      canonical_label: entity.canonical_label,
      aliases: entity.aliases.map((alias) => alias.label),
    });
  }
  const modelInput: NarrativeExtractionModelInput = {
    contract_version: "0.2.0",
    source_revision_id: revisionId,
    evidence_items: evidenceItems
      .filter((evidence) => evidence.raw_content.kind === "text")
      .map((evidence) => ({
        evidence_id: evidence.evidence_id,
        source_kind: evidence.source_kind,
        source_order: evidence.source_order,
        ...(evidence.speaker_or_emitter === undefined
          ? {}
          : { speaker_or_emitter: evidence.speaker_or_emitter }),
        text: evidence.raw_content.kind === "text" ? evidence.raw_content.text : "",
        authority: evidence.authority,
        reliability_hint: evidence.reliability_hint,
      })),
    known_entities: [...knownEntities.values()].sort((left, right) =>
      left.entity_id.localeCompare(right.entity_id),
    ),
    event_type_vocabulary: request.event_type_vocabulary,
    state_key_vocabulary: request.state_key_vocabulary ?? [],
    claim_predicate_vocabulary: request.claim_predicate_vocabulary ?? [],
    vocabulary_policy: "reuse_equivalent_else_propose",
    default_story_time: request.default_story_time,
  };
  return {
    projection_version: TAVERN_CORE_SOURCE_PROJECTION_VERSION,
    memory_space: memorySpace,
    source_revision: sourceRevision,
    evidence_items: evidenceItems,
    source_entities: sourceEntities,
    model_input: modelInput,
  };
}
