import type {
  CausalAuditCandidateBatch,
  CausalAuditCandidateCauseRef,
  CausalAuditCandidateEffectRef,
  EvidenceItem,
  NarraMemId,
} from "@narramem/core-domain";

import { validateWireValue } from "./wire-schema-registry.js";

export interface CausalAuditValidationFinding {
  readonly evidence_id: NarraMemId<"evidence">;
  readonly cue: string;
  readonly start_code_point: number;
  readonly end_code_point: number;
}

export interface CausalAuditCandidateValidationContext {
  readonly task_id: string;
  readonly active_revision_id: NarraMemId<"source_revision">;
  readonly finding: CausalAuditValidationFinding;
  readonly evidence_items: readonly EvidenceItem[];
  readonly allowed_cause_refs: readonly CausalAuditCandidateCauseRef[];
  readonly allowed_effect_refs: readonly CausalAuditCandidateEffectRef[];
  readonly allowed_holder_entity_ids: readonly NarraMemId<"entity">[];
  readonly record_evidence_refs: readonly {
    readonly record_id: NarraMemId;
    readonly evidence_ids: readonly NarraMemId<"evidence">[];
  }[];
}

export interface CausalAuditCandidateValidationIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export type CausalAuditCandidateValidationResult =
  | {
      readonly accepted: true;
      readonly candidate: CausalAuditCandidateBatch;
      readonly issues: readonly [];
    }
  | {
      readonly accepted: false;
      readonly issues: readonly CausalAuditCandidateValidationIssue[];
    };

function issue(code: string, path: string, message: string): CausalAuditCandidateValidationIssue {
  return { code, path, message };
}

function causeKey(reference: CausalAuditCandidateCauseRef): string {
  switch (reference.kind) {
    case "event":
      return `event:${reference.event_id}`;
    case "state_assertion":
      return `state_assertion:${reference.assertion_id}`;
    case "state_delta":
      return `state_delta:${reference.delta_id}`;
    case "epistemic_state":
      return `epistemic_state:${reference.epistemic_id}`;
    case "proposition":
      return `proposition:${reference.proposition_id}`;
    case "narrative_thread":
      return `narrative_thread:${reference.thread_id}`;
  }
}

function effectKey(reference: CausalAuditCandidateEffectRef): string {
  switch (reference.kind) {
    case "event":
      return `event:${reference.event_id}`;
    case "state_delta":
      return `state_delta:${reference.delta_id}`;
    case "epistemic_state":
      return `epistemic_state:${reference.epistemic_id}`;
    case "narrative_thread":
      return `narrative_thread:${reference.thread_id}`;
  }
}

function endpointId(
  reference: CausalAuditCandidateCauseRef | CausalAuditCandidateEffectRef,
): NarraMemId {
  switch (reference.kind) {
    case "event":
      return reference.event_id;
    case "state_assertion":
      return reference.assertion_id;
    case "state_delta":
      return reference.delta_id;
    case "epistemic_state":
      return reference.epistemic_id;
    case "proposition":
      return reference.proposition_id;
    case "narrative_thread":
      return reference.thread_id;
  }
}

function findOccurrence(
  text: string,
  quote: string,
  requestedOccurrence: number,
): number | undefined {
  let searchFrom = 0;
  let occurrence = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) return undefined;
    if (occurrence === requestedOccurrence) return index;
    occurrence += 1;
    searchFrom = index + Math.max(1, quote.length);
  }
  return undefined;
}

function codePointOffset(text: string, codeUnitOffset: number): number {
  return [...text.slice(0, codeUnitOffset)].length;
}

function duplicateValues(values: readonly string[]): readonly string[] {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  for (const value of values) {
    if (seen.has(value)) duplicates.add(value);
    seen.add(value);
  }
  return [...duplicates].sort();
}

export function validateCausalAuditCandidateBatch(
  value: unknown,
  context: CausalAuditCandidateValidationContext,
): CausalAuditCandidateValidationResult {
  const wire = validateWireValue("causal_audit_candidate_batch", value);
  if (!wire.valid) {
    return {
      accepted: false,
      issues: wire.errors.map((error) =>
        issue(
          "CAUSAL_AUDIT_CANDIDATE_SCHEMA_INVALID",
          error.instancePath || "/",
          error.message ?? "invalid",
        ),
      ),
    };
  }

  const candidate = value as CausalAuditCandidateBatch;
  const issues: CausalAuditCandidateValidationIssue[] = [];
  if (candidate.task_id !== context.task_id) {
    issues.push(
      issue("CAUSAL_AUDIT_TASK_MISMATCH", "/task_id", "Candidate belongs to another audit task"),
    );
  }
  if (candidate.source_revision_id !== context.active_revision_id) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_REVISION_MISMATCH",
        "/source_revision_id",
        "Candidate does not target the frozen source revision",
      ),
    );
  }

  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const findingEvidence = evidenceById.get(context.finding.evidence_id);
  const findingPoints =
    findingEvidence?.raw_content.kind === "text" ? [...findingEvidence.raw_content.text] : [];
  const findingContextValid =
    findingEvidence?.raw_content.kind === "text" &&
    Number.isSafeInteger(context.finding.start_code_point) &&
    Number.isSafeInteger(context.finding.end_code_point) &&
    context.finding.start_code_point >= 0 &&
    context.finding.end_code_point > context.finding.start_code_point &&
    findingPoints
      .slice(context.finding.start_code_point, context.finding.end_code_point)
      .join("") === context.finding.cue;
  if (!findingContextValid) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_FINDING_CONTEXT_INVALID",
        "/",
        "Trusted finding must resolve to its exact cue in active text Evidence",
      ),
    );
  }

  const allowedCauses = new Set(context.allowed_cause_refs.map(causeKey));
  const allowedEffects = new Set(context.allowed_effect_refs.map(effectKey));
  const allowedHolders = new Set(context.allowed_holder_entity_ids);
  const evidenceByRecord = new Map(
    context.record_evidence_refs.map((binding) => [
      binding.record_id,
      new Set(binding.evidence_ids),
    ]),
  );
  for (const duplicate of duplicateValues(
    candidate.causal_links.map((link) => link.candidate_key),
  )) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_DUPLICATE_CANDIDATE_KEY",
        "/causal_links",
        `Causal candidate key is duplicated: ${duplicate}`,
      ),
    );
  }

  const semanticKeys: string[] = [];
  candidate.causal_links.forEach((link, linkIndex) => {
    if (link.mechanism !== link.mechanism.trim()) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_MECHANISM_NOT_EXACT",
          `/causal_links/${linkIndex}/mechanism`,
          "Mechanism must not contain leading or trailing whitespace",
        ),
      );
    }
    const causeKeys = link.cause_refs.map(causeKey);
    const effectKeys = link.effect_refs.map(effectKey);
    for (const [causeIndex, key] of causeKeys.entries()) {
      if (!allowedCauses.has(key)) {
        issues.push(
          issue(
            "CAUSAL_AUDIT_CAUSE_REF_NOT_ALLOWED",
            `/causal_links/${linkIndex}/cause_refs/${causeIndex}`,
            `Cause reference is outside the trusted task allowlist: ${key}`,
          ),
        );
      }
    }
    for (const [effectIndex, key] of effectKeys.entries()) {
      if (!allowedEffects.has(key)) {
        issues.push(
          issue(
            "CAUSAL_AUDIT_EFFECT_REF_NOT_ALLOWED",
            `/causal_links/${linkIndex}/effect_refs/${effectIndex}`,
            `Effect reference is outside the trusted task allowlist: ${key}`,
          ),
        );
      }
      if (causeKeys.includes(key)) {
        issues.push(
          issue(
            "CAUSAL_AUDIT_SELF_LOOP",
            `/causal_links/${linkIndex}/effect_refs/${effectIndex}`,
            "The same durable record cannot be both cause and effect in one candidate link",
          ),
        );
      }
    }
    if (
      link.attribution.kind === "character_belief" &&
      !allowedHolders.has(link.attribution.holder_entity_id)
    ) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_HOLDER_NOT_ALLOWED",
          `/causal_links/${linkIndex}/attribution/holder_entity_id`,
          "Character-belief holder is outside the trusted task allowlist",
        ),
      );
    }

    let coversFinding = false;
    let hasSupportingQuote = false;
    const supportingEvidenceIds = new Set<NarraMemId<"evidence">>();
    const quoteKeys: string[] = [];
    link.evidence_quotes.forEach((quote, quoteIndex) => {
      const quotePath = `/causal_links/${linkIndex}/evidence_quotes/${quoteIndex}`;
      const evidence = evidenceById.get(quote.evidence_id);
      const occurrence = quote.occurrence ?? 0;
      quoteKeys.push(`${quote.evidence_id}:${occurrence}:${quote.support_role}:${quote.quote}`);
      if (evidence === undefined || evidence.raw_content.kind !== "text") {
        issues.push(
          issue(
            "CAUSAL_AUDIT_EVIDENCE_NOT_ALLOWED",
            quotePath,
            "Evidence quote is absent, structured-only, or outside the active task allowlist",
          ),
        );
        return;
      }
      const startCodeUnit = findOccurrence(evidence.raw_content.text, quote.quote, occurrence);
      if (startCodeUnit === undefined) {
        issues.push(
          issue(
            "CAUSAL_AUDIT_QUOTE_NOT_FOUND",
            `${quotePath}/quote`,
            "Evidence quote and occurrence must match the frozen Evidence exactly",
          ),
        );
        return;
      }
      const start = codePointOffset(evidence.raw_content.text, startCodeUnit);
      const end = codePointOffset(evidence.raw_content.text, startCodeUnit + quote.quote.length);
      if (quote.support_role !== "contradiction") {
        hasSupportingQuote = true;
        supportingEvidenceIds.add(quote.evidence_id);
      }
      if (
        quote.evidence_id === context.finding.evidence_id &&
        quote.support_role === "direct" &&
        start <= context.finding.start_code_point &&
        end >= context.finding.end_code_point
      ) {
        coversFinding = true;
      }
    });
    for (const duplicate of duplicateValues(quoteKeys)) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_DUPLICATE_QUOTE",
          `/causal_links/${linkIndex}/evidence_quotes`,
          `Evidence quote is duplicated: ${duplicate}`,
        ),
      );
    }
    if (!hasSupportingQuote) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_SUPPORT_MISSING",
          `/causal_links/${linkIndex}/evidence_quotes`,
          "A causal candidate requires at least one non-contradiction quote",
        ),
      );
    }
    if (!coversFinding) {
      issues.push(
        issue(
          "CAUSAL_AUDIT_FINDING_NOT_COVERED",
          `/causal_links/${linkIndex}/evidence_quotes`,
          "Each candidate link must directly quote a span covering the uncovered causal cue",
        ),
      );
    }
    for (const reference of [...link.cause_refs, ...link.effect_refs]) {
      const id = endpointId(reference);
      const endpointEvidence = evidenceByRecord.get(id);
      if (
        endpointEvidence === undefined ||
        ![...supportingEvidenceIds].some((evidenceId) => endpointEvidence.has(evidenceId))
      ) {
        issues.push(
          issue(
            "CAUSAL_AUDIT_ENDPOINT_EVIDENCE_MISSING",
            `/causal_links/${linkIndex}/evidence_quotes`,
            `Each selected endpoint requires a non-contradiction quote from its durable provenance: ${id}`,
          ),
        );
      }
    }
    semanticKeys.push(
      JSON.stringify({
        causes: [...causeKeys].sort(),
        effects: [...effectKeys].sort(),
        relation: link.relation,
        mechanism: link.mechanism,
        attribution: link.attribution,
        necessity: link.necessity,
        strength: link.strength,
        persistence: link.persistence ?? null,
      }),
    );
  });
  for (const duplicate of duplicateValues(semanticKeys)) {
    issues.push(
      issue(
        "CAUSAL_AUDIT_DUPLICATE_SEMANTIC_LINK",
        "/causal_links",
        `Equivalent causal candidates are duplicated: ${duplicate}`,
      ),
    );
  }

  return issues.length === 0
    ? { accepted: true, candidate, issues: [] }
    : { accepted: false, issues };
}
